function _ApplyUltimatePowerPlan {
    $guid = "e9a42b02-d5df-448d-aa00-03f14749eb61"
    $existing = powercfg /list 2>$null | Select-String $guid
    if (-not $existing) {
        powercfg /duplicatescheme $guid 2>$null | Out-Null
    }
    powercfg /setactive $guid 2>$null | Out-Null
    Write-Host "[POWER] Ultimate Performance power plan active ($guid)" -ForegroundColor Green
}

function _DisableAllVisualEffects {
    $regPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects"
    if (-not (Test-Path $regPath)) { New-Item -Path $regPath -Force | Out-Null }
    Set-ItemProperty -Path $regPath -Name "VisualFXSetting" -Value 2 -Type DWord -Force
    $advPath = "HKCU:\Control Panel\Desktop"
    Set-ItemProperty -Path $advPath -Name "UserPreferencesMask" -Value ([byte[]](0x90,0x12,0x03,0x80,0x10,0x00,0x00,0x00)) -Type Binary -Force
    Set-ItemProperty -Path $advPath -Name "DragFullWindows" -Value "0" -Force
    Set-ItemProperty -Path $advPath -Name "MenuShowDelay" -Value "0" -Force
    Set-ItemProperty -Path $advPath -Name "FontSmoothing" -Value "0" -Force
    $dwmPath = "HKCU:\Software\Microsoft\Windows\DWM"
    if (-not (Test-Path $dwmPath)) { New-Item -Path $dwmPath -Force | Out-Null }
    Set-ItemProperty -Path $dwmPath -Name "EnableAeroPeek" -Value 0 -Type DWord -Force
    Set-ItemProperty -Path $dwmPath -Name "AlwaysHibernateThumbnails" -Value 0 -Type DWord -Force
    $taskbarPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"
    Set-ItemProperty -Path $taskbarPath -Name "TaskbarAnimations" -Value 0 -Type DWord -Force
    Set-ItemProperty -Path $taskbarPath -Name "ListviewAlphaSelect" -Value 0 -Type DWord -Force
    Set-ItemProperty -Path $taskbarPath -Name "ListviewShadow" -Value 0 -Type DWord -Force
    Write-Host "[VISUAL] All visual effects disabled" -ForegroundColor Green
}

function _SetNetworkThrottlingMax {
    $netPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters"
    Set-ItemProperty -Path $netPath -Name "NetworkThrottlingIndex" -Value 0xFFFFFFFF -Type DWord -Force
    $mmPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"
    Set-ItemProperty -Path $mmPath -Name "NetworkThrottlingIndex" -Value 0xFFFFFFFF -Type DWord -Force
    Set-ItemProperty -Path $mmPath -Name "SystemResponsiveness" -Value 0 -Type DWord -Force
    Write-Host "[NETWORK] NetworkThrottlingIndex=0xFFFFFFFF, SystemResponsiveness=0" -ForegroundColor Green
}

function _SetBcdeditNuclear {
    bcdedit /set disabledynamictick yes 2>&1 | Out-Null
    bcdedit /set useplatformtick yes 2>&1 | Out-Null
    bcdedit /set tscsyncpolicy enhanced 2>&1 | Out-Null
    Write-Host "[BCDEDIT] disabledynamictick=yes, useplatformtick=yes, tscsyncpolicy=enhanced" -ForegroundColor Green
}

function _DisableHPET {
    bcdedit /deletevalue useplatformclock 2>&1 | Out-Null
    bcdedit /set useplatformclock false 2>&1 | Out-Null
    $hpetPath = "HKLM:\SYSTEM\CurrentControlSet\Enum\ACPI\PNP0103"
    if (Test-Path $hpetPath) {
        Get-ChildItem $hpetPath | ForEach-Object {
            $devParams = Join-Path $_.PSPath "Device Parameters"
            if (-not (Test-Path $devParams)) { New-Item -Path $devParams -Force | Out-Null }
        }
    }
    Write-Host "[HPET] HPET disabled via bcdedit (useplatformclock=false)" -ForegroundColor Green
}

function _SetTimerResMin {
    $timerPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel"
    if (-not (Test-Path $timerPath)) { New-Item -Path $timerPath -Force | Out-Null }
    Set-ItemProperty -Path $timerPath -Name "GlobalTimerResolutionRequests" -Value 1 -Type DWord -Force
    try {
        $code = @"
using System;
using System.Runtime.InteropServices;
public class TimerRes {
    [DllImport("ntdll.dll", SetLastError=true)]
    public static extern int NtSetTimerResolution(uint DesiredResolution, bool SetResolution, ref uint CurrentResolution);
    public static void SetMin() {
        uint cur = 0;
        NtSetTimerResolution(5000, true, ref cur);
    }
}
"@
        Add-Type -TypeDefinition $code -ErrorAction SilentlyContinue
        [TimerRes]::SetMin()
        Write-Host "[TIMER] NtSetTimerResolution set to 5000 (0.5ms)" -ForegroundColor Green
    } catch {
        Write-Host "[TIMER] Registry GlobalTimerResolutionRequests=1 set (NtSetTimerResolution unavailable in this context)" -ForegroundColor Yellow
    }
}

function _SetNVIDIARegistryMax {
    $nvBase = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"
    if (Test-Path $nvBase) {
        Get-ChildItem $nvBase -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
            $key = $_.PSPath
            Set-ItemProperty -Path $key -Name "PerfLevelSrc" -Value 0x3322 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "PowerMizerEnable" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "PowerMizerLevel" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "PowerMizerLevelAC" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "RmGpsPsEnableMsrOv" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "RmGpsPsEnableMsrOvAc" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "VRSOverride" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "TextureFilteringQuality" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "OGL_ThreadedOptimizations" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "NvCplLowLatencyMode" -Value 0x0000000F -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "PreferSystemMemory" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $key -Name "PciLatencyTimer" -Value 0x20 -Type DWord -Force -ErrorAction SilentlyContinue
        }
    }
    $nvProf = "HKCU:\Software\NVIDIA Corporation\Global\NVTweak"
    if (-not (Test-Path $nvProf)) { New-Item -Path $nvProf -Force | Out-Null }
    Set-ItemProperty -Path $nvProf -Name "Hybrid" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
    Write-Host "[NVIDIA] All NVIDIA registry performance keys maxed" -ForegroundColor Green
}

function _SetRyzenMax {
    $cpuPath = "HKLM:\SYSTEM\CurrentControlSet\Services\intelppm"
    if (Test-Path $cpuPath) {
        Set-ItemProperty -Path $cpuPath -Name "Start" -Value 4 -Type DWord -Force -ErrorAction SilentlyContinue
    }
    $amdppm = "HKLM:\SYSTEM\CurrentControlSet\Services\amdppm"
    if (Test-Path $amdppm) {
