    if (-not (Test-Path $usbPath)) { New-Item -Path $usbPath -Force | Out-Null }
    Set-ItemProperty -Path $usbPath -Name "DisableSelectiveSuspend" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue
    Get-ChildItem "HKLM:\SYSTEM\CurrentControlSet\Enum\USB" -ErrorAction SilentlyContinue | Get-ChildItem -ErrorAction SilentlyContinue | ForEach-Object {
        $devMgmt = Join-Path $_.PSPath "Device Parameters\Power Management"
        if (Test-Path $devMgmt) {
            Set-ItemProperty -Path $devMgmt -Name "WaitWakeEnabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $devMgmt -Name "SelectiveSuspendEnabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
        }
    }
    $nicBase = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}"
    if (Test-Path $nicBase) {
        Get-ChildItem $nicBase -ErrorAction SilentlyContinue | Where-Object { $_.PSChildName -match '^\d{4}$' } | ForEach-Object {
            Set-ItemProperty -Path $_.PSPath -Name "ITR" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
            Set-ItemProperty -Path $_.PSPath -Name "*InterruptModeration" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue
        }
    }
    Write-Host "[DPC] DPC max: USB suspend off, NIC interrupt moderation off" -ForegroundColor Green
}

