function _ClearSystemMemory {
    $procs = Get-Process -ErrorAction SilentlyContinue
    $trimmed = 0
    foreach ($proc in $procs) {
        try {
            if ($proc.WorkingSet64 -gt 50MB) {
                [System.Runtime.InteropServices.Marshal]::EmptyWorkingSet($proc.Handle) | Out-Null
                $trimmed++
            }
        } catch {}
    }
    [System.GC]::Collect(2, [System.GCCollectionMode]::Forced, $true, $true)
    [System.GC]::WaitForPendingFinalizers()
    [System.GC]::Collect(2, [System.GCCollectionMode]::Forced, $true, $true)
    $flusher = Add-Type -MemberDefinition '[DllImport("ntdll.dll")] public static extern uint NtSetSystemInformation(int cls, IntPtr buf, uint sz);' -Name 'NtFlush' -Namespace 'Mem' -PassThru -ErrorAction SilentlyContinue
    if ($flusher) { try { $flusher::NtSetSystemInformation(80, [IntPtr]::Zero, 0) | Out-Null } catch {} }
    Write-Host "[MEMORY-CLEAR] $trimmed process working sets trimmed, GC x2, FS cache flushed" -ForegroundColor Green
}

