function ob {
    param([string]$Note = "")
    $vaultPath = "F:\backup\obsidion"
    if ($Note) {
        $found = Get-ChildItem $vaultPath -Recurse -Filter "*.md" | Where-Object { $_.Name -like "*$Note*" } | Select-Object -First 1
        if ($found) {
            Start-Process "obsidian://open?path=$([uri]::EscapeDataString($found.FullName))"
            Write-Host "Opening: $($found.Name)" -ForegroundColor Green
        } else {
            Start-Process "obsidian://open?vault=obsidion"
            Write-Host "Note '$Note' not found - opened vault root" -ForegroundColor Yellow
        }
    } else {
        Start-Process "obsidian://open?vault=obsidion"
        Write-Host "Opened Obsidian vault: $vaultPath" -ForegroundColor Cyan
    }
}

$ProgressPreference = 'SilentlyContinue'

if (Get-Command 'Set-PSReadLineKeyHandler' -ErrorAction SilentlyContinue) {
    Set-PSReadLineKeyHandler -Key Enter -ScriptBlock {
        param($key, $arg)

        $line = $null
        $cursor = $null
        [Microsoft.PowerShell.PSConsoleReadLine]::GetBufferState([ref]$line, [ref]$cursor)

        if ($line -match '&&|\|\|') {
            [Microsoft.PowerShell.PSConsoleReadLine]::RevertLine()
            [Microsoft.PowerShell.PSConsoleReadLine]::AcceptLine()

            Invoke-ChainedCommand $line
        } else {
