function Initialize-BackupDockerEnvironment {
    $requiredEnv = @{
        ProgramData = 'C:\ProgramData'
        APPDATA = [System.Environment]::GetFolderPath('ApplicationData')
        LOCALAPPDATA = [System.Environment]::GetFolderPath('LocalApplicationData')
    }

    foreach ($entry in $requiredEnv.GetEnumerator()) {
        $currentValue = $null
        try {
            $currentValue = (Get-Item -Path ("Env:{0}" -f $entry.Key) -ErrorAction Stop).Value
        } catch {
        }

        if ([string]::IsNullOrWhiteSpace($currentValue)) {
            Set-Item -Path ("Env:{0}" -f $entry.Key) -Value $entry.Value
        }
    }
}

function ConvertTo-BackupDockerSlug {
    param([Parameter(Mandatory)][string]$Value)

    $slug = $Value.ToLowerInvariant()
    $slug = $slug -replace '[^a-z0-9._-]+', '-'
    $slug = $slug.Trim('-._')

    if (-not $slug) {
        throw "Could not derive a Docker-safe repo slug from '$Value'."
    }

    if ($slug.Length -lt 2) {
        $slug = "$slug-b"
    }

    $slug
}

function Resolve-BackupDockerProjectPath {
    param([Parameter(Mandatory)][string]$Path)

    $candidate = $Path.Trim()
    if (-not $candidate) {
        throw "Path cannot be empty."
    }

    if (Test-Path -LiteralPath $candidate -PathType Container) {
        return (Resolve-Path -LiteralPath $candidate).Path
    }

    $currentPath = (Get-Location).Path
    $currentLeaf = Split-Path -Leaf $currentPath
    if ($currentLeaf -and $currentLeaf.Equals($candidate, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $currentPath
    }

    throw "Path not found: $Path"
}

