function ConvertFrom-BackupMenuHistorySegment {
    param([Parameter(Mandatory)][string]$Segment)

    $trimmedSegment = $Segment.Trim()
    if (-not $trimmedSegment) {
        return $null
    }

    $pattern = '^(?<FunctionName>menu(?:\d+)?)\s+(?:-Path\s+)?(?<Path>("([^"]|"")*"|''([^'']|'''')*''|\S.+?))\s*$'
    $match = [regex]::Match($trimmedSegment, $pattern, [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if (-not $match.Success) {
        return $null
    }

    $rawPath = $match.Groups['Path'].Value.Trim()
    if (($rawPath.StartsWith('"') -and $rawPath.EndsWith('"')) -or ($rawPath.StartsWith("'") -and $rawPath.EndsWith("'"))) {
        $rawPath = $rawPath.Substring(1, $rawPath.Length - 2)
    }

    if ($rawPath -notmatch '^[A-Za-z]:[\\/]') {
        return $null
    }

    $details = Get-BackupMenuInvocationDetails -FunctionName $match.Groups['FunctionName'].Value
    return [pscustomobject]@{
        Path = $rawPath
        FunctionName = $details.FunctionName
        Layer = $details.Layer
        LegacySharedRepo = $details.LegacySharedRepo
        SchemaVersion = $details.SchemaVersion
    }
}

