function Get-BackupDockerRegisteredSourcePath {
    param([Parameter(Mandatory)][string]$RepoSlug)

    $mapPath = Get-BackupDockerSourceMapPath
    if (-not (Test-Path -LiteralPath $mapPath -PathType Leaf)) {
        return $null
    }

    $lines = @(Get-Content -LiteralPath $mapPath -ErrorAction SilentlyContinue)
    for ($i = $lines.Count - 1; $i -ge 0; $i--) {
        $parts = $lines[$i] -split "`t", 3
        if ($parts.Count -ge 2 -and $parts[0].Equals($RepoSlug, [System.StringComparison]::OrdinalIgnoreCase)) {
            if ($parts[1] -notmatch '^[A-Za-z]:\\backup(\\|$)') {
                return $parts[1]
            }
        }
    }

    return $null
}

