function Get-BackupDockerRepoSlugFromReference {
    param([Parameter(Mandatory)][string]$Reference)

    $normalizedReference = $Reference.Trim()
    if (-not $normalizedReference) {
        throw "Repo reference cannot be empty."
    }

    if ($normalizedReference -match '^[^/]+/([^:]+)(?::.+)?$') {
        return (Get-BackupDockerRepoSlug -Name $matches[1])
    }

    if ($normalizedReference -match '^([^:]+):.+$') {
        $normalizedReference = $matches[1]
    }

    return (Get-BackupDockerRepoSlug -Name $normalizedReference)
}

