function Get-BackupDockerRepository {
    [CmdletBinding(DefaultParameterSetName = 'Path')]
    param(
        [Parameter(Mandatory, ParameterSetName = 'Path')]
        [string]$Path,

        [Parameter(Mandatory, ParameterSetName = 'Name')]
        [string]$Name
    )

    $repoSlug = if ($PSCmdlet.ParameterSetName -eq 'Path') {
        Get-BackupDockerRepoSlug -Path $Path
    } else {
        Get-BackupDockerRepoSlug -Name $Name
    }

    $namespace = if ([string]::IsNullOrWhiteSpace($script:BackupDockerNamespace)) { 'michadockermisha' } else { [string]$script:BackupDockerNamespace }
    $slug = ([string]$repoSlug).Trim().Trim('/')
    if ($slug -match '/') { $slug = ($slug -split '/')[-1] }
    if ([string]::IsNullOrWhiteSpace($slug)) { throw 'Backup Docker repository slug resolved empty.' }
    "$namespace/$slug"
}

