function Invoke-BackupDockerLatestRestoreForRepoSlug {
    param(
        [Parameter(Mandatory)][string]$RepoSlug,
        [Parameter(Mandatory)][string]$SourcePath,
        [string]$DestinationPath
    )

    $projectPath = Resolve-BackupDockerProjectPath -Path $SourcePath
    $repository = Get-BackupDockerRepositoryFromSlug -RepoSlug $RepoSlug
    $latestTag = Get-BackupDockerLatestRemoteTag -RepoSlug $RepoSlug
    $imageRef = "${repository}:$latestTag"
    $targetPath = if ($DestinationPath) {
        [System.IO.Path]::GetFullPath($DestinationPath)
    } else {
        $projectPath
    }

    $restoreResult = Invoke-BackupDockerImageRestore -ImageRef $imageRef -SourcePath $projectPath -DestinationPath $targetPath
    [pscustomobject]@{
        ProjectPath = $projectPath
        DestinationPath = $restoreResult.DestinationPath
        Repository = $repository
        Tag = $latestTag
        ImageRef = $imageRef
        DockerTargetPath = $restoreResult.DockerTargetPath
    }
}

function Get-BackupDockerLatestTagNameFromSet {
    param([string[]]$TagNames)

    $resolvedTagNames = @($TagNames | Where-Object { $_ -and $_ -ne '<none>' } | ForEach-Object { [string]$_ })
    if ($resolvedTagNames.Count -eq 0) {
        return $null
    }

    $numericTags = @($resolvedTagNames | Where-Object { $_ -match '^\d+$' })
    if ($numericTags.Count -gt 0) {
        return (($numericTags | ForEach-Object { [int64]$_ } | Sort-Object | Select-Object -Last 1).ToString())
    }

    return ($resolvedTagNames | Sort-Object | Select-Object -Last 1)
}

function New-BackupDockerTag {
