function Get-BackupDockerHubErrorStatusCode {
    param([Parameter(Mandatory)][System.Management.Automation.ErrorRecord]$ErrorRecord)

    try {
        if ($ErrorRecord.Exception.Response -and $ErrorRecord.Exception.Response.StatusCode) {
            return [int]$ErrorRecord.Exception.Response.StatusCode
        }
    } catch {
    }

    return $null
}

function Get-BackupDockerHubErrorResponseText {
    param([Parameter(Mandatory)][System.Management.Automation.ErrorRecord]$ErrorRecord)

    try {
        if (-not $ErrorRecord.Exception.Response) {
            return $null
        }

        $stream = $ErrorRecord.Exception.Response.GetResponseStream()
        if (-not $stream) {
            return $null
        }

        $reader = New-Object System.IO.StreamReader($stream)
        try {
            return $reader.ReadToEnd()
        } finally {
            $reader.Dispose()
        }
    } catch {
        return $null
    }
}

function Test-BackupDockerRepositoryExists {
    param(
        [Parameter(Mandatory)][string]$RepoSlug,
        [Parameter(Mandatory)][hashtable]$Headers
    )

    $repoUri = "$script:BackupDockerHubBaseUri/v2/namespaces/$script:BackupDockerNamespace/repositories/$RepoSlug"

    try {
        $null = Invoke-RestMethod -Method Get -Uri $repoUri -Headers $Headers -ErrorAction Stop
        return $true
    } catch {
        $statusCode = Get-BackupDockerHubErrorStatusCode -ErrorRecord $_
        if ($statusCode -eq 404) {
            return $false
        }
        throw
    }
}

