function Get-BackupDockerLatestTag {
    [CmdletBinding(DefaultParameterSetName = 'Path')]
    param(
        [Parameter(Mandatory, ParameterSetName = 'Path')]
        [string]$Path,

        [Parameter(Mandatory, ParameterSetName = 'Name')]
        [string]$Name
    )

    $repository = if ($PSCmdlet.ParameterSetName -eq 'Path') {
        Get-BackupDockerRepository -Path $Path
    } else {
        Get-BackupDockerRepository -Name $Name
    }
    $repoSlug = if ($PSCmdlet.ParameterSetName -eq 'Path') {
        Get-BackupDockerRepoSlug -Path $Path
    } else {
        Get-BackupDockerRepoSlug -Name $Name
    }

    $localTags = @(docker image ls $repository --format '{{.Tag}}' 2>$null | Where-Object { $_ -and $_ -ne '<none>' })
    $latestLocalTag = Get-BackupDockerLatestTagNameFromSet -TagNames $localTags
    if ($latestLocalTag) {
        return $latestLocalTag
    }

    $remoteTags = @(Get-BackupDockerHubTagNames -RepoSlug $repoSlug)
    $latestRemoteTag = Get-BackupDockerLatestTagNameFromSet -TagNames $remoteTags
    if ($latestRemoteTag) {
        return $latestRemoteTag
    }

    throw "No Docker tags were found for $repository. Run the corresponding backup build/push first."
}

function Get-BackupDockerLatestImageRef {
    [CmdletBinding(DefaultParameterSetName = 'Path')]
    param(
        [Parameter(Mandatory, ParameterSetName = 'Path')]
        [string]$Path,

        [Parameter(Mandatory, ParameterSetName = 'Name')]
        [string]$Name
    )

    $repository = if ($PSCmdlet.ParameterSetName -eq 'Path') {
        Get-BackupDockerRepository -Path $Path
    } else {
        Get-BackupDockerRepository -Name $Name
    }
    $tag = if ($PSCmdlet.ParameterSetName -eq 'Path') {
        Get-BackupDockerLatestTag -Path $Path
    } else {
        Get-BackupDockerLatestTag -Name $Name
    }

    "${repository}:$tag"
}

function Get-BackupDockerLatestRemoteTag {
    [CmdletBinding(DefaultParameterSetName = 'Path')]
    param(
        [Parameter(Mandatory, ParameterSetName = 'Path')]
        [string]$Path,

        [Parameter(Mandatory, ParameterSetName = 'Name')]
        [string]$Name,

        [Parameter(Mandatory, ParameterSetName = 'RepoSlug')]
        [string]$RepoSlug
    )

    $resolvedRepoSlug = if ($PSCmdlet.ParameterSetName -eq 'Path') {
        Get-BackupDockerRepoSlug -Path $Path
    } elseif ($PSCmdlet.ParameterSetName -eq 'Name') {
        Get-BackupDockerRepoSlug -Name $Name
    } else {
        $RepoSlug
    }
    $repository = Get-BackupDockerRepositoryFromSlug -RepoSlug $resolvedRepoSlug

    $remoteTags = @(Get-BackupDockerHubTagNames -RepoSlug $resolvedRepoSlug)
    $latestRemoteTag = Get-BackupDockerLatestTagNameFromSet -TagNames $remoteTags
    if ($latestRemoteTag) {
        return $latestRemoteTag
    }

    throw "No Docker Hub tags were found for $repository. Run menu for that path first."
}

function ConvertTo-BackupDockerBindMountPath {
    param([Parameter(Mandatory)][string]$Path)

    $fullPath = [System.IO.Path]::GetFullPath($Path)
    if ($fullPath -notmatch '^(?<Drive>[A-Za-z]):(?<Rest>(\\.*)?)$') {
        throw "Only local Windows drive paths are supported for Docker restore mounts: $Path"
    }

    $drive = $matches.Drive.ToLowerInvariant()
    $rest = ($matches.Rest -replace '\\', '/').Trim('/')

    if ($rest) {
        return "/$drive/$rest"
    }

    return "/$drive"
}

function Invoke-BackupDockerStreamingCommand {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Activity,
        [Parameter(Mandatory)][string[]]$Arguments
    )

    $commandText = 'docker ' + (($Arguments | ForEach-Object {
        $argumentText = [string]$_
        if ($argumentText -match '[\s"]') {
            '"' + ($argumentText -replace '"', '\"') + '"'
        } else {
            $argumentText
        }
    }) -join ' ')

    Write-Host ""
    Write-Host ("[{0}:START] {1}" -f $Activity, $commandText) -ForegroundColor Cyan
    & docker @Arguments | Out-Host
    $exitCode = $LASTEXITCODE
    if ($exitCode -eq 0) {
        Write-Host ("[{0}:END] exit 0" -f $Activity) -ForegroundColor Green
    } else {
        Write-Host ("[{0}:END] exit {1}" -f $Activity, $exitCode) -ForegroundColor Red
    }

    return $exitCode
}

