function Get-BackupDockerSourcePathFromImageRef {
    [CmdletBinding()]
    param([Parameter(Mandatory)][string]$ImageRef)

    $inspectPath = docker image inspect -f '{{index .Config.Labels "backup.source.path"}}' $ImageRef 2>$null
    if ($LASTEXITCODE -eq 0 -and $inspectPath) {
        try { return [System.IO.Path]::GetFullPath($inspectPath) } catch { return $inspectPath }
    }

    for ($attempt = 1; $attempt -le 4; $attempt++) {
        $pullExitCode = Invoke-BackupDockerStreamingCommand -Activity "PULL#$attempt" -Arguments @('pull', $ImageRef)
        if ($pullExitCode -eq 0) {
            break
        }

        if ($attempt -lt 4) {
            Start-Sleep -Seconds 2
        }
    }

    if ($pullExitCode -ne 0) {
        return $null
    }

    $inspectPath = docker image inspect -f '{{index .Config.Labels "backup.source.path"}}' $ImageRef 2>$null
    if ($LASTEXITCODE -eq 0 -and $inspectPath) {
        try { return [System.IO.Path]::GetFullPath($inspectPath) } catch { return $inspectPath }
    }

    return $null
}

