function Invoke-BackupDockerLegacySharedRestore {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)][string]$Path,
        [string]$DestinationPath
    )

    $projectPath = Resolve-BackupDockerProjectPath -Path $Path
    $folderName = Split-Path -Leaf $projectPath
    $imageRef = "michadockermisha/backup:$folderName"
    $targetPath = if ($DestinationPath) {
        [System.IO.Path]::GetFullPath($DestinationPath)
    } else {
        $projectPath
    }

    $restoreResult = Invoke-BackupDockerImageRestore -ImageRef $imageRef -SourcePath $projectPath -DestinationPath $targetPath
    [pscustomobject]@{
        ProjectPath = $projectPath
        DestinationPath = $restoreResult.DestinationPath
        Repository = 'michadockermisha/backup'
        Tag = $folderName
        ImageRef = $imageRef
        DockerTargetPath = $restoreResult.DockerTargetPath
    }
}

