function dp {
    $tag = $args -join ' '
    Write-Host "`n[PUSH] $tag" -ForegroundColor Cyan
    $sw = [System.Diagnostics.Stopwatch]::StartNew()
    $pinfo = New-Object System.Diagnostics.ProcessStartInfo
    $pinfo.FileName = "docker"
    $pinfo.Arguments = "push $tag"
    $pinfo.RedirectStandardOutput = $true
    $pinfo.RedirectStandardError  = $true
    $pinfo.UseShellExecute = $false
    $p = New-Object System.Diagnostics.Process
    $p.StartInfo = $pinfo
    $p.Start() | Out-Null
    while (-not $p.HasExited) {
        while ($true) { $l = $p.StandardError.ReadLine(); if ($null -eq $l) { break }
            if ($l -match "digest|manifest|Pushed") { Write-Host $l -ForegroundColor Green }
            elseif ($l -match "Layer already") { Write-Host $l -ForegroundColor DarkGreen }
            elseif ($l -match "error|failed") { Write-Host $l -ForegroundColor Red }
            else { Write-Host $l -ForegroundColor Gray }
        }
        while ($true) { $l = $p.StandardOutput.ReadLine(); if ($null -eq $l) { break }; Write-Host $l }
        Start-Sleep -Milliseconds 20
    }
    $p.WaitForExit()
    $sw.Stop()
    if ($p.ExitCode -eq 0) {
        Write-Host "[PUSHED] $tag in $($sw.Elapsed.TotalSeconds.ToString('F1'))s" -ForegroundColor Green
    } else {
        Write-Host "[FAILED] $tag after $($sw.Elapsed.TotalSeconds.ToString('F1'))s" -ForegroundColor Red
    }
}
