function Ensure-ProfilePowerShellModulePath {
    $myDocuments = [Environment]::GetFolderPath('MyDocuments')
    if (-not $myDocuments -and $env:USERPROFILE) { $myDocuments = Join-Path $env:USERPROFILE 'Documents' }

    $programFiles = $env:ProgramFiles
    if (-not $programFiles) { $programFiles = 'C:\Program Files' }

    $windir = $env:WINDIR
    if (-not $windir) { $windir = 'C:\Windows' }

    $candidatePaths = @(
        (Join-Path $myDocuments 'WindowsPowerShell\Modules'),
        (Join-Path $myDocuments 'PowerShell\Modules'),
        (Join-Path $programFiles 'WindowsPowerShell\Modules'),
        (Join-Path $programFiles 'PowerShell\Modules'),
        (Join-Path $windir 'System32\WindowsPowerShell\v1.0\Modules')
    ) | Where-Object { $_ -and (Test-Path -LiteralPath $_ -PathType Container) }

    $existingPaths = @($env:PSModulePath -split ';' | Where-Object { $_ })
    $pathMap = [ordered]@{}
    foreach ($path in @($candidatePaths + $existingPaths)) {
        if ($path -and -not $pathMap.Contains($path)) { $pathMap[$path] = $true }
    }

    if ($pathMap.Count -gt 0) {
        $env:PSModulePath = ($pathMap.Keys -join ';')
    }
}

