function Invoke-BackupMenuForPath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string]$Path,

        [switch]$LegacySharedRepo
    )

    Initialize-BackupDockerEnvironment

    try {
        $projectPath = Resolve-BackupDockerProjectPath -Path $Path
    } catch {
        Write-Error $_.Exception.Message
        return $false
    }

    if ($LegacySharedRepo) {
        $folderName = Split-Path -Leaf $projectPath
        $imageRef = "michadockermisha/backup:$folderName"
        return (Invoke-BackupMenuBuildPush -ProjectPath $projectPath -ImageRef $imageRef -EnsureRepositoryName 'backup')
    }

    $repoSlug = Get-BackupMenuRepoSlug -Path $projectPath
    $repository = Get-BackupDockerRepositoryFromSlug -RepoSlug $repoSlug
    $imageRef = "${repository}:$(New-BackupDockerTag -RepoSlug $repoSlug)"
    $succeeded = Invoke-BackupMenuBuildPush -ProjectPath $projectPath -ImageRef $imageRef -EnsureRepositorySlug $repoSlug
    if ($succeeded) {
        Register-BackupDockerSourcePath -RepoSlug $repoSlug -Path $projectPath
    }
    return $succeeded
}

function Resolve-BackupMenuRestoreDestinationPath {
    param(
        [Parameter(Mandatory)][string]$RootPath,
        [Parameter(Mandatory)][string]$SourcePath,
        [string]$DestinationRoot
    )

    if (-not $DestinationRoot) {
        return $SourcePath
    }

    $resolvedRootPath = Resolve-BackupDockerProjectPath -Path $RootPath
    $resolvedSourcePath = Resolve-BackupDockerProjectPath -Path $SourcePath
    $resolvedDestinationRoot = [System.IO.Path]::GetFullPath($DestinationRoot)

    if ((Get-BackupComparablePath -Path $resolvedRootPath) -eq (Get-BackupComparablePath -Path $resolvedSourcePath)) {
        return $resolvedDestinationRoot
    }

    $relativePath = $resolvedSourcePath.Substring($resolvedRootPath.Length).TrimStart([char[]]"\/")
    if (-not $relativePath) {
        return $resolvedDestinationRoot
    }

    return (Join-Path $resolvedDestinationRoot $relativePath)
}

