function unem {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, Position = 0)]
        [string]$Target,

        [string]$DestinationPath
    )

    if (-not $Target) { Write-Error "Usage: unem <path-or-repo> [-DestinationPath <path>]"; return }

    $invokeParams = @{}
    if ((Test-Path -LiteralPath $Target -PathType Container) -or ($Target -match '^[A-Za-z]:[\\/]')) {
        $invokeParams.Path = $Target
    } else {
        $invokeParams.Name = $Target
    }
    if ($PSBoundParameters.ContainsKey('DestinationPath')) {
        $invokeParams.DestinationPath = $DestinationPath
    }

    [void](Invoke-BackupDockerLatestRestore @invokeParams)
}

