function Repair-StandardWindowsEnvironment {
    $userProfile = if (-not [string]::IsNullOrWhiteSpace($env:USERPROFILE)) {
        $env:USERPROFILE
    } else {
        'C:\Users\micha'
    }
    $systemDrive = if (-not [string]::IsNullOrWhiteSpace($env:SystemDrive)) {
        $env:SystemDrive
    } elseif (-not [string]::IsNullOrWhiteSpace($env:SystemRoot) -and $env:SystemRoot -match '^[A-Za-z]:') {
        $env:SystemRoot.Substring(0, 2)
    } else {
        'C:'
    }
    $programData = Join-Path $systemDrive 'ProgramData'
    $publicProfile = Join-Path $systemDrive 'Users\Public'
    $homeDrive = Split-Path $userProfile -Qualifier
    $homePath = if ($homeDrive -and $userProfile.StartsWith($homeDrive, [System.StringComparison]::OrdinalIgnoreCase)) {
        $userProfile.Substring($homeDrive.Length)
    } else {
        '\Users\micha'
    }
    $defaults = [ordered]@{
        SystemDrive = $systemDrive
        ProgramData = $programData
        ALLUSERSPROFILE = $programData
        PUBLIC = $publicProfile
        HOMEDRIVE = if ($homeDrive) { $homeDrive } else { 'C:' }
        HOMEPATH = $homePath
    }

    foreach ($name in $defaults.Keys) {
        if ([string]::IsNullOrWhiteSpace([Environment]::GetEnvironmentVariable($name, 'Process'))) {
            Set-Item -Path "Env:$name" -Value $defaults[$name]
        }
    }
}
