function ccfun {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory, Position = 0)]
        [string]$FunctionName
    )

    try {
        $functionMap = Get-ProfileFunctionMap
    }
    catch {
        Write-Error $_
        return
    }

    if (-not $functionMap.ContainsKey($FunctionName)) {
        Write-Warning "Function '$FunctionName' not found in $PROFILE."
        return
    }

    $dependencyNames = Get-ProfileFunctionDependencyNames -FunctionAst $functionMap[$FunctionName] -FunctionMap $functionMap
    if (-not $dependencyNames -or $dependencyNames.Length -eq 0) {
        Write-Warning "No profile-defined functions were detected inside '$FunctionName'."
        return
    }

    for ($i = 0; $i -lt $dependencyNames.Length; $i++) {
        $dependencyName = $dependencyNames[$i]
        $functionMap[$dependencyName].Extent.Text.TrimEnd() | Write-Output
        if ($i -lt ($dependencyNames.Length - 1)) {
            Write-Output ''
        }
    }
}

