function rmfolders2 {
    [CmdletBinding(SupportsShouldProcess = $true)]
    param()

    $progressId = 770
    $roots = @(
        (Join-Path $env:LOCALAPPDATA 'NVIDIA\DXCache'),
        (Join-Path $env:LOCALAPPDATA 'npm-cache'),
        (Join-Path $env:LOCALAPPDATA 'SquirrelTemp'),
        $env:TEMP
    ) | Select-Object -Unique
    $programFilesX86 = ${env:ProgramFiles(x86)}
    $protectedRoots = @(
        (Join-Path $env:SystemDrive 'Windows'),
        (Join-Path $env:SystemDrive 'Program Files'),
        $programFilesX86,
        (Join-Path $env:SystemDrive 'study'),
        (Join-Path $env:USERPROFILE 'Documents')
    ) | Where-Object { $_ }
    $failures = New-Object System.Collections.Generic.List[string]
    $cleared = 0

    try {
        for ($index = 0; $index -lt $roots.Count; $index++) {
            $root = [IO.Path]::GetFullPath($roots[$index]).TrimEnd('\')
            $percent = [int][Math]::Floor(($index / [Math]::Max($roots.Count, 1)) * 100)
            Write-Progress -Id $progressId -Activity 'rmfolders2 user cache cleanup' -Status "Checking $root" -PercentComplete $percent

            if ($protectedRoots | Where-Object { $root.Equals(([IO.Path]::GetFullPath($_)).TrimEnd('\'), [StringComparison]::OrdinalIgnoreCase) -or $root.StartsWith(([IO.Path]::GetFullPath($_)).TrimEnd('\') + '\', [StringComparison]::OrdinalIgnoreCase) }) {
                throw "rmfolders2 refuses protected path: $root"
            }
            if (-not (Test-Path -LiteralPath $root -PathType Container)) {
                Write-Host "[SKIP] cache root absent: $root" -ForegroundColor DarkGray
                continue
            }

            $items = @(Get-ChildItem -LiteralPath $root -Force -ErrorAction Stop)
            if ($items.Count -eq 0) {
                Write-Host "[SKIP] cache root already empty: $root" -ForegroundColor DarkGray
                continue
            }

            Write-Host "[CLEAN] $root items=$($items.Count)" -ForegroundColor Cyan
            foreach ($item in $items) {
                if ($PSCmdlet.ShouldProcess($item.FullName, 'Remove cache item')) {
                    try {
                        Remove-Item -LiteralPath $item.FullName -Recurse -Force -ErrorAction Stop
                        $cleared++
                    } catch {
                        $failures.Add("$($item.FullName): $($_.Exception.Message)") | Out-Null
                    }
                }
            }
        }
    } finally {
        Write-Progress -Id $progressId -Activity 'rmfolders2 user cache cleanup' -Completed
    }

    Write-Host "RMFOLDERS2_RESULT cleared=$cleared failures=$($failures.Count)" -ForegroundColor $(if ($failures.Count) { 'Yellow' } else { 'Green' })
    if ($failures.Count -gt 0) {
        throw "rmfolders2 left $($failures.Count) cache items undeleted: $($failures -join '; ')"
    }
}

