function 7zit {
    $archives = Get-ChildItem -Path "F:\Downloads" -Include *.zip,*.rar,*.7z,*.tar,*.gz -File -Recurse
    if (-not $archives) { Write-Host "7zit: No archives found in F:\Downloads" -ForegroundColor Yellow; return }
    foreach ($archive in $archives) {
        $destDir = Join-Path $archive.DirectoryName $archive.BaseName
        Write-Host "Extracting: $($archive.Name) -> $destDir" -ForegroundColor Cyan
        7z x $archive.FullName "-o$destDir" -p123 -y
        if ($LASTEXITCODE -ne 0) {
            Write-Host "FAILED: $($archive.Name) (exit $LASTEXITCODE)   skipping delete" -ForegroundColor Red
        } elseif (-not (Test-Path -LiteralPath $destDir) -or (Get-ChildItem -LiteralPath $destDir -Recurse -File).Count -eq 0) {
            Write-Host "FAILED: $($archive.Name)   output folder empty or missing   skipping delete" -ForegroundColor Red
        } else {
            Write-Host "OK: $($archive.Name)" -ForegroundColor Green
        }
    }
}

