function Start-GititProcess {
    param([string]$Directory)

    $scriptPath = 'F:\study\Version_Control\git\gitit\a.py'
    $logRoot = Join-Path $env:TEMP ("gitit-" + [guid]::NewGuid().ToString('N'))
    $null = New-Item -ItemType Directory -Force -Path $logRoot
    $stdoutPath = Join-Path $logRoot 'stdout.log'
    $stderrPath = Join-Path $logRoot 'stderr.log'
    $null = New-Item -ItemType File -Force -Path $stdoutPath
    $null = New-Item -ItemType File -Force -Path $stderrPath

    $argumentString = ('"{0}" "{1}"' -f $scriptPath.Replace('"', '\"'), $Directory.Replace('"', '\"'))
    $process = Start-Process -FilePath "python" -ArgumentList $argumentString -PassThru -NoNewWindow -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath

    [PSCustomObject]@{
        Directory = $Directory
        Process = $process
        StdoutPath = $stdoutPath
        StderrPath = $stderrPath
        StdoutOffset = 0
        StderrOffset = 0
        LogRoot = $logRoot
        StartedAt = Get-Date
    }
}

function Write-GititLogDelta {
    param(
        $State,
        [switch]$FlushAll
    )

    foreach ($spec in @(
        @{ Path = 'StdoutPath'; Offset = 'StdoutOffset' },
        @{ Path = 'StderrPath'; Offset = 'StderrOffset' }
    )) {
        $path = $State.($spec.Path)
        if (-not (Test-Path $path)) { continue }
        try {
            $content = [System.IO.File]::ReadAllText($path)
        } catch {
            continue
        }
        $offset = [int]$State.($spec.Offset)
        if ($content.Length -gt $offset) {
            $delta = $content.Substring($offset)
            if ($delta) {
                Write-Host -NoNewline $delta
            }
            $State.($spec.Offset) = $content.Length
        } elseif ($FlushAll -and $content.Length -lt $offset) {
            $State.($spec.Offset) = $content.Length
        }
    }
}

function Stop-GititProcess {
    param($State)

    if ($null -eq $State -or $null -eq $State.Process) { return }
    Write-GititLogDelta -State $State -FlushAll
    try {
        if (-not $State.Process.HasExited) {
            cmd /c "taskkill /F /T /PID $($State.Process.Id) >nul 2>&1" | Out-Null
            Start-Sleep -Milliseconds 300
        }
    } catch {}
    foreach ($path in @($State.StdoutPath, $State.StderrPath)) {
        try { Remove-Item -LiteralPath $path -Force -ErrorAction SilentlyContinue } catch {}
    }
    try { Remove-Item -LiteralPath $State.LogRoot -Force -Recurse -ErrorAction SilentlyContinue } catch {}
}

function Complete-GititProcess {
    param($State)

    $null = $State.Process.Handle
    $State.Process.WaitForExit()
    Start-Sleep -Milliseconds 200
    Write-GititLogDelta -State $State -FlushAll
    try {
        $State.Process.Refresh()
        $exitCode = $State.Process.ExitCode
    } catch {
        $exitCode = 0
    }
    if ($null -eq $exitCode -or "$exitCode" -eq "") {
        $exitCode = 0
    }
    Stop-GititProcess -State $State
    [PSCustomObject]@{
        Directory = $State.Directory
        ExitCode = $exitCode
        Success = ($exitCode -eq 0)
        TimedOut = $false
    }
}

function Invoke-GititProcess {
    param(
        [string]$Directory,
        [int]$Timeout = 120
    )

    $state = Start-GititProcess -Directory $Directory
    $deadline = (Get-Date).AddSeconds($Timeout)
    while (-not $state.Process.HasExited) {
        Write-GititLogDelta -State $state
        if ((Get-Date) -gt $deadline) {
            Stop-GititProcess -State $state
            return [PSCustomObject]@{
                Directory = $Directory
                ExitCode = $null
                Success = $false
                TimedOut = $true
            }
        }
        Start-Sleep -Milliseconds 250
    }
    return Complete-GititProcess -State $state
}

function Test-GittWorkNeeded {
    param([string]$Directory)

    if (-not (Test-Path $Directory -PathType Container)) { return $false }
    $gitDir = Join-Path $Directory ".git"
    if (-not (Test-Path $gitDir)) { return $true }

    git -C $Directory rev-parse --is-inside-work-tree > $null 2>&1
    if ($LASTEXITCODE -ne 0) { return $true }

    $status = git -C $Directory status --porcelain 2>$null
    return [bool]$status
}

