    Write-Host "===========================================" -ForegroundColor Red
    Write-Host ""
    Write-Host "This will DELETE ALL temp/log/cache files:" -ForegroundColor Yellow
    Write-Host "  - Windows temps and prefetch"
    Write-Host "  - Browser caches"
    Write-Host "  - npm/pip/Maven/Gradle caches"
    Write-Host "  - DirectX/shader caches"
