function ccstatus {
    Write-Host "=== C: Drive Cleanup Status ===" -ForegroundColor Cyan
    $task = Get-ScheduledTask -TaskName "DailyCleanupCDrive" -TaskPath "\Claude Code\" -ErrorAction SilentlyContinue
    if ($task) {
        Write-Host "Status: SCHEDULED" -ForegroundColor Green
        Write-Host "Schedule: Daily at 3:00 AM" -ForegroundColor White
        Write-Host "Last Run: $($task.LastRunTime)" -ForegroundColor White
        Write-Host "Next Run: $($task.NextRunTime)" -ForegroundColor White
    } else {
        Write-Host "Status: NOT SCHEDULED" -ForegroundColor Yellow
        Write-Host "Run 'ccschedule' to enable daily cleanup" -ForegroundColor Yellow
    }

    $logFile = "$env:USERPROFILE\.claude\cleanup-logs\cleanup-today.log"
    if (Test-Path $logFile) {
        Write-Host "`n=== Last Cleanup Log ===" -ForegroundColor Cyan
        Get-Content $logFile | Select-Object -Last 20
    }
}

function ccdisable {
    Write-Host "Disabling daily cleanup task..." -ForegroundColor Yellow
    $task = Get-ScheduledTask -TaskName "DailyCleanupCDrive" -TaskPath "\Claude Code\" -ErrorAction SilentlyContinue
    if ($task) {
        Unregister-ScheduledTask -TaskName "DailyCleanupCDrive" -TaskPath "\Claude Code\" -Confirm:$false
        Write-Host "Daily cleanup DISABLED" -ForegroundColor Green
    } else {
        Write-Host "Daily cleanup is not scheduled" -ForegroundColor Yellow
    }
}

function cclogs {
    $logDir = "$env:USERPROFILE\.claude\cleanup-logs"
    if (Test-Path $logDir) {
        Write-Host "=== C: Drive Cleanup Logs ===" -ForegroundColor Cyan
        Get-ChildItem $logDir -Filter "cleanup-*.log" | Sort-Object LastWriteTime -Descending | ForEach-Object {
            Write-Host "  $($_.Name) - $($_.LastWriteTime)" -ForegroundColor White
        }
        Write-Host "`nUse: Get-Content `"$logDir\cleanup-<date>.log`" | tail -50" -ForegroundColor Yellow
    } else {
        Write-Host "No cleanup logs found" -ForegroundColor Yellow
    }
}

function siz {
    Write-Host "=== KEY DISK SPACE USAGE ===" -ForegroundColor Cyan
    Write-Host ""
    Write-Host "DRIVES:" -ForegroundColor Yellow
    [System.IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -eq 'Fixed' -and $_.IsReady } | Sort-Object Name | ForEach-Object {
        $total = [math]::Round($_.TotalSize / 1GB, 2)
        $free  = [math]::Round($_.TotalFreeSpace / 1GB, 2)
        $used  = [math]::Round(($_.TotalSize - $_.TotalFreeSpace) / 1GB, 2)
        $pct   = if ($total -gt 0) { [math]::Round(($used / $total) * 100, 1) } else { 0 }
        $drive = $_.Name.TrimEnd('\')
        Write-Host ("{0} {1:N2}GB total, {2:N2}GB used, {3:N2}GB free ({4:N1}%)" -f $drive, $total, $used, $free, $pct)
    }
    Write-Host ""
}

