function fixfixfix {
    [CmdletBinding()]
    param()

    function Invoke-FixFixFixNativeRepair {
        param([string]$Label, [string]$FilePath, [string[]]$ArgumentList)
        if (-not (Test-Path -LiteralPath $FilePath -PathType Leaf)) { throw "fixfixfix: required executable not found: $FilePath" }

        $stdoutPath = Join-Path $env:TEMP ('fixfixfix_stdout_' + [guid]::NewGuid().ToString('N') + '.log')
        $stderrPath = Join-Path $env:TEMP ('fixfixfix_stderr_' + [guid]::NewGuid().ToString('N') + '.log')
        $stdoutLineCount = 0
        $stderrLineCount = 0
        $emitNewLines = {
            param([string]$Path, [ref]$LineCount)
            if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return }
            try {
                $lines = @(Get-Content -LiteralPath $Path -ErrorAction Stop)
                for ($index = $LineCount.Value; $index -lt $lines.Count; $index++) { Write-Host $lines[$index] }
                $LineCount.Value = $lines.Count
            } catch {
                # Native tools can briefly lock redirected logs; retry on the next heartbeat.
            }
        }
        try {
            Write-Host "fixfixfix: starting $Label" -ForegroundColor Cyan
            $process = Start-Process -FilePath $FilePath -ArgumentList $ArgumentList -NoNewWindow -PassThru -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath -ErrorAction Stop
            $startedAt = Get-Date
            while (-not $process.HasExited) {
                $elapsed = (Get-Date) - $startedAt
                Write-Progress -Id 741 -Activity 'fixfixfix' -Status ("{0} running for {1:hh\:mm\:ss}" -f $Label, $elapsed) -PercentComplete -1
                & $emitNewLines $stdoutPath ([ref]$stdoutLineCount)
                & $emitNewLines $stderrPath ([ref]$stderrLineCount)
                Start-Sleep -Seconds 1
                $process.Refresh()
            }
            $process.WaitForExit()
            $process.Refresh()
            & $emitNewLines $stdoutPath ([ref]$stdoutLineCount)
            & $emitNewLines $stderrPath ([ref]$stderrLineCount)
            $exitCode = [int]$process.ExitCode
            if ($exitCode -ne 0) { throw "fixfixfix: $Label failed with exit code $exitCode." }
            Write-Host "fixfixfix: $Label completed successfully." -ForegroundColor Green
        } finally {
            Write-Progress -Id 741 -Activity 'fixfixfix' -Completed
            Remove-Item -LiteralPath $stdoutPath, $stderrPath -Force -ErrorAction SilentlyContinue
        }
    }

    Invoke-FixFixFixNativeRepair -Label 'DISM /RestoreHealth' -FilePath (Join-Path $env:SystemRoot 'System32\dism.exe') -ArgumentList @('/Online', '/Cleanup-Image', '/RestoreHealth')
    Invoke-FixFixFixNativeRepair -Label 'sfc.exe /scannow' -FilePath (Join-Path $env:SystemRoot 'System32\sfc.exe') -ArgumentList @('/scannow')
}

