function Enable-WindowsModules { Write-Host "`n------------------------------------------------------------" -ForegroundColor Cyan; Write-Host "  ENABLING WINDOWS DEVELOPMENT FEATURES (FAST MODE)" -ForegroundColor Cyan; Write-Host "------------------------------------------------------------`n" -ForegroundColor Cyan; $features = @("NetFx4-AdvSrvs","Microsoft-Hyper-V-All","Microsoft-Windows-Subsystem-Linux","VirtualMachinePlatform"); $enabled = 0; $skipped = 0; $failed = 0; $needsReboot = $false; foreach ($f in $features) { try { Write-Host "[*] $f..." -ForegroundColor Cyan -NoNewline; $feature = Get-WindowsOptionalFeature -Online -FeatureName $f -ErrorAction SilentlyContinue; if (-not $feature) { Write-Host " [!] NOT FOUND" -ForegroundColor Yellow; $failed++; continue }; if ($feature.State -eq "Enabled") { Write-Host " [~] OK" -ForegroundColor Green; $skipped++; continue }; Write-Host " [+] ENABLING..." -ForegroundColor Yellow; $result = Enable-WindowsOptionalFeature -Online -FeatureName $f -All -NoRestart -ErrorAction Stop; if ($result.RestartNeeded) { $needsReboot = $true }; Write-Host "    [+] DONE" -ForegroundColor Green; $enabled++ } catch { Write-Host " [!] FAILED" -ForegroundColor Red; $failed++ } }; Write-Host "`n------------------------------------------------------------" -ForegroundColor Cyan; Write-Host "  [+] Enabled: $enabled  [~] Skipped: $skipped  [!] Failed: $failed" -ForegroundColor $(if ($failed -gt 0) { "Yellow" } else { "Green" }); if ($needsReboot) { Write-Host "  [!] REBOOT REQUIRED!" -ForegroundColor Yellow } }; Set-Alias -Name gmodule -Value Enable-WindowsModules -Force

