function Get-ClaudeProjectCwd {
    param([string]$JsonlPath)
    if (-not (Test-Path $JsonlPath)) { return $null }
    $line = Get-Content $JsonlPath | Where-Object { $_ -match '"cwd"' } | Select-Object -First 1
    if ($line) { ($line | ConvertFrom-Json).cwd } else { $null }
}

function Resolve-ClaudeSession {
    param([string]$Name)
    $dir = "$env:USERPROFILE\.claude\projects"
    if (-not (Test-Path $dir)) { return $null }
    $jsonl = Get-ChildItem $dir -Recurse -Filter "*.jsonl" | Where-Object { $_.BaseName -eq $Name -or (Get-Content $_.FullName -Raw) -match [regex]::Escape($Name) } | Select-Object -First 1
    if (-not $jsonl) { return $null }
    $cwd = Get-ClaudeProjectCwd $jsonl.FullName
    @{ SessionId = $jsonl.BaseName; Cwd = $cwd }
}

