function tweek {
    $tweekDir = "F:\backup\windowsapps\installed\Fit Launcher\fixers\Tweaking.com"
    $tweekExe = "$tweekDir\Repair_Windows.exe"
    $settingsFile = "$tweekDir\settings.ini"
    $presetFile = "$tweekDir\repairs_presets\tweek-skip-step12.ini"
    if (-not (Test-Path $tweekExe)) { Write-Warning "tweek: Repair_Windows.exe not found at $tweekExe"; return }
    if (Test-Path $settingsFile) {
        $lines = [System.IO.File]::ReadAllLines($settingsFile, [System.Text.Encoding]::Unicode)
        $filtered = @(); $inSec = $false
        foreach ($l in $lines) {
            if ($l -match '^\[Repairs\]') { $inSec = $true; continue }
            if ($inSec -and $l -match '^\[') { $inSec = $false }
            if (-not $inSec) { $filtered += $l }
        }
        $filtered += ''
        $filtered += '[Repairs]'
        $filtered += 'default=True'
        $filtered += 'Repair Icons=False'
        [System.IO.File]::WriteAllLines($settingsFile, $filtered, [System.Text.Encoding]::Unicode)
    }
    Write-Host "Starting Tweaking.com Windows Repair (skipping step 12 - Repair Icons)..."
    & $tweekExe /silent
}

function killgow {
    Write-Host "Killing GoW Ragnarok..." -ForegroundColor Yellow
    cmd /c "taskkill /F /IM GoWR.exe /T" 2>$null
    Stop-Process -Name "GoWR" -Force -ErrorAction SilentlyContinue
    Stop-Process -Name "bridge32" -Force -ErrorAction SilentlyContinue
    Stop-Process -Name "bridge64" -Force -ErrorAction SilentlyContinue
    Stop-Process -Name "crs-handler" -Force -ErrorAction SilentlyContinue
    Stop-Process -Name "crs-uploader" -Force -ErrorAction SilentlyContinue
    Write-Host "Done!" -ForegroundColor Green
}

function killgame {
    param([string]$name)

    if ($name) {
        Write-Host "Killing $name..." -ForegroundColor Yellow
        cmd /c "taskkill /F /IM `"$name.exe`" /T" 2>$null
        Stop-Process -Name $name -Force -ErrorAction SilentlyContinue
    } else {
        Write-Host "Killing all unresponsive games..." -ForegroundColor Yellow
        Get-Process | Where-Object { 
            $_.MainWindowHandle -ne [IntPtr]::Zero -and 
            $_.WorkingSet64 -gt 500MB -and 
            -not $_.Responding 
        } | ForEach-Object {
            Write-Host "  Killing $($_.ProcessName)..." -ForegroundColor Red
            cmd /c "taskkill /F /IM `"$($_.ProcessName).exe`" /T" 2>$null
            Stop-Process -Name $_.ProcessName -Force -ErrorAction SilentlyContinue
        }
    }

    Stop-Process -Name "bridge32" -Force -ErrorAction SilentlyContinue
    Stop-Process -Name "bridge64" -Force -ErrorAction SilentlyContinue
    Stop-Process -Name "crs-handler" -Force -ErrorAction SilentlyContinue
    Stop-Process -Name "crs-uploader" -Force -ErrorAction SilentlyContinue

    Write-Host "Done!" -ForegroundColor Green
}

