function cctools {
    $profile = ". '$env:USERPROFILE\Documents\WindowsPowerShell\Microsoft.PowerShell_profile.ps1'; "

    Write-Host "Starting apps (parallel)..." -ForegroundColor Cyan
    $procs = @('kvrt', 'dism++', 'tweak', 'flyoobe', 'gdbooster', 'adw', 'cleanc', 'getascrm') | ForEach-Object {
        $enc = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($profile + $_))
        Start-Process powershell -ArgumentList "-ExecutionPolicy Bypass -EncodedCommand $enc" -PassThru
    }

    Write-Host "Waiting for all apps to close..." -ForegroundColor Yellow
    $procs | Where-Object { $_ -and !$_.HasExited } | ForEach-Object { $_.WaitForExit() }
    Write-Host "All apps closed." -ForegroundColor Green

    Write-Host "Running dkill..." -ForegroundColor Yellow
    cfun dkill

    Write-Host "Running gccleaner..." -ForegroundColor Yellow
    sj { gccleaner }

    Write-Host "Running classuni..." -ForegroundColor Green
    sj { classuni }

    Write-Host "Running chris (after classuni)..." -ForegroundColor Magenta
    sj { chris }
}

