function ConvertFrom-NvidUriText {
    param([string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) {
        return $Text
    }
    try {
        return [System.Uri]::UnescapeDataString($Text)
    } catch {
        return $Text
    }
}

function ConvertTo-NvidMarketingVersion {
    param([string]$DriverVersion)
    if ([string]::IsNullOrWhiteSpace($DriverVersion)) {
        return $null
    }
    $digits = $DriverVersion -replace '[^\d]', ''
    if ($digits.Length -lt 5) {
        return $null
    }
    $tail = $digits.Substring($digits.Length - 5)
    return ('{0}.{1}' -f $tail.Substring(0, 3), $tail.Substring(3, 2))
}

function Get-NvidUninstallEntry {
    param([string]$NamePattern)
    $entries = Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*', 'HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*' -ErrorAction SilentlyContinue |
        Where-Object { $_.DisplayName -like $NamePattern }
    if (-not $entries) {
        return $null
    }
    return $entries |
        Sort-Object @{ Expression = { try { [Version]($_.DisplayVersion) } catch { [Version]'0.0' } } } -Descending |
        Select-Object -First 1
}

function Test-NvidSmi {
    $command = Get-Command 'nvidia-smi.exe' -ErrorAction SilentlyContinue
    if (-not $command) {
        return [pscustomobject]@{
            Available = $false
            Healthy   = $false
            Path      = $null
            Output    = 'nvidia-smi.exe not found.'
        }
    }

    $output = (& $command.Source 2>&1 | Out-String).Trim()
    $healthy = ($LASTEXITCODE -eq 0 -and $output -notmatch 'Failed to initialize NVML')

    return [pscustomobject]@{
        Available = $true
        Healthy   = $healthy
        Path      = $command.Source
        Output    = $output
    }
}

function Test-NvidNvDebugDump {
    $command = Get-Command 'nvdebugdump.exe' -ErrorAction SilentlyContinue
    if (-not $command) {
        return [pscustomobject]@{
            Available = $false
            Healthy   = $false
            Path      = $null
            Output    = 'nvdebugdump.exe not found.'
        }
    }

    $output = (& $command.Source --list 2>&1 | Out-String).Trim()
    $healthy = ($LASTEXITCODE -eq 0 -and $output -match 'Found\s+\d+\s+NVIDIA devices')

    return [pscustomobject]@{
        Available = $true
        Healthy   = $healthy
        Path      = $command.Source
        Output    = $output
    }
}

function Get-NvidConnectedDisplayState {
    param([string]$InstanceId)

    $rawLines = @(pnputil /enum-devices /connected /class Display 2>&1)
    $currentInstanceId = $null
    $currentStatus = $null
    $matchedStatus = $null

    foreach ($line in $rawLines) {
        if ($line -match '^Instance ID:\s*(?<value>.+)$') {
            if ($currentInstanceId -eq $InstanceId) {
                $matchedStatus = $currentStatus
                break
            }
            $currentInstanceId = $matches['value'].Trim()
            $currentStatus = $null
            continue
        }

        if ($line -match '^Status:\s*(?<value>.+)$') {
            $currentStatus = $matches['value'].Trim()
        }
    }

    if (-not $matchedStatus -and $currentInstanceId -eq $InstanceId) {
        $matchedStatus = $currentStatus
    }

    return [pscustomobject]@{
        InstanceId = $InstanceId
        Status     = $matchedStatus
        Started    = ($matchedStatus -eq 'Started')
        RawOutput  = ($rawLines | Out-String).Trim()
    }
}

