function Get-NvidOfficialAppInfo {
    $pageUrl = 'https://www.nvidia.com/en-us/software/nvidia-app/'
    $releaseUrl = 'https://www.nvidia.com/en-us/software/nvidia-app/release-highlights/'
    $response = Invoke-WebRequest -Uri $pageUrl -UseBasicParsing
    $match = [regex]::Match($response.Content, 'https://us\.download\.nvidia\.com/nvapp/client/(?<version>[\d\.]+)/NVIDIA_app_v(?<fileversion>[\d\.]+)\.exe')
    if (-not $match.Success) {
        throw 'Unable to determine the current NVIDIA App version from the official NVIDIA page.'
    }
    return [pscustomobject]@{
        Version     = $match.Groups['fileversion'].Value
        DownloadURL = $match.Value
        PageURL     = $pageUrl
        ReleaseURL  = $releaseUrl
    }
}

function Get-NvidOfficialPhysXInfo {
    $pageUrl = 'https://www.nvidia.com/en-us/drivers/physx-system-software/'
    $response = Invoke-WebRequest -Uri $pageUrl -UseBasicParsing
    $match = [regex]::Match($response.Content, '/Windows/(?<version>[\d\.]+)/PhysX_(?<fileversion>[\d\.]+)_SystemSoftware\.exe')
    if (-not $match.Success) {
        throw 'Unable to determine the current PhysX version from the official NVIDIA page.'
    }
    $version = $match.Groups['fileversion'].Value
    return [pscustomobject]@{
        Version     = $version
        DownloadURL = ('https://us.download.nvidia.com/Windows/{0}/PhysX_{0}_SystemSoftware.exe' -f $version)
        PageURL     = $pageUrl
    }
}

