        Set-Service -Name 'StorSvc' -StartupType Automatic
    }
    if ($service.Status -ne 'Running') {
        Start-Service -Name 'StorSvc'
    }

    $serviceAfter = Get-Service -Name 'StorSvc'
    return [pscustomobject]@{
        BeforeStatus = $beforeStatus
        BeforeStartType = $beforeStartType
        AfterStatus = $serviceAfter.Status
        AfterStartType = $serviceAfter.StartType
    }
}

