function Script:Write-Banner {
    param(
        [string] $Icon,
        [string] $Label,
        [string] $Subject
    )

    $ESC           = [char]27
    $innerWidth    = 76
    $prefixText    = " $Icon $Label $Subject"
    $paddingNeeded = [Math]::Max(0, $innerWidth - $prefixText.Length - 1)

    Write-Host "$ESC[38;5;201m+$('-' * $innerWidth)+"
    Write-Host "   $ESC[1;38;5;45m$Icon $Label $Subject$(' ' * $paddingNeeded)$ESC[38;5;201m "
    Write-Host "+$('-' * $innerWidth)+$ESC[0m"
    Write-Host ""
}

function Script:Write-ManagerHeader {
    param(
        [string] $Name,
        [string] $AnsiColorCode
    )

    $ESC        = [char]27
    $paddedName = $Name.ToUpper().PadRight(8)

    Write-Host ""
    Write-Host "$ESC[1;4;${AnsiColorCode}m ?? $paddedName ----$ESC[0m"
    Write-Host ("-" * 70) -ForegroundColor DarkGray
}

