function local:Copy-NvidFile {
        param(
            [string]$Source,
            [string]$Target
        )
        if (-not (Test-Path $Source)) {
            throw ("Missing source file: {0}" -f $Source)
        }
        local:Ensure-NvidDirectory (Split-Path -Parent $Target)
        Copy-Item -LiteralPath $Source -Destination $Target -Force
    }

function local:Copy-NvidFolderContent {
        param(
            [string]$SourceDirectory,
            [string]$TargetDirectory
        )
        if (-not (Test-Path $SourceDirectory)) {
            throw ("Missing source directory: {0}" -f $SourceDirectory)
        }
        local:Ensure-NvidDirectory $TargetDirectory
        Get-ChildItem -Path $SourceDirectory -Force | ForEach-Object {
            Copy-Item -LiteralPath $_.FullName -Destination (Join-Path $TargetDirectory $_.Name) -Recurse -Force
        }
    }

