        }
    }

    & $windowsPowerShell -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -File $repairScript 0
    if ($LASTEXITCODE -ne 0) {
        throw "Windows Terminal administrator repair failed with exit code $LASTEXITCODE."
    }

    Get-Process -Name 'elevate-shim' -ErrorAction SilentlyContinue |
        Stop-Process -Force -ErrorAction SilentlyContinue

    $packagedSettings = Get-Content -LiteralPath $packagedSettingsPath -Raw | ConvertFrom-Json
    if ($packagedSettings.profiles.defaults.elevate -ne $false) {
        throw 'The packaged Windows Terminal elevation shim is still enabled.'
    }

    if ($NoLaunch) {
        return [pscustomobject]@{
            Enforcement = 'Enabled'
            PackagedElevation = $false
            Launched = $false
        }
    }

    $launchResult = & $launchScript -StartingDirectory $PWD.Path
    if (-not $launchResult -or $launchResult.Elevated -ne $true) {
        throw 'The administrator Terminal task did not acknowledge an elevated launch.'
    }

    [pscustomobject]@{
        Enforcement = 'Enabled'
        PackagedElevation = $false
        Launched = $true
        Elevated = $true
        Terminal = $launchResult.Terminal
        ProcessId = $launchResult.ProcessId
        RequestId = $launchResult.RequestId
    }
}

function Test-WSLDistroRunning {
