function Repair-StandardWindowsProcessEnvironment {
    $systemRoot = [Environment]::GetEnvironmentVariable('SystemRoot', 'Process')
    if ([string]::IsNullOrWhiteSpace($systemRoot)) {
        $systemRoot = [Environment]::GetEnvironmentVariable('SystemRoot', 'Machine')
    }
    if ([string]::IsNullOrWhiteSpace($systemRoot)) { $systemRoot = 'C:\Windows' }

    $systemDrive = [Environment]::GetEnvironmentVariable('SystemDrive', 'Process')
    if ([string]::IsNullOrWhiteSpace($systemDrive) -and $systemRoot -match '^[A-Za-z]:') {
        $systemDrive = $systemRoot.Substring(0, 2)
    }
    if ([string]::IsNullOrWhiteSpace($systemDrive)) { $systemDrive = 'C:' }

    $defaults = @{
        SystemDrive = $systemDrive
        SystemRoot = $systemRoot
        windir = $systemRoot
        ProgramData = (Join-Path $systemDrive 'ProgramData')
        ALLUSERSPROFILE = (Join-Path $systemDrive 'ProgramData')
        PUBLIC = (Join-Path $systemDrive 'Users\Public')
    }

    foreach ($name in $defaults.Keys) {
        if ([string]::IsNullOrWhiteSpace([Environment]::GetEnvironmentVariable($name, 'Process'))) {
            Set-Item -Path "Env:$name" -Value $defaults[$name]
        }
    }
}

function Resolve-FastTransferLiteralPath {
    param(
        [Parameter(Mandatory = $true)]
        [string]$InputPath
    )

    if ([string]::IsNullOrWhiteSpace($InputPath)) {
        throw 'Source path cannot be empty.'
    }

    $resolved = Resolve-Path -LiteralPath $InputPath -ErrorAction SilentlyContinue
    if ($resolved) {
        return $resolved.ProviderPath
    }

    $candidate = Join-Path (Get-Location).Path $InputPath
    $resolvedCandidate = Resolve-Path -LiteralPath $candidate -ErrorAction SilentlyContinue
    if ($resolvedCandidate) {
        return $resolvedCandidate.ProviderPath
    }

    throw "Path not found: $InputPath"
}

function global:Resolve-WingetExecutable {
    $cached = $script:CachedWingetExecutable
    if ($cached -and (Test-Path -LiteralPath $cached -PathType Leaf) -and ($cached -notlike '*\Microsoft\WindowsApps\winget.exe')) {
        return $cached
    }
    $script:CachedWingetExecutable = $null

    $candidates = New-Object System.Collections.Generic.List[string]
    $appx = Get-AppxPackage -Name Microsoft.DesktopAppInstaller -ErrorAction SilentlyContinue |
        Sort-Object Version -Descending |
        Select-Object -First 1
    if ($appx -and $appx.InstallLocation) {
        $candidates.Add((Join-Path $appx.InstallLocation 'winget.exe'))
    }

    $programFilesWindowsApps = Join-Path $env:ProgramFiles 'WindowsApps'
    if (Test-Path -LiteralPath $programFilesWindowsApps -PathType Container) {
        Get-ChildItem -Path (Join-Path $programFilesWindowsApps 'Microsoft.DesktopAppInstaller_*_x64__8wekyb3d8bbwe\winget.exe') -ErrorAction SilentlyContinue |
            Sort-Object LastWriteTime -Descending |
            ForEach-Object { $candidates.Add($_.FullName) }
    }

    Get-Command winget.exe -CommandType Application -ErrorAction SilentlyContinue |
        ForEach-Object { if ($_.Source) { $candidates.Add([string]$_.Source) } }

    foreach ($candidate in ($candidates | Where-Object { $_ } | Select-Object -Unique)) {
        if (-not (Test-Path -LiteralPath $candidate -PathType Leaf)) { continue }
        if ($candidate -like '*\Microsoft\WindowsApps\winget.exe') { continue }
        $script:CachedWingetExecutable = $candidate
        return $script:CachedWingetExecutable
    }

    throw 'real packaged winget.exe not found. Update/install App Installer from Microsoft Store, or enable the App Installer package.'
}

