            }) -join ' '
            Write-Host ("AHKX4Z_PROGRESS elapsed={0}s {1}" -f $elapsed, $states)
            $lastStatusAt = Get-Date
        }

        if ($remaining.Count -gt 0) {
            Start-Sleep -Seconds 1
        }
    }

