function _fixpip_AddPathPart([string[]]$Parts, [string]$Value) {
        if ([string]::IsNullOrWhiteSpace($Value)) { return $Parts }
        $expanded = [Environment]::ExpandEnvironmentVariables($Value.Trim())
        if (-not (Test-Path -LiteralPath $expanded)) { return $Parts }
        $out = New-Object System.Collections.Generic.List[string]
        foreach ($p in $Parts) {
            if (-not [string]::IsNullOrWhiteSpace($p) -and ($p.TrimEnd('\') -ine $expanded.TrimEnd('\'))) { [void]$out.Add($p) }
        }
        $newOut = New-Object System.Collections.Generic.List[string]
        [void]$newOut.Add($expanded)
        foreach ($p in $out) { [void]$newOut.Add($p) }
        return $newOut.ToArray()
    }

