function _nd([string]$p) {
        if (-not [System.IO.Path]::IsPathRooted($p)) { return }
        try {
            if ([System.IO.File]::Exists($p)) {
                # For VHDX: Dismount first, then takeown/icacls before delete attempt
                if ($p -match '\.vhdx$') {
                    try { Dismount-VHD -Path $p -ErrorAction SilentlyContinue } catch {}
                    cmd /c "takeown /f ""$p"" /a /d Y" 2>$null | Out-Null
                    cmd /c "icacls ""$p"" /grant Administrators:F /q" 2>$null | Out-Null
                    cmd /c "attrib -r -s -h ""$p""" 2>$null | Out-Null
                }
                $ok = $false
                try { [System.IO.File]::Delete($p); $ok = $true } catch {}
                if (-not $ok) {
                    cmd /c "takeown /f ""$p"" /a /d Y" 2>$null | Out-Null
                    cmd /c "icacls ""$p"" /grant Administrators:F /q" 2>$null | Out-Null
                    cmd /c "del /f /q ""$p""" 2>$null | Out-Null
                    if (-not [System.IO.File]::Exists($p)) { $ok = $true }
                }
                if ($ok -or -not [System.IO.File]::Exists($p)) {
                    Write-Host "    [x] $p" -ForegroundColor Green
                } else {
                    Write-Host "    [!] FAILED: $p" -ForegroundColor Red
                }
            } elseif ([System.IO.Directory]::Exists($p)) {
                $ok = $false
                # Attempt 1: takeown + icacls first (avoids permission failures on SYSTEM-owned dirs)
                cmd /c "takeown /f ""$p"" /r /d Y /a" 2>$null | Out-Null
                cmd /c "icacls ""$p"" /grant Administrators:F /t /q" 2>$null | Out-Null
                # Attempt 2: .NET delete
                try { [System.IO.Directory]::Delete($p, $true); $ok = $true } catch {}
                if (-not $ok) {
                    # Attempt 3: rd /s /q
                    cmd /c "rd /s /q ""$p""" 2>$null | Out-Null
                    if (-not [System.IO.Directory]::Exists($p)) { $ok = $true }
                }
                if (-not $ok) {
                    # Attempt 4: RENAME away (works even with locked files inside - path vanishes)
                    $renamed = $p + '-purge-' + (Get-Random)
                    try {
                        [System.IO.Directory]::Move($p, $renamed)
                        try { [System.IO.Directory]::Delete($renamed, $true) } catch {}
                        $ok = $true
                    } catch {}
                }
                if (-not $ok) {
                    # Attempt 5: robocopy mirror with empty dir (zeroes content even if dir stays)
                    $blank = [System.IO.Path]::Combine('C:\Windows\Temp', [System.Guid]::NewGuid().ToString())
                    [System.IO.Directory]::CreateDirectory($blank) | Out-Null
                    cmd /c "robocopy ""$blank"" ""$p"" /MIR /NFL /NDL /NJH /NJS /NC /NS" 2>$null | Out-Null
                    [System.IO.Directory]::Delete($blank, $true) | Out-Null
                    try { [System.IO.Directory]::Delete($p) } catch {}
                }
                if (-not [System.IO.Directory]::Exists($p)) {
                    Write-Host "    [x] $p" -ForegroundColor Green
                } else {
                    Write-Host "    [x] $p (emptied)" -ForegroundColor DarkYellow
                }
            }
        } catch {
            Write-Host "    [!] $p  -->  $($_.Exception.Message)" -ForegroundColor DarkGray
        }
    }

