function aadw {
    $adwExe = "F:\backup\windowsapps\installed\adw\AdwCleaner.exe"
    $logBase = "$env:HOMEDRIVE\AdwCleaner\Logs"
    $totalThreats = 0
    $totalCleaned = 0
    $spinner = @('|','/','-','\')

    Write-Host ""
    Write-Host "================================================================" -ForegroundColor Magenta
    Write-Host "  AADW | ADVANCED ADWCLEANER | MAXIMUM STRENGTH MALWARE SWEEP  " -ForegroundColor Magenta
    Write-Host "================================================================" -ForegroundColor Magenta

    if (-not (Test-Path $adwExe)) {
        Write-Host "  [ERROR] AdwCleaner not found: $adwExe" -ForegroundColor Red
        return
    }
    Write-Host "  [OK]  AdwCleaner: $adwExe" -ForegroundColor Green

    $existing = Get-Process -Name "AdwCleaner" -ErrorAction SilentlyContinue
    if ($existing) {
        Write-Host "  [PRE] Stopping existing AdwCleaner process(es)..." -ForegroundColor Yellow
        $existing | Stop-Process -Force
        Start-Sleep -Seconds 2
    }

    $preBaseline = if (Test-Path $logBase) { (Get-ChildItem $logBase -Filter "*.txt").Count } else { 0 }
    Write-Host "  [PRE] Log baseline: $preBaseline file(s) in $logBase" -ForegroundColor DarkGray
    Write-Host "  Starting 4-to-6 phase scan sequence..." -ForegroundColor Cyan

    $runPhase = {
        param($phaseName, $flags, $phaseColor, $logBase, $adwExe, $spinner)
        Write-Host ""
        Write-Host "  ----------------------------------------------------------------" -ForegroundColor DarkGray
        Write-Host "  [PHASE] $phaseName" -ForegroundColor $phaseColor
        Write-Host "  [FLAGS] $flags" -ForegroundColor DarkGray
        Write-Host "  ----------------------------------------------------------------" -ForegroundColor DarkGray

        $preNames = if (Test-Path $logBase) { @(Get-ChildItem $logBase -Filter "*.txt" | Select-Object -ExpandProperty Name) } else { @() }
        $startTime = Get-Date
        $proc = Start-Process -FilePath $adwExe -ArgumentList $flags -PassThru -WindowStyle Minimized
        Write-Host "  [RUN]  PID $($proc.Id) started at $($startTime.ToString('HH:mm:ss'))" -ForegroundColor DarkGray

        $si = 0
        while (-not $proc.HasExited) {
            Start-Sleep -Milliseconds 500
            $elapsed = [int]((Get-Date) - $startTime).TotalSeconds
            $sc = $spinner[$si % 4]; $si++
            Write-Host "`r  $sc AdwCleaner Running | $($elapsed)s elapsed   " -NoNewline -ForegroundColor Yellow
            if ($elapsed -gt 300) {
                Write-Host ""
                Write-Host "  [WARN] Phase timed out after 300s" -ForegroundColor Red
                break
            }
        }
        $elapsed = [int]((Get-Date) - $startTime).TotalSeconds
        Write-Host "`r  + Done in $($elapsed)s. Waiting for log file (5s)...              " -NoNewline -ForegroundColor Green
        Start-Sleep -Seconds 5
        Write-Host ""

        $null = $proc.WaitForExit(10000)

        $newLog = $null; $logFound = $false
        if (Test-Path $logBase) {
            $allLogs = Get-ChildItem $logBase -Filter "*.txt" | Sort-Object LastWriteTime -Descending
            foreach ($lg in $allLogs) {
                if ($preNames -notcontains $lg.Name) { $newLog = $lg; $logFound = $true; break }
            }
        }

        $threats = 0; $cleaned = 0
        if ($logFound -and $newLog -and (Test-Path -LiteralPath $newLog.FullName)) {
            Write-Host "  [LOG]  $($newLog.Name)" -ForegroundColor DarkGray
            Write-Host ("  " + ("=" * 68)) -ForegroundColor DarkGray
            Get-Content -LiteralPath $newLog.FullName | ForEach-Object {
                $line = $_
                if ($line -match '(?:Threat|Malware(?!bytes)|Adware|PUP\b|Toolbar|Hijack|BHO|Rogue|Spyware|Ransomware|Trojan|Worm|Rootkit)') {
                    Write-Host "    $line" -ForegroundColor Red; $threats++
                } elseif ($line -match '(Deleted|Quarantine|Removed|Cleaned|Fixed|Eliminated)') {
                    Write-Host "    $line" -ForegroundColor Green; $cleaned++
                } elseif ($line -match '(Warning|Skipped|Error|Failed|Could not)') {
                    Write-Host "    $line" -ForegroundColor Yellow
                } elseif ($line -match '^\*\*\*') {
                    Write-Host "    $line" -ForegroundColor Magenta
                } elseif ($line -match '^\[') {
                    Write-Host "    $line" -ForegroundColor Cyan
                } else {
                    Write-Host "    $line" -ForegroundColor Gray
                }
            }
            Write-Host ("  " + ("=" * 68)) -ForegroundColor DarkGray
            Write-Host "  [DONE] Threats flagged: $threats | Items cleaned: $cleaned" -ForegroundColor $phaseColor
        } else {
            Write-Host "  [WARN] No new log detected for this phase." -ForegroundColor Yellow
        }

        return @{ Threats = $threats; Cleaned = $cleaned }
    }

    $r1 = & $runPhase "PHASE 1 - INITIAL THREAT ASSESSMENT (scan only)" "/eula /scan" "Cyan" $logBase $adwExe $spinner
    $totalThreats += if ($r1) { $r1.Threats } else { 0 }

    $r2 = & $runPhase "PHASE 2 - STANDARD CLEAN (adware, PUPs, hijackers)" "/eula /clean /noreboot" "Yellow" $logBase $adwExe $spinner
    $totalCleaned += if ($r2) { $r2.Cleaned } else { 0 }

    $r3 = & $runPhase "PHASE 3 - PREINSTALLED PUP CLEAN (bundled software)" "/eula /clean /noreboot /preinstalled" "Yellow" $logBase $adwExe $spinner
    $totalCleaned += if ($r3) { $r3.Cleaned } else { 0 }

    $r4 = & $runPhase "PHASE 4 - VERIFICATION SCAN (confirm clean state)" "/eula /scan" "Green" $logBase $adwExe $spinner
    $finalThreats = if ($r4) { $r4.Threats } else { 0 }

    if ($finalThreats -gt 0) {
        Write-Host ""
        Write-Host "  [ALERT] Verification found $finalThreats remaining threat(s). Escalating to emergency pass..." -ForegroundColor Red
        $r5 = & $runPhase "PHASE 5 - EMERGENCY CLEAN (third pass, max coverage)" "/eula /clean /noreboot /preinstalled" "Red" $logBase $adwExe $spinner
        $totalCleaned += if ($r5) { $r5.Cleaned } else { 0 }
        $r6 = & $runPhase "PHASE 6 - FINAL VERIFICATION (post-emergency confirm)" "/eula /scan" "Green" $logBase $adwExe $spinner
        $finalThreats = if ($r6) { $r6.Threats } else { 0 }
    }

    Write-Host ""
    Write-Host "================================================================" -ForegroundColor Magenta
    Write-Host "  AADW COMPLETE - SUMMARY" -ForegroundColor Magenta
    Write-Host "================================================================" -ForegroundColor Magenta
    Write-Host "  Total Threats Detected : $totalThreats" -ForegroundColor $(if ($totalThreats -gt 0) { 'Red' } else { 'Green' })
    Write-Host "  Total Items Cleaned    : $totalCleaned" -ForegroundColor Green
    if ($finalThreats -eq 0) {
        Write-Host "  Final Status           : CLEAN - System is threat-free" -ForegroundColor Green
    } else {
        Write-Host "  Final Status           : $finalThreats threat(s) still remain - manual review required" -ForegroundColor Red
        Write-Host "  ACTION: Reboot then run aadw again, or inspect: $logBase" -ForegroundColor Yellow
    }
    Write-Host "  Logs directory         : $logBase" -ForegroundColor DarkGray
    Write-Host "================================================================" -ForegroundColor Magenta
}

function abc {    @('USRFindHandle64.sys','USRobotics') | ForEach-Object { Get-WmiObject Win32_SystemDriver | Where-Object { $_.PathName -like "*$_*" -or $_.Name -like "*$_*" } | ForEach-Object { sc.exe stop $_.Name 2>$null; sc.exe delete $_.Name 2>$null } }; Get-ChildItem 'C:\Windows\System32\drivers\' -Filter '*USR*' -ErrorAction SilentlyContinue | ForEach-Object { takeown /f $_.FullName /a 2>$null; icacls $_.FullName /grant Administrators:F 2>$null; Remove-Item $_.FullName -Force -ErrorAction SilentlyContinue }; Get-ChildItem 'C:\Windows\System32\drivers\' -Filter '*usrfind*' -ErrorAction SilentlyContinue | ForEach-Object { takeown /f $_.FullName /a 2>$null; icacls $_.FullName /grant Administrators:F 2>$null; Remove-Item $_.FullName -Force -ErrorAction SilentlyContinue }; Get-ChildItem 'HKLM:\SYSTEM\CurrentControlSet\Services' -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'USR|USRobotics|USRFindHandle' } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue; Get-ChildItem 'HKLM:\SYSTEM\ControlSet001\Services' -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'USR|USRobotics|USRFindHandle' } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue; Get-ChildItem 'HKLM:\SYSTEM\ControlSet002\Services' -ErrorAction SilentlyContinue | Where-Object { $_.Name -match 'USR|USRobotics|USRFindHandle' } | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue; Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall' -ErrorAction SilentlyContinue | Where-Object { (Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).DisplayName -match 'USR|USRobotics' } | ForEach-Object { $up=(Get-ItemProperty $_.PSPath -ErrorAction SilentlyContinue).UninstallString; if($up){ Start-Process cmd -ArgumentList "/c $up /S /SILENT /VERYSILENT /quiet" -Wait -ErrorAction SilentlyContinue } }; pnputil /enum-drivers 2>$null | Select-String -Pattern 'USR|USRobotics|USRFindHandle' -Context 2 | ForEach-Object { $inf=($_.Context.PreContext + $_.Context.PostContext + $_.Line) -join "`n" | Select-String 'oem\d+\.inf' | ForEach-Object { $_.Matches[0].Value }; if($inf){ pnputil /delete-driver $inf /uninstall /force 2>$null } }; sfc /scannow; DISM /Online /Cleanup-Image /RestoreHealth; Write-Host "USRobotics/USRFindHandle64 fully eradicated. Reboot now." -ForegroundColor Green    }

function Add-AfitgirlChildProcessIds([int] $ParentId) {
                    foreach ($child in @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { [int]$_.ParentProcessId -eq $ParentId })) {
                        if ($child.ProcessId -ne $PID -and -not $killIds.Contains([int]$child.ProcessId)) {
                            [void]$killIds.Add([int]$child.ProcessId)
                            Add-AfitgirlChildProcessIds -ParentId ([int]$child.ProcessId)
                        }
                    }
                }

function Add-FixDocker2PathPart {
        param([string]$Scope, [string]$Part)
        $current = [Environment]::GetEnvironmentVariable('Path', $Scope)
        $parts = @($current -split ';' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
        $exists = @($parts | Where-Object { $_.TrimEnd('\') -ieq $Part.TrimEnd('\') }).Count -gt 0
        if (-not $exists) {
            $newPath = if ([string]::IsNullOrWhiteSpace($current)) { $Part } else { "$Part;$current" }
            [Environment]::SetEnvironmentVariable('Path', $newPath, $Scope)
            return $true
        }
        return $false
    }

function Add-HermesDockerArtifactCandidate {
        param([string]$Path)
        if ([string]::IsNullOrWhiteSpace($Path)) { return }
        if ($sw.Elapsed.TotalSeconds -ge $MaxSeconds) { return }
        try {
            if (-not (Test-Path -LiteralPath $Path)) { return }
            $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
            if (-not (Test-HermesDockerGeneratedArtifactName -Name $item.Name)) { return }
            $resolved = $item.FullName
            if (-not $seen.Add($resolved)) { return }
            if ($PSCmdlet.ShouldProcess($resolved, 'delete generated Docker Commander/mmenu artifact')) {
                Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction SilentlyContinue
            }
            if (-not (Test-Path -LiteralPath $resolved)) { [void]$removed.Add($resolved) }
        } catch { }
    }

function Add-HermesDockerCommanderText([string]$Text,[string]$CarryName) {
        if ([string]::IsNullOrEmpty($Text)) { return }
        $combined = [string](Get-Variable -Name $CarryName -Scope Script -ValueOnly -ErrorAction SilentlyContinue) + $Text
        $parts = [regex]::Split($combined, "`r`n|`n|`r")
        if ($combined -match "(`r`n|`n|`r)$") {
            for($i=0; $i -lt $parts.Count; $i++){ if($parts[$i].Length -gt 0){ Update-HermesDockerCommanderProgressLine $parts[$i] } }
            Set-Variable -Name $CarryName -Scope Script -Value ''
        } else {
            for($i=0; $i -lt ($parts.Count - 1); $i++){ if($parts[$i].Length -gt 0){ Update-HermesDockerCommanderProgressLine $parts[$i] } }
            Set-Variable -Name $CarryName -Scope Script -Value ([string]$parts[$parts.Count - 1])
        }
    }

function Add-HermesDockerPipelineText([string]$Text, [ref]$Carry) {
        if ([string]::IsNullOrEmpty($Text)) { return }
        $combined = $Carry.Value + $Text
        $parts = [regex]::Split($combined, "`r`n|`n|`r")
        if ($combined -match "(`r`n|`n|`r)$") {
            for($i=0; $i -lt $parts.Count; $i++){
                if($parts[$i].Length -gt 0){
                    $script:HermesPipelineLastLine = [string]$parts[$i]
                    Write-Host ([string]$parts[$i])
                }
            }
            $Carry.Value = ''
        } else {
            for($i=0; $i -lt ($parts.Count - 1); $i++){
                if($parts[$i].Length -gt 0){
                    $script:HermesPipelineLastLine = [string]$parts[$i]
                    Write-Host ([string]$parts[$i])
                }
            }
            $Carry.Value = [string]$parts[$parts.Count - 1]
        }
    }

