        $dockerArgs = @('desktop','start','--detach'); docker @dockerArgs
        Wait-DockerCommanderVisibleSeconds -Seconds 10 -Activity 'dfixer desktop start settle'
        $dockerArgs = @('context','use','default'); docker @dockerArgs
        $dockerArgs = @('ps'); docker @dockerArgs
    }

