        Invoke-HermesDockerAllFastLine 'drmariadb' 'running MariaDB container through hardened docker wrapper'
        $dockerArgs = @('run','-v','C:/:/c/','-it','-d','--name','mariadb','-e','MYSQL_ROOT_PASSWORD=123456','-p','3307:3307','mariadb:latest'); docker @dockerArgs
        Wait-DockerCommanderVisibleSeconds -Seconds 30 -Activity 'mariadb initialize'
        $dockerArgs = @('exec','-it','mariadb','mariadb','-u','root','-p'); docker @dockerArgs
