        param()
        Invoke-HermesDockerAllFastLine 'getjenkins' 'running Jenkins container through hardened docker wrapper'
        $dockerArgs = @('run','-d','-p','8080:8080','-p','50000:50000','-v','jenkins_home:/var/jenkins_home','--name','jenkins','jenkins/jenkins:lts'); docker @dockerArgs
        Wait-DockerCommanderVisibleSeconds -Seconds 30 -Activity 'jenkins initialize'
