function global:claw {
        $clawCommand = Get-Command claw -CommandType Application -ErrorAction SilentlyContinue
        if (-not $clawCommand) { $clawCommand = Get-Command claw.cmd -CommandType Application -ErrorAction SilentlyContinue }
        if (-not $clawCommand) { throw 'claw executable was not found on PATH.' }
        $clawBin = if ($clawCommand.Source) { $clawCommand.Source } else { $clawCommand.Path }
        $env:HOME = $env:USERPROFILE
        # Enable VT processing for proper ANSI rendering in PS v5 conhost
        $null = Add-Type -MemberDefinition @'
[DllImport("kernel32.dll", SetLastError = true)]
public static extern IntPtr GetStdHandle(int nStdHandle);
[DllImport("kernel32.dll", SetLastError = true)]
public static extern bool GetConsoleMode(IntPtr hConsoleHandle, out uint lpMode);
[DllImport("kernel32.dll", SetLastError = true)]
public static extern bool SetConsoleMode(IntPtr hConsoleHandle, uint dwMode);
'@ -Name 'VT' -Namespace 'Win32' -PassThru -ErrorAction SilentlyContinue
        try {
            $h = [Win32.VT]::GetStdHandle(-11)
            $m = 0; $null = [Win32.VT]::GetConsoleMode($h, [ref]$m)
            $null = [Win32.VT]::SetConsoleMode($h, ($m -bor 4))
        } catch {}
        [Console]::OutputEncoding = [System.Text.Encoding]::UTF8
        $env:TERM = 'xterm-256color'
        & $clawBin @args
    }

