function global:Clear-HermesDockerGeneratedArtifacts {
    [CmdletBinding(SupportsShouldProcess=$true)]
    param(
        [switch]$Deep,
        [int]$MaxSeconds = 8,
        [switch]$Quiet
    )
    $sw = [Diagnostics.Stopwatch]::StartNew()
    $removed = New-Object System.Collections.Generic.List[string]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([StringComparer]::OrdinalIgnoreCase)
    $exactNames = @(
        'hermes-docker-commander',
        'hermes-docker-realtime-helper',
        'hermes-docker-mmenu-contexts',
        'mmenu-progress',
        'mmmenu-progress'
    )
    $legacyMmenuLayerPrefix = '.' + 'mmenu-layerctx-'
    $prefixes = @(
        $legacyMmenuLayerPrefix,
        'docker-public-mmenu-preflight-',
        'docker-public-mmenu-tarproof-',
        'mmenu-tarproof-',
        'docker-commander-retry-',
        'hermes-docker-full-context-'
    )
    function Test-HermesDockerGeneratedArtifactName {
        param([string]$Name)
        if ([string]::IsNullOrWhiteSpace($Name)) { return $false }
        if ($exactNames -contains $Name) { return $true }
        foreach ($prefix in $prefixes) {
            if ($Name.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase)) { return $true }
        }
        return $false
    }
    function Add-HermesDockerArtifactCandidate {
        param([string]$Path)
        if ([string]::IsNullOrWhiteSpace($Path)) { return }
        if ($sw.Elapsed.TotalSeconds -ge $MaxSeconds) { return }
        try {
            if (-not (Test-Path -LiteralPath $Path)) { return }
            $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
            if (-not (Test-HermesDockerGeneratedArtifactName -Name $item.Name)) { return }
            $resolved = $item.FullName
            if (-not $seen.Add($resolved)) { return }
            if ($PSCmdlet.ShouldProcess($resolved, 'delete generated Docker Commander/mmenu artifact')) {
                Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction SilentlyContinue
            }
            if (-not (Test-Path -LiteralPath $resolved)) { [void]$removed.Add($resolved) }
        } catch { }
    }

    $roots = New-Object System.Collections.Generic.List[string]
    foreach ($root in @('C:\Temp', $env:TEMP, 'F:\Downloads\.fitgirl_tmp')) {
        if ($root -and -not $roots.Contains($root)) { [void]$roots.Add($root) }
    }
    foreach ($root in $roots) {
        if ($sw.Elapsed.TotalSeconds -ge $MaxSeconds) { break }
        if (-not (Test-Path -LiteralPath $root)) { continue }
        foreach ($name in $exactNames) { Add-HermesDockerArtifactCandidate -Path (Join-Path $root $name) }
        try {
            Get-ChildItem -LiteralPath $root -Force -ErrorAction SilentlyContinue | Where-Object {
                Test-HermesDockerGeneratedArtifactName -Name $_.Name
            } | ForEach-Object {
                if ($sw.Elapsed.TotalSeconds -lt $MaxSeconds) { Add-HermesDockerArtifactCandidate -Path $_.FullName }
            }
        } catch { }
    }

    $fixedRoots = @()
    try {
        $fixedRoots = @([System.IO.DriveInfo]::GetDrives() | Where-Object { $_.DriveType -eq 'Fixed' -and $_.IsReady } | ForEach-Object { $_.RootDirectory.FullName })
    } catch { $fixedRoots = @('C:\') }
    foreach ($driveRoot in $fixedRoots) {
        if ($sw.Elapsed.TotalSeconds -ge $MaxSeconds) { break }
        foreach ($name in $prefixes) {
            if ($sw.Elapsed.TotalSeconds -ge $MaxSeconds) { break }
            try {
                Get-ChildItem -LiteralPath $driveRoot -Force -ErrorAction SilentlyContinue | Where-Object {
                    $_.Name.StartsWith($name, [StringComparison]::OrdinalIgnoreCase)
                } | ForEach-Object {
                    if ($sw.Elapsed.TotalSeconds -lt $MaxSeconds) { Add-HermesDockerArtifactCandidate -Path $_.FullName }
                }
            } catch { }
        }
    }

    if ($Deep -and $MaxSeconds -gt 0) {
        foreach ($driveRoot in $fixedRoots) {
            if ($sw.Elapsed.TotalSeconds -ge $MaxSeconds) { break }
            $queue = New-Object System.Collections.Queue
            try { $queue.Enqueue($driveRoot) } catch { }
            while ($queue.Count -gt 0 -and $sw.Elapsed.TotalSeconds -lt $MaxSeconds) {
                $scanRoot = $queue.Dequeue()
                try {
                    foreach ($child in @(Get-ChildItem -LiteralPath $scanRoot -Force -ErrorAction SilentlyContinue)) {
                        if ($sw.Elapsed.TotalSeconds -ge $MaxSeconds) { break }
                        if (Test-HermesDockerGeneratedArtifactName -Name $child.Name) {
                            Add-HermesDockerArtifactCandidate -Path $child.FullName
                            continue
                        }
                        if ($child.PSIsContainer) {
                            try { $queue.Enqueue($child.FullName) } catch { }
                        }
                    }
                } catch { }
            }
        }
    }

    if (-not $Quiet) {
        Write-Host ("[docker-artifacts] removed={0} elapsed={1:N2}s" -f $removed.Count, $sw.Elapsed.TotalSeconds) -ForegroundColor DarkCyan
        $removed | Select-Object -First 20 | ForEach-Object { Write-Host ("  removed {0}" -f $_) -ForegroundColor DarkGray }
    }
    return [pscustomobject]@{
        RemovedCount = $removed.Count
        RemovedPaths = @($removed)
        ElapsedSeconds = [Math]::Round($sw.Elapsed.TotalSeconds, 2)
    }
}

function Complete-HermesDockerCommanderRead($Stream,$AsyncResult,[byte[]]$Buffer,[string]$CarryName,[ref]$Done) {
        if ($null -eq $AsyncResult) { $Done.Value = $true; return $null }
        if (-not $AsyncResult.IsCompleted) { return $AsyncResult }
        try {
            $count = $Stream.EndRead($AsyncResult)
            if ($count -le 0) { $Done.Value = $true; return $null }
            $text = [Text.Encoding]::UTF8.GetString($Buffer,0,$count)
            Add-HermesDockerCommanderText -Text $text -CarryName $CarryName
            return $Stream.BeginRead($Buffer,0,$Buffer.Length,$null,$null)
        } catch {
            $Done.Value = $true
            return $null
        }
    }

function global:Convert-CcRestorePointTime {
    param([Parameter(Mandatory=$true)]$CreationTime)
    try { return ([System.Management.ManagementDateTimeConverter]::ToDateTime([string]$CreationTime)) } catch { return $CreationTime }
