function global:Convert-HermesDockerCommanderBytes {
    param([Parameter(Mandatory=$true)][double]$Value,[Parameter(Mandatory=$true)][string]$Unit)
    switch -Regex ($Unit.ToUpperInvariant()) {
        '^B$' { return [int64]$Value }
        '^KB$' { return [int64]($Value * 1000) }
        '^KIB$' { return [int64]($Value * 1KB) }
        '^MB$' { return [int64]($Value * 1000 * 1000) }
        '^MIB$' { return [int64]($Value * 1MB) }
        '^GB$' { return [int64]($Value * 1000 * 1000 * 1000) }
        '^GIB$' { return [int64]($Value * 1GB) }
        '^TB$' { return [int64]($Value * 1000 * 1000 * 1000 * 1000) }
        '^TIB$' { return [int64]($Value * 1TB) }
        default { return [int64]$Value }
    }
}

function Convert-MmenuDockerSizeToBytes {
        param([string]$Text)
        if ([string]::IsNullOrWhiteSpace($Text)) { return $null }
        if ($Text -match '^\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|B)\s*$') {
            $n=[double]$matches[1]; $u=$matches[2].ToUpperInvariant()
            switch -Regex ($u) {
                '^B$' { return [int64]$n }
                '^KB$' { return [int64]($n*1000) }
                '^KIB$' { return [int64]($n*1KB) }
                '^MB$' { return [int64]($n*1000*1000) }
                '^MIB$' { return [int64]($n*1MB) }
                '^GB$' { return [int64]($n*1000*1000*1000) }
                '^GIB$' { return [int64]($n*1GB) }
                '^TB$' { return [int64]($n*1000*1000*1000*1000) }
                '^TIB$' { return [int64]($n*1TB) }
            }
        }
        return $null
    }

function Convert-MmmenuDockerSizeToBytes {
        param([string]$Text)
        if ([string]::IsNullOrWhiteSpace($Text)) { return $null }
        if ($Text -match '^\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|B)\s*$') {
            $n=[double]$matches[1]; $u=$matches[2].ToUpperInvariant()
            switch -Regex ($u) {
                '^B$' { return [int64]$n }
                '^KB$' { return [int64]($n*1000) }
                '^KIB$' { return [int64]($n*1KB) }
                '^MB$' { return [int64]($n*1000*1000) }
                '^MIB$' { return [int64]($n*1MB) }
                '^GB$' { return [int64]($n*1000*1000*1000) }
                '^GIB$' { return [int64]($n*1GB) }
                '^TB$' { return [int64]($n*1000*1000*1000*1000) }
                '^TIB$' { return [int64]($n*1TB) }
            }
        }
        return $null
    }

function ConvertTo-AfitgirlCommandLineArgument {
    param([AllowNull()][string] $Value)
    if ($null -eq $Value) { return '""' }
    if ($Value -notmatch '[\s\"]') { return $Value }
    $escaped = $Value -replace '\\(?=\")','\\' -replace '"','\"'
    return '"' + $escaped + '"'
}

function ConvertTo-HermesDockerCommanderArrayLiteral([string[]]$Values) {
        if (-not $Values -or $Values.Count -eq 0) { return '@()' }
        return '@(' + ((@($Values) | ForEach-Object { ConvertTo-HermesDockerCommanderLiteral ([string]$_) }) -join ',') + ')'
    }

function ConvertTo-HermesDockerCommanderLiteral([string]$Value) {
        return "'" + ([string]$Value).Replace("'", "''") + "'"
    }

function ConvertTo-HermesDockerProcessArgument([string]$Value) {
        if ($null -eq $Value) { return '""' }
        $text = [string]$Value
        if ($text.Length -eq 0) { return '""' }
        if ($text -notmatch '[\s"&|<>]') { return $text }
        return '"' + ($text -replace '"','\"') + '"'
    }

