function Copy-DKillFastIfExists {
        param([string]$Source,[string]$DestRoot)
        if([string]::IsNullOrWhiteSpace($Source) -or -not (Test-Path -LiteralPath $Source)){ return }
        $name = (($Source -replace '^[A-Za-z]:\\','') -replace '[\\/:*?"<>|]','_')
        $dest = Join-Path $DestRoot $name
        try { Copy-Item -LiteralPath $Source -Destination $dest -Recurse -Force -ErrorAction SilentlyContinue } catch { }
    }

function Copy-DKillFastSettingsFile {
        param([string]$Source,[string]$SnapshotRoot)
        if([string]::IsNullOrWhiteSpace($Source) -or -not (Test-Path -LiteralPath $Source -PathType Leaf)){ return }
        try {
            $resolved = (Resolve-Path -LiteralPath $Source -ErrorAction Stop).ProviderPath
            if($resolved -notmatch '^(?i)C:\\'){ return }
            $relative = $resolved.Substring(3)
            $dest = Join-Path $SnapshotRoot $relative
            $parent = Split-Path -Parent $dest
            New-Item -ItemType Directory -Force -Path $parent | Out-Null
            Copy-Item -LiteralPath $resolved -Destination $dest -Force -ErrorAction SilentlyContinue
        } catch { }
    }

function Copy-DKillFastSettingsSnapshot {
        param([string]$SnapshotRoot)
        foreach($dir in @((Join-Path $env:USERPROFILE '.docker'),(Join-Path $env:APPDATA 'Docker'),(Join-Path $env:APPDATA 'Docker Desktop'))){
            if([string]::IsNullOrWhiteSpace($dir) -or -not (Test-Path -LiteralPath $dir)){ continue }
            try {
                Get-ChildItem -LiteralPath $dir -File -Force -ErrorAction SilentlyContinue |
                    Where-Object { $_.Extension -ieq '.json' -or $_.Name -match '^(config|daemon|windows-daemon|settings-store|settings|features|login-info)(\..*)?$' } |
                    ForEach-Object { Copy-DKillFastSettingsFile -Source $_.FullName -SnapshotRoot $SnapshotRoot }
            } catch { }
        }
    }

function Copy-RedockerSafeDir {
        param([string]$Source,[string]$Dest)
        if([string]::IsNullOrWhiteSpace($Source) -or -not (Test-Path -LiteralPath $Source)){ return $false }
        try {
            New-Item -ItemType Directory -Force -Path $Dest | Out-Null
            $sourceItem = Get-Item -LiteralPath $Source -Force -ErrorAction Stop
            if(-not $sourceItem.PSIsContainer){
                Copy-Item -LiteralPath $Source -Destination $Dest -Force -ErrorAction Stop
                return $true
            }
            $copied = 0
            Get-ChildItem -LiteralPath $Source -Force -Recurse -ErrorAction SilentlyContinue | ForEach-Object {
                $rel = $_.FullName.Substring($Source.Length).TrimStart('\')
                if([string]::IsNullOrWhiteSpace($rel)){ return }
                $target = Join-Path $Dest $rel
                try {
                    if($_.PSIsContainer){
                        New-Item -ItemType Directory -Force -Path $target | Out-Null
                    } else {
                        $sourceFile = $_.FullName
                        New-Item -ItemType Directory -Force -Path (Split-Path -Parent $target) | Out-Null
                        Copy-Item -LiteralPath $sourceFile -Destination $target -Force -ErrorAction Stop
                        $script:RedockerSafeCopiedFiles++
                        $copied++
                    }
                } catch {
                    Write-RedockerSafeLine ("snapshot skipped locked file {0}" -f $sourceFile) DarkYellow
                }
            }
            return ($copied -gt 0 -or (Test-Path -LiteralPath $Dest))
        } catch { Write-RedockerSafeLine ("snapshot copy failed {0}: {1}" -f $Source,$_.Exception.Message) Yellow; return $false }
    }

