function global:Ensure-HermesDockerCommanderReady {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][string]$DockerExe,[string]$Name='docker',[int]$ReadySeconds=180)
    function Test-HermesDockerCommanderReadyNow([string]$Exe,[int]$Milliseconds) {
        $p = $null
        try {
            $psi = New-Object Diagnostics.ProcessStartInfo
            $psi.FileName = $Exe
            $psi.Arguments = 'version --format "{{.Server.Version}}"'
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $psi.RedirectStandardOutput = $true
            $psi.RedirectStandardError = $true
            $p = New-Object Diagnostics.Process
            $p.StartInfo = $psi
            [void]$p.Start()
            if (-not $p.WaitForExit($Milliseconds)) { try { $p.Kill() } catch {}; return $false }
            $out = ''
            try { $out = $p.StandardOutput.ReadToEnd().Trim() } catch { $out = '' }
            return ($p.ExitCode -eq 0 -and -not [string]::IsNullOrWhiteSpace($out))
        } catch {
            return $false
        } finally {
            if ($p) { try { $p.Dispose() } catch {} }
        }
    }
    if (Test-HermesDockerCommanderReadyNow $DockerExe 1800) { return $true }
    $started = Get-Date
    Invoke-HermesDockerAllFastLine $Name 'Docker daemon is not ready; starting Docker Desktop with docker desktop start --detach'
    try {
        $p = Start-Process -FilePath $DockerExe -ArgumentList @('desktop','start','--detach') -PassThru -WindowStyle Hidden
        [void]$p.WaitForExit(350)
    } catch {
        Invoke-HermesDockerAllFastLine $Name ("Docker Desktop start request failed but retry gate will continue: {0}" -f $_.Exception.Message)
    }
    $deadline = (Get-Date).AddSeconds([Math]::Max(5,$ReadySeconds))
    while ((Get-Date) -lt $deadline) {
        if (Test-HermesDockerCommanderReadyNow $DockerExe 1800) {
            Write-HermesDockerCommanderDashboard -Name $Name -Phase 'daemon ready' -Started $started -DoneBytes 1 -TotalBytes 1 -Detail 'Docker daemon accepted version probe'
            Write-Host ''
            return $true
        }
        Write-HermesDockerCommanderDashboard -Name $Name -Phase 'starting' -Started $started -DoneBytes 0 -TotalBytes 0 -Detail 'waiting for Docker daemon to accept commands'
        Start-Sleep -Seconds 1
    }
    Write-Host ''
    Invoke-HermesDockerAllFastLine $Name 'Docker daemon did not become ready before the readiness gate; command will enter normal visible retry path'
    return $false
}

