function Find-RedockerSafeDockerPath {
        param([ValidateSet('Desktop','Cli')][string]$Kind)
        $names = if($Kind -eq 'Desktop'){ @('Docker Desktop.exe') } else { @('docker.exe') }
        $candidates = @()
        if($Kind -eq 'Desktop'){
            $candidates += (Join-Path ${env:ProgramFiles} 'Docker\Docker\Docker Desktop.exe')
            if($env:ProgramFiles -and (Test-Path -LiteralPath (Join-Path ${env:ProgramFiles} 'Docker'))){
                try {
                    $candidates += Get-ChildItem -LiteralPath (Join-Path ${env:ProgramFiles} 'Docker') -Filter 'Docker Desktop.exe' -Recurse -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName
                } catch { }
            }
        } else {
            $candidates += (Join-Path ${env:ProgramFiles} 'Docker\Docker\resources\bin\docker.exe')
            $cmd = Get-Command docker.exe -ErrorAction SilentlyContinue | Select-Object -First 1
            if($cmd -and $cmd.Source){ $candidates += $cmd.Source }
            if($env:ProgramFiles -and (Test-Path -LiteralPath (Join-Path ${env:ProgramFiles} 'Docker'))){
                try {
                    $candidates += Get-ChildItem -LiteralPath (Join-Path ${env:ProgramFiles} 'Docker') -Filter 'docker.exe' -Recurse -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName
                } catch { }
            }
        }
        foreach($candidate in ($candidates | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique)){
            foreach($name in $names){
                if((Split-Path -Leaf $candidate) -ieq $name -and (Test-Path -LiteralPath $candidate)){ return $candidate }
            }
        }
        return $null
    }

