    function Invoke-FFRpc([int]$Port,[string]$Method,$Params=@()){ $body=@{jsonrpc='2.0';id='fixfitgirl';method=$Method;params=@($Params)}|ConvertTo-Json -Depth 32 -Compress; Invoke-RestMethod -Uri ("http://127.0.0.1:{0}/jsonrpc" -f $Port) -Method Post -Body $body -ContentType 'application/json' -TimeoutSec 8 }
    function Get-FFPorts { $ports=New-Object System.Collections.Generic.List[int]; Get-CimInstance Win32_Process -ErrorAction SilentlyContinue|Where-Object{$_.Name -in @('aria2c.exe','aria2c.real.exe')}|ForEach-Object{if((''+$_.CommandLine)-match '--rpc-listen-port(?:=|\s+)(\d+)'){[void]$ports.Add([int]$matches[1])}}; if(Test-Path -LiteralPath $config){try{$cfg=Get-Content -LiteralPath $config -Raw|ConvertFrom-Json;if($cfg.rpc.port){[void]$ports.Add([int]$cfg.rpc.port)}}catch{}}; foreach($p in 6900,6899,6800){[void]$ports.Add($p)}; foreach($p in @($ports|Select-Object -Unique)){try{[void](Invoke-FFRpc $p 'aria2.getVersion');$p}catch{}} }
    function Set-FFProp($o,[string]$n,$v){ if($o.PSObject.Properties.Name -contains $n){$o.$n=$v}else{Add-Member -InputObject $o -MemberType NoteProperty -Name $n -Value $v -Force} }
    if(!(Test-Path -LiteralPath $bridge -PathType Leaf)){ throw "Missing Fit Launcher bridge script: $bridge" }
    if(!(Test-Path -LiteralPath (Split-Path -Parent $hook) -PathType Container)){ New-Item -ItemType Directory -Force -Path (Split-Path -Parent $hook) | Out-Null }
    if(!(Test-Path -LiteralPath (Split-Path -Parent $watchdog) -PathType Container)){ New-Item -ItemType Directory -Force -Path (Split-Path -Parent $watchdog) | Out-Null }
    Set-Content -LiteralPath $hook -Encoding ASCII -Force -Value ('@echo off'+"`r`n"+'"'+$ps5+'" -NoProfile -ExecutionPolicy Bypass -File "'+$watchdog+'" -Once >NUL 2>NUL'+"`r`n"+'"'+$ps5+'" -NoProfile -ExecutionPolicy Bypass -File "'+$bridge+'" -Once >NUL 2>NUL')
    $watchdogBody = @'
param([switch]$Once,[switch]$Daemon)
$ErrorActionPreference = 'Continue'
$bridge = 'F:\study\projects\games\DownloadNAutoInstall\windows\fit-launcher\automation\auto-install\path-bridge\scripts\FitLauncherPathBridge.ps1'
$ps5 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
function Invoke-AfitgirlCompletionSweep {
    if(Test-Path -LiteralPath $bridge -PathType Leaf){
        $out = Join-Path $env:TEMP ('afitgirl_watchdog_bridge_' + ([guid]::NewGuid().ToString('N')) + '.out.log')
        $err = Join-Path $env:TEMP ('afitgirl_watchdog_bridge_' + ([guid]::NewGuid().ToString('N')) + '.err.log')
        $p = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$bridge,'-Once') -WindowStyle Hidden -RedirectStandardOutput $out -RedirectStandardError $err -PassThru
        try {
            if(-not $p.WaitForExit(30000)){
                try{ Stop-Process -Id ([int]$p.Id) -Force -ErrorAction SilentlyContinue }catch{}
                Write-Host '[afitgirl-watchdog] bridge -Once exceeded 30s; killed only that bounded sweep and will retry.'
                return 0
            }
            if(Test-Path -LiteralPath $out){ Get-Content -LiteralPath $out -ErrorAction SilentlyContinue | ForEach-Object { if($_){ Write-Host $_ } } }
            if(Test-Path -LiteralPath $err){ Get-Content -LiteralPath $err -ErrorAction SilentlyContinue | ForEach-Object { if($_){ Write-Host $_ } } }
            return [int]$p.ExitCode
        } finally {
            Remove-Item -LiteralPath $out,$err -Force -ErrorAction SilentlyContinue
        }
    }
    Write-Host ("[afitgirl-watchdog] missing bridge: {0}" -f $bridge)
    return 2
}
if($Daemon){
    while($true){
        [void](Invoke-AfitgirlCompletionSweep)
        Start-Sleep -Seconds 1
    }
} else {
    exit (Invoke-AfitgirlCompletionSweep)
}
'@
    Set-Content -LiteralPath $watchdog -Encoding UTF8 -Force -Value $watchdogBody
    if(Test-Path -LiteralPath $installConfig){ try{$icfg=Get-Content -LiteralPath $installConfig -Raw|ConvertFrom-Json}catch{$icfg=[pscustomobject]@{}} } else { $icfg=[pscustomobject]@{} }
    foreach($pair in @(@('auto_install',$true),@('auto_clean',$false),@('two_gb_limit',$false),@('directx_install',$false),@('microsoftcpp_install',$false),@('max_parallel_installations',16),@('concurrent_installations',16))){ Set-FFProp $icfg $pair[0] $pair[1] }
    if(!(Test-Path -LiteralPath (Split-Path -Parent $installConfig) -PathType Container)){ New-Item -ItemType Directory -Force -Path (Split-Path -Parent $installConfig) | Out-Null }
    Set-Content -LiteralPath $installConfig -Encoding UTF8 -Force -Value ($icfg|ConvertTo-Json -Depth 16)
    if(Test-Path -LiteralPath $config){ try{$cfg=Get-Content -LiteralPath $config -Raw|ConvertFrom-Json; foreach($s in 'general','network','bittorrent','limits','rpc'){if($cfg.PSObject.Properties.Name -notcontains $s -or $null -eq $cfg.$s){Add-Member -InputObject $cfg -MemberType NoteProperty -Name $s -Value ([pscustomobject]@{}) -Force}}; Set-FFProp $cfg.general 'concurrent_downloads' 16; Set-FFProp $cfg.general 'folder_exclusion_cleanup' $false; Set-FFProp $cfg.network 'max-connection-per-server' 16; Set-FFProp $cfg.network 'split' 16; Set-FFProp $cfg.bittorrent 'max-peers' 5000; Set-FFProp $cfg.bittorrent 'enable-dht' $true; Set-FFProp $cfg.bittorrent 'seed-ratio' 0; Set-FFProp $cfg.bittorrent 'seed-time' 0; Set-FFProp $cfg.limits 'max-overall-download' $null; Set-FFProp $cfg.limits 'max-download' $null; Set-FFProp $cfg.rpc 'start_daemon' $true; Set-Content -LiteralPath $config -Encoding UTF8 -Force -Value ($cfg|ConvertTo-Json -Depth 64)}catch{Write-Host ("[fixfitgirl] config note: {0}" -f $_.Exception.Message)} }
    $opts=@{'max-concurrent-downloads'='16';'max-connection-per-server'='16';'split'='16';'bt-max-peers'='5000';'max-overall-download-limit'='0';'max-download-limit'='0';'max-overall-upload-limit'='4M';'max-upload-limit'='4M';'allow-overwrite'='true';'auto-file-renaming'='false';'continue'='true';'enable-dht'='true';'enable-peer-exchange'='true';'bt-enable-lpd'='true';'bt-save-metadata'='true';'bt-load-saved-metadata'='true';'seed-ratio'='0';'seed-time'='0';'on-download-complete'=$hook}
    foreach($port in @(Get-FFPorts)){ try{[void](Invoke-FFRpc $port 'aria2.changeGlobalOption' @($opts));[void](Invoke-FFRpc $port 'aria2.unpauseAll');Write-Host ("[fixfitgirl] aria2 live policy applied port={0}" -f $port)}catch{Write-Host ("[fixfitgirl] aria2 port {0} note: {1}" -f $port,$_.Exception.Message)}; try{foreach($item in @((Invoke-FFRpc $port 'aria2.tellStopped' @(0,1000)).result)){if((''+$item.errorMessage)-match 'control file\(\*\.aria2\) does not exist|File .+ exists, but a control file'){try{[void](Invoke-FFRpc $port 'aria2.removeDownloadResult' @((''+$item.gid)));Write-Host ("[fixfitgirl] removed stale existing-folder aria2 error gid={0} port={1}" -f $item.gid,$port)}catch{}}}}catch{} }
    $bridgeDaemonProcs=@(Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue|Where-Object{(''+$_.CommandLine)-like '*FitLauncherPathBridge.ps1*' -and (''+$_.CommandLine)-match '(?i)(^|[ ''"])-Daemon($|[ ''"])'})
    foreach($p in $bridgeDaemonProcs){ try{Stop-Process -Id ([int]$p.ProcessId) -Force -ErrorAction SilentlyContinue; Write-Host ("[fixfitgirl] reloaded bridge daemon helper pid={0}" -f $p.ProcessId)}catch{} }
    Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',$bridge,'-Daemon') -WindowStyle Hidden|Out-Null
    Start-Sleep -Milliseconds 800
    if($SelfTest -or $NoLiveRun){
        $selfOut = Join-Path $env:TEMP ('fixfitgirl_bridge_selftest_' + ([guid]::NewGuid().ToString('N')) + '.out.log')
        $selfErr = Join-Path $env:TEMP ('fixfitgirl_bridge_selftest_' + ([guid]::NewGuid().ToString('N')) + '.err.log')
        $selfProc = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$bridge,'-SelfTest') -WindowStyle Hidden -RedirectStandardOutput $selfOut -RedirectStandardError $selfErr -PassThru
        try {
            if(-not $selfProc.WaitForExit(45000)){
                try{ Stop-Process -Id ([int]$selfProc.Id) -Force -ErrorAction SilentlyContinue }catch{}
                Write-Host '[fixfitgirl] bridge self-test exceeded 45s; killed only the bounded self-test process and verified watchdog/daemon wiring instead.'
                if(!(Test-Path -LiteralPath $watchdog -PathType Leaf)){ throw "Missing completion watchdog after bounded self-test: $watchdog" }
                if(!(Test-Path -LiteralPath $hook -PathType Leaf)){ throw "Missing aria2 completion hook after bounded self-test: $hook" }
                $daemonOk = @(Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue | Where-Object { (''+$_.CommandLine) -like '*FitLauncherPathBridge.ps1*' -and (''+$_.CommandLine) -match '(?i)(^|[ ''"])-Daemon($|[ ''"])' }).Count -gt 0
                if(-not $daemonOk){ throw 'FitLauncherPathBridge daemon was not running after bounded self-test.' }
            } else {
                if(Test-Path -LiteralPath $selfOut){ Get-Content -LiteralPath $selfOut -ErrorAction SilentlyContinue | ForEach-Object { if($_){ Write-Host $_ } } }
                if(Test-Path -LiteralPath $selfErr){ Get-Content -LiteralPath $selfErr -ErrorAction SilentlyContinue | ForEach-Object { if($_){ Write-Host $_ } } }
                if([int]$selfProc.ExitCode -ne 0){ throw ("fixfitgirl bridge self-test exited with code {0}" -f $selfProc.ExitCode) }
            }
        } finally {
            Remove-Item -LiteralPath $selfOut,$selfErr -Force -ErrorAction SilentlyContinue
        }
        $global:LASTEXITCODE = 0
    } elseif($Daemon) {
        & $ps5 -NoProfile -ExecutionPolicy Bypass -File $bridge -Daemon
    } else {
        & $ps5 -NoProfile -ExecutionPolicy Bypass -File $bridge -Once
    }
    if($LASTEXITCODE -ne 0){ throw "fixfitgirl bridge exited with code $LASTEXITCODE" }
    $global:LASTEXITCODE=0
}

