function fixpip {
    [CmdletBinding()]
    param(
        [switch]$NoUpgrade
    )

    $ErrorActionPreference = 'Stop'

    function _fixpip_AddPathPart([string[]]$Parts, [string]$Value) {
        if ([string]::IsNullOrWhiteSpace($Value)) { return $Parts }
        $expanded = [Environment]::ExpandEnvironmentVariables($Value.Trim())
        if (-not (Test-Path -LiteralPath $expanded)) { return $Parts }
        $out = New-Object System.Collections.Generic.List[string]
        foreach ($p in $Parts) {
            if (-not [string]::IsNullOrWhiteSpace($p) -and ($p.TrimEnd('\') -ine $expanded.TrimEnd('\'))) { [void]$out.Add($p) }
        }
        $newOut = New-Object System.Collections.Generic.List[string]
        [void]$newOut.Add($expanded)
        foreach ($p in $out) { [void]$newOut.Add($p) }
        return $newOut.ToArray()
    }

    $pyLauncher = Join-Path $env:WINDIR 'py.exe'
    if (-not (Test-Path -LiteralPath $pyLauncher)) { throw 'Python launcher not found at C:\Windows\py.exe' }

    $python = (& $pyLauncher -3 -c "import sys; print(sys.executable)" 2>$null | Select-Object -First 1).Trim()
    if ([string]::IsNullOrWhiteSpace($python) -or -not (Test-Path -LiteralPath $python)) { throw 'No working Python 3 executable found through py -3.' }

    $pythonDir = Split-Path -Parent $python
    $scriptsDir = (& $python -c "import sysconfig; print(sysconfig.get_path('scripts'))" | Select-Object -First 1).Trim()
    $userScriptsDir = (& $python -m site --user-base | Select-Object -First 1).Trim()
    if (-not [string]::IsNullOrWhiteSpace($userScriptsDir)) { $userScriptsDir = Join-Path $userScriptsDir 'Scripts' }

    & $python -m ensurepip --upgrade | Write-Host
    if (-not $NoUpgrade) {
        & $python -m pip install --upgrade pip wheel | Write-Host
        # Open Interpreter 0.4.3 still imports pkg_resources; newest setuptools removed it on this host.
        & $python -m pip install --ignore-installed --no-deps 'setuptools==75.8.0' | Write-Host
    }

    $userPathRaw = [Environment]::GetEnvironmentVariable('Path','User')
    $userParts = @()
    if (-not [string]::IsNullOrWhiteSpace($userPathRaw)) { $userParts = $userPathRaw -split ';' | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } }
    $userParts = _fixpip_AddPathPart $userParts $userScriptsDir
    $userParts = _fixpip_AddPathPart $userParts $scriptsDir
    $userParts = _fixpip_AddPathPart $userParts $pythonDir
    $newUserPath = ($userParts -join ';')
    [Environment]::SetEnvironmentVariable('Path', $newUserPath, 'User')

    $machinePath = [Environment]::GetEnvironmentVariable('Path','Machine')
    $env:Path = ($newUserPath, $machinePath -join ';')

    $pip = Join-Path $scriptsDir 'pip.exe'
    if (-not (Test-Path -LiteralPath $pip)) { throw "pip.exe was not created at $pip" }
    $pipCmd = Get-Command pip.exe -ErrorAction Stop
    if ($pipCmd.Path -like '*\Microsoft\WindowsApps\pip.exe') { throw "pip still resolves to WindowsApps alias: $($pipCmd.Path)" }

    Write-Host ("Python: {0}" -f $python)
    Write-Host ("Pip: {0}" -f $pipCmd.Path)
    & $python -m pip --version | Write-Host
    Write-Host 'Permanent user PATH updated; open a new PowerShell window or run: $env:Path = [Environment]::GetEnvironmentVariable(''Path'',''User'') + '';'' + [Environment]::GetEnvironmentVariable(''Path'',''Machine'')'
    Write-Host 'Permanent PowerShell pip alias repair active: pip install interpreter -> pip install open-interpreter'
}

