function fixstore {
    [CmdletBinding()]
    param(
        [switch]$NoWsReset,
        [switch]$SkipLongRepair
    )

    $oldPreference = $ErrorActionPreference
    $ErrorActionPreference = 'Continue'
    $script:fixstoreRegistered = 0
    $script:fixstoreSkipped = 0

    try {
        $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
        $principal = New-Object Security.Principal.WindowsPrincipal($identity)
        $isAdmin = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    } catch {
        $isAdmin = $false
    }

    $registerPackage = {
        param($Package)
        try {
            if($null -eq $Package){ return }
            $location = [string]$Package.InstallLocation
            if([string]::IsNullOrWhiteSpace($location)){
                $script:fixstoreSkipped++
                return
            }
            if(-not [System.IO.Path]::IsPathRooted($location)){
                $script:fixstoreSkipped++
                return
            }
            $manifest = [System.IO.Path]::Combine($location, 'AppXManifest.xml')
            Add-AppxPackage -DisableDevelopmentMode -Register $manifest -ErrorAction SilentlyContinue 2>$null | Out-Null
            $script:fixstoreRegistered++
        } catch {
            $script:fixstoreSkipped++
        }
    }

    try {
        Get-AppXPackage -AllUsers -ErrorAction SilentlyContinue | ForEach-Object { & $registerPackage $_ }
    } catch {}

    try {
        Get-AppXPackage -Name Microsoft.WindowsStore -AllUsers -ErrorAction SilentlyContinue | ForEach-Object { & $registerPackage $_ }
    } catch {}

    try { Stop-Process -Name 'WinStore.App' -Force -ErrorAction SilentlyContinue } catch {}

    if(-not $NoWsReset){
        try { Start-Process -FilePath 'wsreset.exe' -WindowStyle Hidden -ErrorAction SilentlyContinue | Out-Null } catch {}
    }

    try {
        Get-Service -Name wscsvc,wuauserv,bits,cryptsvc,AppXSvc,ClipSVC,TokenBroker,StorSvc -ErrorAction SilentlyContinue | ForEach-Object {
            try { Set-Service -Name $_.Name -StartupType Automatic -ErrorAction SilentlyContinue } catch {}
            try { Start-Service -Name $_.Name -ErrorAction SilentlyContinue } catch {}
        }
    } catch {}

    try { & reg.exe delete 'HKCU\Software\Microsoft\Windows\CurrentVersion\Store' /f 2>$null | Out-Null } catch {}

    if($isAdmin){
        try { & reg.exe add 'HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\Appx\AppxAllUserStore\Deprovisioned' /f 2>$null | Out-Null } catch {}
        try { & netsh.exe winsock reset 2>$null | Out-Null } catch {}
        try { & netsh.exe int ip reset 2>$null | Out-Null } catch {}
        try { Get-ScheduledTask -TaskPath '\Microsoft\Windows\WindowsUpdate\' -ErrorAction SilentlyContinue | Start-ScheduledTask -ErrorAction SilentlyContinue } catch {}
        try { Get-ScheduledTask -TaskPath '\Microsoft\Windows\WS\' -ErrorAction SilentlyContinue | Start-ScheduledTask -ErrorAction SilentlyContinue } catch {}
        if(-not $SkipLongRepair){
            try { & sfc.exe /scannow 2>$null | Out-Null } catch {}
            try { & Dism.exe /Online /Cleanup-Image /RestoreHealth 2>$null | Out-Null } catch {}
        }
    } else {
        Write-Host '[fixstore] Non-elevated shell: admin-only repairs skipped (HKLM/netsh/scheduled tasks/SFC/DISM). Run as Administrator for those.'
    }

    Write-Host (('[fixstore] Store/AppX repair pass complete. registered={0}; skipped={1}; wsreset={2}; admin={3}; longRepair={4}') -f $script:fixstoreRegistered,$script:fixstoreSkipped,(-not $NoWsReset),$isAdmin,($isAdmin -and -not $SkipLongRepair))
    Remove-Variable -Name fixstoreRegistered,fixstoreSkipped -Scope Script -ErrorAction SilentlyContinue
    $global:LASTEXITCODE = 0
    $ErrorActionPreference = $oldPreference
}

