function Format-DKillBytes { param([Int64]$Bytes) if ($Bytes -ge 1TB) { return ('{0:N2} TB' -f ($Bytes / 1TB)) } elseif ($Bytes -ge 1GB) { return ('{0:N2} GB' -f ($Bytes / 1GB)) } elseif ($Bytes -ge 1MB) { return ('{0:N2} MB' -f ($Bytes / 1MB)) } else { return ('{0:N0} B' -f $Bytes) } }

function Format-DKillFastBytes { param([int64]$Bytes) if($Bytes -ge 1TB){'{0:N2} TB' -f ($Bytes/1TB)}elseif($Bytes -ge 1GB){'{0:N2} GB' -f ($Bytes/1GB)}elseif($Bytes -ge 1MB){'{0:N2} MB' -f ($Bytes/1MB)}else{'{0:N0} B' -f $Bytes} }

function Format-HermesDockerCommanderElapsed([TimeSpan]$Elapsed) {
        if ($Elapsed.TotalHours -ge 1) { return ('{0:hh\:mm\:ss}' -f $Elapsed) }
        return ('{0:mm\:ss}' -f $Elapsed)
    }

function global:Format-HermesDockerCommanderMiB {
    param([int64]$Bytes)
    if ($Bytes -le 0) { return '0 B' }
    if ($Bytes -lt 1KB) { return ('{0:N0} B' -f $Bytes) }
    if ($Bytes -lt 1MB) { return ('{0:N2} KiB' -f ([double]$Bytes / 1KB)) }
    return ('{0:N2} MiB' -f ([double]$Bytes / 1MB))
}

function Format-MmenuMB { param([int64]$Bytes) return ('{0:N2} MiB' -f ($Bytes / 1MB)) }

function Format-MmmenuMB { param([int64]$Bytes) return ('{0:N2} MiB' -f ($Bytes / 1MB)) }

function FR($label,$paths){$b=0;foreach($p in $paths){if(Test-Path $p -EA 0){$s=SZ $p;if($s -gt 0){Write-Host "    $p ($([math]::Round($s/1MB))MB)" -ForegroundColor DarkGray};$b+=$s;Get-ChildItem $p -Force -EA 0|Remove-Item -Recurse -Force -EA 0}};$script:freed+=$b;if($b -gt 0){Write-Host "  -> $label freed: $([math]::Round($b/1MB))MB" -ForegroundColor $(if($b -gt 50MB){'Green'}elseif($b -gt 1MB){'Yellow'}else{'Gray'})}}

