function Get-DKillPathBytes {
        param([string]$Path)
        $total = [Int64]0
        try {
            if (Test-Path -LiteralPath $Path) {
                $item = Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
                if ($item -and -not $item.PSIsContainer) { return [Int64]$item.Length }
                Get-ChildItem -LiteralPath $Path -Force -Recurse -ErrorAction SilentlyContinue | ForEach-Object { if (-not $_.PSIsContainer) { $total += [Int64]$_.Length } }
            }
        } catch {}
        return $total
    }

