function getgamebar {
    [CmdletBinding()]
    param(
        [switch]$VerifyOnly,
        [switch]$NoElevate
    )

    $ErrorActionPreference = 'Stop'
    $packageName = 'Microsoft.XboxGamingOverlay'
    $familyName = 'Microsoft.XboxGamingOverlay_8wekyb3d8bbwe'
    $productId = '9NZKPSTSNW4P'

    $TestAdmin = {
        $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
        return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    }

    $GetPackage = {
        @(Get-AppxPackage -Name $packageName -AllUsers -ErrorAction SilentlyContinue | Select-Object -First 1)
    }

    $RegisterPackage = {
        try { Add-AppxPackage -RegisterByFamilyName -MainPackage $familyName -ErrorAction Stop | Out-Null } catch { }
        $pkg = & $GetPackage
        if($pkg -and $pkg.PackageFamilyName){
            try { Add-AppxPackage -RegisterByFamilyName -MainPackage $pkg.PackageFamilyName -ErrorAction Stop | Out-Null } catch { }
        }
    }

    $ResolveWinget = {
        try { return Resolve-WingetExecutable } catch { return $null }
    }

    $InstallWingetPrerequisites = {
        $wc = New-Object System.Net.WebClient
        $wc.Headers['User-Agent'] = 'Mozilla/5.0'
        $items = @(
            @{ Url='https://aka.ms/Microsoft.VCLibs.x64.14.00.Desktop.appx'; File='Microsoft.VCLibs.x64.14.00.Desktop.appx' },
            @{ Url='https://github.com/microsoft/microsoft-ui-xaml/releases/download/v2.8.6/Microsoft.UI.Xaml.2.8.x64.appx'; File='Microsoft.UI.Xaml.2.8.x64.appx' },
            @{ Url='https://github.com/microsoft/winget-cli/releases/latest/download/Microsoft.DesktopAppInstaller_8wekyb3d8bbwe.msixbundle'; File='Microsoft.DesktopAppInstaller_8wekyb3d8bbwe.msixbundle' }
        )
        foreach($item in $items){
            $dest = Join-Path $env:TEMP $item.File
            Write-Host "Downloading $($item.File)..."
            $wc.DownloadFile($item.Url, $dest)
            Write-Host "Installing $($item.File)..."
            Add-AppxPackage -Path $dest -ForceApplicationShutdown -ErrorAction Stop | Out-Null
        }
        Start-Sleep -Seconds 2
    }

    $WingetInstall = {
        $winget = & $ResolveWinget
        if(-not $winget){
            & $InstallWingetPrerequisites
            $winget = & $ResolveWinget
        }
        if(-not $winget){ throw 'winget.exe is not available after installing App Installer.' }

        $env:PATH = (Join-Path $env:LOCALAPPDATA 'Microsoft\WindowsApps') + ';' + $env:PATH
        Write-Host 'Resetting and refreshing Microsoft Store winget source...'
        & $winget source reset --force | Write-Host
        & $winget source update --disable-interactivity | Write-Host

        $baseArgs = @('install',$productId,'--source','msstore','--accept-package-agreements','--accept-source-agreements','--force')
        $argsWithNoInteraction = $baseArgs + @('--disable-interactivity')
        Write-Host 'Installing Microsoft Xbox Game Bar through winget/msstore product id 9NZKPSTSNW4P...'
        & $winget @argsWithNoInteraction
        $code = $LASTEXITCODE
        if($code -ne 0){
            Write-Host "winget first attempt exited $code; retrying without --disable-interactivity for older winget compatibility..."
            & $winget @baseArgs
            $code = $LASTEXITCODE
        }
        if($code -ne 0){ throw "winget install failed with exit code $code" }
    }

    $StoreFallback = {
        Write-Host 'winget did not leave Game Bar installed; trying Store package fallback...'
        $wc = New-Object System.Net.WebClient
        $wc.Headers['User-Agent'] = 'Mozilla/5.0'
        $htmlPath = Join-Path $env:TEMP 'getgamebar-store.html'
        $body = "type=ProductId&url=$productId&ring=Retail&lang=en-US"
        $html = (Invoke-WebRequest -Uri 'https://store.rg-adguard.net/api/GetFiles' -Method Post -Body $body -ContentType 'application/x-www-form-urlencoded' -UseBasicParsing -ErrorAction Stop).Content
        Set-Content -LiteralPath $htmlPath -Value $html -Encoding UTF8
        $links = [regex]::Matches($html, 'https?://[^\"''<> ]+') | ForEach-Object { [System.Net.WebUtility]::HtmlDecode($_.Value) }
        $depLinks = @($links | Where-Object { $_ -match 'Microsoft\.(VCLibs|UI\.Xaml).*\.(appx|msix)$' } | Sort-Object -Unique)
        $gameLinks = @($links | Where-Object { $_ -match 'Microsoft\.XboxGamingOverlay_.*\.(appxbundle|msixbundle)$' -and $_ -notmatch 'BlockMap' } | Sort-Object @{ Expression = { $_.Length }; Descending = $true })
        foreach($link in $depLinks){
            $file = Join-Path $env:TEMP ([IO.Path]::GetFileName(([Uri]$link).AbsolutePath))
            Write-Host "Downloading dependency $file..."
            $wc.DownloadFile($link, $file)
            try { Add-AppxPackage -Path $file -ForceApplicationShutdown -ErrorAction Stop | Out-Null } catch { Write-Host "Dependency install warning: $($_.Exception.Message)" }
        }
        if(-not $gameLinks -or -not $gameLinks[0]){ throw "Could not find a Game Bar appxbundle/msixbundle link in $htmlPath" }
        $bundlePath = Join-Path $env:TEMP ([IO.Path]::GetFileName(([Uri]$gameLinks[0]).AbsolutePath))
        Write-Host "Downloading Game Bar bundle $bundlePath..."
        $wc.DownloadFile($gameLinks[0], $bundlePath)
        Add-AppxPackage -Path $bundlePath -ForceApplicationShutdown -ErrorAction Stop | Out-Null
    }

    $AssertInstalled = {
        & $RegisterPackage
        $pkg = & $GetPackage
        if(-not $pkg){ throw 'Xbox Game Bar is still not installed after all install paths.' }
        $currentUserPkg = Get-AppxPackage -Name $packageName -ErrorAction SilentlyContinue | Select-Object -First 1
        if(-not $currentUserPkg){ & $RegisterPackage }
        $pkg = & $GetPackage
        [pscustomobject]@{
            Installed = [bool]$pkg
            Name = if($pkg){ $pkg.Name } else { $null }
            PackageFullName = if($pkg){ $pkg.PackageFullName } else { $null }
            PackageFamilyName = if($pkg){ $pkg.PackageFamilyName } else { $familyName }
            Status = if($pkg){ $pkg.Status } else { $null }
        }
    }

    if($VerifyOnly){
        & $AssertInstalled
        return
    }

    if((-not (& $TestAdmin)) -and (-not $NoElevate)){
        $ps = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $profilePath = 'C:\Users\micha\Documents\WindowsPowerShell\Microsoft.PowerShell_profile.ps1'
        $command = ". '$profilePath'; getgamebar -NoElevate"
        Write-Host 'Restarting getgamebar elevated so Appx repair/install can succeed...'
        $p = Start-Process -FilePath $ps -Verb RunAs -Wait -PassThru -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-Command',$command)
        if($p.ExitCode -ne 0){ throw "Elevated getgamebar exited with code $($p.ExitCode)" }
        return
    }

    try { [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12 } catch { }
    Stop-Process -Name 'winget','XboxGamingOverlay','GameBar','GameBarFTServer' -Force -ErrorAction SilentlyContinue

    $before = & $GetPackage
    if($before){
        Write-Host "Game Bar package already present: $($before.PackageFullName). Repairing registration and verifying..."
        & $RegisterPackage
    }

    $ok = $false
    try {
        & $WingetInstall
        $ok = [bool](& $GetPackage)
    } catch {
        Write-Host "winget path failed: $($_.Exception.Message)"
    }

    if(-not $ok){
        & $StoreFallback
    }

    $status = & $AssertInstalled
    Write-Host 'DONE - Xbox Game Bar is installed and registered.'
    $status
}

