function global:Get-HermesDockerAllFastCommandKind {
    param([string[]]$DockerArgs)
    if (-not $DockerArgs -or $DockerArgs.Count -eq 0) { return 'other' }
    if ($DockerArgs[0] -ieq 'push') { return 'push' }
    if ($DockerArgs[0] -ieq 'build') { return 'build' }
    if ($DockerArgs.Count -ge 2 -and $DockerArgs[0] -ieq 'buildx' -and $DockerArgs[1] -ieq 'build') { return 'build' }
    return 'other'
}

function global:Get-HermesDockerAllFastContextIndex {
    param([string[]]$DockerArgs)
    $skipNext = $false
    $last = -1
    $valueOptions = @('-f','--file','-t','--tag','--target','--platform','--build-arg','--secret','--ssh','--output','-o','--cache-from','--cache-to','--label','--network','--add-host','--iidfile','--metadata-file','--builder','--progress')
    for ($i = 0; $i -lt $DockerArgs.Count; $i++) {
        $arg = $DockerArgs[$i]
        if ($skipNext) { $skipNext = $false; continue }
        if ($arg -in @('build','buildx')) { continue }
        if ($arg -eq '--') { if ($i + 1 -lt $DockerArgs.Count) { $last = $i + 1 }; continue }
        if ($arg -like '--*=*') { continue }
        if ($valueOptions -contains $arg) { $skipNext = $true; continue }
        if ($arg -like '-*') { continue }
        $last = $i
    }
    return $last
}

function global:Get-HermesDockerAllFastDockerfileIndex {
    param([string[]]$DockerArgs)
    for ($i = 0; $i -lt $DockerArgs.Count; $i++) {
        if (($DockerArgs[$i] -eq '-f' -or $DockerArgs[$i] -eq '--file') -and $i + 1 -lt $DockerArgs.Count) { return ($i + 1) }
        if ($DockerArgs[$i] -like '--file=*') { return $i }
    }
    return -1
}

function global:Get-HermesDockerAllFastRealExe {
    $preferred = 'C:\Program Files\Docker\Docker\resources\bin\docker.exe'
    if (Test-Path -LiteralPath $preferred -PathType Leaf) { return $preferred }
    $cmd = Get-Command docker.exe -CommandType Application -ErrorAction Stop
    if ($cmd.Source) { return $cmd.Source }
    if ($cmd.Path) { return $cmd.Path }
    return $cmd.Definition
}

function Get-HermesDockerNetworkSentBytes {
        try {
            $total = 0L
            foreach ($adapter in [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) {
                if ($adapter.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Loopback) { continue }
                if ($adapter.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Tunnel) { continue }
                $stats = $adapter.GetIPv4Statistics()
                if ($null -ne $stats) { $total += [int64]$stats.BytesSent }
            }
            return $total
        } catch {
            return -1L
        }
    }

function Get-HermesDockerPushImageBytes([string]$DockerExe,[string]$ImageName) {
        if ([string]::IsNullOrWhiteSpace($ImageName)) { return 0L }
        try {
            $sizeText = & $DockerExe image inspect --format '{{.Size}}' $ImageName 2>$null | Select-Object -First 1
            $size = 0L
            if ([int64]::TryParse(([string]$sizeText).Trim(),[ref]$size) -and $size -gt 0) { return $size }
        } catch {}
        return 0L
    }

function Get-HermesDockerPushImageName([string[]]$DockerArgList) {
        if (-not $DockerArgList -or $DockerArgList.Count -eq 0) { return '' }
        $normalized = New-Object System.Collections.Generic.List[string]
        foreach ($rawArg in @($DockerArgList)) {
            $argText = [string]$rawArg
            if ([string]::IsNullOrWhiteSpace($argText)) { continue }
            if ($argText -match '\s') {
                foreach ($match in [regex]::Matches($argText, "(?:""([^""]*)""|'([^']*)'|(\S+))")) {
                    if ($match.Groups[1].Success) { [void]$normalized.Add($match.Groups[1].Value) }
                    elseif ($match.Groups[2].Success) { [void]$normalized.Add($match.Groups[2].Value) }
                    else { [void]$normalized.Add($match.Groups[3].Value) }
                }
            } else {
                [void]$normalized.Add($argText)
            }
        }
        $argItems = [string[]]$normalized.ToArray()
        if (-not $argItems -or $argItems.Count -eq 0) { return '' }
        $pushIndex = -1
        for ($i = 0; $i -lt $argItems.Count; $i++) {
            if ([string]$argItems[$i] -ieq 'push') { $pushIndex = $i; break }
        }
        if ($pushIndex -lt 0) { return '' }
        for ($i = $pushIndex + 1; $i -lt $argItems.Count; $i++) {
            $arg = [string]$argItems[$i]
            if ([string]::IsNullOrWhiteSpace($arg)) { continue }
            if ($arg -like '--*') {
                if ($arg -notlike '*=*' -and $i + 1 -lt $argItems.Count -and [string]$argItems[$i + 1] -notlike '-*') { $i++ }
                continue
            }
            if ($arg -like '-*') { continue }
            return $arg
        }
        return ''
    }

function global:Get-InstalledStateToolPython {
    $portablePython = 'F:\backup\windowsapps\AppsBackups\Macrium\python312\python.exe'
    if (Test-Path -LiteralPath $portablePython) {
        & $portablePython -m pip --version *> $null
        if ($LASTEXITCODE -ne 0) {
            & $portablePython -m ensurepip --upgrade | Out-Host
        }
        return $portablePython
    }

    $python = Get-Command python -ErrorAction SilentlyContinue
    if ($python) {
        python -m pip --version *> $null
        if ($LASTEXITCODE -ne 0) {
            python -m ensurepip --upgrade | Out-Host
        }
        return 'python'
    }

    throw 'No Python runtime found for installed-state backup/restore.'
}

function global:Get-InstalledStateToolScript {
    $primary = 'F:\study\Devops\backup\WindowsInstalled\state\backup_restore\tooling\installed_state_backup_restore.py'
    $backup = 'F:\backup\windowsapps\AppsBackups\installed\tooling\installed_state_backup_restore.py'
    if (Test-Path -LiteralPath $primary) {
        $backupDir = Split-Path -Parent $backup
        if (-not (Test-Path -LiteralPath $backupDir)) {
            New-Item -ItemType Directory -Path $backupDir -Force | Out-Null
        }
        Copy-Item -LiteralPath $primary -Destination $backup -Force -ErrorAction SilentlyContinue
        return $primary
    }
    if (Test-Path -LiteralPath $backup) {
        return $backup
    }
    throw "Installed-state restore script not found. Checked: $primary and $backup"
}

function Get-LinkedIssueNumbers {
        param($Pr)

        $numbers = New-Object 'System.Collections.Generic.HashSet[int]'

        foreach ($ref in @($Pr.closingIssuesReferences)) {
            if ($ref.number) {
                [void]$numbers.Add([int]$ref.number)
            }
        }

        $text = @($Pr.title, $Pr.body) -join "`n"
        foreach ($match in [regex]::Matches($text, '#(\d+)')) {
            [void]$numbers.Add([int]$match.Groups[1].Value)
        }

        @($numbers)
    }

function Get-MmenuContextTotalBytes {
        $total=[int64]0; $count=0; $started=Get-Date; $last=Get-Date
        Write-Host "[mmenu][scan] START counting real source bytes" -ForegroundColor Cyan
        foreach($file in [IO.Directory]::EnumerateFiles($projectPath,'*',[IO.SearchOption]::AllDirectories)){
            try {
                $info=Get-Item -LiteralPath $file -Force -ErrorAction Stop
                $total += [int64]$info.Length; $count++
            } catch {
                Write-Host ("[mmenu][scan-warning] unreadable_reserved_or_phantom_path path={0} error={1}" -f $file,$_.Exception.Message) -ForegroundColor Yellow
                continue
            }
            if(((Get-Date)-$last).TotalSeconds -ge 1){ Write-Host ("[mmenu][scan] files={0} total={1}" -f $count,(Format-MmenuMB $total)) -ForegroundColor DarkCyan; $last=Get-Date }
        }
        Write-Host ("[mmenu][scan] DONE files={0} total={1} elapsed={2}s" -f $count,(Format-MmenuMB $total),[int][Math]::Ceiling(((Get-Date)-$started).TotalSeconds)) -ForegroundColor Cyan
        return $total
    }

