function Get-NvidDisplayTarget {
        $displayDevices = @(Get-PnpDevice -Class Display -ErrorAction SilentlyContinue | Where-Object { $_.InstanceId -match 'VEN_10DE' })
        if ($displayDevices.Count -eq 0) { throw 'No NVIDIA display adapter was detected by Windows PnP. Cannot install NVIDIA display driver automatically.' }
        $dev = $displayDevices | Select-Object -First 1
        $devId = $null
        if ($dev.InstanceId -match 'DEV_([0-9A-Fa-f]{4})') { $devId = $matches[1].ToUpperInvariant() }
        $seriesId = 131
        $productId = $null
        $productName = $dev.FriendlyName
        switch ($devId) {
            '2C02' { $productId = 1065; $productName = 'NVIDIA GeForce RTX 5080' }
            '2B85' { $productId = 1066; $productName = 'NVIDIA GeForce RTX 5090' }
            '2C05' { $productId = 1068; $productName = 'NVIDIA GeForce RTX 5070 Ti' }
            '2D04' { $productId = 1070; $productName = 'NVIDIA GeForce RTX 5070' }
        }
        if (-not $productId) {
            if ($dev.FriendlyName -match '5090') { $productId = 1066; $seriesId = 131 }
            elseif ($dev.FriendlyName -match '5080') { $productId = 1065; $seriesId = 131 }
            elseif ($dev.FriendlyName -match '5070\s*Ti') { $productId = 1068; $seriesId = 131 }
            elseif ($dev.FriendlyName -match '5070') { $productId = 1070; $seriesId = 131 }
            else { throw ("Unsupported NVIDIA adapter for automatic driver lookup: {0} ({1}). Add its DEV_* mapping to nvid." -f $dev.FriendlyName,$dev.InstanceId) }
        }
        [pscustomobject]@{ Device = $dev; DeviceId = $devId; SeriesId = $seriesId; ProductId = $productId; ProductName = $productName }
    }

function Get-TaskAssignees {
        param($Item)

        @($Item.assignees | ForEach-Object { $_.login })
    }

function Get-UpgraderBunGlobalPackages {
        $root = Join-Path $HOME '.bun\install\global\node_modules'
        if (-not (Test-Path $root)) {
            return @()
        }

        $items = New-Object System.Collections.ArrayList
        foreach ($entry in Get-ChildItem $root -Directory -Force) {
            if ($entry.Name -like '@*') {
                foreach ($child in Get-ChildItem $entry.FullName -Directory -Force) {
                    $pkg = Join-Path $child.FullName 'package.json'
                    if (Test-Path $pkg) {
                        try {
                            $j = Get-Content $pkg -Raw | ConvertFrom-Json
                            if ($j.name -and $j.version) {
                                [void]$items.Add([pscustomobject]@{
                                    Name = [string]$j.name
                                    Version = [string]$j.version
                                })
                            }
                        } catch {}
                    }
                }
            } else {
                $pkg = Join-Path $entry.FullName 'package.json'
                if (Test-Path $pkg) {
                    try {
                        $j = Get-Content $pkg -Raw | ConvertFrom-Json
                        if ($j.name -and $j.version) {
                            [void]$items.Add([pscustomobject]@{
                                Name = [string]$j.name
                                Version = [string]$j.version
                            })
                        }
                    } catch {}
                }
            }
        }

        return @($items)
    }

function Get-UpgraderBunVersion {
        if (-not (Get-Command bun.exe -ErrorAction SilentlyContinue)) {
            return $null
        }

        return ((& bun.exe --version 2>$null | Out-String).Trim())
    }

function Get-UpgraderChocolateyLibPackages {
        $root = 'C:\ProgramData\chocolatey\lib'
        if (-not (Test-Path -LiteralPath $root)) {
            return @()
        }

        return @(Get-ChildItem -LiteralPath $root -Directory -ErrorAction SilentlyContinue |
            Where-Object { $_.Name -and $_.Name -ne 'chocolatey' } |
            Select-Object -ExpandProperty Name)
    }

function Get-UpgraderCommandPath {
        param([string]$Name)

        $command = Get-Command $Name -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $command) {
            return $null
        }

        foreach ($property in @('Source', 'Path', 'Definition')) {
            if ($command.$property) {
                return [string]$command.$property
            }
        }

        return $null
    }

function Get-UpgraderCommandVersion {
        param(
            [string]$Path,
            [string[]]$Arguments = @('--version')
        )

        if ([string]::IsNullOrWhiteSpace($Path)) {
            return $null
        }

        try {
            $raw = ((& $Path @Arguments 2>$null | Out-String).Trim())
        } catch {
            return $null
        }

        if ([string]::IsNullOrWhiteSpace($raw)) {
            return $null
        }

        return (($raw -split "`r?`n" |
            ForEach-Object { $_.Trim() } |
            Where-Object { $_ } |
            Select-Object -First 1))
    }

function Get-UpgraderNpmInstalledVersion {
        param([string]$Name)

        $raw = (& npm.cmd list -g $Name --depth=0 --json 2>$null | Out-String).Trim()
        if ([string]::IsNullOrWhiteSpace($raw)) {
            return $null
        }

        try {
            $obj = $raw | ConvertFrom-Json
        } catch {
            return $null
        }

        return [string]$obj.dependencies.$Name.version
    }

function Get-UpgraderNpmOutdatedGlobals {
        $raw = (& npm.cmd outdated -g --depth=0 --json 2>$null | Out-String).Trim()
        if ([string]::IsNullOrWhiteSpace($raw) -or $raw -eq '{}') {
            return @()
        }

        try {
            $obj = $raw | ConvertFrom-Json
        } catch {
            return @()
        }

        if (-not $obj) {
            return @()
        }

        return @($obj.PSObject.Properties.Name)
    }

function Get-UpgraderNpmRegistryVersion {
        param([string]$Name)

        $raw = (& npm.cmd view --json $Name version 2>$null | Out-String).Trim()
        if ([string]::IsNullOrWhiteSpace($raw)) {
            return $null
        }

        try {
            $obj = $raw | ConvertFrom-Json
        } catch {
            return $raw.Trim('"')
        }

        if ($obj -is [string]) {
            return $obj
        }

        return $null
    }

function Get-UpgraderUvTools {
        $uvPath = Get-UpgraderCommandPath 'uv'
        if (-not $uvPath) {
            return @()
        }

        $raw = (& $uvPath tool list 2>$null | Out-String).Trim()
        if ([string]::IsNullOrWhiteSpace($raw)) {
            return @()
        }

        return @($raw -split "`r?`n" |
            ForEach-Object { $_.Trim() } |
            Where-Object { $_ -and $_ -notmatch '^-' })
    }

function Get-UpgraderWingetOutdatedPackages {
        $wingetPath = Get-UpgraderCommandPath 'winget'
        if (-not $wingetPath) {
            return @()
        }

        $raw = (& $wingetPath upgrade --include-unknown --accept-source-agreements --disable-interactivity 2>&1 | Out-String)
        if ([string]::IsNullOrWhiteSpace($raw)) {
            return @()
        }

        $items = New-Object System.Collections.ArrayList
        $lines = $raw -split "`r?`n"
        $headerLine = $lines | Where-Object { $_ -match '^Name\s+Id\s+Version\s+Available\s+Source$' } | Select-Object -First 1
        if (-not $headerLine) {
            return @()
        }

        $idIndex = $headerLine.IndexOf('Id')
        $versionIndex = $headerLine.IndexOf('Version')
        $availableIndex = $headerLine.IndexOf('Available')
        $sourceIndex = $headerLine.IndexOf('Source')

        foreach ($line in $lines) {
            $trimmed = $line.Trim()
            if ([string]::IsNullOrWhiteSpace($trimmed)) { continue }
            if ($trimmed -match '[\u2580-\u259F]') { continue }
            if ($trimmed -match '^(Name|[-]{3,})') { continue }
            if ($trimmed -match '^(Upgrades available\.|No installed package found matching input criteria\.|The following packages have upgrades available:|(\d+) upgrades available\.)') { continue }
            if ($line.Length -lt $sourceIndex) { continue }

            $normalizedLine = $line.PadRight($sourceIndex + 16)

            [void]$items.Add([pscustomobject]@{
                Name = [string]$normalizedLine.Substring(0, $idIndex).Trim()
                Id = [string]$normalizedLine.Substring($idIndex, $versionIndex - $idIndex).Trim()
                Version = [string]$normalizedLine.Substring($versionIndex, $availableIndex - $versionIndex).Trim()
                Available = [string]$normalizedLine.Substring($availableIndex, $sourceIndex - $availableIndex).Trim()
                Source = [string]$normalizedLine.Substring($sourceIndex).Trim()
            })
        }

        return @($items)
    }

function Get-WingetResult([string]$text) {
        $value = if ($text) { $text } else { '' }
        return [pscustomobject]@{
            Text = $value
            Succeeded = ($value -match '(?im)^Successfully installed\b')
            RestartRequired = ($value -match 'Restart the application to complete the upgrade')
            NoApplicableUpgrade = ($value -match 'No applicable upgrade found' -or $value -match 'No available upgrade found')
            AccessDenied = ($value -match 'Access is denied')
        }
    }

function Get-WingetSummary([string]$text) {
        if (-not $text) { return @() }

        $lines = New-Object System.Collections.ArrayList
        foreach ($rawLine in ($text -split "`r?`n")) {
            $line = $rawLine.Trim()
            if (-not $line) { continue }
            if ($line -match '^[\\/|\-]+$') { continue }
            if ($line -match '^\d+(\.\d+)?\s*(KB|MB|GB)\s*/') { continue }
            if ($line -match '^Name\s+Id\s+Version') { continue }
            if ($line -match '^-{5,}$') { continue }
            if ($line -match '^\(\d+/\d+\)\s+Found ') { continue }
            if ($line -match '^This application is licensed to you by its owner\.?$') { continue }
            if ($line -match '^Microsoft is not responsible for, nor does it grant any licenses to, third-party packages\.?$') { continue }
            if ($line -match '^Successfully verified installer hash$') { continue }
            if ($line -match '^Downloading ') { continue }
            if ($line -match '^Extracting archive\.\.\.$') { continue }
            if ($line -match '^Starting package install\.\.\.$') { continue }
            [void]$lines.Add($line)
        }

        return @($lines | Select-Object -Last 3)
    }

function Get-WingetUpgradeById([string]$id) {
        foreach ($package in @(Get-WingetUpgrades)) {
            if ($package.Id -eq $id) {
                return $package
            }
        }
        return $null
    }

function Get-WingetUpgrades {
        $raw = winget upgrade --include-unknown 2>&1 | Out-String
        $lines = $raw -split "`r?`n"
        $headerLine = $null
        $idCol = -1
        $verCol = -1
        $availCol = -1
        $srcCol = -1

        for ($i = 0; $i -lt $lines.Count; $i++) {
            if ($lines[$i] -match '^-{20,}') {
                $headerLine = $lines[$i - 1]
                break
            }
        }

        if (-not $headerLine -or $headerLine -notmatch 'Id') {
            return @()
        }

        $idCol = $headerLine.IndexOf('Id')
        $verCol = $headerLine.IndexOf('Version')
        $availCol = $headerLine.IndexOf('Available')
        $srcCol = $headerLine.IndexOf('Source')

        if ($idCol -lt 0 -or $verCol -lt 0 -or $availCol -lt 0) {
            return @()
        }

        $packages = @()
        $dataSection = $false
        foreach ($line in $lines) {
            if ($line -match '^-{20,}') {
                $dataSection = $true
                continue
            }

            if (-not $dataSection) { continue }
            if ($line -match '^\d+ upgrades? available') { break }
            if ([string]::IsNullOrWhiteSpace($line)) { continue }

            $padded = if ($srcCol -gt 0) {
                $line.PadRight([Math]::Max($line.Length, $srcCol + 1))
            } else {
                $line
            }

            if ($padded.Length -lt $availCol) { continue }

            $name = $padded.Substring(0, $idCol).Trim()
            $pkgId = $padded.Substring($idCol, $verCol - $idCol).Trim()
            $current = $padded.Substring($verCol, $availCol - $verCol).Trim()
            $available = if ($srcCol -gt $availCol) {
                $padded.Substring($availCol, $srcCol - $availCol).Trim()
            } else {
                $padded.Substring($availCol).Trim()
            }

            if ($name -and $pkgId -and $current -and $available) {
                $packages += [pscustomobject]@{
                    Name = $name
                    Id = $pkgId
                    Current = $current
                    Available = $available
                }
            }
        }

        return $packages
    }

function Get-WingiBareTokens {
        param([string[]]$ArgsList)
        $valueOptions = @('--id','--name','--moniker','-q','--query','-s','--source','-v','--version','--locale','-a','--architecture','--installer-type','--scope','--location','--override','--custom','--log','--header','--authentication-mode','--authentication-account')
        $tokens = @()
        for ($i = 0; $i -lt $ArgsList.Count; $i++) {
            $current = $ArgsList[$i]
            if ($current.StartsWith('-')) {
                if ($valueOptions -contains $current) { $i++ }
                continue
            }
            $tokens += $current
        }
        return $tokens
    }

function Get-WingiShowMetadata {
        param(
            [string[]]$ArgsList,
            [switch]$StoreExact
        )

        if ($StoreExact) {
            $bare = Get-WingiBareTokens -ArgsList $ArgsList
            if (-not $bare.Count) { return $null }
            $tempFile = Join-Path $env:TEMP ('wingi-show-' + [System.Guid]::NewGuid().ToString('N') + '.txt')
            cmd /c "winget show --id $($bare[0]) --source msstore --exact --accept-source-agreements --disable-interactivity > `"$tempFile`" 2>&1" | Out-Null
            $rawLines = if (Test-Path $tempFile) { Get-Content $tempFile -ErrorAction SilentlyContinue } else { @() }
            Remove-Item $tempFile -Force -ErrorAction SilentlyContinue
        } else {
            $rawLines = @(& winget show @ArgsList --accept-source-agreements --disable-interactivity 2>&1)
        }
        $metadata = [ordered]@{
            Name = ''
            Id = ''
            Version = ''
            Publisher = ''
            InstallerType = ''
            InstallerUrl = ''
            InstallerSha256 = ''
        }

        foreach ($line in $rawLines) {
            $trimmed = [regex]::Replace(($line.ToString()).Trim(), '\x1B\[[0-9;?]*[A-Za-z]', '')
            if (-not $trimmed) { continue }

            if (-not $metadata.Name -and $trimmed -match '^Found\s+(.+?)\s+\[([^\]]+)\]') {
                $metadata.Name = $matches[1].Trim()
                $metadata.Id = $matches[2].Trim()
                continue
            }

            if (-not $metadata.Version -and $trimmed.StartsWith('Version:')) {
                $metadata.Version = $trimmed.Substring('Version:'.Length).Trim()
                continue
            }

            if (-not $metadata.Publisher -and $trimmed.StartsWith('Publisher:')) {
                $metadata.Publisher = $trimmed.Substring('Publisher:'.Length).Trim()
                continue
            }

            if (-not $metadata.InstallerType -and $trimmed.StartsWith('Installer Type:')) {
                $metadata.InstallerType = $trimmed.Substring('Installer Type:'.Length).Trim()
                continue
            }

            if (-not $metadata.InstallerUrl -and $trimmed.StartsWith('Installer Url:')) {
                $metadata.InstallerUrl = $trimmed.Substring('Installer Url:'.Length).Trim()
                continue
            }

            if (-not $metadata.InstallerSha256 -and $trimmed.StartsWith('Installer SHA256:')) {
                $metadata.InstallerSha256 = $trimmed.Substring('Installer SHA256:'.Length).Trim()
            }
        }

        if (-not $metadata.InstallerUrl) { return $null }
        return [pscustomobject]$metadata
    }

function Get-WingupStateEntry($state, [string]$id) {
        foreach ($entry in @($state.Entries)) {
            if ($entry.Id -eq $id) { return $entry }
        }
        return $null
    }

