function Initialize-NvidControlPanelBaseline {
        $base = 'F:\hermes\nvid\NVIDIAControlPanelBaseline'
        $current = Join-Path $base 'current'
        New-Item -ItemType Directory -Path $base -Force | Out-Null
        if (Test-Path -LiteralPath $current) { return $current }
        $stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
        $versioned = Join-Path $base $stamp
        New-Item -ItemType Directory -Path $versioned -Force | Out-Null
        $paths = @(
            'C:\ProgramData\NVIDIA Corporation\Drs',
            'C:\ProgramData\NVIDIA Corporation\NVIDIA App\NvBackend\config.xml',
            'C:\ProgramData\NVIDIA Corporation\NVIDIA App\NvConfig',
            'C:\ProgramData\NVIDIA Corporation\NVIDIA App\AcceptedEULA.txt',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\storage.json',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\overrides.json',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend\config.xml',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend\batteryboost2.json',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend\nis2settings.json',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend\QuietMode2SupportState.json',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend\SHIM.json'
        )
        $copied = @()
        foreach($p in $paths) {
            if (Test-Path -LiteralPath $p) {
                $rel = ($p -replace '^[A-Za-z]:\\','') -replace '[\\/:*?""<>|]','_'
                $dest = Join-Path $versioned $rel
                if (Test-Path -LiteralPath $p -PathType Container) { Copy-Item -LiteralPath $p -Destination $dest -Recurse -Force }
                else { New-Item -ItemType Directory -Path (Split-Path -Parent $dest) -Force | Out-Null; Copy-Item -LiteralPath $p -Destination $dest -Force }
                $copied += $p
            }
        }
        try { & reg.exe export 'HKCU\Software\NVIDIA Corporation' (Join-Path $versioned 'HKCU_NVIDIA_Corporation.reg') /y 2>$null | Out-Null } catch {}
        try { & reg.exe export 'HKLM\SOFTWARE\NVIDIA Corporation' (Join-Path $versioned 'HKLM_NVIDIA_Corporation.reg') /y 2>$null | Out-Null } catch {}
        $manifest = [ordered]@{ Created = (Get-Date).ToString('o'); BaselineRoot = $versioned; Copied = $copied; PortableRoot = $base }
        $manifest | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $versioned 'manifest.json') -Encoding UTF8
        Copy-Item -LiteralPath $versioned -Destination $current -Recurse -Force
        Write-NvidStep ("captured NVIDIA Control Panel/NVIDIA App settings baseline on F drive: {0}" -f $current)
        return $current
    }

function Initialize-ProfileCommandModeFunctions {
    if (-not $script:ProfileIsCommandMode) { return }

    $proxy = {
        $calledName = $MyInvocation.MyCommand.Name
        if (-not $calledName -or $calledName -eq '&') { $calledName = $MyInvocation.InvocationName }
        if (-not $calledName -or $calledName -eq '&') { throw 'Full profile proxy could not determine the command name to reload.' }

        $lookupName = $calledName -replace '^(?i:global:)', ''
        foreach ($sourcePath in Get-ProfileFunctionSourcePaths) {
            $functionMap = Get-ProfileFunctionMap -ProfilePath $sourcePath
            if (-not $functionMap.ContainsKey($lookupName)) { continue }
            . ([scriptblock]::Create("function global:$lookupName $($functionMap[$lookupName].Body.Extent.Text)"))
            $targetCommand = Get-Command $lookupName -CommandType Function -ErrorAction Stop
            & $targetCommand @args
            return
        }

        Write-Host "Function '$calledName' unavailable: no source definition was found." -ForegroundColor Yellow
    }

    $skip = @('Load-FullPowerShellProfile', 'fullprofile', 'nomouse', 'ps527', 'pps527', 'Get-ProfileFunctionMap', 'Get-ProfileFunctionSourcePaths', 'cfun', 'Repair-StandardWindowsProcessEnvironment', 'Apply-HermesDockerProfileBridgeFix', 'Initialize-FastProfilePsReadLineHistory', 'Initialize-ProfileCommandModeFunctions')
    foreach ($sourcePath in @($PROFILE)) {
        if ([string]::IsNullOrWhiteSpace($sourcePath) -or -not (Test-Path -LiteralPath $sourcePath -PathType Leaf)) { continue }
        $functionMap = Get-ProfileFunctionMap -ProfilePath $sourcePath
        foreach ($functionName in $functionMap.Keys) {
            $lookupName = $functionName -replace '^(?i:global:)', ''
            if ($lookupName -in $skip) { continue }
            if (Get-Command $lookupName -CommandType Function -ErrorAction SilentlyContinue) { continue }
            Set-Item -Path "Function:\global:$lookupName" -Value $proxy -Force
        }
    }
}



function Install-NvidDriverWithPnpUtilFallback {
        param([Parameter(Mandatory=$true)][string]$ExtractRoot,[Parameter(Mandatory=$true)][string]$GpuInstanceId)
        $displayRoot = Join-Path $ExtractRoot 'Display.Driver'
        $dev = [regex]::Match($GpuInstanceId, 'DEV_([0-9A-Fa-f]{4})').Groups[1].Value
        $subsys = [regex]::Match($GpuInstanceId, 'SUBSYS_([0-9A-Fa-f]{8})').Groups[1].Value
        if (-not $dev) { throw "Unable to resolve NVIDIA device id from $GpuInstanceId" }
        $infMatches = @()
        foreach ($inf in Get-ChildItem -Path $displayRoot -Filter '*.inf' -ErrorAction Stop) {
            $text = Get-Content -LiteralPath $inf.FullName -Raw
            $score = 0
            if ($subsys -and $text -match [regex]::Escape("DEV_$dev&SUBSYS_$subsys")) { $score += 100 }
            if ($text -match [regex]::Escape("DEV_$dev")) { $score += 10 }
            if ($inf.Name -ieq 'nv_dispi.inf') { $score += 5 }
            if ($score -gt 0) { $infMatches += [pscustomobject]@{ Path=$inf.FullName; Score=$score } }
        }
        $selected = $infMatches | Sort-Object -Property @{Expression='Score';Descending=$true}, @{Expression='Path';Descending=$false} | Select-Object -First 1
        if (-not $selected) { throw "No extracted NVIDIA display INF matched DEV_$dev under $displayRoot" }
        Write-Host ("  NVIDIA setup failed or did not activate the driver; falling back to pnputil with {0}" -f $selected.Path) -ForegroundColor DarkYellow
        $output = (& pnputil.exe /add-driver $selected.Path /install 2>&1 | Out-String).Trim()
        Write-Host ("  pnputil /add-driver exit: {0}" -f $LASTEXITCODE) -ForegroundColor Gray
        if ($output) { Write-Host ("  pnputil output: {0}" -f (($output -split "`r?`n") -join ' | ')) -ForegroundColor Gray }
        try { & pnputil.exe /restart-device $GpuInstanceId 2>&1 | Out-Null } catch {}
        Start-Sleep -Seconds 10
    }

function Install-NvidLatestDisplayDriver {
        $target = Get-NvidDisplayTarget
        Write-NvidStep ("detected NVIDIA adapter {0} ({1}) mapped to ProductID {2}/SeriesID {3}" -f $target.ProductName,$target.Device.InstanceId,$target.ProductId,$target.SeriesId)
        $latest = Resolve-NvidLatestDriverDownload -Target $target
        Write-NvidStep ("latest NVIDIA display driver target is {0} (driver id {1})" -f $latest.Version,$latest.DriverId)
        $driverWork = Join-Path 'F:\hermes\nvid' ("nvid-driver-{0}" -f ($latest.Version -replace '[^0-9]',''))
        New-Item -ItemType Directory -Force -Path $driverWork | Out-Null
        $driverInstaller = Join-Path $driverWork (Split-Path $latest.Url -Leaf)
        if (-not (Test-Path -LiteralPath $driverInstaller -PathType Leaf)) {
            Write-NvidStep ("downloading NVIDIA display driver {0}" -f $latest.Url)
            Invoke-WebRequest -Uri $latest.Url -OutFile $driverInstaller -UseBasicParsing -TimeoutSec 1800
        } else {
            Write-NvidStep ("using existing NVIDIA display driver installer {0}" -f $driverInstaller)
        }
        $sig = Get-AuthenticodeSignature -LiteralPath $driverInstaller
        if ($sig.Status -ne 'Valid' -or $sig.SignerCertificate.Subject -notmatch 'NVIDIA') { throw ("NVIDIA display driver signature check failed: {0}" -f $sig.StatusMessage) }
        try { Unblock-File -LiteralPath $driverInstaller -ErrorAction SilentlyContinue } catch {}
        Stop-NvidAppProcesses
        try {
            Invoke-NvidNativeInstaller -FilePath $driverInstaller -Arguments @('-s','-noreboot') -Name 'NVIDIA display driver installer' | Out-Null
        } catch {
            if ($_.Exception.Message -notmatch '-2146762751|0x800B0001') { throw }
            Write-NvidStep 'NVIDIA package launcher hit 0x800B0001; falling back to signed-package extraction plus pnputil driver install'
            $extractDir = Join-Path $driverWork 'extracted'
            $sevenZip = @('C:\Program Files\7-Zip\7z.exe','C:\Program Files (x86)\7-Zip\7z.exe') | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } | Select-Object -First 1
            if (-not $sevenZip) { throw '7-Zip is required for the 0x800B0001 extraction fallback but was not found.' }
            $displayDriverExtracted = Join-Path $extractDir 'Display.Driver'
            $extractedLooksComplete = $false
            if (Test-Path -LiteralPath $displayDriverExtracted -PathType Container) {
                $infCount = @(Get-ChildItem -LiteralPath $displayDriverExtracted -Filter '*.inf' -ErrorAction SilentlyContinue).Count
                $sysCount = @(Get-ChildItem -LiteralPath $displayDriverExtracted -Filter '*.sys' -ErrorAction SilentlyContinue).Count
                $catCount = @(Get-ChildItem -LiteralPath $displayDriverExtracted -Filter '*.cat' -ErrorAction SilentlyContinue).Count
                $extractedLooksComplete = ($infCount -gt 5 -and $sysCount -gt 0 -and $catCount -gt 0)
                if (-not $extractedLooksComplete) {
                    Write-Host ("[nvid] existing extracted NVIDIA driver package on F: is incomplete (inf={0}, sys={1}, cat={2}); deleting and re-extracting cleanly" -f $infCount,$sysCount,$catCount) -ForegroundColor Yellow
                    Remove-Item -LiteralPath $extractDir -Recurse -Force -ErrorAction SilentlyContinue
                }
            }
            if (-not $extractedLooksComplete) {
                New-Item -ItemType Directory -Force -Path $extractDir | Out-Null
                Invoke-NvidNativeInstaller -FilePath $sevenZip -Arguments @('x','-y',('-o{0}' -f $extractDir),$driverInstaller) -Name 'NVIDIA driver extraction via 7-Zip' -AllowedExitCodes @(0) | Out-Null
            } else {
                Write-NvidStep ("using existing complete extracted NVIDIA driver package {0}" -f $extractDir)
            }
            $infRoot = Join-Path $extractDir 'Display.Driver'
            $infs = @(Get-ChildItem -LiteralPath $infRoot -Filter '*.inf' -Recurse -ErrorAction SilentlyContinue)
            if ($infs.Count -eq 0) { throw ("No NVIDIA Display.Driver INF files found under {0}" -f $infRoot) }
            $hardwareIdCandidates = New-Object 'System.Collections.Generic.List[string]'
            foreach($rawId in @($target.Device.InstanceId)) {
                if ($rawId) { [void]$hardwareIdCandidates.Add(([string]$rawId).ToUpperInvariant()) }
            }
            foreach($propKey in @('DEVPKEY_Device_HardwareIds','DEVPKEY_Device_CompatibleIds')) {
                try {
                    $prop = Get-PnpDeviceProperty -InstanceId $target.Device.InstanceId -KeyName $propKey -ErrorAction SilentlyContinue
                    foreach($rawId in @($prop.Data)) {
                        if ($rawId) { [void]$hardwareIdCandidates.Add(([string]$rawId).ToUpperInvariant()) }
                    }
                } catch {}
            }
            $expandedHardwareIds = New-Object 'System.Collections.Generic.List[string]'
            foreach($rawId in @($hardwareIdCandidates | Select-Object -Unique)) {
                if (-not $rawId) { continue }
                [void]$expandedHardwareIds.Add($rawId)
                $withoutInstance = ($rawId -replace '\\[^\\]+$','')
                if ($withoutInstance -and $withoutInstance -ne $rawId) { [void]$expandedHardwareIds.Add($withoutInstance) }
                $withoutRev = ($rawId -replace '&REV_[0-9A-F]{2}','')
                if ($withoutRev -and $withoutRev -ne $rawId) { [void]$expandedHardwareIds.Add($withoutRev) }
                $withoutSubsys = ($withoutRev -replace '&SUBSYS_[0-9A-F]{8}','')
                if ($withoutSubsys -and $withoutSubsys -ne $withoutRev) { [void]$expandedHardwareIds.Add($withoutSubsys) }
            }
            $expandedHardwareIds = @($expandedHardwareIds | Where-Object { $_ -and ($_ -match 'VEN_10DE&DEV_') } | Select-Object -Unique)
            Write-NvidStep ("matching NVIDIA INF against hardware IDs: {0}" -f ($expandedHardwareIds -join '; '))
            $selectedInf = $null
            foreach($pattern in $expandedHardwareIds) {
                foreach($inf in $infs) {
                    $txt = (Get-Content -LiteralPath $inf.FullName -Raw -ErrorAction SilentlyContinue).ToUpperInvariant()
                    if ($txt.IndexOf($pattern, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) { $selectedInf = $inf; break }
                }
                if ($selectedInf) { break }
            }
            if (-not $selectedInf) {
                $genericPattern = 'PCI\VEN_10DE&DEV_' + $target.DeviceId
                foreach($inf in @($infs | Sort-Object @{Expression={ if($_.Name -eq 'nv_dispi.inf'){0}elseif($_.Name -match '^nv.*\.inf$'){1}else{2} }},Name)){ 
                    $txt = (Get-Content -LiteralPath $inf.FullName -Raw -ErrorAction SilentlyContinue).ToUpperInvariant()
                    if ($txt.IndexOf($genericPattern, [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -or ($txt -match 'CLASS\s*=\s*DISPLAY' -and $txt -match 'NVIDIA')) { $selectedInf = $inf; break }
                }
            }
            if ($selectedInf) {
                Write-NvidStep ("installing best NVIDIA Display.Driver INF through pnputil: {0}" -f $selectedInf.FullName)
                & pnputil.exe /add-driver $selectedInf.FullName /install 2>&1 | Tee-Object -Variable pnputilOutput | Out-Host
                if (($LASTEXITCODE -ne 0) -and ($LASTEXITCODE -ne 259)) {
                    Write-Host ("[nvid] selected INF install exited {0}; retrying whole Display.Driver INF tree so Windows can choose the correct OEM match" -f $LASTEXITCODE) -ForegroundColor Yellow
                    & pnputil.exe /add-driver (Join-Path $infRoot '*.inf') /subdirs /install 2>&1 | Tee-Object -Variable pnputilOutputAll | Out-Host
                }
            } else {
                Write-Host ("[nvid] no single INF text matched {0}; installing whole Display.Driver INF tree so Windows SetupAPI can select the correct NVIDIA package" -f $target.Device.InstanceId) -ForegroundColor Yellow
                & pnputil.exe /add-driver (Join-Path $infRoot '*.inf') /subdirs /install 2>&1 | Tee-Object -Variable pnputilOutputAll | Out-Host
            }
            if (($LASTEXITCODE -ne 0) -and ($LASTEXITCODE -ne 259)) { throw ("pnputil NVIDIA Display.Driver install failed with exit {0}; tried selected INF and full INF-tree fallback under {1}" -f $LASTEXITCODE,$infRoot) }
            if ($LASTEXITCODE -eq 259) { Write-NvidStep 'pnputil returned 259 after reporting the NVIDIA driver package is already installed/up-to-date on the device; treating as success' }
        }
        try { pnputil.exe /scan-devices 2>&1 | Out-Host } catch {}
        Start-Sleep -Seconds 5
        $after = Get-CimInstance Win32_PnPSignedDriver | Where-Object { $_.DeviceName -match 'NVIDIA|GeForce|RTX' -or $_.HardwareID -match 'VEN_10DE' } | Sort-Object DriverDate -Descending | Select-Object -First 1
        if (-not $after) { throw 'NVIDIA display driver installation finished but Windows still reports no NVIDIA signed display driver.' }
        Write-NvidStep ("Windows reports NVIDIA driver after install: {0} {1}" -f $after.DeviceName,$after.DriverVersion)
        return [pscustomobject]@{ Version = $latest.Version; Installer = $driverInstaller; DeviceName = $after.DeviceName; InstalledDriverVersion = $after.DriverVersion }
    }

function Install-SpeedtestCliExecutable {
        if (-not (Test-Path -LiteralPath $installRoot -PathType Container)) {
            New-Item -ItemType Directory -Force -Path $installRoot | Out-Null
        }
        $extractRoot = Join-Path $env:TEMP ('ookla-speedtest-extract-' + [Guid]::NewGuid().ToString('N'))
        if (Test-Path -LiteralPath $zipPath -PathType Leaf) { Remove-Item -LiteralPath $zipPath -Force -ErrorAction SilentlyContinue }
        [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
        Invoke-WebRequest -Uri $url -OutFile $zipPath -UseBasicParsing -ErrorAction Stop
        $actualSha256 = (Get-FileHash -LiteralPath $zipPath -Algorithm SHA256).Hash.ToUpperInvariant()
        if ($actualSha256 -ne $expectedSha256) { throw "Speedtest CLI download hash mismatch: $actualSha256" }
        Add-Type -AssemblyName System.IO.Compression.FileSystem
        New-Item -ItemType Directory -Force -Path $extractRoot | Out-Null
        try {
            [System.IO.Compression.ZipFile]::ExtractToDirectory($zipPath, $extractRoot)
            $extractedExe = Join-Path $extractRoot 'speedtest.exe'
            if (-not (Test-Path -LiteralPath $extractedExe -PathType Leaf)) { throw "Speedtest CLI zip did not contain speedtest.exe" }
            Copy-Item -LiteralPath $extractedExe -Destination $installExe -Force
            $license = Join-Path $extractRoot 'speedtest.md'
            if (Test-Path -LiteralPath $license -PathType Leaf) { Copy-Item -LiteralPath $license -Destination (Join-Path $installRoot 'speedtest.md') -Force }
        } finally {
            Remove-Item -LiteralPath $extractRoot -Recurse -Force -ErrorAction SilentlyContinue
        }
        if (-not (Test-SpeedtestCliExecutable -Path $installExe)) { throw "Installed Speedtest CLI is not executable: $installExe" }
        $userPath = [Environment]::GetEnvironmentVariable('Path','User')
        $pathParts = @($userPath -split ';' | Where-Object { $_ })
        if ($pathParts -notcontains $installRoot) {
            [Environment]::SetEnvironmentVariable('Path', (($pathParts + $installRoot) -join ';'), 'User')
        }
        $envParts = @($env:Path -split ';' | Where-Object { $_ })
        if ($envParts -notcontains $installRoot) { $env:Path = (($envParts + $installRoot) -join ';') }
        return $installExe
    }

function Invoke-AfitgirlAria2Rpc {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string] $Method,
        $Params = @(),
        [int] $TimeoutSec = 15
    )

    $configPath = Join-Path $env:APPDATA 'com.fitlauncher.carrotrub\config.json'
    $port = 6899
    $token = $null
    if (Test-Path -LiteralPath $configPath -PathType Leaf) {
        try {
            $cfg = Get-Content -LiteralPath $configPath -Raw | ConvertFrom-Json
            if ($cfg.rpc -and $cfg.rpc.port) { $port = [int]$cfg.rpc.port }
            if ($cfg.rpc -and $cfg.rpc.token) { $token = '' + $cfg.rpc.token }
        } catch {}
    }
    $p = @($Params)
    if ($token) { $p = @('token:' + $token) + $p }
    $body = @{ jsonrpc = '2.0'; id = ('afitgirl-' + [guid]::NewGuid().ToString('N')); method = $Method; params = $p } | ConvertTo-Json -Depth 64 -Compress
    $curl = Join-Path $env:SystemRoot 'System32\curl.exe'
    $effectiveTimeout = [Math]::Max(60, $TimeoutSec)
    $resp = Invoke-RestMethod -Uri ("http://127.0.0.1:{0}/jsonrpc" -f $port) -Method Post -ContentType 'application/json' -Body ([string]$body) -TimeoutSec $effectiveTimeout
    return ,$resp
}

function Invoke-AfitgirlDownloadPolicy {
    [CmdletBinding()]
    param(
        [int] $MinimumActive = 16,
        [int] $MinimumTotalSpeedMBps = 40,
        [switch] $Quiet
    )

    $desiredActive = [Math]::Max(16, $MinimumActive)
    $root = Join-Path $env:APPDATA 'com.fitlauncher.carrotrub'
    $configPath = Join-Path $root 'config.json'
    $installConfig = Join-Path $root 'fitgirlConfig\settings\installation\installation.json'

    try {
        if (Test-Path -LiteralPath $configPath -PathType Leaf) {
            $cfg = Get-Content -LiteralPath $configPath -Raw | ConvertFrom-Json
            foreach ($section in @('general','limits','network','bittorrent','rpc')) {
                if ($cfg.PSObject.Properties.Name -notcontains $section -or $null -eq $cfg.$section) {
                    Add-Member -InputObject $cfg -MemberType NoteProperty -Name $section -Value ([pscustomobject]@{})
                }
            }
            $pairs = @(
                @($cfg.general,'concurrent_downloads',$desiredActive),
                @($cfg.general,'folder_exclusion',$true),
                @($cfg.general,'folder_exclusion_cleanup',$false),
                @($cfg.network,'max-connection-per-server',16),
                @($cfg.network,'split',16),
                @($cfg.network,'min-split-size',1048576),
                @($cfg.bittorrent,'enable-dht',$true),
                @($cfg.bittorrent,'max-peers',1000),
                @($cfg.bittorrent,'seed-ratio',0),
                @($cfg.bittorrent,'seed-time',0),
                @($cfg.rpc,'start_daemon',$true),
                @($cfg.rpc,'port',6899)
            )
            foreach ($pair in $pairs) {
                $o = $pair[0]; $n = $pair[1]; $v = $pair[2]
                if ($o.PSObject.Properties.Name -notcontains $n) { Add-Member -InputObject $o -MemberType NoteProperty -Name $n -Value $v } else { $o.$n = $v }
            }
            foreach ($cap in @('max-overall-download','max-overall-upload','max-download','max-upload')) {
                if ($cfg.limits.PSObject.Properties.Name -notcontains $cap) { Add-Member -InputObject $cfg.limits -MemberType NoteProperty -Name $cap -Value $null } else { $cfg.limits.$cap = $null }
            }
            Set-Content -LiteralPath $configPath -Value ($cfg | ConvertTo-Json -Depth 64) -Encoding UTF8 -Force
        }
        if (Test-Path -LiteralPath $installConfig -PathType Leaf) {
            $icfg = Get-Content -LiteralPath $installConfig -Raw | ConvertFrom-Json
            foreach ($pair in @(@('auto_install',$true),@('auto_clean',$false),@('two_gb_limit',$false),@('directx_install',$false),@('microsoftcpp_install',$false),@('max_parallel_installations',999),@('concurrent_installations',999))) {
                $n = $pair[0]; $v = $pair[1]
                if ($icfg.PSObject.Properties.Name -notcontains $n) { Add-Member -InputObject $icfg -MemberType NoteProperty -Name $n -Value $v } else { $icfg.$n = $v }
            }
            Set-Content -LiteralPath $installConfig -Value ($icfg | ConvertTo-Json -Depth 64) -Encoding UTF8 -Force
        }
    } catch {
        if (-not $Quiet) { Write-Host ("[afitgirl] config repair warning: {0}" -f $_.Exception.Message) }
    }

    $opts = @{
        'max-concurrent-downloads' = ('' + $desiredActive)
        'max-connection-per-server' = '16'
        'split' = '16'
        'min-split-size' = '1M'
        'bt-max-peers' = '1000'
        'bt-tracker' = 'udp://tracker.opentrackr.org:1337/announce,udp://open.tracker.cl:1337/announce,udp://open.demonii.com:1337/announce,udp://tracker.torrent.eu.org:451/announce,udp://tracker-udp.gbitt.info:80/announce,udp://explodie.org:6969/announce,udp://tracker.skyts.net:6969/announce,udp://tracker.ololosh.space:6969/announce,udp://exodus.desync.com:6969/announce,udp://ipv4.tracker.harry.lu:80/announce,udp://open.stealth.si:80/announce,udp://tracker.moeking.me:6969/announce,udp://tracker.dler.org:6969/announce,udp://tracker.bitsearch.to:1337/announce,https://tracker.gbitt.info:443/announce,https://tracker.bt4g.com:443/announce,http://tracker.bt4g.com:2095/announce,http://tracker.files.fm:6969/announce'
        'max-overall-download-limit' = '0'
        'max-download-limit' = '0'
        'max-overall-upload-limit' = '0'
        'max-upload-limit' = '0'
        'lowest-speed-limit' = '0'
        'bt-request-peer-speed-limit' = '1K'
        'continue' = 'true'
        'enable-dht' = 'true'
        'enable-peer-exchange' = 'true'
        'bt-enable-lpd' = 'true'
        'bt-save-metadata' = 'true'
        'bt-load-saved-metadata' = 'true'
        'seed-ratio' = '0'
        'seed-time' = '0'
        'file-allocation' = 'none'
        'disk-cache' = '128M'
        'connect-timeout' = '8'
        'timeout' = '20'
        'max-tries' = '0'
        'retry-wait' = '2'
    }

    $active = @(); $waiting = @(); $stopped = @(); $speedBytes = 0L; $rpcOk = $false
    $ariaProc = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -in @('aria2c.real.exe','aria2c.exe') })
    if (($ariaProc.Count -eq 0) -or (@($ariaProc | Where-Object { ('' + $_.CommandLine) -match '--max-connection-per-server=(1|2|3|4|5|6|7|8)(\D|$)|--split=(1|2|3|4|5|6|7|8)(\D|$)|--bt-max-peers=(?:[1-9]|[1-9][0-9]|[1-8][0-9][0-9])(\D|$)|--max-concurrent-downloads=(1|2|3|4|5|6|7)(\D|$)|--enable-dht=false' }).Count -gt 0)) {
        Restart-AfitgirlAria2MaxSpeed -Reason 'missing/low-cap aria2 startup arguments'
    }
    try { [void](Invoke-AfitgirlAria2Rpc -Method 'aria2.changeGlobalOption' -Params @($opts) -TimeoutSec 8) } catch { if (-not $Quiet) { Write-Host ("[afitgirl] aria2 global policy warning, preserving active downloads: {0}" -f $_.Exception.Message) } }
    try { [void](Invoke-AfitgirlAria2Rpc -Method 'aria2.unpauseAll' -Params @() -TimeoutSec 5) } catch {}
    try {
        $active = @((Invoke-AfitgirlAria2Rpc -Method 'aria2.tellActive' -Params @() -TimeoutSec 8).result)
        $waiting = @((Invoke-AfitgirlAria2Rpc -Method 'aria2.tellWaiting' -Params @(0,1000) -TimeoutSec 8).result)
        $stopped = @((Invoke-AfitgirlAria2Rpc -Method 'aria2.tellStopped' -Params @(0,1000) -TimeoutSec 8).result)
        # Avoid per-torrent RPC storms while aria2 is busy; global policy and unpauseAll keep the queue moving.
        $speedBytes = 0L
        foreach ($item in $active) { if ($item -and $item.downloadSpeed) { try { $speedBytes += [int64]$item.downloadSpeed } catch {} } }
        $rpcOk = $true
    } catch {
        if (-not $Quiet) { Write-Host ("[afitgirl] aria2 read-only policy warning, preserving current downloader process: {0}" -f $_.Exception.Message) }
    }

    if ($rpcOk -and $speedBytes -lt ([int64]$MinimumTotalSpeedMBps * 1MB)) {
        $rescued = 0
        foreach ($item in @($active)) {
            $gid = '' + $item.gid
            if ([string]::IsNullOrWhiteSpace($gid)) { continue }
            $total = 0L; $done = 0L; $spd = 0L
            try { $total = [int64]$item.totalLength } catch {}
            try { $done = [int64]$item.completedLength } catch {}
            try { $spd = [int64]$item.downloadSpeed } catch {}
            if (($total -le 0) -or (($done -le 0) -and ($spd -lt 131072))) {
                try { [void](Invoke-AfitgirlAria2Rpc -Method 'aria2.forcePause' -Params @($gid) -TimeoutSec 2); $rescued++ } catch {}
            }
        }
        if ($rescued -gt 0) {
            try { [void](Invoke-AfitgirlAria2Rpc -Method 'aria2.unpauseAll' -Params @() -TimeoutSec 3) } catch {}
            try {
                $active = @((Invoke-AfitgirlAria2Rpc -Method 'aria2.tellActive' -Params @() -TimeoutSec 5).result)
                $waiting = @((Invoke-AfitgirlAria2Rpc -Method 'aria2.tellWaiting' -Params @(0,1000) -TimeoutSec 5).result)
                $stopped = @((Invoke-AfitgirlAria2Rpc -Method 'aria2.tellStopped' -Params @(0,1000) -TimeoutSec 5).result)
                $speedBytes = 0L
                foreach ($item in $active) { if ($item -and $item.downloadSpeed) { try { $speedBytes += [int64]$item.downloadSpeed } catch {} } }
            } catch {}
            if (-not $Quiet) { Write-Host ("[afitgirl] abyssal-speed rescue rotated {0} dead/0-speed metadata slots and resumed queue" -f $rescued) }
        }
    }

    $speedMB = [Math]::Round(($speedBytes / 1MB), 2)
    $status = if ($rpcOk -and $speedMB -ge $MinimumTotalSpeedMBps) { 'OK' } elseif ($rpcOk) { 'BELOW_TARGET_EXTERNAL_PEERS' } else { 'RPC_PENDING' }
    if (-not $Quiet) {
        Write-Host ("[afitgirl] live download policy: active={0}; waiting={1}; stopped={2}; speed={3} MB/s; target>={4} MB/s; status={5}; min-active-target={6}" -f @($active).Count,@($waiting).Count,@($stopped).Count,$speedMB,$MinimumTotalSpeedMBps,$status,$desiredActive)
    }
    [pscustomobject]@{ Active = @($active).Count; Waiting = @($waiting).Count; Stopped = @($stopped).Count; SpeedMBps = $speedMB; TargetMBps = $MinimumTotalSpeedMBps; Status = $status; MinimumActiveTarget = $desiredActive }
}

function Invoke-AfitgirlDurableRepair {
        param([string] $Phase)
        $bridgeScript = 'F:\study\projects\games\DownloadNAutoInstall\windows\fit-launcher\automation\auto-install\path-bridge\scripts\FitLauncherPathBridge.ps1'
        if (-not (Test-Path -LiteralPath $bridgeScript -PathType Leaf)) { throw "Missing Fit Launcher bridge script: $bridgeScript" }
        $tokens = $null
        $parseErrors = $null
        [System.Management.Automation.Language.Parser]::ParseFile($bridgeScript, [ref]$tokens, [ref]$parseErrors) | Out-Null
        if ($parseErrors -and $parseErrors.Count -gt 0) { throw ("Fit Launcher bridge parser failed: " + $parseErrors[0].Message) }
        Write-Host ("[afitgirl] {0}: enforcing PS5 bridge, 16 active downloads, unlimited speed, anti-stall, and instant completion handoff" -f $Phase)
        if (-not (Invoke-AfitgirlPs5Code -Code ". '$ps5Profile'; fixfitgirl -SelfTest" -Label 'bridge self-test' -TimeoutSeconds 45)) {
            Write-Host '[afitgirl] bridge self-test did not finish quickly; continuing with bounded Once repair/fallback instead of freezing the queue.'
        }
        $fullOk = Invoke-AfitgirlPs5Code -Code ". '$ps5Profile'; fixfitgirl -Once" -Label 'bounded fixfitgirl Once repair' -TimeoutSeconds 120
        if (-not $fullOk) {
            Write-Host '[afitgirl] full repair did not finish cleanly; applying noninteractive daemon/Once fallback now.'
            $fallback = @"
`$ErrorActionPreference = 'Continue'
`$bridge = '$bridgeScript'
`$ps5 = '$ps5'
`$daemon = @(Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue | Where-Object { (`$_.CommandLine -like '*FitLauncherPathBridge.ps1*') -and (`$_.CommandLine -like '*-Daemon*') })
if (`$daemon.Count -eq 0) { Start-Process -FilePath `$ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',`$bridge,'-Daemon') -WindowStyle Hidden | Out-Null; Start-Sleep -Seconds 2 }
& `$ps5 -NoProfile -ExecutionPolicy Bypass -File `$bridge -Once
if (`$null -ne `$LASTEXITCODE -and `$LASTEXITCODE -ne 0) { exit `$LASTEXITCODE }
"@
            if (-not (Invoke-AfitgirlPs5Code -Code $fallback -Label 'bridge daemon/Once fallback' -TimeoutSeconds 60)) {
                Write-Host '[afitgirl] bridge fallback did not finish quickly; continuing queue with the already-armed daemon/watchdog/clicker instead of freezing.'
            }
        }
        try { Start-AfitgirlMinuteMonitor -MinimumActive $MinimumActiveDownloads -MinimumTotalSpeedMBps $MinimumTotalSpeedMBps | Out-Null } catch { Write-Host ("[afitgirl] monitor warning: {0}" -f $_.Exception.Message) }
        try {
            $policy = Invoke-AfitgirlDownloadPolicy -MinimumActive $MinimumActiveDownloads -MinimumTotalSpeedMBps $MinimumTotalSpeedMBps
            if ($policy -and $policy.Status -eq 'RPC_PENDING') {
                Restart-AfitgirlAria2MaxSpeed -Reason ('Afitgirl {0} RPC recovery' -f $Phase)
                Start-Sleep -Seconds 3
                Invoke-AfitgirlDownloadPolicy -MinimumActive $MinimumActiveDownloads -MinimumTotalSpeedMBps $MinimumTotalSpeedMBps | Out-Null
            }
        } catch {
            Write-Host ("[afitgirl] speed policy warning: {0}" -f $_.Exception.Message)
        }
    }

function Invoke-AfitgirlPs5Code {
        param(
            [Parameter(Mandatory=$true)][string] $Code,
            [Parameter(Mandatory=$true)][string] $Label,
            [int] $TimeoutSeconds = 240
        )
        $outFile = Join-Path $env:TEMP ('afitgirl_' + ([guid]::NewGuid().ToString('N')) + '.out.log')
        $errFile = Join-Path $env:TEMP ('afitgirl_' + ([guid]::NewGuid().ToString('N')) + '.err.log')
        $encoded = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($Code))
        $proc = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-EncodedCommand',$encoded) -NoNewWindow -RedirectStandardOutput $outFile -RedirectStandardError $errFile -PassThru
        try {
            if (-not $proc.WaitForExit([Math]::Max(30,$TimeoutSeconds) * 1000)) {
                $killIds = New-Object System.Collections.Generic.List[int]
                function Add-AfitgirlChildProcessIds([int] $ParentId) {
                    foreach ($child in @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { [int]$_.ParentProcessId -eq $ParentId })) {
                        if ($child.ProcessId -ne $PID -and -not $killIds.Contains([int]$child.ProcessId)) {
                            [void]$killIds.Add([int]$child.ProcessId)
                            Add-AfitgirlChildProcessIds -ParentId ([int]$child.ProcessId)
                        }
                    }
                }
                [void]$killIds.Add([int]$proc.Id)
                Add-AfitgirlChildProcessIds -ParentId ([int]$proc.Id)
                foreach ($killId in @($killIds | Sort-Object -Descending)) { try { Stop-Process -Id ([int]$killId) -Force -ErrorAction SilentlyContinue } catch {} }
                Write-Host ("[afitgirl] {0} timed out after {1}s; killed the bounded helper process tree and kept Fit Launcher/aria2/installers alive." -f $Label,$TimeoutSeconds)
                return $false
            }
            if (Test-Path -LiteralPath $outFile) { Get-Content -LiteralPath $outFile -ErrorAction SilentlyContinue | ForEach-Object { if($_){ Write-Host $_ } } }
            if (Test-Path -LiteralPath $errFile) { Get-Content -LiteralPath $errFile -ErrorAction SilentlyContinue | ForEach-Object { if($_){ Write-Host $_ } } }
            if ([int]$proc.ExitCode -ne 0) {
                Write-Host ("[afitgirl] {0} exited with code {1}" -f $Label,$proc.ExitCode)
                return $false
            }
            return $true
        } finally {
            Remove-Item -LiteralPath $outFile,$errFile -Force -ErrorAction SilentlyContinue
        }
    }

function Invoke-AfitgirlPythonProcess {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string] $FilePath,
        [Parameter(Mandatory=$true)][string[]] $Arguments,
        [Parameter(Mandatory=$true)][string] $WorkingDirectory,
        [int] $TimeoutSeconds = 900
    )

    $outFile = Join-Path $env:TEMP ("afitgirl_stdout_{0}.log" -f ([guid]::NewGuid().ToString('N')))
    $errFile = Join-Path $env:TEMP ("afitgirl_stderr_{0}.log" -f ([guid]::NewGuid().ToString('N')))
    $argText = (($Arguments | ForEach-Object { ConvertTo-AfitgirlCommandLineArgument $_ }) -join ' ')
    $proc = Start-Process -FilePath $FilePath -ArgumentList $argText -WorkingDirectory $WorkingDirectory -NoNewWindow -RedirectStandardOutput $outFile -RedirectStandardError $errFile -PassThru
    try {
        if (-not $proc.WaitForExit($TimeoutSeconds * 1000)) {
            try { Stop-Process -Id $proc.Id -Force -ErrorAction SilentlyContinue } catch {}
            if (Test-Path -LiteralPath $outFile) { Get-Content -LiteralPath $outFile -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_ } }
            if (Test-Path -LiteralPath $errFile) { Get-Content -LiteralPath $errFile -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_ } }
            throw "afitgirl queue command timed out after $TimeoutSeconds seconds; returned control to PowerShell and reran speed/auto-install repair."
        }
        $stdout = if (Test-Path -LiteralPath $outFile) { Get-Content -LiteralPath $outFile -ErrorAction SilentlyContinue } else { @() }
        $stderr = if (Test-Path -LiteralPath $errFile) { Get-Content -LiteralPath $errFile -ErrorAction SilentlyContinue } else { @() }
        $stdout | ForEach-Object { Write-Host $_ }
        $stderr | ForEach-Object { Write-Host $_ }
        $code = [int]$proc.ExitCode
        $combined = (($stdout + $stderr) -join "`n")
        if ($code -eq 0 -and ($combined -match 'fit_download_list\.py: error:|Traceback|SyntaxError|RuntimeError|failed with exit code|Fit Launcher manager queue failed|falling back to aria2 direct queue|manager verification failed|(?m)^- .+: MISSING\b|SKIPPED_METADATA_TIMEOUT|SKIPPED_LEGACY_MAGNET|NO_MAGNET|RPC_PENDING|Connection timed out|timed out after|aria2 RPC is not reachable')) {
            $code = 4
        }
        $global:LASTEXITCODE = $code
        return $code
    }
    finally {
        Remove-Item -LiteralPath $outFile,$errFile -Force -ErrorAction SilentlyContinue
    }
}

function Invoke-AfitgirlVisibleDownloadsRepair {
    [CmdletBinding()]
    param([string] $Reason = 'post-queue visible Downloads repair')

    $tool = 'F:\study\Windows\Applications\Gaming\Launchers\FitLauncher\Automation\fit-download-list-terminal\tools\fit_download_list.py'
    $fitLauncher = 'F:\backup\windowsapps\installed\Fit Launcher\Fit Launcher.exe'
    if (-not (Test-Path -LiteralPath $tool -PathType Leaf)) { return }
    if (-not (Test-Path -LiteralPath $fitLauncher -PathType Leaf)) { return }
    $py = Get-Command py.exe -ErrorAction SilentlyContinue | Select-Object -First 1
    if (-not $py) { return }

    $oldEncoding = $env:PYTHONIOENCODING
    $oldLimit = $env:AFITGIRL_REHYDRATE_LIMIT
    $env:PYTHONIOENCODING = 'utf-8'
    $env:AFITGIRL_REHYDRATE_LIMIT = '16'
    $code = @'
from pathlib import Path
import sys
sys.path.insert(0, r"F:\study\Windows\Applications\Gaming\Launchers\FitLauncher\Automation\fit-download-list-terminal\tools")
import fit_download_list as f

try:
    if not f.webview_debug_available(9223):
        f.ensure_fit_launcher_debug(Path(r"F:\backup\windowsapps\installed\Fit Launcher\Fit Launcher.exe"), 9223, restart=True, timeout=35)
    changed = f.rehydrate_paused_manager_jobs_via_aria2("http://127.0.0.1:6899/jsonrpc")
    synced = f.sync_manager_status_from_aria2("http://127.0.0.1:6899/jsonrpc")
    try:
        f.force_downloads_tab_visible(9223)
