function Invoke-CleancDeleteOneLocal {
        param([Parameter(Mandatory=$true)]$Item,[Parameter(Mandatory=$true)][string]$FallbackPath)
        $path = $Item.FullName
        $method = 'Failed'
        $escalated = $false
        try {
            $current = (Get-Location).ProviderPath
            if ($current) {
                $cur = [System.IO.Path]::GetFullPath($current).TrimEnd('\')
                $target = [System.IO.Path]::GetFullPath($path).TrimEnd('\')
                if ($cur.Equals($target,[System.StringComparison]::OrdinalIgnoreCase) -or $cur.StartsWith($target + '\',[System.StringComparison]::OrdinalIgnoreCase)) { Set-Location -LiteralPath $FallbackPath }
            }
        } catch {}
        if (Test-CleancGoneLocal $path) { return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Already absent.';Method='NoOp';PermissionEscalated=$false} }
        $quoted = '"' + $path + '"'
        $attempts = @()
        if ($Item.IsReparsePoint) {
            if ($Item.IsDirectory) { $attempts += @("rmdir $quoted >nul 2>&1") } else { $attempts += @("del /f /q $quoted >nul 2>&1") }
        } elseif ($Item.IsDirectory) {
            $attempts += @("rd /s /q $quoted >nul 2>&1")
        } else {
            $attempts += @("del /f /q $quoted >nul 2>&1")
        }
        foreach ($cmd in $attempts) { try { Invoke-CleancNativeLocal $cmd } catch {}; if (Test-CleancGoneLocal $path) { $method='QuickNative'; return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Deleted with quick native delete.';Method=$method;PermissionEscalated=$false} } }
        try { if ($Item.IsDirectory -and -not $Item.IsReparsePoint) { Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop } else { Remove-Item -LiteralPath $path -Force -ErrorAction Stop } } catch {}
        if (Test-CleancGoneLocal $path) { return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Deleted with Remove-Item.';Method='RemoveItem';PermissionEscalated=$false} }

        try {
            if ($Item.IsDirectory -and -not $Item.IsReparsePoint) {
                Invoke-CleancNativeLocal ("takeown /f $quoted /r /d y >nul 2>&1")
                Invoke-CleancNativeLocal ("icacls $quoted /grant `"$env:USERNAME`":F /t /c /q >nul 2>&1")
                Invoke-CleancNativeLocal ("icacls $quoted /grant Administrators:F /t /c /q >nul 2>&1")
                Invoke-CleancNativeLocal ("attrib -r -h -s $quoted /s /d >nul 2>&1")
            } else {
                Invoke-CleancNativeLocal ("takeown /f $quoted >nul 2>&1")
                Invoke-CleancNativeLocal ("icacls $quoted /grant `"$env:USERNAME`":F /c /q >nul 2>&1")
                Invoke-CleancNativeLocal ("icacls $quoted /grant Administrators:F /c /q >nul 2>&1")
                Invoke-CleancNativeLocal ("attrib -r -h -s $quoted >nul 2>&1")
            }
            $escalated = $true
        } catch {}
        try { if ($Item.IsDirectory) { Invoke-CleancNativeLocal ("rd /s /q $quoted >nul 2>&1") } else { Invoke-CleancNativeLocal ("del /f /q $quoted >nul 2>&1") } } catch {}
        if (Test-CleancGoneLocal $path) { return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Deleted after ACL/attribute escalation.';Method='EscalatedNative';PermissionEscalated=$escalated} }
        try { if ($Item.IsDirectory -and -not $Item.IsReparsePoint) { Remove-Item -LiteralPath $path -Recurse -Force -ErrorAction Stop } else { Remove-Item -LiteralPath $path -Force -ErrorAction Stop } } catch {}
        if (Test-CleancGoneLocal $path) { return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Deleted after escalation with Remove-Item.';Method='EscalatedRemoveItem';PermissionEscalated=$escalated} }
        if ($Item.IsDirectory -and -not $Item.IsReparsePoint) {
            try {
                $empty = Join-Path ([System.IO.Path]::GetTempPath()) ('cleanc-empty-' + [guid]::NewGuid().ToString('N'))
                New-Item -ItemType Directory -Path $empty -Force | Out-Null
                Invoke-CleancNativeLocal ("robocopy `"$empty`" $quoted /MIR /XJ /R:0 /W:0 /NFL /NDL /NJH /NJS /NC /NS >nul 2>&1")
                Remove-Item -LiteralPath $empty -Recurse -Force -ErrorAction SilentlyContinue
                Invoke-CleancNativeLocal ("rd /s /q $quoted >nul 2>&1")
            } catch {}
            if (Test-CleancGoneLocal $path) { return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$true;Reason='Deleted after robocopy mirror reset.';Method='RobocopyReset';PermissionEscalated=$escalated} }
        }
        return [pscustomobject]@{Name=$Item.Name;Path=$path;ItemType=$Item.ItemType;Succeeded=$false;Reason='Item still exists after quick delete, Remove-Item, ACL/attribute escalation, and robocopy reset.';Method='Failed';PermissionEscalated=$escalated}
    }

function Invoke-CleancNativeLocal { param([string]$CommandLine) & $env:ComSpec /d /c $CommandLine | Out-Null }

function Invoke-DKillFastBoundedDocker {
        param(
            [string]$DockerExe,
            [string[]]$DockerArgs,
            [int]$Seconds = 4
        )
        if([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe)){ return $null }
        $outFile = Join-Path 'C:\Temp' ('dkill-docker-out-' + [guid]::NewGuid().ToString('N') + '.log')
        $errFile = Join-Path 'C:\Temp' ('dkill-docker-err-' + [guid]::NewGuid().ToString('N') + '.log')
        $label = 'docker ' + ($DockerArgs -join ' ')
        try {
            $p = Start-Process -FilePath $DockerExe -ArgumentList $DockerArgs -WindowStyle Hidden -PassThru -RedirectStandardOutput $outFile -RedirectStandardError $errFile
            if(-not $p.WaitForExit([Math]::Max(1,$Seconds) * 1000)){
                try { $p.Kill() } catch { }
                Write-DKillFastLine ("{0} timed out after {1}s; continuing forced C-drive delete path" -f $label,$Seconds) Yellow
                return 124
            }
            foreach($file in @($outFile,$errFile)){
                if(Test-Path -LiteralPath $file){
                    Get-Content -LiteralPath $file -ErrorAction SilentlyContinue | Select-Object -Last 12 | ForEach-Object {
                        if(-not [string]::IsNullOrWhiteSpace([string]$_)){ Write-DKillFastLine ([string]$_) DarkGray }
                    }
                }
            }
            return [int]$p.ExitCode
        } catch {
            Write-DKillFastLine ("{0} failed: {1}" -f $label,$_.Exception.Message) Yellow
            return 1
        } finally {
            foreach($file in @($outFile,$errFile)){ try { Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue } catch { } }
        }
    }

function Invoke-DKillFastBoundedRemove {
        param([string]$Path)
        if([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)){ return $true }
        $remaining = Get-DKillFastRemainingMilliseconds
        $isDockerVhd = ($Path -match '(?i)\\DockerDesktop\\vm-data\\DockerDesktop\.vhdx$|\\DockerDesktop\\vm-data$')
        if((-not $isDockerVhd) -and $remaining -lt 4200){ return $false }
        if($isDockerVhd){ Invoke-DKillFastReleaseDockerVhdLocks -Milliseconds 2400 }
        $budget = if($isDockerVhd){ [Math]::Max(1200,[Math]::Min(6500,[Math]::Max(1200,$remaining - 2200))) } else { [Math]::Max(600,[Math]::Min(4200,$remaining - 3200)) }
        $ps5 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        if(-not (Test-Path -LiteralPath $ps5)){ return $false }
        $encodedPath = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($Path))
        $cmd = '$p=[Text.Encoding]::Unicode.GetString([Convert]::FromBase64String(''' + $encodedPath + ''')); if($p -match ''(?i)\\DockerDesktop\\vm-data(\\DockerDesktop\.vhdx)?$''){ $takeown=Join-Path $env:SystemRoot ''System32\takeown.exe''; $icacls=Join-Path $env:SystemRoot ''System32\icacls.exe''; $item=Get-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue; if($item -and (Test-Path -LiteralPath $takeown)){ if($item.PSIsContainer){ & $takeown /F $p /A /R /D Y 2>$null | Out-Null } else { & $takeown /F $p /A 2>$null | Out-Null } }; if(Test-Path -LiteralPath $icacls){ if($item -and $item.PSIsContainer){ & $icacls $p /grant ''Administrators:(OI)(CI)F'' /T /C 2>$null | Out-Null } else { & $icacls $p /grant ''Administrators:F'' /C 2>$null | Out-Null } } }; Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue; if(Test-Path -LiteralPath $p){ Start-Sleep -Milliseconds 150; Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue }'
        try {
            $p = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-Command',$cmd) -PassThru -WindowStyle Hidden
            if(-not $p.WaitForExit($budget)){
                try { $p.Kill() } catch { }
                return $false
            }
        } catch { return $false }
        return (-not (Test-Path -LiteralPath $Path))
    }

function Invoke-DKillFastForegroundPrune {
        param([string]$DockerExe)
        if([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe)){ return $false }
        if(-not (Test-DKillFastDockerReady -DockerExe $DockerExe -FinalProbe)){ return $false }
        $prunePlan = @(
            ,@('builder','prune','--all','--force')
            ,@('system','prune','--all','--volumes','--force')
        )
        $allOk = $true
        try {
            foreach($args in $prunePlan){
                $remaining = Get-DKillFastRemainingMilliseconds
                if($remaining -lt 2500){
                    Write-DKillFastLine 'foreground Docker prune budget reached; preserving readiness gate' Yellow
                    $allOk = $false
                    break
                }
                $budgetSeconds = [Math]::Max(1,[Math]::Min(4,[int][Math]::Floor(($remaining - 1200) / 1000)))
                Write-DKillFastLine ("foreground prune: docker {0} (budget={1}s)" -f ($args -join ' '),$budgetSeconds) DarkCyan
                $code = Invoke-DKillFastBoundedDocker -DockerExe $DockerExe -DockerArgs $args -Seconds $budgetSeconds
                if($null -eq $code -or [int]$code -ne 0){ $allOk = $false }
                if(-not (Test-DKillFastDockerReady -DockerExe $DockerExe -FinalProbe)){
                    Write-DKillFastLine 'Docker daemon not ready after prune command; readiness recovery will run before returning' Yellow
                    $allOk = $false
                    break
                }
            }
        } catch {
            Write-DKillFastLine ("foreground Docker prune failed: {0}" -f $_.Exception.Message) Yellow
            $allOk = $false
        }
        if($allOk){ Write-DKillFastLine 'foreground Docker prune completed before readiness return' Green }
        return [bool]$allOk
    }

function Invoke-DKillFastHardDeleteDockerVhd {
        $vhd = 'C:\ProgramData\DockerDesktop\vm-data\DockerDesktop.vhdx'
        $vmData = 'C:\ProgramData\DockerDesktop\vm-data'
        if(-not $script:DKillFastIsAdmin){
            Write-DKillFastLine 'cannot hard-delete DockerDesktop.vhdx without elevated Administrator rights' Yellow
            return ((-not (Test-Path -LiteralPath $vhd)) -and (-not (Test-Path -LiteralPath $vmData)))
        }
        $bytesBefore = 0L
        try {
            if(Test-Path -LiteralPath $vmData){ $bytesBefore = [Math]::Max($bytesBefore,[int64](Get-DKillFastPathBytes -Path $vmData)) }
            elseif(Test-Path -LiteralPath $vhd){ $bytesBefore = [Math]::Max($bytesBefore,[int64](Get-DKillFastPathBytes -Path $vhd)) }
        } catch { $bytesBefore = 0L }
        $deleted = $false
        $attempt = 1
        while(-not $deleted -and (Get-DKillFastRemainingMilliseconds) -ge 1200){
            if((Get-DKillFastRemainingMilliseconds) -lt 1200){ break }
            if($attempt -gt 1){
                Write-DKillFastLine ("hard VHDX delete retry {0} after lock release" -f $attempt) Yellow
                try { Stop-DKillFastDocker } catch { }
            }
            try { Invoke-DKillFastReleaseDockerVhdLocks -Milliseconds ([Math]::Min(1400,[Math]::Max(500,(Get-DKillFastRemainingMilliseconds) - 13000))) } catch { }
            try {
                $vmMgmtPreDelete = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_VirtualSystemManagementService -ErrorAction SilentlyContinue
                $dockerVmPreDelete = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_ComputerSystem -ErrorAction SilentlyContinue | Where-Object { $_.ElementName -eq 'DockerDesktopVM' } | Select-Object -First 1
                if($vmMgmtPreDelete -and $dockerVmPreDelete){
                    $destroyPreDelete = Invoke-CimMethod -InputObject $vmMgmtPreDelete -MethodName DestroySystem -Arguments @{ AffectedSystem = $dockerVmPreDelete } -ErrorAction SilentlyContinue
                    Write-DKillFastLine ("destroyed DockerDesktopVM definition before VHDX deletion so locks release; return={0}" -f $destroyPreDelete.ReturnValue) DarkCyan
                }
            } catch {
                Write-DKillFastLine ("DockerDesktopVM definition destroy before VHDX deletion failed: {0}" -f $_.Exception.Message) Yellow
            }
            try {
                $hcs = Join-Path $env:SystemRoot 'System32\hcsdiag.exe'
                if(Test-Path -LiteralPath $hcs){
                    $hcsList = @(& $hcs list 2>$null)
                    $ids = @()
                    for($i=0; $i -lt $hcsList.Count; $i++){
                        $line = [string]$hcsList[$i]
                        if($line -match '^[0-9A-Fa-f-]{36}$'){
                            $id = $line.Trim()
                            $next = if($i + 1 -lt $hcsList.Count){ [string]$hcsList[$i+1] } else { '' }
                            if($next -match 'VMMS' -and $next -notmatch 'WSL'){ $ids += $id }
                        }
                    }
                    foreach($id in $ids){
                        try {
                            Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction SilentlyContinue |
                                Where-Object { ([string]$_.CommandLine).ToUpperInvariant().Contains(([string]$id).ToUpperInvariant()) } |
                                ForEach-Object {
                                    Write-DKillFastLine ("force-kill Docker vmwp.exe pid {0} before VHDX delete" -f $_.ProcessId) DarkCyan
                                    try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { }
                                }
                        } catch { }
                        Start-Sleep -Milliseconds 120
                        Write-DKillFastLine ("force-kill Docker HCS VMMS id {0} before VHDX delete" -f $id) DarkCyan
                        try { & $hcs kill $id 2>$null | Out-Null } catch { }
                    }
                }
            } catch { }
            Start-Sleep -Milliseconds 250
            try {
                Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction SilentlyContinue |
                    Where-Object { ([string]$_.CommandLine) -match '(?i)DockerDesktopVM|DockerDesktop\.vhdx|\\DockerDesktop\\vm-data' } |
                    ForEach-Object {
                        Write-DKillFastLine ("force-kill DockerDesktop-specific vmwp.exe pid {0} before VHDX delete" -f $_.ProcessId) DarkCyan
                        try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { }
                    }
            } catch { }
            foreach($target in @($vhd,$vmData)){
                if(-not (Test-Path -LiteralPath $target)){ continue }
                try {
                    $takeown = Join-Path $env:SystemRoot 'System32\takeown.exe'
                    $icacls = Join-Path $env:SystemRoot 'System32\icacls.exe'
                    $item = Get-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
                    if($item -and (Test-Path -LiteralPath $takeown)){
                        if($item.PSIsContainer){ & $takeown /F $target /A /R /D Y 2>$null | Out-Null }
                        else { & $takeown /F $target /A 2>$null | Out-Null }
                    }
                    if(Test-Path -LiteralPath $icacls){
                        if($item -and $item.PSIsContainer){ & $icacls $target /grant 'Administrators:(OI)(CI)F' /T /C 2>$null | Out-Null }
                        else { & $icacls $target /grant 'Administrators:F' /C 2>$null | Out-Null }
                    }
                    try { attrib -R -S -H $target /S /D 2>$null | Out-Null } catch { }
                } catch {
                    Write-DKillFastLine ("ownership/ACL step failed for {0}: {1}" -f $target,$_.Exception.Message) Yellow
                }
                try {
                    Remove-Item -LiteralPath $target -Recurse -Force -ErrorAction Stop
                } catch {
                    Write-DKillFastLine ("PowerShell delete failed for {0}: {1}" -f $target,$_.Exception.Message) Yellow
                    try {
                        $itemAfterFailure = Get-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
                        if($itemAfterFailure -and $itemAfterFailure.PSIsContainer){
                            [IO.Directory]::Delete($target,$true)
                        } elseif($itemAfterFailure) {
                            [IO.File]::Delete($target)
                        }
                    } catch {
                        Write-DKillFastLine ("dotnet delete fallback failed for {0}: {1}" -f $target,$_.Exception.Message) Yellow
                    }
                }
            }
            if((Test-Path -LiteralPath $vhd) -or (Test-Path -LiteralPath $vmData)){
                Start-Sleep -Milliseconds 160
            } else {
                $deleted = $true
            }
            $attempt++
        }
        if(Test-Path -LiteralPath $vhd){
            Write-DKillFastLine ("hard VHDX and vm-data delete not verified before readiness deadline; still exists: {0}" -f $vhd) Red
            return $false
        }
        if(Test-Path -LiteralPath $vmData){
            Write-DKillFastLine ("hard vm-data folder delete not verified before readiness deadline; still exists: {0}" -f $vmData) Red
            return $false
        }
        try {
            $serviceLogBytes = 0L
            $serviceLogs = @(Get-ChildItem -LiteralPath 'C:\ProgramData\DockerDesktop' -Force -ErrorAction SilentlyContinue -Filter 'service*.txt')
            foreach($serviceLog in $serviceLogs){
                try { if(-not $serviceLog.PSIsContainer){ $serviceLogBytes += [int64]$serviceLog.Length } } catch { }
                try { Remove-Item -LiteralPath $serviceLog.FullName -Force -ErrorAction SilentlyContinue } catch { }
            }
            if($serviceLogs.Count -gt 0){
                $script:DKillFastDeletedBytes += [int64]$serviceLogBytes
                Write-DKillFastLine ("old DockerDesktop service logs deleted before restart: files={0} bytes={1}" -f $serviceLogs.Count,(Format-DKillFastBytes $serviceLogBytes)) Green
            }
        } catch {
            Write-DKillFastLine ("old DockerDesktop service log cleanup failed before restart: {0}" -f $_.Exception.Message) Yellow
        }
        try {
            $vmMgmt = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_VirtualSystemManagementService -ErrorAction SilentlyContinue
            $dockerVm = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_ComputerSystem -ErrorAction SilentlyContinue | Where-Object { $_.ElementName -eq 'DockerDesktopVM' } | Select-Object -First 1
            if($vmMgmt -and $dockerVm){
                $destroy = Invoke-CimMethod -InputObject $vmMgmt -MethodName DestroySystem -Arguments @{ AffectedSystem = $dockerVm } -ErrorAction SilentlyContinue
                Write-DKillFastLine ("destroyed DockerDesktopVM definition after VHDX deletion so Docker can recreate a valid VM; return={0}" -f $destroy.ReturnValue) DarkCyan
            }
        } catch {
            Write-DKillFastLine ("DockerDesktopVM definition destroy after VHDX deletion failed: {0}" -f $_.Exception.Message) Yellow
        }
        if($bytesBefore -gt 0){ $script:DKillFastDeletedBytes += [int64]$bytesBefore }
        $script:DKillFastForcedVhdDeleteCompletedAt = Get-Date
        Write-DKillFastLine ("hard VHDX and vm-data folder delete verified; removed old payload={0}" -f (Format-DKillFastBytes $bytesBefore)) Green
        return $true
    }

