        $release = @'
$ErrorActionPreference='SilentlyContinue'
Import-Module Hyper-V -ErrorAction SilentlyContinue
$vm = Get-VM -Name 'DockerDesktopVM' -ErrorAction SilentlyContinue
$vmId = $null
if($vm){
  try { $vmId = ([string]$vm.Id).ToUpperInvariant() } catch { $vmId = $null }
  if($vm.State -ne 'Off'){ Stop-VM -Name 'DockerDesktopVM' -TurnOff -Force -ErrorAction SilentlyContinue }
