  $dockerVm = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_ComputerSystem -ErrorAction SilentlyContinue | Where-Object { $_.ElementName -eq 'DockerDesktopVM' } | Select-Object -First 1
  if($vmMgmt -and $dockerVm){ [void](Invoke-CimMethod -InputObject $vmMgmt -MethodName DestroySystem -Arguments @{ AffectedSystem = $dockerVm } -ErrorAction SilentlyContinue) }
} catch { }
if($vmId){
  Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction SilentlyContinue |
    Where-Object { ([string]$_.CommandLine).ToUpperInvariant().Contains($vmId) } |
    ForEach-Object { try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { } }
}
Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction SilentlyContinue |
  Where-Object { ([string]$_.CommandLine) -match '(?i)DockerDesktopVM|DockerDesktop\.vhdx|\\DockerDesktop\\vm-data' } |
  ForEach-Object { try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { } }
$vhd = 'C:\ProgramData\DockerDesktop\vm-data\DockerDesktop.vhdx'
try { Dismount-VHD -Path $vhd -ErrorAction SilentlyContinue } catch { }
try {
  $hcs = Join-Path $env:SystemRoot 'System32\hcsdiag.exe'
  if(Test-Path -LiteralPath $hcs){
    $hcsList = & $hcs list 2>$null
    $ids = @()
    for($i=0; $i -lt @($hcsList).Count; $i++){
      $line = [string]$hcsList[$i]
      if($line -match '^[0-9A-Fa-f-]{36}$'){
        $id = $line.Trim()
        $next = if($i + 1 -lt @($hcsList).Count){ [string]$hcsList[$i+1] } else { '' }
        if($next -match 'VMMS' -and $next -notmatch 'WSL'){ $ids += $id }
      }
    }
    foreach($id in $ids){
      try { & $hcs kill $id 2>$null | Out-Null } catch { }
      try {
        Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction SilentlyContinue |
          Where-Object { ([string]$_.CommandLine).ToUpperInvariant().Contains(([string]$id).ToUpperInvariant()) } |
          ForEach-Object { try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { } }
      } catch { }
    }
  }
} catch { }
Get-Process -ErrorAction SilentlyContinue |
  Where-Object { @('Docker Desktop','Docker Desktop Installer','com.docker.backend','com.docker.build','com.docker.proxy','com.docker.service','docker-agent','docker-buildx','docker-compose','docker-sandbox','dockerd','docker','vpnkit','containerd') -contains $_.ProcessName } |
  Stop-Process -Force -ErrorAction SilentlyContinue
'@
        try {
            $p = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-Command',$release) -PassThru -WindowStyle Hidden
            if(-not $p.WaitForExit([Math]::Max(300,$Milliseconds))){ try { $p.Kill() } catch { } }
        } catch { }
    }

