        Where-Object { $_.CommandLine -like '*FitLauncherPathBridge.ps1*' -and $_.CommandLine -like '*-Daemon*' })
    if ($daemon.Count -eq 0) {
        Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-WindowStyle','Hidden','-File',$bridgeScript,'-Daemon') -WindowStyle Hidden | Out-Null
        Start-Sleep -Seconds 2
    }

    if ($OnceOnly) {
        $outFile = Join-Path $env:TEMP ("fitlauncher_bridge_once_stdout_{0}.log" -f ([guid]::NewGuid().ToString('N')))
        $errFile = Join-Path $env:TEMP ("fitlauncher_bridge_once_stderr_{0}.log" -f ([guid]::NewGuid().ToString('N')))
        $proc = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-File',$bridgeScript,'-Once') -RedirectStandardOutput $outFile -RedirectStandardError $errFile -NoNewWindow -PassThru
        try {
            if (-not $proc.WaitForExit(90000)) {
                try { Stop-Process -Id $proc.Id -Force -ErrorAction SilentlyContinue } catch {}
                if (Test-Path -LiteralPath $outFile) { Get-Content -LiteralPath $outFile -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_ } }
                if (Test-Path -LiteralPath $errFile) { Get-Content -LiteralPath $errFile -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_ } }
                throw 'Fit Launcher speed/auto-install bridge -Once exceeded 90 seconds; killed only the one-shot repair process so PowerShell returns instead of hanging. The background daemon remains active.'
            }
            if (Test-Path -LiteralPath $outFile) { Get-Content -LiteralPath $outFile -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_ } }
            if (Test-Path -LiteralPath $errFile) { Get-Content -LiteralPath $errFile -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_ } }
            $code = [int]$proc.ExitCode
        }
        finally {
            Remove-Item -LiteralPath $outFile,$errFile -Force -ErrorAction SilentlyContinue
        }
    } else {
        & $ps5 -NoProfile -ExecutionPolicy Bypass -File $bridgeScript
        $code = if ($null -ne $global:LASTEXITCODE) { [int]$global:LASTEXITCODE } else { 0 }
    }
    if ($code -ne 0) {
        throw "Fit Launcher speed/auto-install bridge failed with exit code $code"
    }
}

function global:Invoke-HermesDockerAllFastLine {
    param([string]$Name,[string]$Message)
    Write-Host ('[{0}] {1} {2}' -f (Get-Date -Format 'HH:mm:ss'), $Name, $Message) -ForegroundColor Cyan
}

function global:Invoke-HermesDockerAllFastNative {
    [CmdletBinding()]
    param([Parameter(ValueFromRemainingArguments=$true)][string[]]$DockerArgs)
    function Test-HermesDockerAllFastNeedsDaemon {
        param([string[]]$Args)
        if (-not $Args -or $Args.Count -eq 0) { return $false }
        $first = [string]$Args[0]
        if ([string]::IsNullOrWhiteSpace($first)) { return $false }
        if ($first -in @('-v','--version','-h','--help','help')) { return $false }
        if ($first -eq 'version') {
            $joined = ($Args -join ' ')
            if ($joined -match '--format\s+["'']?\{\{\.Client\.') { return $false }
            return $true
        }
        if ($first -eq 'buildx') {
            if ($Args.Count -ge 2 -and ([string]$Args[1]) -in @('version','--version','help','--help','-h')) { return $false }
            return $true
        }
        if ($first -eq 'compose') {
            if ($Args.Count -ge 2 -and ([string]$Args[1]) -in @('version','--version','help','--help','-h')) { return $false }
            return $true
        }
        if ($first -match '^-') { return $false }
        return $true
    }
    if ($DockerArgs -and $DockerArgs.Count -eq 1 -and $DockerArgs[0] -match '\s') {
        $normalizedDockerArgs = New-Object System.Collections.Generic.List[string]
        foreach ($match in [regex]::Matches($DockerArgs[0], "(?:""([^""]*)""|'([^']*)'|(\S+))")) {
            if ($match.Groups[1].Success) { [void]$normalizedDockerArgs.Add($match.Groups[1].Value) }
            elseif ($match.Groups[2].Success) { [void]$normalizedDockerArgs.Add($match.Groups[2].Value) }
            else { [void]$normalizedDockerArgs.Add($match.Groups[3].Value) }
        }
        if ($normalizedDockerArgs.Count -gt 0) { $DockerArgs = [string[]]$normalizedDockerArgs.ToArray() }
    }
    $realDocker = Get-HermesDockerAllFastRealExe
    if ([string]::IsNullOrWhiteSpace($realDocker) -or -not (Test-Path -LiteralPath $realDocker -PathType Leaf)) {
        Invoke-HermesDockerAllFastLine 'docker' ("docker.exe missing: $realDocker; returning to PowerShell shell without exception dump")
        $global:LASTEXITCODE = 1
        return 1
    }
    $prepared = $null
    $oldBuildKit = $env:DOCKER_BUILDKIT
    $oldProgress = $env:BUILDKIT_PROGRESS
    $oldCompose = $env:COMPOSE_PROGRESS
    $oldTimeout = $env:COMPOSE_HTTP_TIMEOUT
    $oldClientTimeout = $env:DOCKER_CLIENT_TIMEOUT
    $oldCliHints = $env:DOCKER_CLI_HINTS
    $oldScanSuggest = $env:DOCKER_SCAN_SUGGEST
    $oldExperimental = $env:DOCKER_CLI_EXPERIMENTAL
    try {
        $env:DOCKER_BUILDKIT='1'
        $env:BUILDKIT_PROGRESS='plain'
        $env:COMPOSE_PROGRESS='plain'
        $env:COMPOSE_HTTP_TIMEOUT='86400'
        $env:DOCKER_CLIENT_TIMEOUT='86400'
        $env:DOCKER_CLI_HINTS='false'
        $env:DOCKER_SCAN_SUGGEST='false'
        $env:DOCKER_CLI_EXPERIMENTAL='enabled'
        $prepared = Resolve-HermesDockerAllFastBuildArgs -DockerArgs $DockerArgs
        $contextBytes = 0L
        if ($prepared.FullContext) {
            try {
                Get-ChildItem -LiteralPath $prepared.ContextPath -File -Recurse -Force -ErrorAction SilentlyContinue |
                    ForEach-Object { $contextBytes += [int64]$_.Length }
            } catch { }
            Invoke-HermesDockerAllFastLine 'docker' ("full-context build enabled: source=$(Format-HermesDockerCommanderMiB $contextBytes); root .dockerignore bypassed")
        } elseif (-not $DockerArgs -or $DockerArgs.Count -eq 0) {
            $prepared = [pscustomobject]@{ Args = @('--help'); TempRoot = $null; FullContext = $false; ContextPath = $null }
        }
        $primaryArg = if ($prepared.Args -and $prepared.Args.Count -gt 0) { [string]$prepared.Args[0] } else { '' }
        $retryDockerStage = ($primaryArg -in @('build','buildx','push','pull','load','manifest'))
        if (Test-HermesDockerAllFastNeedsDaemon -Args @($prepared.Args)) {
            [void](Ensure-HermesDockerCommanderReady -DockerExe $realDocker -Name 'docker')
        }
        $rawCode = @(Invoke-HermesDockerCommanderProcess -DockerExe $realDocker -DockerArgs @($prepared.Args) -Name 'docker' -ContextTotalBytes $contextBytes -RetryUntilSuccess:$retryDockerStage); $code = [int]($rawCode | Select-Object -Last 1)
        $global:LASTEXITCODE = $code
        if ($code -ne 0) {
            Invoke-HermesDockerAllFastLine 'docker' ("exited with code $code; returning to PowerShell shell without exception dump")
            return [int]$code
        }
    } finally {
        if ($prepared -and $prepared.TempRoot -and (Test-Path -LiteralPath $prepared.TempRoot -PathType Container)) { Remove-Item -LiteralPath $prepared.TempRoot -Recurse -Force -ErrorAction SilentlyContinue }
        if($null -eq $oldBuildKit){Remove-Item Env:DOCKER_BUILDKIT -ErrorAction SilentlyContinue}else{$env:DOCKER_BUILDKIT=$oldBuildKit}
        if($null -eq $oldProgress){Remove-Item Env:BUILDKIT_PROGRESS -ErrorAction SilentlyContinue}else{$env:BUILDKIT_PROGRESS=$oldProgress}
        if($null -eq $oldCompose){Remove-Item Env:COMPOSE_PROGRESS -ErrorAction SilentlyContinue}else{$env:COMPOSE_PROGRESS=$oldCompose}
        if($null -eq $oldTimeout){Remove-Item Env:COMPOSE_HTTP_TIMEOUT -ErrorAction SilentlyContinue}else{$env:COMPOSE_HTTP_TIMEOUT=$oldTimeout}
        if($null -eq $oldClientTimeout){Remove-Item Env:DOCKER_CLIENT_TIMEOUT -ErrorAction SilentlyContinue}else{$env:DOCKER_CLIENT_TIMEOUT=$oldClientTimeout}
        if($null -eq $oldCliHints){Remove-Item Env:DOCKER_CLI_HINTS -ErrorAction SilentlyContinue}else{$env:DOCKER_CLI_HINTS=$oldCliHints}
        if($null -eq $oldScanSuggest){Remove-Item Env:DOCKER_SCAN_SUGGEST -ErrorAction SilentlyContinue}else{$env:DOCKER_SCAN_SUGGEST=$oldScanSuggest}
        if($null -eq $oldExperimental){Remove-Item Env:DOCKER_CLI_EXPERIMENTAL -ErrorAction SilentlyContinue}else{$env:DOCKER_CLI_EXPERIMENTAL=$oldExperimental}
    }
}


function global:Invoke-HermesDockerAllFastOriginal {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][string]$Name,[hashtable]$BoundParameters = @{},[object[]]$Arguments = @())
    if (-not $script:HermesDockerAllFastOriginals.ContainsKey($Name)) { throw "original Docker helper not captured: $Name" }
    Invoke-HermesDockerAllFastLine $Name 'start: streaming original helper output in real time'
    & $script:HermesDockerAllFastOriginals[$Name] @BoundParameters @Arguments
    $code = if ($null -eq $global:LASTEXITCODE) { 0 } else { [int]$global:LASTEXITCODE }
    Invoke-HermesDockerAllFastLine $Name ("finished exit=$code; returning to shell now")
    $global:LASTEXITCODE = $code
    if ($code -ne 0) { throw "$Name exited with code $code" }
}

function global:Invoke-HermesDockerChunkedBackupPush {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true,Position=0)][string]$Path,[switch]$PreflightOnly,[ValidateRange(128,4096)][int64]$TargetLayerMiB=4096,[string]$EntryPoint='menu')
    $scriptPath = 'C:\Users\micha\Documents\WindowsPowerShell\mmenu_chunked_push.ps1'
    $oldBuildKit = $env:DOCKER_BUILDKIT; $oldProgress = $env:BUILDKIT_PROGRESS; $oldCompose = $env:COMPOSE_PROGRESS; $oldTimeout = $env:COMPOSE_HTTP_TIMEOUT
    try {
        if (-not (Test-Path -LiteralPath $scriptPath -PathType Leaf)) { throw "Docker chunked push script missing: $scriptPath" }
        $env:DOCKER_BUILDKIT='1'; $env:BUILDKIT_PROGRESS='plain'; $env:COMPOSE_PROGRESS='plain'; $env:COMPOSE_HTTP_TIMEOUT='86400'
        Invoke-HermesDockerAllFastLine $EntryPoint ("start: until-success full-context Docker push; target layer=$TargetLayerMiB MiB; source helper=$scriptPath; generated helper=none")
        $helperArgs = @{ Path=$Path; TargetLayerMiB=$TargetLayerMiB; EntryPoint=$EntryPoint }
        if ($PreflightOnly) { $helperArgs['PreflightOnly'] = $true }
        & $scriptPath @helperArgs
        $code = if ($null -eq $global:LASTEXITCODE) { 0 } else { [int]$global:LASTEXITCODE }
        Invoke-HermesDockerAllFastLine $EntryPoint ("finished exit=$code; returning to shell now")
        $global:LASTEXITCODE = $code
        if ($code -ne 0 -and -not $PreflightOnly) { throw "$EntryPoint chunked Docker helper exited with code $code" }
    } finally {
        try { Remove-Item -LiteralPath 'C:\Temp\hermes-docker-realtime-helper' -Recurse -Force -ErrorAction SilentlyContinue } catch { }
        if($null -eq $oldBuildKit){Remove-Item Env:DOCKER_BUILDKIT -ErrorAction SilentlyContinue}else{$env:DOCKER_BUILDKIT=$oldBuildKit}
        if($null -eq $oldProgress){Remove-Item Env:BUILDKIT_PROGRESS -ErrorAction SilentlyContinue}else{$env:BUILDKIT_PROGRESS=$oldProgress}
        if($null -eq $oldCompose){Remove-Item Env:COMPOSE_PROGRESS -ErrorAction SilentlyContinue}else{$env:COMPOSE_PROGRESS=$oldCompose}
        if($null -eq $oldTimeout){Remove-Item Env:COMPOSE_HTTP_TIMEOUT -ErrorAction SilentlyContinue}else{$env:COMPOSE_HTTP_TIMEOUT=$oldTimeout}
    }
}

