function global:Invoke-HermesDockerCommanderPipelineProcess {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$DockerExe,
        [string[]]$DockerArgs = @(),
        [object[]]$InputObject = @(),
        [string]$Name = 'docker',
        [switch]$RetryUntilSuccess
    )
    function Get-HermesDockerPipelineStallSeconds {
        $seconds = 900
        $raw = [string]$env:HERMES_DOCKER_PIPELINE_STALL_SECONDS
        if (-not [string]::IsNullOrWhiteSpace($raw)) { [void][int]::TryParse($raw,[ref]$seconds) }
        return [Math]::Max(120,[Math]::Min(7200,[int]$seconds))
    }
    function Wait-HermesDockerPipelineRetry([string]$Name,[string]$Phase,[datetime]$Started,[int]$Seconds,[int]$Attempt,[string]$Detail) {
        $until = (Get-Date).AddSeconds([Math]::Max(1,$Seconds))
        while ((Get-Date) -lt $until) {
            $remaining = [int][Math]::Ceiling(($until - (Get-Date)).TotalSeconds)
            Write-HermesDockerCommanderDashboard -Name $Name -Phase "$Phase-retry" -Started $Started -DoneBytes 0 -TotalBytes 0 -Detail ("retry attempt {0} in {1}s; {2}" -f ($Attempt + 1),$remaining,$Detail)
            Start-Sleep -Milliseconds 250
        }
        Write-Host ''
    }
    if ([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe -PathType Leaf)) {
        Invoke-HermesDockerAllFastLine $Name ("docker.exe missing: $DockerExe; returning to PowerShell shell without exception dump")
        $global:LASTEXITCODE = 1
        return 1
    }
    $phase = if ($DockerArgs.Count -ge 1) { [string]$DockerArgs[0] } else { 'pipeline' }
    $inputText = ''
    if ($InputObject) {
        $inputText = (($InputObject | ForEach-Object { if ($null -eq $_) { '' } else { [string]$_ } }) -join [Environment]::NewLine)
        if ($InputObject.Count -gt 0) { $inputText += [Environment]::NewLine }
    }
    $inputBytes = [int64]([Text.Encoding]::UTF8.GetByteCount($inputText))
    $totalBytes = $inputBytes
    $attempt = 0
    while ($true) {
        $attempt++
        $started = Get-Date
        $doneBytes = 0L
        $lastDetail = 'stdin queued'
        $lastOutput = Get-Date
        $queue = [System.Collections.Queue]::Synchronized((New-Object System.Collections.Queue))

        Write-Host ''
        Invoke-HermesDockerAllFastLine $Name ("pipeline attempt={0}{1} command=docker {2}" -f $attempt,$(if($RetryUntilSuccess){'/until-success'}else{''}),($DockerArgs -join ' '))
        Write-HermesDockerCommanderDashboard -Name $Name -Phase $phase -Started $started -DoneBytes 0 -TotalBytes $totalBytes -Detail 'stdin queued; Docker process starting'

        $psi = New-Object Diagnostics.ProcessStartInfo
        $psi.FileName = $DockerExe
        $psi.Arguments = ((@($DockerArgs) | ForEach-Object {
            $v = [string]$_
            if ($v -eq '') { '""' }
            elseif ($v -match '[\s"`]') { '"' + $v.Replace('\','\\').Replace('"','\"') + '"' }
            else { $v }
        }) -join ' ')
        $psi.UseShellExecute = $false
        $psi.CreateNoWindow = $true
        $psi.RedirectStandardInput = $true
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $dockerDir = Split-Path -Parent $DockerExe
        if ($dockerDir -and (Test-Path -LiteralPath $dockerDir -PathType Container)) {
            $childPath = [string]$psi.EnvironmentVariables['PATH']
            if ($childPath -notlike "*$dockerDir*") { $psi.EnvironmentVariables['PATH'] = "$dockerDir;$childPath" }
        }
        $psi.EnvironmentVariables['DOCKER_BUILDKIT'] = '1'
        $psi.EnvironmentVariables['BUILDKIT_PROGRESS'] = 'plain'
        $psi.EnvironmentVariables['COMPOSE_PROGRESS'] = 'plain'
        $psi.EnvironmentVariables['COMPOSE_HTTP_TIMEOUT'] = '86400'
        $psi.EnvironmentVariables['DOCKER_CLIENT_TIMEOUT'] = '86400'
        $psi.EnvironmentVariables['DOCKER_CLI_HINTS'] = 'false'
        $psi.EnvironmentVariables['DOCKER_SCAN_SUGGEST'] = 'false'
        $psi.EnvironmentVariables['DOCKER_CLI_EXPERIMENTAL'] = 'enabled'

        $p = New-Object Diagnostics.Process
        $p.StartInfo = $psi
        $outAction = {
            if ($EventArgs.Data) {
                $Event.MessageData.Enqueue([string]$EventArgs.Data)
            }
        }
        $errAction = {
            if ($EventArgs.Data) {
                $Event.MessageData.Enqueue([string]$EventArgs.Data)
            }
        }
        $outSub = $null
        $errSub = $null
        $code = 1
        try {
            $outSub = Register-ObjectEvent -InputObject $p -EventName OutputDataReceived -Action $outAction -MessageData $queue
            $errSub = Register-ObjectEvent -InputObject $p -EventName ErrorDataReceived -Action $errAction -MessageData $queue
            [void]$p.Start()
            $p.BeginOutputReadLine()
            $p.BeginErrorReadLine()
            try {
                $p.StandardInput.Write($inputText)
                $p.StandardInput.Close()
                $doneBytes = $inputBytes
                $lastDetail = if ($inputBytes -gt 0) { 'stdin transferred to Docker process' } else { 'stdin closed' }
            } catch {
                try { $p.StandardInput.Close() } catch { }
                $lastDetail = 'stdin closed after write error'
            }
            $lastRender = Get-Date
            while (-not $p.HasExited) {
                while ($queue.Count -gt 0) {
                    $line = [string]$queue.Dequeue()
                    if (-not [string]::IsNullOrWhiteSpace($line)) {
                        $lastDetail = $line
                        $lastOutput = Get-Date
                        Write-Host $line
                    }
                }
                if (((Get-Date) - $lastRender).TotalMilliseconds -ge 250) {
                    Write-HermesDockerCommanderDashboard -Name $Name -Phase $phase -Started $started -DoneBytes $doneBytes -TotalBytes $totalBytes -Detail $lastDetail
                    $lastRender = Get-Date
                }
                if ($RetryUntilSuccess -and $doneBytes -ge $totalBytes -and ((Get-Date) - $lastOutput).TotalSeconds -ge (Get-HermesDockerPipelineStallSeconds)) {
                    Invoke-HermesDockerAllFastLine $Name ("pipeline stall-guard: no Docker output for {0}s after stdin transfer; aborting attempt for retry" -f (Get-HermesDockerPipelineStallSeconds))
                    try { $p.Kill() } catch { }
                    break
                }
                Start-Sleep -Milliseconds 50
            }
            try { $p.WaitForExit() } catch { }
            Start-Sleep -Milliseconds 50
            while ($queue.Count -gt 0) {
                $line = [string]$queue.Dequeue()
                if (-not [string]::IsNullOrWhiteSpace($line)) {
                    $lastDetail = $line
                    $lastOutput = Get-Date
                    Write-Host $line
                }
            }
            $code = if ($p.HasExited) { [int]$p.ExitCode } else { 1 }
            if ($code -eq 0 -and $totalBytes -gt 0) { $doneBytes = $totalBytes }
            Write-Host ''
            Write-HermesDockerCommanderDashboard -Name $Name -Phase $phase -Started $started -DoneBytes $doneBytes -TotalBytes $totalBytes -Detail "exit=$code"
            Write-Host ''
        } finally {
            try { if ($outSub) { Unregister-Event -SubscriptionId $outSub.Id -ErrorAction SilentlyContinue; Remove-Job -Id $outSub.Id -Force -ErrorAction SilentlyContinue } } catch { }
            try { if ($errSub) { Unregister-Event -SubscriptionId $errSub.Id -ErrorAction SilentlyContinue; Remove-Job -Id $errSub.Id -Force -ErrorAction SilentlyContinue } } catch { }
            try { if ($p -and -not $p.HasExited) { $p.Kill() } } catch { }
            try { if ($p) { $p.Dispose() } } catch { }
        }
        if ($code -eq 0 -or -not $RetryUntilSuccess) { return $code }
        Invoke-HermesDockerAllFastLine $Name ("pipeline recoverable Docker failure exit={0}; retrying until success unless manually stopped" -f $code)
        Wait-HermesDockerPipelineRetry -Name $Name -Phase $phase -Started $started -Seconds 10 -Attempt $attempt -Detail ("exit={0}" -f $code)
    }
}


function global:Invoke-HermesDockerCommanderProcess {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory=$true)][string]$DockerExe,
        [string[]]$DockerArgs = @(),
        [string]$Name = 'docker',
        [int64]$ContextTotalBytes = 0,
        [switch]$RetryUntilSuccess
    )
    function ConvertTo-HermesDockerProcessArgument([string]$Value) {
        if ($null -eq $Value) { return '""' }
        $text = [string]$Value
        if ($text.Length -eq 0) { return '""' }
        if ($text -notmatch '[\s"&|<>]') { return $text }
        return '"' + ($text -replace '"','\"') + '"'
    }
    function Format-HermesDockerCommanderElapsed([TimeSpan]$Elapsed) {
        if ($Elapsed.TotalHours -ge 1) { return ('{0:hh\:mm\:ss}' -f $Elapsed) }
        return ('{0:mm\:ss}' -f $Elapsed)
    }
    function Get-HermesDockerPushImageName([string[]]$DockerArgList) {
        if (-not $DockerArgList -or $DockerArgList.Count -eq 0) { return '' }
        $normalized = New-Object System.Collections.Generic.List[string]
        foreach ($rawArg in @($DockerArgList)) {
            $argText = [string]$rawArg
            if ([string]::IsNullOrWhiteSpace($argText)) { continue }
            if ($argText -match '\s') {
                foreach ($match in [regex]::Matches($argText, "(?:""([^""]*)""|'([^']*)'|(\S+))")) {
                    if ($match.Groups[1].Success) { [void]$normalized.Add($match.Groups[1].Value) }
                    elseif ($match.Groups[2].Success) { [void]$normalized.Add($match.Groups[2].Value) }
                    else { [void]$normalized.Add($match.Groups[3].Value) }
                }
            } else {
                [void]$normalized.Add($argText)
            }
        }
        $argItems = [string[]]$normalized.ToArray()
        if (-not $argItems -or $argItems.Count -eq 0) { return '' }
        $pushIndex = -1
        for ($i = 0; $i -lt $argItems.Count; $i++) {
            if ([string]$argItems[$i] -ieq 'push') { $pushIndex = $i; break }
        }
        if ($pushIndex -lt 0) { return '' }
        for ($i = $pushIndex + 1; $i -lt $argItems.Count; $i++) {
            $arg = [string]$argItems[$i]
            if ([string]::IsNullOrWhiteSpace($arg)) { continue }
            if ($arg -like '--*') {
                if ($arg -notlike '*=*' -and $i + 1 -lt $argItems.Count -and [string]$argItems[$i + 1] -notlike '-*') { $i++ }
                continue
            }
            if ($arg -like '-*') { continue }
            return $arg
        }
        return ''
    }
    function Get-HermesDockerPushImageBytes([string]$DockerExe,[string]$ImageName) {
        if ([string]::IsNullOrWhiteSpace($ImageName)) { return 0L }
        $p = $null
        try {
            $p = New-Object System.Diagnostics.Process
            $psi = New-Object System.Diagnostics.ProcessStartInfo
            $psi.FileName = $DockerExe
            $psi.Arguments = 'image inspect --format "{{.Size}}" ' + (ConvertTo-HermesDockerProcessArgument $ImageName)
            $psi.UseShellExecute = $false
            $psi.RedirectStandardOutput = $true
            $psi.RedirectStandardError = $true
            $psi.CreateNoWindow = $true
            $p.StartInfo = $psi
            [void]$p.Start()
            if (-not $p.WaitForExit(5000)) {
                try { $p.Kill() } catch {}
                return 0L
            }
            $sizeText = $p.StandardOutput.ReadLine()
            $size = 0L
            if ([int64]::TryParse(([string]$sizeText).Trim(),[ref]$size) -and $size -gt 0) { return $size }
        } catch {}
        finally {
            try { if ($p) { $p.Dispose() } } catch {}
        }
        return 0L
    }
    function Get-HermesDockerNetworkSentBytes {
        try {
            $total = 0L
            foreach ($adapter in [System.Net.NetworkInformation.NetworkInterface]::GetAllNetworkInterfaces()) {
                if ($adapter.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Loopback) { continue }
                if ($adapter.NetworkInterfaceType -eq [System.Net.NetworkInformation.NetworkInterfaceType]::Tunnel) { continue }
                $stats = $adapter.GetIPv4Statistics()
                if ($null -ne $stats) { $total += [int64]$stats.BytesSent }
            }
            return $total
        } catch {
            return -1L
        }
    }
    function Wait-HermesDockerCommanderRetry([string]$Name,[string]$Phase,[datetime]$Started,[int]$Seconds,[int]$Attempt,[string]$Detail) {
        $until = (Get-Date).AddSeconds([Math]::Max(1,$Seconds))
        while ((Get-Date) -lt $until) {
            $remaining = [int][Math]::Ceiling(($until - (Get-Date)).TotalSeconds)
            Write-HermesDockerCommanderDashboard -Name $Name -Phase $Phase -Started $Started -DoneBytes 0 -TotalBytes 0 -Detail ("retry attempt {0} in {1}s; {2}" -f ($Attempt + 1),$remaining,$Detail)
            Start-Sleep -Milliseconds 250
        }
        Write-Host ''
    }
    function Get-HermesDockerCommanderStallSeconds {
        $seconds = 120
        $raw = [string]$env:HERMES_DOCKER_STALL_SECONDS
        if (-not [string]::IsNullOrWhiteSpace($raw)) { [void][int]::TryParse($raw,[ref]$seconds) }
        return [Math]::Max(30,[Math]::Min(3600,[int]$seconds))
    }
    function Get-HermesDockerCommanderMinBytesPerSecond {
        $bytes = [int64](20MB)
        $raw = [string]$env:HERMES_DOCKER_MIN_BYTES_PER_SECOND
        if (-not [string]::IsNullOrWhiteSpace($raw)) { [void][int64]::TryParse($raw,[ref]$bytes) }
        return [Math]::Max([int64](1MB),[Math]::Min([int64](1GB),[int64]$bytes))
    }
    function Write-HermesDockerPushSummary([datetime]$Started) {
        $now = Get-Date
        $totalLayers = $script:HermesDockerCommanderPushLayerStatus.Count
        $doneCount = 0
        $uploadingCount = 0
        $waitingCount = 0
        $otherCount = 0
        $knownDone = 0L
        $knownTotal = 0L
        foreach ($layer in $script:HermesDockerCommanderPushLayerStatus.Keys) {
            $status = [string]$script:HermesDockerCommanderPushLayerStatus[$layer]
            if ($script:HermesDockerCommanderPushLayerDone.ContainsKey($layer)) { $knownDone += [int64]$script:HermesDockerCommanderPushLayerDone[$layer] }
            if ($script:HermesDockerCommanderPushLayerTotal.ContainsKey($layer)) { $knownTotal += [int64]$script:HermesDockerCommanderPushLayerTotal[$layer] }
            if ($status -match '(?i)\b(Pushed|Mounted from|Layer already exists|Already exists)\b') { $doneCount++ }
            elseif ($status -match '(?i)\b(Pushing|Preparing)\b') { $uploadingCount++ }
            elseif ($status -match '(?i)\bWaiting\b') { $waitingCount++ }
            else { $otherCount++ }
        }
        $estimatedTotal = [int64]$script:HermesDockerCommanderPushImageBytes
        $estimatedDone = 0L
        if ($estimatedTotal -gt 0) {
            $denominator = [Math]::Max(1,$totalLayers)
            $weightedDone = [double]$doneCount
            if ($uploadingCount -gt 0) { $weightedDone += ([double]$uploadingCount * 0.5) }
            $estimatedDone = [int64]([Math]::Min([double]$estimatedTotal,[double]$estimatedTotal * $weightedDone / [double]$denominator))
        }
        $knownPct = 0.0
        $knownBytes = if ($knownTotal -gt 0) {
            $pct = [Math]::Min([double]100.0,[Math]::Round(100.0 * [double]$knownDone / [Math]::Max([double]1.0,[double]$knownTotal),2))
            $knownPct = $pct
            ('docker-bytes {0:N2}% {1}/{2}' -f $pct,(Format-HermesDockerCommanderMiB $knownDone),(Format-HermesDockerCommanderMiB $knownTotal))
        } elseif ($estimatedTotal -gt 0) {
            ('docker-layer-bytes=not-exposed; local-image-size={0}' -f (Format-HermesDockerCommanderMiB $estimatedTotal))
        } else {
            'image-size-unavailable 0.00% 0.00 MiB/0.00 MiB'
        }
        $networkBytes = Get-HermesDockerNetworkSentBytes
        $networkText = 'sent=unavailable'
        if ($networkBytes -ge 0 -and $script:HermesDockerCommanderPushNetStartBytes -ge 0) {
            $sessionBytes = [Math]::Max([int64]0,([int64]$networkBytes - [int64]$script:HermesDockerCommanderPushNetStartBytes))
            $lastBytes = [int64]$script:HermesDockerCommanderPushNetLastBytes
            $lastSample = [datetime]$script:HermesDockerCommanderPushNetLastSample
            $deltaBytes = [Math]::Max([int64]0,([int64]$networkBytes - $lastBytes))
            $deltaSeconds = [Math]::Max(0.001,($now - $lastSample).TotalSeconds)
            $rateBytes = [int64]([double]$deltaBytes / $deltaSeconds)
            $networkPct = if ($estimatedTotal -gt 0) { [Math]::Min([double]100.0,[Math]::Round(100.0 * [double]$sessionBytes / [Math]::Max([double]1.0,[double]$estimatedTotal),2)) } else { 0.0 }
            $networkText = if ($estimatedTotal -gt 0 -and $knownTotal -le 0) {
                ('sent~{0:N2}% {1}/{2}; rate={3}/s' -f $networkPct,(Format-HermesDockerCommanderMiB $sessionBytes),(Format-HermesDockerCommanderMiB $estimatedTotal),(Format-HermesDockerCommanderMiB $rateBytes))
            } else {
                ('sent={0}; rate={1}/s' -f (Format-HermesDockerCommanderMiB $sessionBytes),(Format-HermesDockerCommanderMiB $rateBytes))
            }
            $script:HermesDockerCommanderPushNetLastBytes = [int64]$networkBytes
            $script:HermesDockerCommanderPushNetLastSample = $now
        }
        $sinceChange = [int][Math]::Max(0,($now - $script:HermesDockerCommanderPushLastChange).TotalSeconds)
        $elapsed = Format-HermesDockerCommanderElapsed ($now - $Started)
        $states = New-Object System.Collections.Generic.List[string]
        foreach ($entry in ($script:HermesDockerCommanderPushLayerStatus.GetEnumerator() | Sort-Object Name | Select-Object -First 4)) {
            $layer = [string]$entry.Name
            $short = if ($layer.Length -gt 12) { $layer.Substring(0,12) } else { $layer }
            $status = ([string]$entry.Value) -replace '\s+',' '
            $age = if ($script:HermesDockerCommanderPushLayerChanged.ContainsKey($layer)) { [int][Math]::Max(0,($now - ([datetime]$script:HermesDockerCommanderPushLayerChanged[$layer])).TotalSeconds) } else { 0 }
            [void]$states.Add(('{0}={1} age={2}s' -f $short,$status,$age))
        }
        $silence = if ($knownTotal -eq 0 -and $estimatedTotal -gt 0 -and $waitingCount -gt 0 -and $uploadingCount -eq 0) {
            '; registry waiting'
        } elseif ($uploadingCount -gt 0 -and $knownTotal -eq 0) {
            '; upload active'
        } elseif ($knownTotal -eq 0 -and $estimatedTotal -le 0) {
            '; image size unavailable'
        } else {
            ''
        }
        Invoke-HermesDockerAllFastLine $script:HermesDockerCommanderName (
            'push {0}; layers {1}/{2} done, {3} uploading, {4} waiting; {5}; {6}; quiet={7}s; suppressed={8}{9}; {10}' -f
            $elapsed,$doneCount,$totalLayers,$uploadingCount,$waitingCount,$knownBytes,$networkText,$sinceChange,$script:HermesDockerCommanderPushSuppressedWaiting,$silence,($states -join '; ')
        )
        $script:HermesDockerCommanderPushLastSummary = Get-Date
    }
    function Update-HermesDockerPushStateLine([string]$Line) {
        $s = ([string]$Line).Trim()
        if ([string]::IsNullOrWhiteSpace($s)) { return $true }
        if ($s -match '(?i)\bdigest:\s*sha256:') { return $false }
        if ($s -notmatch '^([A-Za-z0-9][A-Za-z0-9_.-]{5,127}):\s+(.+)$') { return $false }
        $layer = [string]$matches[1]
        $status = ([string]$matches[2]).Trim() -replace '\s+',' '
        $now = Get-Date
        if (-not $script:HermesDockerCommanderPushLayerSeen.ContainsKey($layer)) { $script:HermesDockerCommanderPushLayerSeen[$layer] = $now }
        if ($status -match '(?i)([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)\s*/\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)') {
            $script:HermesDockerCommanderPushLayerDone[$layer] = Convert-HermesDockerCommanderBytes ([double]$matches[1]) $matches[2]
            $script:HermesDockerCommanderPushLayerTotal[$layer] = Convert-HermesDockerCommanderBytes ([double]$matches[3]) $matches[4]
            $script:HermesDockerCommanderLastDone = [int64](($script:HermesDockerCommanderPushLayerDone.Values | Measure-Object -Sum).Sum)
            $script:HermesDockerCommanderLastTotal = [int64](($script:HermesDockerCommanderPushLayerTotal.Values | Measure-Object -Sum).Sum)
        }
        $previous = if ($script:HermesDockerCommanderPushLayerStatus.ContainsKey($layer)) { [string]$script:HermesDockerCommanderPushLayerStatus[$layer] } else { '' }
        $script:HermesDockerCommanderPushLayerStatus[$layer] = $status
        if ($previous -ne $status) {
            $script:HermesDockerCommanderPushLayerChanged[$layer] = $now
            $script:HermesDockerCommanderPushLastChange = $now
            $script:HermesDockerCommanderLastDetail = ('layer {0}: {1}' -f $layer,$status)
            Write-Host ''
            Invoke-HermesDockerAllFastLine $script:HermesDockerCommanderName ('push-layer {0}: {1}' -f $layer,$status)
            return $true
        }
        if ($status -match '(?i)^Waiting$') { $script:HermesDockerCommanderPushSuppressedWaiting++ }
        return $true
    }
    function Update-HermesDockerCommanderProgressLine([string]$Line) {
        if ([string]::IsNullOrEmpty($Line)) { return }
        $script:HermesDockerCommanderLastOutput = Get-Date
        $s = [string]$Line
        $matched = $false
        if ($script:HermesDockerCommanderIsPush -and (Update-HermesDockerPushStateLine $s)) { return }
        if ($script:HermesDockerCommanderIsPush) {
            Write-Host ''
            if ($s -match '(?i)(digest:|ERROR|failed|warning|denied|unauthorized|timeout|refused)') {
                Write-Host $s -ForegroundColor DarkGray
            } else {
                Write-Host $s -ForegroundColor Gray
            }
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
            return
        }
        if ($s -match 'archived_bytes=(\d+)\s+total_bytes=(\d+)\s+percent=([0-9.]+).*current_layer=([^\s]+)(?:.*current_file=([^\s]+))?') {
            $script:HermesDockerCommanderLastDone = [int64]$matches[1]
            $script:HermesDockerCommanderLastTotal = [int64]$matches[2]
            $script:HermesDockerCommanderLastDetail = if ($matches[5]) { "$($matches[4]) $($matches[5])" } else { $matches[4] }
            $script:HermesDockerCommanderPhase = 'tar archive'
            $matched = $true
        } elseif ($s -match '(?i)transferring context:\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)') {
            $script:HermesDockerCommanderLastDone = Convert-HermesDockerCommanderBytes ([double]$matches[1]) $matches[2]
            if ($script:HermesDockerCommanderContextTotalBytes -gt 0) {
                $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderContextTotalBytes
                if ($script:HermesDockerCommanderLastDone -gt $script:HermesDockerCommanderLastTotal) { $script:HermesDockerCommanderLastDone = $script:HermesDockerCommanderLastTotal }
            } elseif ($script:HermesDockerCommanderLastDone -gt $script:HermesDockerCommanderLastTotal) { $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderLastDone }
            $script:HermesDockerCommanderLastDetail = 'build context'
            $script:HermesDockerCommanderPhase = 'build context'
            $matched = $true
        } elseif ($s -match '(?i)(sha256:[a-f0-9]+|[A-Za-z0-9_.-]+):?.*?([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)\s*/\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)') {
            $id = $matches[1]
            $script:HermesDockerCommanderLayerDone[$id] = Convert-HermesDockerCommanderBytes ([double]$matches[2]) $matches[3]
            $script:HermesDockerCommanderLayerTotal[$id] = Convert-HermesDockerCommanderBytes ([double]$matches[4]) $matches[5]
            $script:HermesDockerCommanderLastDone = [int64](($script:HermesDockerCommanderLayerDone.Values | Measure-Object -Sum).Sum)
            $script:HermesDockerCommanderLastTotal = [int64](($script:HermesDockerCommanderLayerTotal.Values | Measure-Object -Sum).Sum)
            $script:HermesDockerCommanderLastDetail = "layer $id"
            $script:HermesDockerCommanderPhase = if ($script:HermesDockerCommanderArgs -contains 'pull') { 'pull' } elseif ($script:HermesDockerCommanderArgs -contains 'push' -or $script:HermesDockerCommanderArgs -contains '--push') { 'push' } else { $script:HermesDockerCommanderPhase }
            $matched = $true
        } elseif ($s -match '(?i)exporting layers') {
            if ($script:HermesDockerCommanderContextTotalBytes -gt 0) {
                $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderContextTotalBytes
                $targetPct = if ($s -match '(?i)\bdone\b') { 85.0 } else { 70.0 }
                $phaseBytes = [int64]([double]$script:HermesDockerCommanderLastTotal * $targetPct / 100.0)
                if ($script:HermesDockerCommanderLastDone -lt $phaseBytes) { $script:HermesDockerCommanderLastDone = $phaseBytes }
            }
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
            $script:HermesDockerCommanderPhase = 'export layers'
            $matched = $true
        } elseif ($s -match '(?i)pushing layers') {
            if ($script:HermesDockerCommanderContextTotalBytes -gt 0) {
                $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderContextTotalBytes
                $targetPct = if ($s -match '(?i)\bdone\b') { 97.0 } else { 90.0 }
                $phaseBytes = [int64]([double]$script:HermesDockerCommanderLastTotal * $targetPct / 100.0)
                if ($script:HermesDockerCommanderLastDone -lt $phaseBytes) { $script:HermesDockerCommanderLastDone = $phaseBytes }
            }
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
            $script:HermesDockerCommanderPhase = 'push layers'
            $matched = $true
        } elseif ($s -match '(?i)pushing manifest') {
            if ($script:HermesDockerCommanderContextTotalBytes -gt 0) {
                $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderContextTotalBytes
                $phaseBytes = [int64]([double]$script:HermesDockerCommanderLastTotal * 99.0 / 100.0)
                if ($script:HermesDockerCommanderLastDone -lt $phaseBytes) { $script:HermesDockerCommanderLastDone = $phaseBytes }
            }
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
            $script:HermesDockerCommanderPhase = 'push manifest'
            $matched = $true
        } elseif ($s -match '(?i)(DONE|ERROR|failed|warning|success|digest:|writing image|naming to|exporting|importing|extracting|pull complete|pushed)') {
            Write-Host ''
            Write-Host $s -ForegroundColor DarkGray
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
        } else {
            Write-Host ''
            Write-Host $s -ForegroundColor Gray
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
        }
        if ($matched -or ((Get-Date) - $script:HermesDockerCommanderLastRender).TotalMilliseconds -ge 750) {
            Write-HermesDockerCommanderDashboard -Name $script:HermesDockerCommanderName -Phase $script:HermesDockerCommanderPhase -Started $script:HermesDockerCommanderStarted -DoneBytes $script:HermesDockerCommanderLastDone -TotalBytes $script:HermesDockerCommanderLastTotal -Detail $script:HermesDockerCommanderLastDetail
            $script:HermesDockerCommanderLastRender = Get-Date
        }
    }
    function Add-HermesDockerCommanderText([string]$Text,[string]$CarryName) {
        if ([string]::IsNullOrEmpty($Text)) { return }
        $combined = [string](Get-Variable -Name $CarryName -Scope Script -ValueOnly -ErrorAction SilentlyContinue) + $Text
        $parts = [regex]::Split($combined, "`r`n|`n|`r")
        if ($combined -match "(`r`n|`n|`r)$") {
            for($i=0; $i -lt $parts.Count; $i++){ if($parts[$i].Length -gt 0){ Update-HermesDockerCommanderProgressLine $parts[$i] } }
            Set-Variable -Name $CarryName -Scope Script -Value ''
        } else {
            for($i=0; $i -lt ($parts.Count - 1); $i++){ if($parts[$i].Length -gt 0){ Update-HermesDockerCommanderProgressLine $parts[$i] } }
            Set-Variable -Name $CarryName -Scope Script -Value ([string]$parts[$parts.Count - 1])
        }
    }
    function Complete-HermesDockerCommanderRead($Stream,$AsyncResult,[byte[]]$Buffer,[string]$CarryName,[ref]$Done) {
        if ($null -eq $AsyncResult) { $Done.Value = $true; return $null }
        if (-not $AsyncResult.IsCompleted) { return $AsyncResult }
        try {
            $count = $Stream.EndRead($AsyncResult)
            if ($count -le 0) { $Done.Value = $true; return $null }
            $text = [Text.Encoding]::UTF8.GetString($Buffer,0,$count)
            Add-HermesDockerCommanderText -Text $text -CarryName $CarryName
            return $Stream.BeginRead($Buffer,0,$Buffer.Length,$null,$null)
        } catch {
            $Done.Value = $true
            return $null
        }
    }
    $attempt = 0
    while ($true) {
        $attempt++
        $started = Get-Date
        $phase = if ($DockerArgs.Count -ge 1) { [string]$DockerArgs[0] } else { 'docker' }
        if ($DockerArgs.Count -ge 2 -and $DockerArgs[0] -ieq 'buildx') { $phase = 'buildx ' + $DockerArgs[1] }
        $isPush = ($DockerArgs -contains 'push' -or $DockerArgs -contains '--push')
        $pushImageName = if ($isPush) { Get-HermesDockerPushImageName $DockerArgs } else { '' }
        $pushImageBytes = if ($isPush) { Get-HermesDockerPushImageBytes $DockerExe $pushImageName } else { 0L }
        Write-Host ''
        $shownCommand = if ($DockerArgs -and $DockerArgs.Count -gt 0) { "docker $($DockerArgs -join ' ')" } else { $DockerExe }
        Invoke-HermesDockerAllFastLine $Name ("attempt=$attempt command=$shownCommand")
        if ($isPush) {
            $imageSizeText = if ($pushImageBytes -gt 0) { Format-HermesDockerCommanderMiB $pushImageBytes } else { '0.00 MiB' }
            Invoke-HermesDockerAllFastLine $Name ("push progress mode: real-time network MiB active; image={0}; local-image-size={1}; exact Docker push bytes used when Docker exposes them; live network-sent MiB/rate shown every 250ms; repeated Waiting spam suppressed" -f $pushImageName,$imageSizeText)
        }
        $p = New-Object System.Diagnostics.Process
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $DockerExe
        $psi.Arguments = ((@($DockerArgs) | ForEach-Object { ConvertTo-HermesDockerProcessArgument ([string]$_) }) -join ' ')
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true
        $psi.WorkingDirectory = (Get-Location).ProviderPath
        $dockerDir = Split-Path -Parent $DockerExe
        if ($dockerDir -and (Test-Path -LiteralPath $dockerDir -PathType Container)) {
            $childPath = [string]$psi.EnvironmentVariables['PATH']
            if ($childPath -notlike "*$dockerDir*") { $psi.EnvironmentVariables['PATH'] = "$dockerDir;$childPath" }
        }
        $psi.EnvironmentVariables['DOCKER_BUILDKIT'] = '1'
        $psi.EnvironmentVariables['BUILDKIT_PROGRESS'] = 'plain'
        $psi.EnvironmentVariables['COMPOSE_PROGRESS'] = 'plain'
        $psi.EnvironmentVariables['COMPOSE_HTTP_TIMEOUT'] = '86400'
        $psi.EnvironmentVariables['DOCKER_CLIENT_TIMEOUT'] = '86400'
        $psi.EnvironmentVariables['DOCKER_CLI_HINTS'] = 'false'
        $psi.EnvironmentVariables['DOCKER_SCAN_SUGGEST'] = 'false'
        $psi.EnvironmentVariables['DOCKER_CLI_EXPERIMENTAL'] = 'enabled'
        $p.StartInfo = $psi
        try {
            $script:HermesDockerCommanderName = $Name
            $script:HermesDockerCommanderStarted = $started
            $script:HermesDockerCommanderContextTotalBytes = $ContextTotalBytes
            $script:HermesDockerCommanderArgs = @($DockerArgs)
            $script:HermesDockerCommanderIsPush = [bool]$isPush
            $script:HermesDockerCommanderLayerDone = @{}
            $script:HermesDockerCommanderLayerTotal = @{}
            $script:HermesDockerCommanderPushLayerStatus = @{}
            $script:HermesDockerCommanderPushLayerDone = @{}
            $script:HermesDockerCommanderPushLayerTotal = @{}
            $script:HermesDockerCommanderPushLayerSeen = @{}
            $script:HermesDockerCommanderPushLayerChanged = @{}
            $script:HermesDockerCommanderPushLastChange = $started
            $script:HermesDockerCommanderPushLastSummary = [datetime]::MinValue
            $script:HermesDockerCommanderPushImageName = $pushImageName
            $script:HermesDockerCommanderPushImageBytes = [int64]$pushImageBytes
            $script:HermesDockerCommanderPushSuppressedWaiting = 0
            $script:HermesDockerCommanderPushNetStartBytes = if ($isPush) { Get-HermesDockerNetworkSentBytes } else { -1L }
            $script:HermesDockerCommanderPushNetLastBytes = [int64]$script:HermesDockerCommanderPushNetStartBytes
            $script:HermesDockerCommanderPushNetLastSample = Get-Date
            $script:HermesDockerCommanderStdoutCarry = ''
            $script:HermesDockerCommanderStderrCarry = ''
            $script:HermesDockerCommanderLastOutput = Get-Date
            $script:HermesDockerCommanderLastRender = Get-Date
            $script:HermesDockerCommanderLastHeartbeatLine = Get-Date
            $script:HermesDockerCommanderLastDetail = ''
            $script:HermesDockerCommanderLastDone = 0L
            $script:HermesDockerCommanderLastTotal = $ContextTotalBytes
            $script:HermesDockerCommanderPhase = $phase
            $stallSeconds = Get-HermesDockerCommanderStallSeconds
            $minBytesPerSecond = Get-HermesDockerCommanderMinBytesPerSecond
            $lastObservedBytes = 0L
            $lastObservedAt = Get-Date
            $lastRateWarnAt = [datetime]::MinValue
            [void]$p.Start()
            $outBuffer = New-Object byte[] 65536
            $errBuffer = New-Object byte[] 65536
            $outDone = $false
            $errDone = $false
            $outAsync = $p.StandardOutput.BaseStream.BeginRead($outBuffer,0,$outBuffer.Length,$null,$null)
            $errAsync = $p.StandardError.BaseStream.BeginRead($errBuffer,0,$errBuffer.Length,$null,$null)
            $exitSeenAt = $null
            while (-not ($p.HasExited -and $outDone -and $errDone)) {
                $outAsync = Complete-HermesDockerCommanderRead $p.StandardOutput.BaseStream $outAsync $outBuffer 'HermesDockerCommanderStdoutCarry' ([ref]$outDone)
                $errAsync = Complete-HermesDockerCommanderRead $p.StandardError.BaseStream $errAsync $errBuffer 'HermesDockerCommanderStderrCarry' ([ref]$errDone)
                if ($p.HasExited) {
                    if ($null -eq $exitSeenAt) { $exitSeenAt = Get-Date }
                    if (((Get-Date) - $exitSeenAt).TotalMilliseconds -ge 2000) {
                        $outDone = $true
                        $errDone = $true
                        break
                    }
                }
                if (-not $isPush -and ((Get-Date) - $script:HermesDockerCommanderLastRender).TotalMilliseconds -ge 250) {
                    $renderDetail = $script:HermesDockerCommanderLastDetail
                    if (((Get-Date) - $script:HermesDockerCommanderLastOutput).TotalSeconds -ge 2) {
                        $renderDetail = if([string]::IsNullOrWhiteSpace($script:HermesDockerCommanderLastDetail)) { 'active; waiting for Docker engine output' } else { "active; waiting for Docker engine output; $script:HermesDockerCommanderLastDetail" }
                    }
                    Write-HermesDockerCommanderDashboard -Name $Name -Phase $script:HermesDockerCommanderPhase -Started $started -DoneBytes $script:HermesDockerCommanderLastDone -TotalBytes $script:HermesDockerCommanderLastTotal -Detail $renderDetail
                    $script:HermesDockerCommanderLastRender = Get-Date
                }
                $heartbeatMilliseconds = if ($isPush) { 250 } else { 2000 }
                if (((Get-Date) - $script:HermesDockerCommanderLastHeartbeatLine).TotalMilliseconds -ge $heartbeatMilliseconds) {
                    if ($isPush) {
                        Write-HermesDockerPushSummary -Started $started
                    } else {
                        $heartbeatDetail = $script:HermesDockerCommanderLastDetail
                        if (((Get-Date) - $script:HermesDockerCommanderLastOutput).TotalSeconds -ge 2) {
                            $heartbeatDetail = if([string]::IsNullOrWhiteSpace($script:HermesDockerCommanderLastDetail)) { 'active; waiting for Docker engine output' } else { "active; waiting for Docker engine output; $script:HermesDockerCommanderLastDetail" }
                        }
                        $heartbeatState = if ([string]::IsNullOrWhiteSpace($heartbeatDetail)) { 'active' } elseif ($heartbeatDetail -like 'active;*') { $heartbeatDetail } else { "active; $heartbeatDetail" }
                        $elapsedSeconds = [int]((Get-Date) - $started).TotalSeconds
                        Write-Host ''
                        if ($script:HermesDockerCommanderLastTotal -gt 0) {
                            $pct = [Math]::Min(100.0, [Math]::Max(0.0, ([double]$script:HermesDockerCommanderLastDone / [double]$script:HermesDockerCommanderLastTotal) * 100.0))
                            Invoke-HermesDockerAllFastLine $Name ("progress:$($script:HermesDockerCommanderPhase) {0:N2}% {1}/{2} elapsed={3}s {4}" -f $pct,(Format-HermesDockerCommanderMiB $script:HermesDockerCommanderLastDone),(Format-HermesDockerCommanderMiB $script:HermesDockerCommanderLastTotal),$elapsedSeconds,$heartbeatState)
                        } else {
                            Invoke-HermesDockerAllFastLine $Name ("progress:$($script:HermesDockerCommanderPhase) elapsed={0}s {1}" -f $elapsedSeconds,$heartbeatState)
                        }
                    }
                    $script:HermesDockerCommanderLastHeartbeatLine = Get-Date
                }
                if ($RetryUntilSuccess) {
                    $observedBytes = [int64]$script:HermesDockerCommanderLastDone
                    if ($isPush -and $script:HermesDockerCommanderPushNetStartBytes -ge 0) {
                        $networkNow = Get-HermesDockerNetworkSentBytes
                        if ($networkNow -ge 0) {
                            $observedBytes = [Math]::Max($observedBytes,[int64]($networkNow - [int64]$script:HermesDockerCommanderPushNetStartBytes))
                        }
                    }
                    if ($observedBytes -gt $lastObservedBytes) {
                        $deltaBytes = [int64]($observedBytes - $lastObservedBytes)
                        $deltaSeconds = [Math]::Max(0.001,((Get-Date) - $lastObservedAt).TotalSeconds)
                        $rateBytes = [int64]([double]$deltaBytes / $deltaSeconds)
                        if ($rateBytes -lt $minBytesPerSecond -and ((Get-Date) - $lastRateWarnAt).TotalSeconds -ge 10) {
                            Invoke-HermesDockerAllFastLine $Name ("speed-floor: {0} moving at {1}/s below target {2}/s; continuing while bytes move" -f $script:HermesDockerCommanderPhase,(Format-HermesDockerCommanderMiB $rateBytes),(Format-HermesDockerCommanderMiB $minBytesPerSecond))
                            $lastRateWarnAt = Get-Date
                        }
                        $lastObservedBytes = $observedBytes
                        $lastObservedAt = Get-Date
                    } elseif (((Get-Date) - $lastObservedAt).TotalSeconds -ge $stallSeconds -and ((Get-Date) - $script:HermesDockerCommanderLastOutput).TotalSeconds -ge $stallSeconds) {
                        Invoke-HermesDockerAllFastLine $Name ("stall-guard: no Docker output and no byte progress for {0}s; aborting attempt for retry" -f $stallSeconds)
                        try { if (-not $p.HasExited) { $p.Kill() } } catch {}
                        throw ("Docker command stalled for {0}s without output or byte progress" -f $stallSeconds)
                    }
                }
                Start-Sleep -Milliseconds 50
            }
            if(-not [string]::IsNullOrEmpty($script:HermesDockerCommanderStdoutCarry)){ Update-HermesDockerCommanderProgressLine $script:HermesDockerCommanderStdoutCarry }
            if(-not [string]::IsNullOrEmpty($script:HermesDockerCommanderStderrCarry)){ Update-HermesDockerCommanderProgressLine $script:HermesDockerCommanderStderrCarry }
            $p.WaitForExit()
            $code = [int]$p.ExitCode
            if ($isPush) {
                if (((Get-Date) - $script:HermesDockerCommanderPushLastSummary).TotalMilliseconds -ge 750) {
                    Write-HermesDockerPushSummary -Started $started
                }
                Invoke-HermesDockerAllFastLine $Name ("push complete exit={0} attempt={1}; returning to PowerShell shell" -f $code,$attempt)
            } elseif ($code -eq 0 -and $script:HermesDockerCommanderLastTotal -gt 0) {
                $script:HermesDockerCommanderLastDone = $script:HermesDockerCommanderLastTotal
                Write-HermesDockerCommanderDashboard -Name $Name -Phase $script:HermesDockerCommanderPhase -Started $started -DoneBytes $script:HermesDockerCommanderLastDone -TotalBytes $script:HermesDockerCommanderLastTotal -Detail "exit=$code attempt=$attempt"
                Write-Host ''
            } else {
                Write-HermesDockerCommanderDashboard -Name $Name -Phase $script:HermesDockerCommanderPhase -Started $started -DoneBytes $script:HermesDockerCommanderLastDone -TotalBytes $script:HermesDockerCommanderLastTotal -Detail "exit=$code attempt=$attempt"
                Write-Host ''
            }
            if ($code -eq 0) {
                $global:LASTEXITCODE = 0
                return 0
            }
            if (-not $RetryUntilSuccess) {
                $global:LASTEXITCODE = $code
                Invoke-HermesDockerAllFastLine $Name ("exit=$code; returning to PowerShell shell without automatic retry")
                return $code
            }
            $global:LASTEXITCODE = 0
            Invoke-HermesDockerAllFastLine $Name ("retry-safe LASTEXITCODE=0 while retry loop continues after exit=$code")
            Invoke-HermesDockerAllFastLine $Name ("exit=$code; retrying until success unless manually stopped")
            $retryDelay = [Math]::Min(60,[Math]::Max(2,2*$attempt))
            Wait-HermesDockerCommanderRetry -Name $Name -Phase $script:HermesDockerCommanderPhase -Started $started -Seconds $retryDelay -Attempt $attempt -Detail $script:HermesDockerCommanderLastDetail
        } catch {
            $message = if ($_.Exception -and $_.Exception.Message) { $_.Exception.Message } else { [string]$_ }
            $code = -1
            Invoke-HermesDockerAllFastLine $Name ("process runner failure exit={0} attempt={1}: {2}" -f $code,$attempt,$message)
            if (-not $RetryUntilSuccess) {
                $global:LASTEXITCODE = $code
                Invoke-HermesDockerAllFastLine $Name ("exit=$code; returning to PowerShell shell without automatic retry")
                return $code
            }
            $global:LASTEXITCODE = 0
            Invoke-HermesDockerAllFastLine $Name ("retry-safe LASTEXITCODE=0 while retry loop continues after exit=$code")
            Invoke-HermesDockerAllFastLine $Name ("exit=$code; retrying until success unless manually stopped")
            $retryDelay = [Math]::Min(60,[Math]::Max(2,2*$attempt))
            Wait-HermesDockerCommanderRetry -Name $Name -Phase $phase -Started $started -Seconds $retryDelay -Attempt $attempt -Detail $message
        } finally {
            try { if ($p -and -not $p.HasExited) { $p.Kill() } } catch {}
            try { if ($p) { $p.Dispose() } } catch {}
            Remove-Variable -Name HermesDockerCommanderName,HermesDockerCommanderStarted,HermesDockerCommanderContextTotalBytes,HermesDockerCommanderArgs,HermesDockerCommanderIsPush,HermesDockerCommanderLayerDone,HermesDockerCommanderLayerTotal,HermesDockerCommanderPushLayerStatus,HermesDockerCommanderPushLayerDone,HermesDockerCommanderPushLayerTotal,HermesDockerCommanderPushLayerSeen,HermesDockerCommanderPushLayerChanged,HermesDockerCommanderPushLastChange,HermesDockerCommanderPushLastSummary,HermesDockerCommanderPushImageName,HermesDockerCommanderPushImageBytes,HermesDockerCommanderPushSuppressedWaiting,HermesDockerCommanderPushNetStartBytes,HermesDockerCommanderPushNetLastBytes,HermesDockerCommanderPushNetLastSample,HermesDockerCommanderStdoutCarry,HermesDockerCommanderStderrCarry,HermesDockerCommanderLastOutput,HermesDockerCommanderLastRender,HermesDockerCommanderLastHeartbeatLine,HermesDockerCommanderLastDetail,HermesDockerCommanderLastDone,HermesDockerCommanderLastTotal,HermesDockerCommanderPhase -Scope Script -ErrorAction SilentlyContinue
        }
    }
}


function global:Invoke-HermesDockerForceDkill {
    [CmdletBinding(SupportsShouldProcess=$true)]
    param(
        [switch]$NoLaunch,
        [int]$ReadySeconds = 15,
        [switch]$NoElevate,
        [switch]$FullServiceStop
    )
    $ErrorActionPreference = 'Continue'
    $started = Get-Date
    $script:DKillFastProofPath = $null
    function Write-DKillFastLine {
        param([string]$Message,[ConsoleColor]$Color=[ConsoleColor]::Cyan)
        $line = "[dkill] {0}" -f $Message
        Write-Host $line -ForegroundColor $Color
        if($script:DKillFastProofPath){
            try { Add-Content -LiteralPath $script:DKillFastProofPath -Value ("{0:o} {1}" -f (Get-Date),$line) -Encoding UTF8 -ErrorAction SilentlyContinue } catch { }
        }
    }
    function Test-DKillFastAdmin {
        try {
            $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
            return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
        } catch { return $false }
    }
    function Format-DKillFastBytes { param([int64]$Bytes) if($Bytes -ge 1TB){'{0:N2} TB' -f ($Bytes/1TB)}elseif($Bytes -ge 1GB){'{0:N2} GB' -f ($Bytes/1GB)}elseif($Bytes -ge 1MB){'{0:N2} MB' -f ($Bytes/1MB)}else{'{0:N0} B' -f $Bytes} }
    function Get-DKillFastCFree { try { return ([IO.DriveInfo]'C').AvailableFreeSpace } catch { return 0L } }
    function Get-DKillFastPathBytes {
        param([string]$Path)
        $total = 0L
        if([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)){ return 0L }
        try {
            $item = Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue
            if($item -and -not $item.PSIsContainer){ return [int64]$item.Length }
            Get-ChildItem -LiteralPath $Path -Force -Recurse -ErrorAction SilentlyContinue | ForEach-Object { if(-not $_.PSIsContainer){ $total += [int64]$_.Length } }
        } catch { }
        return [int64]$total
    }
    function Invoke-DKillFastBoundedDocker {
        param(
            [string]$DockerExe,
            [string[]]$DockerArgs,
            [int]$Seconds = 4
        )
        if([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe)){ return $null }
        $outFile = Join-Path 'C:\Temp' ('dkill-docker-out-' + [guid]::NewGuid().ToString('N') + '.log')
        $errFile = Join-Path 'C:\Temp' ('dkill-docker-err-' + [guid]::NewGuid().ToString('N') + '.log')
        $label = 'docker ' + ($DockerArgs -join ' ')
        try {
            $p = Start-Process -FilePath $DockerExe -ArgumentList $DockerArgs -WindowStyle Hidden -PassThru -RedirectStandardOutput $outFile -RedirectStandardError $errFile
            if(-not $p.WaitForExit([Math]::Max(1,$Seconds) * 1000)){
                try { $p.Kill() } catch { }
                Write-DKillFastLine ("{0} timed out after {1}s; continuing forced C-drive delete path" -f $label,$Seconds) Yellow
                return 124
            }
            foreach($file in @($outFile,$errFile)){
                if(Test-Path -LiteralPath $file){
                    Get-Content -LiteralPath $file -ErrorAction SilentlyContinue | Select-Object -Last 12 | ForEach-Object {
                        if(-not [string]::IsNullOrWhiteSpace([string]$_)){ Write-DKillFastLine ([string]$_) DarkGray }
                    }
                }
            }
            return [int]$p.ExitCode
        } catch {
            Write-DKillFastLine ("{0} failed: {1}" -f $label,$_.Exception.Message) Yellow
            return 1
        } finally {
            foreach($file in @($outFile,$errFile)){ try { Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue } catch { } }
        }
    }
    function Test-DKillFastDockerReady {
        param([string]$DockerExe,[switch]$FinalProbe)
        if([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe)){ return $false }
        $proc = $null
        try {
            $remaining = Get-DKillFastRemainingMilliseconds
            if(-not $FinalProbe -and $remaining -lt 300){ return $false }
            $waitMs = if($FinalProbe){ 2500 } else { [Math]::Max(350,[Math]::Min(1400,$remaining - 150)) }
            $psi = New-Object Diagnostics.ProcessStartInfo
            $psi.FileName = $DockerExe
            $psi.Arguments = 'version --format "{{.Server.Version}}"'
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $psi.RedirectStandardOutput = $true
            $psi.RedirectStandardError = $true
            $proc = New-Object Diagnostics.Process
            $proc.StartInfo = $psi
            [void]$proc.Start()
            if(-not $proc.WaitForExit($waitMs)){ try { $proc.Kill() } catch { }; return $false }
            $stdout = ''
            $stderr = ''
            try { $stdout = $proc.StandardOutput.ReadToEnd().Trim() } catch { $stdout = '' }
            try { $stderr = $proc.StandardError.ReadToEnd().Trim() } catch { $stderr = '' }
            if($proc.ExitCode -ne 0){ return $false }
            if([string]::IsNullOrWhiteSpace($stdout)){ return $false }
            if($stderr -match '(?i)failed to connect|daemon is not running|cannot find|error during connect'){ return $false }
            return $true
        } catch {
            return $false
        } finally {
            if($proc){ try { $proc.Dispose() } catch { } }
        }
    }
    function Invoke-DKillFastSc {
        param([ValidateSet('start','stop')][string]$Action,[string]$ServiceName,[int]$Milliseconds = 900)
        $sc = Join-Path $env:SystemRoot 'System32\sc.exe'
        if(-not (Test-Path -LiteralPath $sc)){ return }
        try {
            $p = Start-Process -FilePath $sc -ArgumentList @($Action,$ServiceName) -PassThru -WindowStyle Hidden
            [void]$p.WaitForExit([Math]::Max(100,$Milliseconds))
        } catch { }
    }
    function Invoke-DKillFastReleaseDockerVhdLocks {
        param([int]$Milliseconds = 2500)
        if(-not $script:DKillFastIsAdmin){ return }
        $ps5 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        if(-not (Test-Path -LiteralPath $ps5)){ return }
        $release = @'
$ErrorActionPreference='SilentlyContinue'
Import-Module Hyper-V -ErrorAction SilentlyContinue
$vm = Get-VM -Name 'DockerDesktopVM' -ErrorAction SilentlyContinue
$vmId = $null
if($vm){
  try { $vmId = ([string]$vm.Id).ToUpperInvariant() } catch { $vmId = $null }
  if($vm.State -ne 'Off'){ Stop-VM -Name 'DockerDesktopVM' -TurnOff -Force -ErrorAction SilentlyContinue }
}
Start-Sleep -Milliseconds 200
try {
  $vmMgmt = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_VirtualSystemManagementService -ErrorAction SilentlyContinue
  $dockerVm = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_ComputerSystem -ErrorAction SilentlyContinue | Where-Object { $_.ElementName -eq 'DockerDesktopVM' } | Select-Object -First 1
  if($vmMgmt -and $dockerVm){ [void](Invoke-CimMethod -InputObject $vmMgmt -MethodName DestroySystem -Arguments @{ AffectedSystem = $dockerVm } -ErrorAction SilentlyContinue) }
} catch { }
if($vmId){
  Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction SilentlyContinue |
    Where-Object { ([string]$_.CommandLine).ToUpperInvariant().Contains($vmId) } |
    ForEach-Object { try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { } }
}
Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction SilentlyContinue |
  Where-Object { ([string]$_.CommandLine) -match '(?i)DockerDesktopVM|DockerDesktop\.vhdx|\\DockerDesktop\\vm-data' } |
  ForEach-Object { try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { } }
$vhd = 'C:\ProgramData\DockerDesktop\vm-data\DockerDesktop.vhdx'
try { Dismount-VHD -Path $vhd -ErrorAction SilentlyContinue } catch { }
try {
  $hcs = Join-Path $env:SystemRoot 'System32\hcsdiag.exe'
  if(Test-Path -LiteralPath $hcs){
    $hcsList = & $hcs list 2>$null
    $ids = @()
    for($i=0; $i -lt @($hcsList).Count; $i++){
      $line = [string]$hcsList[$i]
      if($line -match '^[0-9A-Fa-f-]{36}$'){
        $id = $line.Trim()
        $next = if($i + 1 -lt @($hcsList).Count){ [string]$hcsList[$i+1] } else { '' }
        if($next -match 'VMMS' -and $next -notmatch 'WSL'){ $ids += $id }
      }
    }
    foreach($id in $ids){
      try { & $hcs kill $id 2>$null | Out-Null } catch { }
      try {
        Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction SilentlyContinue |
          Where-Object { ([string]$_.CommandLine).ToUpperInvariant().Contains(([string]$id).ToUpperInvariant()) } |
          ForEach-Object { try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { } }
      } catch { }
    }
  }
} catch { }
Get-Process -ErrorAction SilentlyContinue |
  Where-Object { @('Docker Desktop','Docker Desktop Installer','com.docker.backend','com.docker.build','com.docker.proxy','com.docker.service','docker-agent','docker-buildx','docker-compose','docker-sandbox','dockerd','docker','vpnkit','containerd') -contains $_.ProcessName } |
  Stop-Process -Force -ErrorAction SilentlyContinue
'@
        try {
            $p = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-Command',$release) -PassThru -WindowStyle Hidden
            if(-not $p.WaitForExit([Math]::Max(300,$Milliseconds))){ try { $p.Kill() } catch { } }
        } catch { }
    }
    function Invoke-DKillFastForegroundPrune {
        param([string]$DockerExe)
        if([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe)){ return $false }
        if(-not (Test-DKillFastDockerReady -DockerExe $DockerExe -FinalProbe)){ return $false }
        $prunePlan = @(
            ,@('builder','prune','--all','--force')
            ,@('system','prune','--all','--volumes','--force')
        )
        $allOk = $true
        try {
            foreach($args in $prunePlan){
                $remaining = Get-DKillFastRemainingMilliseconds
                if($remaining -lt 2500){
                    Write-DKillFastLine 'foreground Docker prune budget reached; preserving readiness gate' Yellow
                    $allOk = $false
                    break
                }
                $budgetSeconds = [Math]::Max(1,[Math]::Min(4,[int][Math]::Floor(($remaining - 1200) / 1000)))
                Write-DKillFastLine ("foreground prune: docker {0} (budget={1}s)" -f ($args -join ' '),$budgetSeconds) DarkCyan
                $code = Invoke-DKillFastBoundedDocker -DockerExe $DockerExe -DockerArgs $args -Seconds $budgetSeconds
                if($null -eq $code -or [int]$code -ne 0){ $allOk = $false }
                if(-not (Test-DKillFastDockerReady -DockerExe $DockerExe -FinalProbe)){
                    Write-DKillFastLine 'Docker daemon not ready after prune command; readiness recovery will run before returning' Yellow
                    $allOk = $false
                    break
                }
            }
        } catch {
            Write-DKillFastLine ("foreground Docker prune failed: {0}" -f $_.Exception.Message) Yellow
            $allOk = $false
        }
        if($allOk){ Write-DKillFastLine 'foreground Docker prune completed before readiness return' Green }
        return [bool]$allOk
    }
    function Invoke-DKillFastTaskKill {
        param([string]$ImageName,[int]$Milliseconds = 450)
        if([string]::IsNullOrWhiteSpace($ImageName)){ return }
        $taskkill = Join-Path $env:SystemRoot 'System32\taskkill.exe'
        if(-not (Test-Path -LiteralPath $taskkill)){ return }
        try {
            $p = Start-Process -FilePath $taskkill -ArgumentList @('/F','/T','/IM',$ImageName) -PassThru -WindowStyle Hidden
            if(-not $p.WaitForExit([Math]::Max(100,$Milliseconds))){ try { $p.Kill() } catch { } }
        } catch { }
    }
    function Start-DKillFastHiddenProcess {
        param([string]$FilePath,[string[]]$ArgumentList)
        if([string]::IsNullOrWhiteSpace($FilePath) -or -not (Test-Path -LiteralPath $FilePath)){ return $false }
        try {
            $psi = New-Object Diagnostics.ProcessStartInfo
            $psi.FileName = $FilePath
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $psi.WindowStyle = [Diagnostics.ProcessWindowStyle]::Hidden
            $psi.Arguments = ((@($ArgumentList) | ForEach-Object { '"' + ([string]$_).Replace('"','\"') + '"' }) -join ' ')
            [void][Diagnostics.Process]::Start($psi)
            return $true
        } catch {
            try {
                Start-Process -FilePath $FilePath -ArgumentList $ArgumentList -WindowStyle Hidden | Out-Null
                return $true
            } catch { return $false }
        }
    }
    function Start-DKillFastDockerDesktopCli {
        param([string]$DockerExe)
        if([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe)){ return $false }
        try {
            $psi = New-Object Diagnostics.ProcessStartInfo
            $psi.FileName = $DockerExe
            $psi.Arguments = 'desktop start --detach'
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $psi.WindowStyle = [Diagnostics.ProcessWindowStyle]::Hidden
            $psi.RedirectStandardOutput = $false
            $psi.RedirectStandardError = $false
            $proc = New-Object Diagnostics.Process
            $proc.StartInfo = $psi
            [void]$proc.Start()
            if(-not $proc.WaitForExit(350)){
                try { $proc.Dispose() } catch { }
                return $true
            }
            try { $proc.Dispose() } catch { }
            return $true
        } catch { return $false }
    }
    function Start-DKillFastFrontendSuppressor {
        param([int]$Seconds = 90)
        Write-DKillFastLine 'Docker Desktop frontend suppressor is permanently disabled; visible app must stay running after dkill' DarkCyan
        return $false
    }
    function Start-DKillFastBackendHeadless {
        param([string]$DockerExe)
        $backendExe = Join-Path ${env:ProgramFiles} 'Docker\Docker\resources\com.docker.backend.exe'
        if([string]::IsNullOrWhiteSpace($backendExe) -or -not (Test-Path -LiteralPath $backendExe)){ return $false }
        try {
            if($script:DKillFastIsAdmin){
                foreach($svc in @('vmms','vmcompute','hns','com.docker.service')){
                    try { Set-Service -Name $svc -StartupType Automatic -ErrorAction SilentlyContinue } catch { }
                    Invoke-DKillFastSc -Action start -ServiceName $svc -Milliseconds 140
                }
            }
            try { New-Item -ItemType Directory -Force -Path 'C:\ProgramData\DockerDesktop\vm-data' -ErrorAction SilentlyContinue | Out-Null } catch { }
            [void](Start-DKillFastHiddenProcess -FilePath $backendExe -ArgumentList @('-unattended','-with-frontend=false','-accept-license','-engine','HyperV'))
            Start-Sleep -Milliseconds 120
            return $true
        } catch { return $false }
    }
    function Start-DKillFastDockerHeadless {
        param([string]$DockerExe,[string]$Reason = 'headless restart')
        if($NoLaunch -or $WhatIfPreference -or $script:DKillFastEarlyLaunchStarted){ return }
        if($script:DKillFastIsAdmin){
            foreach($svc in @('vmms','vmcompute','hns','com.docker.service')){
                try { Set-Service -Name $svc -StartupType Automatic -ErrorAction SilentlyContinue } catch { }
                Invoke-DKillFastSc -Action start -ServiceName $svc -Milliseconds 250
            }
        }
        $serviceOnlyReady = $false
        try {
            $serviceDeadline = (Get-Date).AddMilliseconds([Math]::Max(80,[Math]::Min(250,(Get-DKillFastRemainingMilliseconds) - 900)))
            while((Get-Date) -lt $serviceDeadline){
                if(Test-DKillFastDockerReady -DockerExe $DockerExe){ $serviceOnlyReady = $true; break }
                Start-Sleep -Milliseconds 120
            }
        } catch { $serviceOnlyReady = $false }
        if($serviceOnlyReady){
            $script:DKillFastEarlyLaunchStarted = $true
            Write-DKillFastLine ("Docker backend ready from Windows service only after {0}; no Desktop GUI launch used" -f $Reason) Green
            return
        }
        if(Start-DKillFastDockerDesktopCli -DockerExe $DockerExe){
            $script:DKillFastEarlyLaunchStarted = $true
            Write-DKillFastLine ("started Docker Desktop through unbounded docker desktop start --detach after {0}; frontend GUI suppression is delayed until daemon readiness; readiness gate={1}s" -f $Reason,$ReadySeconds) Green
            return
        }
        if(Start-DKillFastBackendHeadless -DockerExe $DockerExe){
            $script:DKillFastEarlyLaunchStarted = $true
            Write-DKillFastLine ("started Docker backend headless/unattended after {0}; frontend GUI is blocked; readiness gate={1}s" -f $Reason,$ReadySeconds) Green
            return
        }
        Write-DKillFastLine 'direct Docker Desktop GUI launch is blocked; only headless backend/unattended or docker desktop start --detach fallback is allowed' Yellow
    }
    function Get-DKillFastRemainingMilliseconds {
        try {
            if(-not $script:DKillFastDeadline){ return 10000 }
            return [Math]::Max(0,[int](($script:DKillFastDeadline - (Get-Date)).TotalMilliseconds))
        } catch { return 0 }
    }
    function Invoke-DKillFastBoundedRemove {
        param([string]$Path)
        if([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)){ return $true }
        $remaining = Get-DKillFastRemainingMilliseconds
        $isDockerVhd = ($Path -match '(?i)\\DockerDesktop\\vm-data\\DockerDesktop\.vhdx$|\\DockerDesktop\\vm-data$')
        if((-not $isDockerVhd) -and $remaining -lt 4200){ return $false }
        if($isDockerVhd){ Invoke-DKillFastReleaseDockerVhdLocks -Milliseconds 2400 }
        $budget = if($isDockerVhd){ [Math]::Max(1200,[Math]::Min(6500,[Math]::Max(1200,$remaining - 2200))) } else { [Math]::Max(600,[Math]::Min(4200,$remaining - 3200)) }
        $ps5 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        if(-not (Test-Path -LiteralPath $ps5)){ return $false }
        $encodedPath = [Convert]::ToBase64String([Text.Encoding]::Unicode.GetBytes($Path))
        $cmd = '$p=[Text.Encoding]::Unicode.GetString([Convert]::FromBase64String(''' + $encodedPath + ''')); if($p -match ''(?i)\\DockerDesktop\\vm-data(\\DockerDesktop\.vhdx)?$''){ $takeown=Join-Path $env:SystemRoot ''System32\takeown.exe''; $icacls=Join-Path $env:SystemRoot ''System32\icacls.exe''; $item=Get-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue; if($item -and (Test-Path -LiteralPath $takeown)){ if($item.PSIsContainer){ & $takeown /F $p /A /R /D Y 2>$null | Out-Null } else { & $takeown /F $p /A 2>$null | Out-Null } }; if(Test-Path -LiteralPath $icacls){ if($item -and $item.PSIsContainer){ & $icacls $p /grant ''Administrators:(OI)(CI)F'' /T /C 2>$null | Out-Null } else { & $icacls $p /grant ''Administrators:F'' /C 2>$null | Out-Null } } }; Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue; if(Test-Path -LiteralPath $p){ Start-Sleep -Milliseconds 150; Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction SilentlyContinue }'
        try {
            $p = Start-Process -FilePath $ps5 -ArgumentList @('-NoProfile','-ExecutionPolicy','Bypass','-Command',$cmd) -PassThru -WindowStyle Hidden
            if(-not $p.WaitForExit($budget)){
                try { $p.Kill() } catch { }
                return $false
            }
        } catch { return $false }
        return (-not (Test-Path -LiteralPath $Path))
    }
    function Invoke-DKillFastHardDeleteDockerVhd {
        $vhd = 'C:\ProgramData\DockerDesktop\vm-data\DockerDesktop.vhdx'
        $vmData = 'C:\ProgramData\DockerDesktop\vm-data'
        if(-not $script:DKillFastIsAdmin){
            Write-DKillFastLine 'cannot hard-delete DockerDesktop.vhdx without elevated Administrator rights' Yellow
            return ((-not (Test-Path -LiteralPath $vhd)) -and (-not (Test-Path -LiteralPath $vmData)))
        }
        $bytesBefore = 0L
        try {
            if(Test-Path -LiteralPath $vmData){ $bytesBefore = [Math]::Max($bytesBefore,[int64](Get-DKillFastPathBytes -Path $vmData)) }
            elseif(Test-Path -LiteralPath $vhd){ $bytesBefore = [Math]::Max($bytesBefore,[int64](Get-DKillFastPathBytes -Path $vhd)) }
        } catch { $bytesBefore = 0L }
        $deleted = $false
        $attempt = 1
        while(-not $deleted -and (Get-DKillFastRemainingMilliseconds) -ge 1200){
            if((Get-DKillFastRemainingMilliseconds) -lt 1200){ break }
            if($attempt -gt 1){
                Write-DKillFastLine ("hard VHDX delete retry {0} after lock release" -f $attempt) Yellow
                try { Stop-DKillFastDocker } catch { }
            }
            try { Invoke-DKillFastReleaseDockerVhdLocks -Milliseconds ([Math]::Min(1400,[Math]::Max(500,(Get-DKillFastRemainingMilliseconds) - 13000))) } catch { }
            try {
                $vmMgmtPreDelete = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_VirtualSystemManagementService -ErrorAction SilentlyContinue
                $dockerVmPreDelete = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_ComputerSystem -ErrorAction SilentlyContinue | Where-Object { $_.ElementName -eq 'DockerDesktopVM' } | Select-Object -First 1
                if($vmMgmtPreDelete -and $dockerVmPreDelete){
                    $destroyPreDelete = Invoke-CimMethod -InputObject $vmMgmtPreDelete -MethodName DestroySystem -Arguments @{ AffectedSystem = $dockerVmPreDelete } -ErrorAction SilentlyContinue
                    Write-DKillFastLine ("destroyed DockerDesktopVM definition before VHDX deletion so locks release; return={0}" -f $destroyPreDelete.ReturnValue) DarkCyan
                }
            } catch {
                Write-DKillFastLine ("DockerDesktopVM definition destroy before VHDX deletion failed: {0}" -f $_.Exception.Message) Yellow
            }
            try {
                $hcs = Join-Path $env:SystemRoot 'System32\hcsdiag.exe'
                if(Test-Path -LiteralPath $hcs){
                    $hcsList = @(& $hcs list 2>$null)
                    $ids = @()
                    for($i=0; $i -lt $hcsList.Count; $i++){
                        $line = [string]$hcsList[$i]
                        if($line -match '^[0-9A-Fa-f-]{36}$'){
                            $id = $line.Trim()
                            $next = if($i + 1 -lt $hcsList.Count){ [string]$hcsList[$i+1] } else { '' }
                            if($next -match 'VMMS' -and $next -notmatch 'WSL'){ $ids += $id }
                        }
                    }
                    foreach($id in $ids){
                        try {
                            Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction SilentlyContinue |
                                Where-Object { ([string]$_.CommandLine).ToUpperInvariant().Contains(([string]$id).ToUpperInvariant()) } |
                                ForEach-Object {
                                    Write-DKillFastLine ("force-kill Docker vmwp.exe pid {0} before VHDX delete" -f $_.ProcessId) DarkCyan
                                    try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { }
                                }
                        } catch { }
                        Start-Sleep -Milliseconds 120
                        Write-DKillFastLine ("force-kill Docker HCS VMMS id {0} before VHDX delete" -f $id) DarkCyan
                        try { & $hcs kill $id 2>$null | Out-Null } catch { }
                    }
                }
            } catch { }
            Start-Sleep -Milliseconds 250
            try {
                Get-CimInstance Win32_Process -Filter "Name='vmwp.exe'" -ErrorAction SilentlyContinue |
                    Where-Object { ([string]$_.CommandLine) -match '(?i)DockerDesktopVM|DockerDesktop\.vhdx|\\DockerDesktop\\vm-data' } |
                    ForEach-Object {
                        Write-DKillFastLine ("force-kill DockerDesktop-specific vmwp.exe pid {0} before VHDX delete" -f $_.ProcessId) DarkCyan
                        try { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue } catch { }
                    }
            } catch { }
            foreach($target in @($vhd,$vmData)){
                if(-not (Test-Path -LiteralPath $target)){ continue }
                try {
                    $takeown = Join-Path $env:SystemRoot 'System32\takeown.exe'
                    $icacls = Join-Path $env:SystemRoot 'System32\icacls.exe'
                    $item = Get-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
                    if($item -and (Test-Path -LiteralPath $takeown)){
                        if($item.PSIsContainer){ & $takeown /F $target /A /R /D Y 2>$null | Out-Null }
                        else { & $takeown /F $target /A 2>$null | Out-Null }
                    }
                    if(Test-Path -LiteralPath $icacls){
                        if($item -and $item.PSIsContainer){ & $icacls $target /grant 'Administrators:(OI)(CI)F' /T /C 2>$null | Out-Null }
                        else { & $icacls $target /grant 'Administrators:F' /C 2>$null | Out-Null }
                    }
                    try { attrib -R -S -H $target /S /D 2>$null | Out-Null } catch { }
                } catch {
                    Write-DKillFastLine ("ownership/ACL step failed for {0}: {1}" -f $target,$_.Exception.Message) Yellow
                }
                try {
                    Remove-Item -LiteralPath $target -Recurse -Force -ErrorAction Stop
                } catch {
                    Write-DKillFastLine ("PowerShell delete failed for {0}: {1}" -f $target,$_.Exception.Message) Yellow
                    try {
                        $itemAfterFailure = Get-Item -LiteralPath $target -Force -ErrorAction SilentlyContinue
                        if($itemAfterFailure -and $itemAfterFailure.PSIsContainer){
                            [IO.Directory]::Delete($target,$true)
                        } elseif($itemAfterFailure) {
                            [IO.File]::Delete($target)
                        }
                    } catch {
                        Write-DKillFastLine ("dotnet delete fallback failed for {0}: {1}" -f $target,$_.Exception.Message) Yellow
                    }
                }
            }
            if((Test-Path -LiteralPath $vhd) -or (Test-Path -LiteralPath $vmData)){
                Start-Sleep -Milliseconds 160
            } else {
                $deleted = $true
            }
            $attempt++
        }
        if(Test-Path -LiteralPath $vhd){
            Write-DKillFastLine ("hard VHDX and vm-data delete not verified before readiness deadline; still exists: {0}" -f $vhd) Red
            return $false
        }
        if(Test-Path -LiteralPath $vmData){
            Write-DKillFastLine ("hard vm-data folder delete not verified before readiness deadline; still exists: {0}" -f $vmData) Red
            return $false
        }
        try {
            $serviceLogBytes = 0L
            $serviceLogs = @(Get-ChildItem -LiteralPath 'C:\ProgramData\DockerDesktop' -Force -ErrorAction SilentlyContinue -Filter 'service*.txt')
            foreach($serviceLog in $serviceLogs){
                try { if(-not $serviceLog.PSIsContainer){ $serviceLogBytes += [int64]$serviceLog.Length } } catch { }
                try { Remove-Item -LiteralPath $serviceLog.FullName -Force -ErrorAction SilentlyContinue } catch { }
            }
            if($serviceLogs.Count -gt 0){
                $script:DKillFastDeletedBytes += [int64]$serviceLogBytes
                Write-DKillFastLine ("old DockerDesktop service logs deleted before restart: files={0} bytes={1}" -f $serviceLogs.Count,(Format-DKillFastBytes $serviceLogBytes)) Green
            }
        } catch {
            Write-DKillFastLine ("old DockerDesktop service log cleanup failed before restart: {0}" -f $_.Exception.Message) Yellow
        }
        try {
            $vmMgmt = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_VirtualSystemManagementService -ErrorAction SilentlyContinue
            $dockerVm = Get-CimInstance -Namespace root\virtualization\v2 -ClassName Msvm_ComputerSystem -ErrorAction SilentlyContinue | Where-Object { $_.ElementName -eq 'DockerDesktopVM' } | Select-Object -First 1
            if($vmMgmt -and $dockerVm){
                $destroy = Invoke-CimMethod -InputObject $vmMgmt -MethodName DestroySystem -Arguments @{ AffectedSystem = $dockerVm } -ErrorAction SilentlyContinue
                Write-DKillFastLine ("destroyed DockerDesktopVM definition after VHDX deletion so Docker can recreate a valid VM; return={0}" -f $destroy.ReturnValue) DarkCyan
            }
        } catch {
            Write-DKillFastLine ("DockerDesktopVM definition destroy after VHDX deletion failed: {0}" -f $_.Exception.Message) Yellow
        }
        if($bytesBefore -gt 0){ $script:DKillFastDeletedBytes += [int64]$bytesBefore }
        $script:DKillFastForcedVhdDeleteCompletedAt = Get-Date
        Write-DKillFastLine ("hard VHDX and vm-data folder delete verified; removed old payload={0}" -f (Format-DKillFastBytes $bytesBefore)) Green
        return $true
    }
    function Copy-DKillFastIfExists {
        param([string]$Source,[string]$DestRoot)
        if([string]::IsNullOrWhiteSpace($Source) -or -not (Test-Path -LiteralPath $Source)){ return }
        $name = (($Source -replace '^[A-Za-z]:\\','') -replace '[\\/:*?"<>|]','_')
        $dest = Join-Path $DestRoot $name
        try { Copy-Item -LiteralPath $Source -Destination $dest -Recurse -Force -ErrorAction SilentlyContinue } catch { }
    }
    function Copy-DKillFastSettingsFile {
        param([string]$Source,[string]$SnapshotRoot)
        if([string]::IsNullOrWhiteSpace($Source) -or -not (Test-Path -LiteralPath $Source -PathType Leaf)){ return }
        try {
            $resolved = (Resolve-Path -LiteralPath $Source -ErrorAction Stop).ProviderPath
            if($resolved -notmatch '^(?i)C:\\'){ return }
            $relative = $resolved.Substring(3)
            $dest = Join-Path $SnapshotRoot $relative
            $parent = Split-Path -Parent $dest
            New-Item -ItemType Directory -Force -Path $parent | Out-Null
            Copy-Item -LiteralPath $resolved -Destination $dest -Force -ErrorAction SilentlyContinue
        } catch { }
    }
    function Copy-DKillFastSettingsSnapshot {
        param([string]$SnapshotRoot)
        foreach($dir in @((Join-Path $env:USERPROFILE '.docker'),(Join-Path $env:APPDATA 'Docker'),(Join-Path $env:APPDATA 'Docker Desktop'))){
            if([string]::IsNullOrWhiteSpace($dir) -or -not (Test-Path -LiteralPath $dir)){ continue }
            try {
                Get-ChildItem -LiteralPath $dir -File -Force -ErrorAction SilentlyContinue |
                    Where-Object { $_.Extension -ieq '.json' -or $_.Name -match '^(config|daemon|windows-daemon|settings-store|settings|features|login-info)(\..*)?$' } |
                    ForEach-Object { Copy-DKillFastSettingsFile -Source $_.FullName -SnapshotRoot $SnapshotRoot }
            } catch { }
        }
    }
    function Restore-DKillFastSnapshot {
        param([string]$SnapshotRoot)
        if(-not (Test-Path -LiteralPath $SnapshotRoot)){ return }
        Get-ChildItem -LiteralPath $SnapshotRoot -Force -ErrorAction SilentlyContinue | ForEach-Object {
            $rel = $_.Name -replace '_','\'
            if($rel -match '^(Users\\[^\\]+\\\.docker)$'){ $dest = 'C:\' + $rel }
            elseif($rel -match '^(Users\\[^\\]+\\AppData\\Roaming\\Docker)$'){ $dest = 'C:\' + $rel }
            elseif($rel -match '^(Users\\[^\\]+\\AppData\\Roaming\\Docker Desktop)$'){ $dest = 'C:\' + $rel }
            else { return }
            try {
                $parent = Split-Path -Parent $dest
                New-Item -ItemType Directory -Force -Path $parent | Out-Null
                Copy-Item -LiteralPath $_.FullName -Destination $dest -Recurse -Force -ErrorAction SilentlyContinue
            } catch { }
        }
    }
    function Restore-DKillFastSettingsSnapshot {
        param([string]$SnapshotRoot)
        if(-not (Test-Path -LiteralPath $SnapshotRoot)){ return }
        try {
            Get-ChildItem -LiteralPath $SnapshotRoot -File -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object {
                try {
                    $relative = $_.FullName.Substring($SnapshotRoot.TrimEnd('\').Length).TrimStart('\')
                    if([string]::IsNullOrWhiteSpace($relative)){ return }
                    $dest = Join-Path 'C:\' $relative
                    $parent = Split-Path -Parent $dest
                    New-Item -ItemType Directory -Force -Path $parent | Out-Null
                    Copy-Item -LiteralPath $_.FullName -Destination $dest -Force -ErrorAction SilentlyContinue
                } catch { }
            }
        } catch { }
    }
    function Clear-DKillFastSettingsSnapshots {
        try {
            Get-ChildItem -LiteralPath 'C:\Temp' -Directory -Filter 'dkill-docker-settings-*' -ErrorAction SilentlyContinue |
                ForEach-Object { try { Remove-Item -LiteralPath $_.FullName -Recurse -Force -ErrorAction SilentlyContinue } catch { } }
        } catch { }
    }
    function Stop-DKillFastDocker {
        try {
            $tempWorkerPattern = 'hermes-docker-commander|hermes-docker-realtime-helper|hermes-docker-mmenu-contexts|mmenu-progress'
            $tempWorkers = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object {
                $_.ProcessId -ne $PID -and $_.CommandLine -match $tempWorkerPattern
            })
            if($tempWorkers.Count -gt 0){
                Write-DKillFastLine ("force-stopping generated Docker temp workers: {0}" -f (($tempWorkers | Select-Object -ExpandProperty ProcessId) -join ', ')) DarkCyan
                foreach($tw in ($tempWorkers | Sort-Object ProcessId -Descending)){
                    try { Stop-Process -Id $tw.ProcessId -Force -ErrorAction SilentlyContinue } catch { }
                }
            }
        } catch { }
        try {
            $names = @('Docker Desktop','Docker Desktop Installer','com.docker.backend','com.docker.build','com.docker.proxy','com.docker.service','docker-agent','docker-buildx','docker-compose','docker-sandbox','dockerd','docker','vpnkit','containerd')
            $procs = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $names -contains $_.ProcessName })
            if($procs.Count -gt 0){
                Write-DKillFastLine ("force-stopping Docker processes: {0}" -f (($procs | Select-Object -ExpandProperty ProcessName -Unique) -join ', ')) DarkCyan
                $procs | Stop-Process -Force -ErrorAction SilentlyContinue
            }
        } catch { }
        Start-Sleep -Milliseconds 80
        $stillRunningImages = @()
        try {
            $stillRunningImages = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $names -contains $_.ProcessName } | ForEach-Object {
                if($_.Path){ Split-Path -Leaf $_.Path } else { $_.ProcessName + '.exe' }
            } | Select-Object -Unique)
        } catch { $stillRunningImages = @() }
        foreach($imageName in $stillRunningImages){
            Invoke-DKillFastTaskKill -ImageName $imageName -Milliseconds 80
        }
        if($script:DKillFastIsAdmin -and (Get-DKillFastRemainingMilliseconds) -gt 7000){
            Write-DKillFastLine 'force-stop Docker Desktop Windows service without waiting on slow SCM shutdown' DarkCyan
            Invoke-DKillFastSc -Action stop -ServiceName 'com.docker.service' -Milliseconds 120
        }
    }
    function Remove-DKillFastPath {
        param([string]$Path)
        if([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)){ return }
        $resolved = $null
        try { $resolved = (Resolve-Path -LiteralPath $Path -ErrorAction Stop).ProviderPath } catch { $resolved = $Path }
        if($resolved -notmatch '^(?i)C:\\'){ return }
        if($resolved -notmatch '(?i)(\\Docker\\?|\\Docker Desktop\\?|\\DockerDesktop\\?|\\containerd\\?|\\Windows\\Containers\\?|docker-desktop|ext4\.vhdx|\.avhdx$|docker.*\.vhdx)'){ return }
        $size = 0L
        try {
            $itemForSize = Get-Item -LiteralPath $resolved -Force -ErrorAction SilentlyContinue
            if($itemForSize -and -not $itemForSize.PSIsContainer){ $size = [int64]$itemForSize.Length }
        } catch { $size = 0L }
        Write-DKillFastLine ("delete {0} ({1})" -f $resolved,(Format-DKillFastBytes $size)) DarkCyan
        if($PSCmdlet.ShouldProcess($resolved,'delete Docker-owned C-drive data/cache')){
            [void](Invoke-DKillFastBoundedRemove -Path $resolved)
        }
        if(-not (Test-Path -LiteralPath $resolved)){
            $script:DKillFastDeletedBytes += [int64]$size
        } elseif(-not $WhatIfPreference) {
            $remainingSize = if((Get-DKillFastRemainingMilliseconds) -gt 1500){ Get-DKillFastPathBytes -Path $resolved } else { -1L }
            if($remainingSize -gt 0){
                Write-DKillFastLine ("blocked still exists: {0} ({1})" -f $resolved,(Format-DKillFastBytes $remainingSize)) Yellow
            } elseif($remainingSize -lt 0) {
                Write-DKillFastLine ("blocked still exists: {0} (size scan skipped to preserve readiness deadline)" -f $resolved) Yellow
            } else {
                Write-DKillFastLine ("empty live folder remains/recreated: {0}" -f $resolved) DarkGray
            }
        }
    }

    $isAdmin = Test-DKillFastAdmin
    $script:DKillFastIsAdmin = $isAdmin
    $ReadySeconds = [int][Math]::Min(60,[Math]::Max(1,$ReadySeconds))
    if($ReadySeconds -gt 15){ $ReadySeconds = 15 }
    if($ReadySeconds -lt 15){ $ReadySeconds = 15 }
    $script:DKillFastReadySeconds = $ReadySeconds
    $script:DKillFastFullServiceStop = $true
    $deadlineMs = [Math]::Max(500,($ReadySeconds * 1000) - 1000)
    $script:DKillFastDeadline = (Get-Date).AddMilliseconds($deadlineMs)
    if(-not $isAdmin -and -not $WhatIfPreference){
        Write-DKillFastLine 'not elevated; no UAC/GUI prompt will be opened. Protected machine-wide Docker paths are skipped unless this shell is already admin.' Yellow
    }

    $script:DKillFastDeletedBytes = 0L
    $script:DKillFastForcedVhdDeleteCompletedAt = $null
    Clear-DKillFastSettingsSnapshots
    $freeBefore = Get-DKillFastCFree
    $snapshotRoot = 'C:\Temp'
    try { New-Item -ItemType Directory -Force -Path $snapshotRoot -ErrorAction SilentlyContinue | Out-Null } catch { $snapshotRoot = $env:TEMP }
    $snapshot = Join-Path $snapshotRoot ('dkill-docker-settings-' + [guid]::NewGuid().ToString('N'))
    try {
        New-Item -ItemType Directory -Force -Path $snapshot | Out-Null
        Copy-DKillFastSettingsSnapshot -SnapshotRoot $snapshot
        Write-DKillFastLine ("saved Docker settings snapshot: {0}" -f $snapshot) DarkGray
    } catch {
        Write-DKillFastLine ("settings snapshot failed; preserving settings paths only: {0}" -f $_.Exception.Message) Yellow
    }
    Write-DKillFastLine ("C free before: {0}" -f (Format-DKillFastBytes $freeBefore))
    $proofVhd = 'C:\ProgramData\DockerDesktop\vm-data\DockerDesktop.vhdx'
    $proofVmData = 'C:\ProgramData\DockerDesktop\vm-data'
    if(Test-Path -LiteralPath $proofVhd){
        try {
            $proofVhdBefore = Get-Item -LiteralPath $proofVhd -Force -ErrorAction Stop
            Write-DKillFastLine ("exact VHDX before delete: exists size={0} lastwrite={1:o}" -f (Format-DKillFastBytes ([int64]$proofVhdBefore.Length)),$proofVhdBefore.LastWriteTime) DarkCyan
        } catch { Write-DKillFastLine 'exact VHDX before delete: exists but size read failed' Yellow }
    } else {
        Write-DKillFastLine 'exact VHDX before delete: absent' DarkCyan
    }

    $dockerExe = Join-Path ${env:ProgramFiles} 'Docker\Docker\resources\bin\docker.exe'
    $script:DKillFastPreserveRunningEngine = $false
    if(-not $WhatIfPreference -and (Test-DKillFastDockerReady -DockerExe $dockerExe -FinalProbe)){
        Write-DKillFastLine 'Docker daemon is ready; skipping foreground prune so force-stop starts immediately' DarkGray
    }
    if(-not $WhatIfPreference){
        Write-DKillFastLine 'forcing Docker process stop before cleanup/restart' Yellow
        Stop-DKillFastDocker
        $script:DKillFastEarlyLaunchStarted = $false
        Write-DKillFastLine 'Docker is stopped; deleting Docker-owned C-drive data before restart' Yellow
        $script:DKillFastHardVhdDeleted = Invoke-DKillFastHardDeleteDockerVhd
        if($script:DKillFastHardVhdDeleted){
            Start-DKillFastDockerHeadless -DockerExe $dockerExe -Reason 'hard VHDX/vm-data delete'
            if($script:DKillFastEarlyLaunchStarted){
                $script:DKillFastDeadline = (Get-Date).AddSeconds($ReadySeconds)
                Write-DKillFastLine ("fresh Docker readiness window started after verified VHDX/vm-data delete; gate={0}s" -f $ReadySeconds) DarkCyan
            }
        }
    }

    $targets = New-Object System.Collections.Generic.List[string]
    $baseTargets = @(
        "$env:LOCALAPPDATA\Docker\log",
        "$env:LOCALAPPDATA\Docker\cache",
        "$env:LOCALAPPDATA\Docker\wsl",
        "$env:LOCALAPPDATA\Docker\buildx",
        "$env:LOCALAPPDATA\Docker\desktop-build",
        "$env:LOCALAPPDATA\Docker Desktop\Local Storage",
        "$env:LOCALAPPDATA\Docker Desktop\log",
        "$env:LOCALAPPDATA\Docker Desktop\Cache",
        "$env:LOCALAPPDATA\Docker Desktop\GPUCache",
        "$env:LOCALAPPDATA\Docker Desktop\Code Cache",
        "$env:LOCALAPPDATA\Docker Desktop\DawnCache",
        "$env:LOCALAPPDATA\Docker Desktop\ShaderCache",
        "C:\ProgramData\Docker\windowsfilter",
        "C:\ProgramData\Docker\image",
        "C:\ProgramData\Docker\containers",
        "C:\ProgramData\Docker\volumes",
        "C:\ProgramData\Docker\buildkit",
        "C:\ProgramData\DockerDesktop\vm-data\DockerDesktop.vhdx",
        "C:\ProgramData\DockerDesktop\vm-data",
        "C:\ProgramData\DockerDesktop\service.txt",
        "$env:TEMP\hermes-docker-commander",
        "$env:TEMP\hermes-docker-realtime-helper",
        "$env:TEMP\hermes-docker-mmenu-contexts",
        "$env:TEMP\mmenu-progress",
        "$env:TEMP\mmmenu-progress",
        "C:\Temp\hermes-docker-commander",
        "C:\Temp\hermes-docker-realtime-helper",
        "C:\Temp\hermes-docker-mmenu-contexts",
        "C:\Temp\mmenu-progress",
        "C:\Temp\mmmenu-progress"
    )
    try {
        Get-ChildItem -LiteralPath 'C:\ProgramData\DockerDesktop' -Force -ErrorAction SilentlyContinue |
            Where-Object { -not $_.PSIsContainer -and $_.Name -like 'service*.txt' } |
            ForEach-Object { $baseTargets += $_.FullName }
    } catch { }
    foreach($path in $baseTargets){
        if(($script:DKillFastPreserveRunningEngine -or $script:DKillFastEarlyLaunchStarted) -and $path -match '(?i)\\Docker( Desktop)?\\log$'){
            Write-DKillFastLine ("preserve live daemon log folder while Docker is starting/ready: {0}" -f $path) DarkGray
            continue
        }
        if($script:DKillFastEarlyLaunchStarted -and $path -match '(?i)^C:\\ProgramData\\DockerDesktop\\(vm-data(\\DockerDesktop\.vhdx)?|service\.txt)$'){
            Write-DKillFastLine ("preserve freshly recreated Docker startup path after verified hard delete: {0}" -f $path) DarkGray
            continue
        }
        if($path -and -not $targets.Contains($path)){ [void]$targets.Add($path) }
    }
    foreach($path in ($targets.ToArray() | Sort-Object Length -Descending -Unique)){
        $isCriticalDockerVhdTarget = ($path -match '(?i)^C:\\ProgramData\\DockerDesktop\\vm-data(\\DockerDesktop\.vhdx)?$')
        if((-not $isCriticalDockerVhdTarget) -and (Get-DKillFastRemainingMilliseconds) -lt 4200){ Write-DKillFastLine 'restart budget reached before remaining delete targets; returning to restart/readiness path' Yellow; break }
        if(-not $isAdmin -and $path -notlike "$env:USERPROFILE\*"){
            Write-DKillFastLine ("skip protected target without elevation: {0}" -f $path) Yellow
            continue
        }
        Remove-DKillFastPath -Path $path
    }
    if($snapshot -and (Test-Path -LiteralPath $snapshot)){
        Write-DKillFastLine ("Docker settings snapshot kept for rollback only; live settings files were not rewritten: {0}" -f $snapshot) DarkGray
    }
    Write-DKillFastLine 'Docker CLI/Desktop settings were preserved in place; no settings rewrite was applied' Green

    if($isAdmin -and -not $WhatIfPreference -and -not $script:DKillFastEarlyLaunchStarted){
        foreach($svc in @('vmms','vmcompute','hns','com.docker.service')){
            try { Set-Service -Name $svc -StartupType Automatic -ErrorAction SilentlyContinue } catch { }
            Invoke-DKillFastSc -Action start -ServiceName $svc -Milliseconds 900
        }
    }
    if(-not $script:DKillFastPreserveRunningEngine -and -not $script:DKillFastEarlyLaunchStarted -and -not $NoLaunch -and -not $WhatIfPreference){
        $serviceOnlyReady = $false
        try {
            $serviceDeadline = (Get-Date).AddMilliseconds([Math]::Max(600,[Math]::Min(1800,(Get-DKillFastRemainingMilliseconds) - 1800)))
            while((Get-Date) -lt $serviceDeadline){
                if(Test-DKillFastDockerReady -DockerExe $dockerExe){ $serviceOnlyReady = $true; break }
                Start-Sleep -Milliseconds 150
            }
        } catch { $serviceOnlyReady = $false }
        if($serviceOnlyReady){
            Write-DKillFastLine 'Docker backend ready from Windows service only; no Desktop GUI launch used' Green
        } elseif(Start-DKillFastDockerDesktopCli -DockerExe $dockerExe){
            Write-DKillFastLine ("started Docker Desktop through unbounded docker desktop start --detach; visible frontend will not be force-closed; readiness gate={0}s" -f $ReadySeconds) Green
        } elseif(Start-DKillFastBackendHeadless -DockerExe $dockerExe){
            Write-DKillFastLine ("started Docker backend headless/unattended; frontend GUI is blocked; readiness gate={0}s" -f $ReadySeconds) Green
        } else {
            Write-DKillFastLine 'direct Docker Desktop GUI launch is blocked; returning failure unless Docker daemon becomes ready through service/CLI start' Yellow
        }
    }
    $ready = $false
    if(-not $WhatIfPreference -and -not $NoLaunch -and (Test-Path -LiteralPath $dockerExe)){
        $deadline = $script:DKillFastDeadline
        while((Get-Date) -lt $deadline -and (Get-DKillFastRemainingMilliseconds) -gt 300){
            try {
                if(Test-DKillFastDockerReady -DockerExe $dockerExe){ $ready=$true; break }
            } catch { }
            Start-Sleep -Milliseconds 250
        }
        if(-not $ready){
            try { if(Test-DKillFastDockerReady -DockerExe $dockerExe -FinalProbe){ $ready=$true } } catch { }
        }
    }
    $freeAfter = Get-DKillFastCFree
    $elapsed = [Math]::Round(((Get-Date)-$started).TotalSeconds,2)
    if(Test-Path -LiteralPath $proofVhd){
        try {
            $proofVhdAfter = Get-Item -LiteralPath $proofVhd -Force -ErrorAction Stop
            $freshText = ''
            if($script:DKillFastForcedVhdDeleteCompletedAt){
                if($proofVhdAfter.LastWriteTime -lt $script:DKillFastForcedVhdDeleteCompletedAt.AddSeconds(-2)){
                    Write-DKillFastLine ("old DockerDesktop.vhdx still exists after forced vm-data deletion; lastwrite={0:o} delete_completed={1:o}" -f $proofVhdAfter.LastWriteTime,$script:DKillFastForcedVhdDeleteCompletedAt) Red
                    return 1
                }
                $freshText = ' fresh/recreated-after-delete'
            }
            Write-DKillFastLine ("exact VHDX final state: exists{0} size={1} lastwrite={2:o}" -f $freshText,(Format-DKillFastBytes ([int64]$proofVhdAfter.Length)),$proofVhdAfter.LastWriteTime) DarkCyan
        } catch { Write-DKillFastLine 'exact VHDX final state: exists but size read failed' Yellow }
    } else {
        Write-DKillFastLine 'exact VHDX final state: absent' DarkCyan
    }
    if(Test-Path -LiteralPath $proofVmData){
        $vmDataBytesAfter = Get-DKillFastPathBytes -Path $proofVmData
        $vmDataFreshText = if($script:DKillFastForcedVhdDeleteCompletedAt){ 'fresh/recreated after verified delete' } else { 'exists after cleanup' }
        Write-DKillFastLine ("exact vm-data final state: {0}; current_payload={1}" -f $vmDataFreshText,(Format-DKillFastBytes $vmDataBytesAfter)) DarkCyan
    } else {
        Write-DKillFastLine 'exact vm-data final state: absent' DarkCyan
    }
    Write-DKillFastLine ("deleted target estimate: {0}" -f (Format-DKillFastBytes $script:DKillFastDeletedBytes)) Green
    Write-DKillFastLine ("C free after: {0}; delta: {1}; elapsed={2}s" -f (Format-DKillFastBytes $freeAfter),(Format-DKillFastBytes ([int64]($freeAfter-$freeBefore))),$elapsed) Green
    if($snapshot -and (Test-Path -LiteralPath $snapshot) -and ($ready -or $NoLaunch -or $WhatIfPreference)){
        Clear-DKillFastSettingsSnapshots
    }
    if(-not $ready -and -not $NoLaunch -and -not $WhatIfPreference){
        try {
            if(Test-DKillFastDockerReady -DockerExe $dockerExe -FinalProbe){
                $ready = $true
                Write-DKillFastLine 'final direct Docker CLI probe is ready before frontend suppression' Green
            }
        } catch { }
    }
    try {
        $frontends = @(Get-Process -Name 'Docker Desktop' -ErrorAction SilentlyContinue)
        if($ready -and $frontends.Count -gt 0){
            Write-DKillFastLine ("preserving Docker Desktop frontend GUI processes after restart: {0}" -f (($frontends | Select-Object -ExpandProperty Id) -join ', ')) Green
        }
    } catch { }
    if($ready -and -not $NoLaunch -and -not $WhatIfPreference){
        [void](Start-DKillFastFrontendSuppressor -Seconds 90)
    }
    if(-not $WhatIfPreference -and -not $script:DKillFastHardVhdDeleted -and ((Test-Path -LiteralPath 'C:\ProgramData\DockerDesktop\vm-data\DockerDesktop.vhdx') -or (Test-Path -LiteralPath 'C:\ProgramData\DockerDesktop\vm-data'))){
        Write-DKillFastLine 'DockerDesktop.vhdx/vm-data still exists after hard delete path; returning failure instead of false success' Red
        return 1
    }
    if(-not $ready -and -not $NoLaunch -and -not $WhatIfPreference){
        try {
            if(Test-DKillFastDockerReady -DockerExe $dockerExe -FinalProbe){
                $ready = $true
                Write-DKillFastLine 'final direct Docker CLI probe is ready after frontend suppression' Green
            }
        } catch { }
    }
    if($ready){
        if($snapshot -and (Test-Path -LiteralPath $snapshot)){ Clear-DKillFastSettingsSnapshots }
        Write-DKillFastLine ("Docker daemon ready within <= {0}s; returning to shell now" -f $ReadySeconds) Green
        return 0
    }
    if($NoLaunch -or $WhatIfPreference){ Write-DKillFastLine 'returning to shell now' Green; return 0 }
    Write-DKillFastLine ("Docker daemon was not ready inside {0}s; returning failure instead of a false success" -f $ReadySeconds) Red
    return 1
}

function global:Invoke-HermesDockerNormalReadyAfterDkill {
    [CmdletBinding()]
    param(
        [int]$ReadySeconds = 180,
        [switch]$NoLaunch
    )
    if ($NoLaunch) { return $false }
    $ReadySeconds = [Math]::Max(30,[Math]::Min(600,[int]$ReadySeconds))
    $dockerExe = 'C:\Program Files\Docker\Docker\resources\bin\docker.exe'
    $dockerDesktopExe = 'C:\Program Files\Docker\Docker\Docker Desktop.exe'
    if (-not (Test-Path -LiteralPath $dockerExe -PathType Leaf)) {
        Write-Host '[dkill] docker.exe missing after cleanup; cannot prove Docker ready.' -ForegroundColor Red
        return $false
    }
    if (-not (Test-Path -LiteralPath $dockerDesktopExe -PathType Leaf)) {
        Write-Host '[dkill] Docker Desktop.exe missing after cleanup; cannot start Docker normally.' -ForegroundColor Red
        return $false
    }
    foreach ($serviceName in @('vmms','vmcompute','hns','com.docker.service')) {
        try {
            $service = Get-Service -Name $serviceName -ErrorAction Stop
            if ($service.Status -ne 'Running') {
                Write-Host ("[dkill] starting service {0} for normal Docker startup" -f $serviceName) -ForegroundColor DarkCyan
                Start-Service -Name $serviceName -ErrorAction SilentlyContinue
            }
        } catch {
            Write-Host ("[dkill] service start warning for {0}: {1}" -f $serviceName,$_.Exception.Message) -ForegroundColor Yellow
        }
    }
    try {
        Write-Host '[dkill] forcing Docker Desktop to start normally after cleanup' -ForegroundColor Cyan
        Start-Process -FilePath $dockerDesktopExe | Out-Null
    } catch {
        Write-Host ("[dkill] normal Docker Desktop launch warning: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
    }
    $deadline = (Get-Date).AddSeconds($ReadySeconds)
    $last = ''
    while ((Get-Date) -lt $deadline) {
        try {
            $out = & $dockerExe info --format '{{.ServerVersion}}' 2>&1 | Out-String
            $exit = $LASTEXITCODE
            $last = $out.Trim()
            if ($exit -eq 0 -and -not [string]::IsNullOrWhiteSpace($last) -and $last -notmatch '(?i)error|failed|cannot connect|daemon is not running') {
                Write-Host ("[dkill] Docker is ready. ServerVersion={0}; returning to shell now" -f $last) -ForegroundColor Green
                return $true
            }
        } catch {
            $last = $_.Exception.Message
        }
        Write-Host ("[dkill] waiting for normal Docker readiness: {0}" -f $last) -ForegroundColor DarkGray
        Start-Sleep -Seconds 3
    }
    Write-Host ("[dkill] Docker did not become ready within {0}s after normal launch. Last result: {1}" -f $ReadySeconds,$last) -ForegroundColor Red
    return $false
}

function global:Invoke-HermesDockerRealtimeNative {
    [CmdletBinding()]
    param([Parameter(ValueFromRemainingArguments=$true)][string[]]$DockerArgs)
    $oldBuildKit=$env:DOCKER_BUILDKIT; $oldProgress=$env:BUILDKIT_PROGRESS; $oldCompose=$env:COMPOSE_PROGRESS; $oldTimeout=$env:COMPOSE_HTTP_TIMEOUT
    try {
        $env:DOCKER_BUILDKIT='1'; $env:BUILDKIT_PROGRESS='plain'; $env:COMPOSE_PROGRESS='plain'; $env:COMPOSE_HTTP_TIMEOUT='86400'
        if($DockerArgs -and $DockerArgs.Count -gt 0 -and $DockerArgs[0] -in @('push','image','manifest','compose','buildx')){
            & 'C:\ProgramData\pip\docker.cmd' @DockerArgs
        } else {
            & 'C:\Program Files\Docker\Docker\resources\bin\docker.exe' @DockerArgs
        }
    } finally {
        if($null -eq $oldBuildKit){Remove-Item Env:DOCKER_BUILDKIT -ErrorAction SilentlyContinue}else{$env:DOCKER_BUILDKIT=$oldBuildKit}
        if($null -eq $oldProgress){Remove-Item Env:BUILDKIT_PROGRESS -ErrorAction SilentlyContinue}else{$env:BUILDKIT_PROGRESS=$oldProgress}
        if($null -eq $oldCompose){Remove-Item Env:COMPOSE_PROGRESS -ErrorAction SilentlyContinue}else{$env:COMPOSE_PROGRESS=$oldCompose}
        if($null -eq $oldTimeout){Remove-Item Env:COMPOSE_HTTP_TIMEOUT -ErrorAction SilentlyContinue}else{$env:COMPOSE_HTTP_TIMEOUT=$oldTimeout}
    }
}

function global:Invoke-HermesDockerVisibleReadyAfterDkill {
    [CmdletBinding()]
    param(
        [int]$ReadySeconds = 180,
        [switch]$NoLaunch
    )
    if ($NoLaunch) { return $false }
    $ReadySeconds = [Math]::Max(30,[Math]::Min(600,[int]$ReadySeconds))
    $dockerExe = 'C:\Program Files\Docker\Docker\resources\bin\docker.exe'
    $dockerDesktopExe = 'C:\Program Files\Docker\Docker\Docker Desktop.exe'
    if (-not (Test-Path -LiteralPath $dockerExe -PathType Leaf)) {
        Write-Host '[dkill] docker.exe missing after cleanup; cannot prove Docker ready.' -ForegroundColor Red
        return $false
    }
    if (-not (Test-Path -LiteralPath $dockerDesktopExe -PathType Leaf)) {
        Write-Host '[dkill] Docker Desktop.exe missing after cleanup; cannot start Docker normally.' -ForegroundColor Red
        return $false
    }
    Stop-HermesDockerDesktopSuppressors
    foreach ($serviceName in @('vmms','vmcompute','hns','com.docker.service')) {
        try {
            $service = Get-Service -Name $serviceName -ErrorAction Stop
            if ($service.Status -ne 'Running') {
                Write-Host ("[dkill] starting service {0} for normal Docker startup" -f $serviceName) -ForegroundColor DarkCyan
                Start-Service -Name $serviceName -ErrorAction SilentlyContinue
            }
        } catch {
            Write-Host ("[dkill] service start warning for {0}: {1}" -f $serviceName,$_.Exception.Message) -ForegroundColor Yellow
        }
    }
    try {
        Write-Host '[dkill] launching visible Docker Desktop app normally after cleanup' -ForegroundColor Cyan
        Start-Process -FilePath $dockerDesktopExe | Out-Null
    } catch {
        Write-Host ("[dkill] normal Docker Desktop launch warning: {0}" -f $_.Exception.Message) -ForegroundColor Yellow
    }
    $deadline = (Get-Date).AddSeconds($ReadySeconds)
    $last = ''
    while ((Get-Date) -lt $deadline) {
        Stop-HermesDockerDesktopSuppressors
        $desktopProcess = @(Get-Process -Name 'Docker Desktop' -ErrorAction SilentlyContinue)
        if ($desktopProcess.Count -eq 0) {
            try { Start-Process -FilePath $dockerDesktopExe | Out-Null } catch { }
            Start-Sleep -Seconds 2
            $desktopProcess = @(Get-Process -Name 'Docker Desktop' -ErrorAction SilentlyContinue)
        }
        try {
            $out = & $dockerExe info --format '{{.ServerVersion}}' 2>&1 | Out-String
            $exit = $LASTEXITCODE
            $last = $out.Trim()
            if ($exit -eq 0 -and -not [string]::IsNullOrWhiteSpace($last) -and $last -notmatch '(?i)error|failed|cannot connect|daemon is not running' -and $desktopProcess.Count -gt 0) {
                Write-Host ("[dkill] Docker Desktop app is running (pid={0}) and daemon is ready. ServerVersion={1}; returning to shell now" -f (($desktopProcess | Select-Object -First 1).Id),$last) -ForegroundColor Green
                return $true
            }
        } catch {
            $last = $_.Exception.Message
        }
        Write-Host ("[dkill] waiting for visible Docker Desktop + daemon readiness: appProcesses={0}; last={1}" -f $desktopProcess.Count,$last) -ForegroundColor DarkGray
        Start-Sleep -Seconds 3
    }
    Write-Host ("[dkill] Docker Desktop app/daemon did not become ready within {0}s. Last result: {1}" -f $ReadySeconds,$last) -ForegroundColor Red
    return $false
}

