function Invoke-MegaFixNative {
        param([string]$Label,[string]$FilePath,[string[]]$Arguments)
        Write-MegaFixLine ("START: {0}" -f $Label)
        Write-MegaFixLine ("CMD: {0} {1}" -f $FilePath, ($Arguments -join ' '))
        $old = $ErrorActionPreference
        try {
            $ErrorActionPreference = 'Continue'
            & $FilePath @Arguments 2>&1 | ForEach-Object {
                $text = [string]$_
                Write-Host $text
                Add-Content -LiteralPath $log -Value $text -Encoding UTF8
            }
            $code = if ($null -eq $global:LASTEXITCODE) { 0 } else { [int]$global:LASTEXITCODE }
        } finally {
            $ErrorActionPreference = $old
        }
        Write-MegaFixLine ("END: {0}; exit={1}" -f $Label, $code)
        return $code
    }

function Invoke-MmenuCmdProgress {
        param([Parameter(Mandatory=$true)][string]$Label,[Parameter(Mandatory=$true)][string]$CommandLine,[int]$HeartbeatSeconds=1,[switch]$QuietOutput)
        $runId=[Guid]::NewGuid().ToString('N'); $outFile=Join-Path $progressRoot "$runId.out.log"; $errFile=Join-Path $progressRoot "$runId.err.log"; $exitFile=Join-Path $progressRoot "$runId.exit"
        $started=Get-Date; Write-Host "[mmenu][docker:$Label] START $(Get-Date -Format 'HH:mm:ss')" -ForegroundColor Cyan
        Push-Location $env:TEMP
        try {
            $wrappedCommand='('+$CommandLine+') & echo !ERRORLEVEL!>'+(Quote-MmenuCmdArg $exitFile)+' & exit /b !ERRORLEVEL!'
            $p=Start-Process -FilePath $cmdExe -ArgumentList @('/v:on','/d','/s','/c',$wrappedCommand) -RedirectStandardOutput $outFile -RedirectStandardError $errFile -WindowStyle Hidden -PassThru
            $outOffset=[int64]0; $errOffset=[int64]0; $tick=0
            while(-not $p.HasExited){
                Start-Sleep -Seconds $HeartbeatSeconds; $tick++
                if(-not $QuietOutput){ Write-MmenuNewLogBytes -File $outFile -Offset ([ref]$outOffset); Write-MmenuNewLogBytes -File $errFile -Offset ([ref]$errOffset) }
                $elapsed=[int][Math]::Floor(((Get-Date)-$started).TotalSeconds)
                Write-MmenuRealProgressLine -Label $Label -Elapsed $elapsed -ProcessId $p.Id -Tick $tick
            }
            $p.WaitForExit(); $p.Refresh()
            if(-not $QuietOutput){ Write-MmenuNewLogBytes -File $outFile -Offset ([ref]$outOffset); Write-MmenuNewLogBytes -File $errFile -Offset ([ref]$errOffset) }
            $code=$null
            if(Test-Path -LiteralPath $exitFile -PathType Leaf){ $exitRaw=Get-Content -LiteralPath $exitFile -Raw -ErrorAction SilentlyContinue; if(-not [string]::IsNullOrWhiteSpace($exitRaw)){ $parsedExit=0; if([int]::TryParse($exitRaw.Trim(),[ref]$parsedExit)){ $code=$parsedExit } } }
            if($null -eq $code){ $code=[int]$p.ExitCode }
            $elapsedFinal=[int][Math]::Ceiling(((Get-Date)-$started).TotalSeconds)
            Write-Host ("[mmenu][docker:{0}] EXIT code={1} elapsed={2}s" -f $Label,$code,$elapsedFinal) -ForegroundColor Cyan
            return [int]$code
        } finally { Pop-Location; Remove-Item -LiteralPath $outFile,$errFile,$exitFile -Force -ErrorAction SilentlyContinue }
    }

