function Invoke-MmenuDockerPushInteractiveProgress {
        param([string]$Image)
        $sizeBytes = 0L
        try { $raw = & $dockerExe image inspect $Image --format '{{.Size}}' 2>$null; [void][int64]::TryParse(($raw | Select-Object -Last 1), [ref]$sizeBytes) } catch {}
        Write-Host ("[mmenu][docker:push] START {0} image-size={1}" -f (Get-Date -Format 'HH:mm:ss'),(Format-MmenuMB $sizeBytes)) -ForegroundColor Cyan
        Write-Host "[mmenu][docker:push] Docker's native live push progress below is intentionally attached to this console so layer MB current/total is real, not guessed." -ForegroundColor Cyan
        $started=Get-Date
        $p=Start-Process -FilePath $dockerExe -ArgumentList @('push',$Image) -NoNewWindow -PassThru
        $tick=0
        while(-not $p.HasExited){
            Start-Sleep -Seconds 1; $tick++
            $elapsed=[int][Math]::Floor(((Get-Date)-$started).TotalSeconds)
            Write-Host ("[mmenu][docker:push] progress elapsed={0}s pid={1} image-total={2}; see Docker layer current/total MB above" -f $elapsed,$p.Id,(Format-MmenuMB $sizeBytes)) -ForegroundColor DarkCyan
        }
        $p.WaitForExit(); $p.Refresh()
        $pushCode = $p.ExitCode
        if ($null -eq $pushCode) { $pushCode = 0 }
        $elapsedFinal=[int][Math]::Ceiling(((Get-Date)-$started).TotalSeconds)
        Write-Host ("[mmenu][docker:push] EXIT code={0} elapsed={1}s image-total={2}" -f $pushCode,$elapsedFinal,(Format-MmenuMB $sizeBytes)) -ForegroundColor Cyan
        return [int]$pushCode
    }

