function Invoke-MmmenuTarToDockerBuild {
        param([string[]]$DockerArgs)
        $scriptPath=Join-Path $progressRoot ('tarstream-'+[Guid]::NewGuid().ToString('N')+'.py')
        Write-MmmenuTarStreamerScript -ScriptPath $scriptPath
        try {
            $dockerPart=Quote-MmmenuCmdArg $dockerCommand.Source; foreach($arg in $DockerArgs){ $dockerPart+=' '+(Quote-MmmenuCmdArg $arg) }
            $commandLine=(Quote-MmmenuCmdArg $pythonExe)+$pythonArgsPrefix+' '+(Quote-MmmenuCmdArg $scriptPath)+' '+(Quote-MmmenuCmdArg $projectPath)+' | '+$dockerPart
            return (Invoke-MmmenuCmdProgress -Label 'tar-import' -CommandLine $commandLine)
        } finally { Remove-Item -LiteralPath $scriptPath -Force -ErrorAction SilentlyContinue }
    }

function Invoke-NvidLastChanceRuntimeRepair {
        Write-NvidStep 'running last-chance no-reboot NVIDIA runtime repair: services, AppX, caches, protocol/runtime state'
        Stop-NvidAppProcesses
        foreach($svcName in @('NVDisplay.ContainerLocalSystem','NvContainerLocalSystem')) {
            try { Set-Service -Name $svcName -StartupType Automatic -ErrorAction SilentlyContinue } catch {}
            try { Restart-Service -Name $svcName -Force -ErrorAction SilentlyContinue; Start-Sleep -Seconds 3 } catch { try { Start-Service -Name $svcName -ErrorAction SilentlyContinue } catch {} }
            $svcObj = Get-Service -Name $svcName -ErrorAction SilentlyContinue
            if ($svcObj) { Write-NvidStep ("service {0} status {1}" -f $svcName,$svcObj.Status) }
        }
        foreach($cacheDir in @(
            'C:\Users\micha\AppData\Local\NVIDIA\DXCache',
            'C:\Users\micha\AppData\Local\NVIDIA\GLCache',
            'C:\Users\micha\AppData\Local\NVIDIA\ComputeCache',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\CefCache',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\GPUCache',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\DawnCache',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\UXD',
            'C:\Users\micha\AppData\Local\NVIDIA Corporation\NVIDIA App\NvBackend',
            'C:\ProgramData\NVIDIA Corporation\NVIDIA App\MessageBus'
        )) { Backup-And-ClearDirectory $cacheDir 'lastchance-cache' }
        try {
            $cpl = Get-AppxPackage -Name 'NVIDIACorp.NVIDIAControlPanel' -ErrorAction SilentlyContinue | Select-Object -First 1
            if ($cpl -and (Test-Path -LiteralPath (Join-Path $cpl.InstallLocation 'AppxManifest.xml'))) {
                Add-AppxPackage -DisableDevelopmentMode -Register (Join-Path $cpl.InstallLocation 'AppxManifest.xml') -ErrorAction SilentlyContinue
                Write-NvidStep ("re-registered NVIDIA Control Panel AppX {0}" -f $cpl.Version)
            }
        } catch { Write-Host ("[nvid] NVIDIA Control Panel AppX repair warning: {0}" -f $_.Exception.Message) -ForegroundColor Yellow }
        try {
            $nvProfile = 'C:\Program Files\NVIDIA Corporation\Control Panel Client\nvcplui.exe'
            $nvCplDll = 'C:\Windows\System32\nvcpl.dll'
            if (Test-Path -LiteralPath $nvCplDll) { & regsvr32.exe /s $nvCplDll 2>$null | Out-Null; Write-NvidStep 'refreshed NVIDIA Control Panel shell registration' }
            if (Test-Path -LiteralPath $nvProfile) { Start-Process -FilePath $nvProfile -ArgumentList '-forcepsem' -WindowStyle Minimized -ErrorAction SilentlyContinue | Out-Null }
        } catch { Write-Host ("[nvid] NVIDIA Control Panel registration warning: {0}" -f $_.Exception.Message) -ForegroundColor Yellow }
        try {
            $nvContainerExe = 'C:\Program Files\NVIDIA Corporation\NvContainer\x86_64\NvContainer.exe'
            if (Test-Path -LiteralPath $nvContainerExe -and -not (Get-Process NvContainer -ErrorAction SilentlyContinue)) { Start-Process -FilePath $nvContainerExe -WindowStyle Hidden -ErrorAction SilentlyContinue | Out-Null }
        } catch {}
        try {
            $baseKey = 'HKLM:\SOFTWARE\NVIDIA Corporation\Global\NVTweak'
            if (-not (Test-Path $baseKey)) { New-Item -Path $baseKey -Force | Out-Null }
            New-ItemProperty -Path $baseKey -Name 'NvCplEnableRotatePage' -PropertyType DWord -Value 1 -Force | Out-Null
            New-ItemProperty -Path $baseKey -Name 'NvCplThermalSettings' -PropertyType DWord -Value 1 -Force | Out-Null
        } catch {}
    }

function Invoke-NvidNativeInstaller {
        param(
            [Parameter(Mandatory=$true)][string]$FilePath,
            [Parameter(Mandatory=$true)][string[]]$Arguments,
            [Parameter(Mandatory=$true)][string]$Name,
            [int[]]$AllowedExitCodes = @(0,3010)
        )
        Write-NvidStep ("starting {0}: {1} {2}" -f $Name,$FilePath,($Arguments -join ' '))
        $p = Start-Process -FilePath $FilePath -ArgumentList $Arguments -PassThru -WindowStyle Hidden
        $started = Get-Date
        while(-not $p.HasExited) {
            Start-Sleep -Seconds 15
            try { $p.Refresh() } catch {}
            $elapsed = [int]((Get-Date) - $started).TotalSeconds
            Write-NvidStep ("{0} still running after {1}s (pid {2})" -f $Name,$elapsed,$p.Id)
        }
        Write-NvidStep ("{0} exit {1}" -f $Name,$p.ExitCode)
        if ($AllowedExitCodes -notcontains [int]$p.ExitCode) { throw ("{0} failed with exit {1}" -f $Name,$p.ExitCode) }
        return [int]$p.ExitCode
    }

function Invoke-ProfileCluChild {
        param([object[]]$ChildArguments)

        $powerShell5 = Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $psi = New-Object System.Diagnostics.ProcessStartInfo
        $psi.FileName = $powerShell5
        $psi.UseShellExecute = $false
        $psi.RedirectStandardOutput = $true
        $psi.RedirectStandardError = $true
        $psi.CreateNoWindow = $true
        $psi.WorkingDirectory = $env:USERPROFILE
        function Quote-ProfileCluArgument([string]$Value) {
            if ($null -eq $Value) { return '""' }
            return '"' + ($Value -replace '([\\"])', '\$1') + '"'
        }
        $argumentList = New-Object 'System.Collections.Generic.List[string]'
        [void]$argumentList.Add('-NoProfile')
        [void]$argumentList.Add('-ExecutionPolicy')
        [void]$argumentList.Add('Bypass')
        [void]$argumentList.Add('-File')
        [void]$argumentList.Add((Quote-ProfileCluArgument $scriptPath))
        foreach ($argument in @($ChildArguments)) {
            if ($null -ne $argument) { [void]$argumentList.Add((Quote-ProfileCluArgument ([string]$argument))) }
        }
        $psi.Arguments = ($argumentList -join ' ')

        $process = [System.Diagnostics.Process]::Start($psi)
        $stdout = $process.StandardOutput.ReadToEnd()
        $stderr = $process.StandardError.ReadToEnd()
        $process.WaitForExit()
        $combined = ($stdout + $stderr)
        if ($combined.Length -gt 0) { Write-Host $combined.TrimEnd() }
        [pscustomobject]@{ ExitCode = $process.ExitCode; Text = $combined }
    }

function global:Invoke-ProfileNvidDriverAppOnly {
    [CmdletBinding()]
    param([switch]$SkipDriverInstall)
    $ErrorActionPreference = 'Stop'
    $ProgressPreference = 'SilentlyContinue'
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
    function Stop-NvidDriverAppOnlyProcesses {
        Get-Process -Name 'NVIDIA App','NVIDIA Overlay','NVIDIA Share','NVIDIA Web Helper','NVIDIA Notification','nvapp' -ErrorAction SilentlyContinue |
            Stop-Process -Force -ErrorAction SilentlyContinue
        Start-Sleep -Seconds 2
    }
    function Install-NvidDriverWithPnpUtilFallback {
        param([Parameter(Mandatory=$true)][string]$ExtractRoot,[Parameter(Mandatory=$true)][string]$GpuInstanceId)
        $displayRoot = Join-Path $ExtractRoot 'Display.Driver'
        $dev = [regex]::Match($GpuInstanceId, 'DEV_([0-9A-Fa-f]{4})').Groups[1].Value
        $subsys = [regex]::Match($GpuInstanceId, 'SUBSYS_([0-9A-Fa-f]{8})').Groups[1].Value
        if (-not $dev) { throw "Unable to resolve NVIDIA device id from $GpuInstanceId" }
        $infMatches = @()
        foreach ($inf in Get-ChildItem -Path $displayRoot -Filter '*.inf' -ErrorAction Stop) {
            $text = Get-Content -LiteralPath $inf.FullName -Raw
            $score = 0
            if ($subsys -and $text -match [regex]::Escape("DEV_$dev&SUBSYS_$subsys")) { $score += 100 }
            if ($text -match [regex]::Escape("DEV_$dev")) { $score += 10 }
            if ($inf.Name -ieq 'nv_dispi.inf') { $score += 5 }
            if ($score -gt 0) { $infMatches += [pscustomobject]@{ Path=$inf.FullName; Score=$score } }
        }
        $selected = $infMatches | Sort-Object -Property @{Expression='Score';Descending=$true}, @{Expression='Path';Descending=$false} | Select-Object -First 1
        if (-not $selected) { throw "No extracted NVIDIA display INF matched DEV_$dev under $displayRoot" }
        Write-Host ("  NVIDIA setup failed or did not activate the driver; falling back to pnputil with {0}" -f $selected.Path) -ForegroundColor DarkYellow
        $output = (& pnputil.exe /add-driver $selected.Path /install 2>&1 | Out-String).Trim()
        Write-Host ("  pnputil /add-driver exit: {0}" -f $LASTEXITCODE) -ForegroundColor Gray
        if ($output) { Write-Host ("  pnputil output: {0}" -f (($output -split "`r?`n") -join ' | ')) -ForegroundColor Gray }
        try { & pnputil.exe /restart-device $GpuInstanceId 2>&1 | Out-Null } catch {}
        Start-Sleep -Seconds 10
    }
    Write-Host '========================================' -ForegroundColor Cyan
    Write-Host '  NVID - NVIDIA DRIVER + APP REPAIR' -ForegroundColor Cyan
    Write-Host '========================================' -ForegroundColor Cyan
    $root = 'C:\ProgramData\NVID'
    $downloads = Join-Path $root 'downloads'
    $work = Join-Path $root 'work'
    foreach($p in @($root,$downloads,$work)){ New-Item -ItemType Directory -Path $p -Force | Out-Null }
    $gpu = Get-CimInstance Win32_VideoController | Where-Object { $_.AdapterCompatibility -match 'NVIDIA' -and $_.Name -match 'NVIDIA' } | Select-Object -First 1
    if (-not $gpu) { throw 'No NVIDIA GPU was detected.' }
    $officialDriver = Get-NvidOfficialDriverInfo -GpuName $gpu.Name
    $officialApp = Get-NvidOfficialAppInfo
    $healthBefore = Get-NvidDriverHealth -GpuName $gpu.Name -OfficialDriverVersion $officialDriver.Version
    Write-Host ("[1/4] Latest compatible official driver: {0}; installed/active: {1}; health: {2}" -f $officialDriver.Version,$healthBefore.WmiMarketingVersion,$healthBefore.Classification) -ForegroundColor Yellow
    if (-not $SkipDriverInstall) {
        $driverInstaller = Join-Path $downloads ("nvidia-driver-{0}.exe" -f $officialDriver.Version)
        if (-not (Test-Path -LiteralPath $driverInstaller -PathType Leaf)) {
            Write-Host '  Downloading official compatible NVIDIA driver package...' -ForegroundColor Gray
            $curl = (Get-Command curl.exe -CommandType Application -ErrorAction Stop).Source
            & $curl -L --fail --retry 3 --silent --show-error --output $driverInstaller $officialDriver.DownloadURL
            if ($LASTEXITCODE -ne 0 -or -not (Test-Path -LiteralPath $driverInstaller -PathType Leaf)) { throw 'Driver download failed.' }
        }
        if ((Get-Item -LiteralPath $driverInstaller).Length -lt 100MB) { throw ("Driver download is incomplete or unexpectedly small: {0}" -f $driverInstaller) }
        $extractRoot = Join-Path $work ("driver-{0}-driver-app-only" -f $officialDriver.Version)
        $sevenZip = @('C:\Program Files\7-Zip\7z.exe','C:\Program Files (x86)\7-Zip\7z.exe') | Where-Object { Test-Path -LiteralPath $_ -PathType Leaf } | Select-Object -First 1
        if (-not $sevenZip) { throw '7-Zip is required for NVIDIA driver extraction but was not found.' }
        if (-not (Test-Path -LiteralPath (Join-Path $extractRoot 'setup.exe') -PathType Leaf)) {
            if (Test-Path -LiteralPath $extractRoot) { Remove-Item -LiteralPath $extractRoot -Recurse -Force -ErrorAction SilentlyContinue }
            New-Item -ItemType Directory -Path $extractRoot -Force | Out-Null
            & $sevenZip x $driverInstaller ("-o" + $extractRoot) -y 2>$null | Out-Null
        }
        $setup = Join-Path $extractRoot 'setup.exe'
        Stop-NvidDriverAppOnlyProcesses
        Write-Host '  Running NVIDIA driver installer even if current, so the NVIDIA App Drivers tab cannot retain a newer available driver...' -ForegroundColor Gray
        $proc = Start-Process -FilePath $setup -ArgumentList '-clean','-passive','-noreboot','-noeula' -Wait -PassThru
        Write-Host ("  Driver installer exit: {0}" -f $proc.ExitCode) -ForegroundColor Gray
        Start-Sleep -Seconds 10
    } else {
        Write-Host '  Driver reinstall explicitly skipped by caller.' -ForegroundColor DarkYellow
    }
    $healthAfter = Get-NvidDriverHealth -GpuName $gpu.Name -OfficialDriverVersion $officialDriver.Version
    if (-not $SkipDriverInstall -and ($proc.ExitCode -notin @(0,1,3010,1641) -or $healthAfter.RepairRequired -or $healthAfter.WmiMarketingVersion -ne $officialDriver.Version)) {
        Install-NvidDriverWithPnpUtilFallback -ExtractRoot $extractRoot -GpuInstanceId $gpu.PNPDeviceID
        $healthAfter = Get-NvidDriverHealth -GpuName $gpu.Name -OfficialDriverVersion $officialDriver.Version
    }
    if ($healthAfter.RepairRequired -or $healthAfter.WmiMarketingVersion -ne $officialDriver.Version) { throw ("Driver verification failed: active={0}, expected={1}, health={2}" -f $healthAfter.WmiMarketingVersion,$officialDriver.Version,$healthAfter.Classification) }
    Write-Host ("[2/4] Driver verified: {0} ({1})" -f $healthAfter.WmiMarketingVersion,$healthAfter.Classification) -ForegroundColor Green
    $appInstaller = Join-Path $downloads ("NVIDIA_app_v{0}.exe" -f $officialApp.Version)
    if (-not (Test-Path -LiteralPath $appInstaller -PathType Leaf)) {
        Write-Host '  Downloading official NVIDIA App installer...' -ForegroundColor Gray
        Invoke-WebRequest -Uri $officialApp.DownloadURL -OutFile $appInstaller -UseBasicParsing -TimeoutSec 900
    }
    Stop-NvidDriverAppOnlyProcesses
    Get-Process -Name 'setup','610.47-desktop-win10-win11-64bit-international-dch-whql-g' -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
    foreach($stalePath in @(
        'C:\ProgramData\NVIDIA Corporation\NVIDIA App\UpdateFramework\ota-artifacts\grd',
        'C:\ProgramData\NVIDIA Corporation\NVIDIA App\UpdateFramework\status\grd',
        'C:\ProgramData\NVIDIA Corporation\NVIDIA App\NvDriverDiagnostics\storage'
    )) { if (Test-Path -LiteralPath $stalePath) { Remove-Item -LiteralPath $stalePath -Recurse -Force -ErrorAction SilentlyContinue } }
    Start-Sleep -Seconds 2
    Write-Host ("[3/4] Reinstalling/repairing NVIDIA App {0}..." -f $officialApp.Version) -ForegroundColor Yellow
    $appProc = Start-Process -FilePath $appInstaller -ArgumentList '-s','-noreboot','-noeula','-nofinish','-nosplash' -Wait -PassThru -WindowStyle Hidden
    if ($appProc.ExitCode -eq -2146762751) {
        Write-Host '  NVIDIA App installer returned the known NVIDIA trust-store code; continuing to payload/version/window verification.' -ForegroundColor DarkYellow
    } else {
        Write-Host ("  NVIDIA App installer exit: {0}" -f $appProc.ExitCode) -ForegroundColor Gray
    }
    if ($appProc.ExitCode -notin @(0,3010,-2146762751)) { throw ("NVIDIA App installer failed with exit {0}" -f $appProc.ExitCode) }
    $appExe = 'C:\Program Files\NVIDIA Corporation\NVIDIA App\CEF\NVIDIA App.exe'
    if (-not (Test-Path -LiteralPath $appExe -PathType Leaf)) { throw 'NVIDIA App executable is missing after reinstall.' }
    $appVersion = (Get-Item -LiteralPath $appExe).VersionInfo.ProductVersion
    if ($appVersion -ne $officialApp.Version) { throw ("NVIDIA App version verification failed: {0} expected {1}" -f $appVersion,$officialApp.Version) }
    Write-Host '[4/4] Launching NVIDIA App Drivers tab and waiting for a ready window...' -ForegroundColor Yellow
    try { Start-Process 'nvidiaapp://route/#nvapp/drivers' | Out-Null } catch {}
    Start-Process -FilePath $appExe -WorkingDirectory (Split-Path -Parent $appExe) -ArgumentList 'nvidiaapp://route/#nvapp/drivers' | Out-Null
    Start-Sleep -Seconds 3
    try { Start-Process 'nvidiaapp://route/#nvapp/drivers' | Out-Null } catch {}
    $appWindow = Wait-NvidWindow -TitlePattern @('NVIDIA*') -ProcessNames @('NVIDIA App') -ExcludeTitlePattern @('*Control Panel*') -TimeoutSeconds 90
    if (-not $appWindow) { throw 'NVIDIA App did not open a visible ready window.' }
    Start-Sleep -Seconds 8
    try { Start-Process 'nvidiaapp://route/#nvapp/drivers' | Out-Null } catch {}
    [pscustomobject]@{
        Gpu = $gpu.Name
        DriverVersion = $healthAfter.WmiMarketingVersion
        DriverHealth = $healthAfter.Classification
        NvidiaAppVersion = $appVersion
        NvidiaAppPath = $appExe
        NvidiaAppWindow = $appWindow.MainWindowTitle
        DriverSource = $officialDriver.SourceURL
        AppSource = $officialApp.PageURL
    } | Format-List | Out-Host
    Write-Host 'NVID completed successfully.' -ForegroundColor Green
}

function global:Invoke-ProfileNvidPostFailureRecovery {
    param([Parameter(Mandatory=$true)]$ErrorRecord)
    $message = [string]$ErrorRecord.Exception.Message
    if ($message -notmatch 'NVIDIA Control Panel launch failed|NVIDIA Control Panel is not visibly open|Timed out waiting for window') { return $false }
    Write-Host ("  Recovering from NVIDIA UI launch verification failure: {0}" -f $message) -ForegroundColor DarkYellow
    $appExe = 'C:\Program Files\NVIDIA Corporation\NVIDIA App\CEF\NVIDIA App.exe'
    if (-not (Test-Path -LiteralPath $appExe -PathType Leaf)) { return $false }
    try { Start-Process -FilePath $appExe -WorkingDirectory (Split-Path -Parent $appExe) | Out-Null } catch {}
    $appWindow = Wait-NvidWindow -TitlePattern @('NVIDIA*') -ProcessNames @('NVIDIA App') -ExcludeTitlePattern @('*Control Panel*') -TimeoutSeconds 60
    $cplPackage = Get-AppxPackage -Name 'NVIDIACorp.NVIDIAControlPanel' -ErrorAction SilentlyContinue | Select-Object -First 1
    $cplWindow = Wait-NvidWindow -TitlePattern @('*NVIDIA Control Panel*','NVIDIA*') -ProcessNames @('nvcplui','vcplui','ApplicationFrameHost') -TimeoutSeconds 4
    if (-not $cplWindow -and $cplPackage -and $cplPackage.InstallLocation) {
        foreach ($candidateName in @('nvcplui.exe','vcplui.exe')) {
            $candidatePath = Join-Path $cplPackage.InstallLocation $candidateName
            if (Test-Path -LiteralPath $candidatePath -PathType Leaf) {
                try { Start-Process -FilePath $candidatePath | Out-Null } catch {}
                $cplWindow = Wait-NvidWindow -TitlePattern @('*NVIDIA Control Panel*','NVIDIA*') -ProcessNames @('nvcplui','vcplui','ApplicationFrameHost') -TimeoutSeconds 90
                if ($cplWindow) { break }
            }
        }
    }
    $driver = Get-CimInstance Win32_PnPSignedDriver | Where-Object { $_.DeviceName -match 'NVIDIA|RTX|GeForce' -or $_.Manufacturer -match 'NVIDIA' } | Sort-Object DriverDate -Descending | Select-Object -First 1
    $appVersion = (Get-Item -LiteralPath $appExe).VersionInfo.ProductVersion
    if ($driver -and $appWindow -and $cplPackage -and $cplWindow) {
        Write-Host 'NVID completed successfully after UI launch recovery.' -ForegroundColor Green
        [pscustomobject]@{
            DriverDevice = $driver.DeviceName
            DriverVersion = $driver.DriverVersion
            NvidiaAppVersion = $appVersion
            NvidiaAppWindow = $appWindow.MainWindowTitle
            ControlPanelPackage = $cplPackage.PackageFullName
            ControlPanelWindow = $cplWindow.MainWindowTitle
            RecoveredFrom = $message
        } | Format-List | Out-Host
        return $true
    }
    return $false
}

function Invoke-RealFixNative([string]$Exe, [string[]]$Arguments) {
        Write-RealFixLog ("> {0} {1}" -f $Exe, ($Arguments -join ' '))
        & $Exe @Arguments 2>&1 | Tee-Object -FilePath $logPath -Append | Out-Host
        $code = [int]$LASTEXITCODE
        Write-RealFixLog ("exit={0}" -f $code)
        return $code
    }

function Invoke-RedockerDownload([string]$Url,[string]$Destination) {
        $dir=Split-Path -Parent $Destination
        if (-not (Test-Path -LiteralPath $dir -PathType Container)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
        Remove-Item -LiteralPath $Destination -Force -ErrorAction SilentlyContinue
        try { Get-BitsTransfer -AllUsers -ErrorAction SilentlyContinue | Where-Object { $_.DisplayName -eq 'Docker Desktop' } | Remove-BitsTransfer -Confirm:$false -ErrorAction SilentlyContinue } catch {}
        Write-RedockerStep 'downloading Docker Desktop with direct WebClient progress (BITS disabled to avoid 0%/unknown-size stall)'
        $wc=New-Object Net.WebClient
        $lastPct=-1
        $lastBytes=0L
        $lastProgress=Get-Date
        Register-ObjectEvent -InputObject $wc -EventName DownloadProgressChanged -SourceIdentifier RedockerDownloadProgress -Action {
            $pct=[int]$EventArgs.ProgressPercentage
            $bytes=[int64]$EventArgs.BytesReceived
            $total=[int64]$EventArgs.TotalBytesToReceive
            $script:RedockerDownloadLastBytes=$bytes
            $script:RedockerDownloadLastProgress=Get-Date
            if($pct -gt $script:RedockerDownloadLastPct){
                $script:RedockerDownloadLastPct=$pct
                $totalLabel=if($total -gt 0){ [math]::Round($total/1MB,0) } else { '?' }
                Write-Host ("`r[redocker] download {0}% ({1}/{2} MB)    " -f $pct,[math]::Round($bytes/1MB,0),$totalLabel) -NoNewline -ForegroundColor Cyan
            }
        } | Out-Null
        $script:RedockerDownloadLastPct=-1
        $script:RedockerDownloadLastBytes=0L
        $script:RedockerDownloadLastProgress=Get-Date
        try {
            $wc.DownloadFileAsync([Uri]$Url,$Destination)
            while($wc.IsBusy){
                Start-Sleep -Milliseconds 500
                if(((Get-Date)-$script:RedockerDownloadLastProgress).TotalSeconds -gt 60 -and $script:RedockerDownloadLastBytes -le 0){
                    $wc.CancelAsync(); throw 'direct download made no byte progress for 60s'
                }
            }
            Write-Host ''
        } finally {
            try { Unregister-Event -SourceIdentifier RedockerDownloadProgress -ErrorAction SilentlyContinue } catch {}
            try { Remove-Job -Name RedockerDownloadProgress -Force -ErrorAction SilentlyContinue } catch {}
            $wc.Dispose()
        }
        $item=Get-Item -LiteralPath $Destination -ErrorAction Stop
        if ($item.Length -lt 100MB) { throw "downloaded installer too small: $($item.Length) bytes" }
        Write-RedockerStep ("downloaded installer {0} MB" -f [math]::Round($item.Length/1MB,0))
    }

function Invoke-RedockerSafeNative {
        param([string]$Label,[string]$FilePath,[string[]]$ArgumentList,[int]$TimeoutSeconds = 900)
        Write-RedockerSafeLine ("{0}: {1} {2}" -f $Label,$FilePath,($ArgumentList -join ' '))
        if([string]::IsNullOrWhiteSpace($FilePath) -or -not (Test-Path -LiteralPath $FilePath)){ Write-RedockerSafeLine ("{0} executable not found: {1}" -f $Label,$FilePath) Yellow; return 9009 }
        try {
            $p = Start-Process -FilePath $FilePath -ArgumentList $ArgumentList -PassThru -NoNewWindow -ErrorAction Stop
            if(-not $p.WaitForExit([Math]::Max(1,$TimeoutSeconds) * 1000)){
                try { $p.Kill() } catch { }
                Write-RedockerSafeLine ("{0} timed out after {1}s and was stopped" -f $Label,$TimeoutSeconds) Yellow
                return 124
            }
            $p.Refresh()
            Write-RedockerSafeLine ("{0} exit={1}" -f $Label,$p.ExitCode)
            return [int]$p.ExitCode
        } catch {
            Write-RedockerSafeLine ("{0} failed: {1}" -f $Label,$_.Exception.Message) Yellow
            return 1
        }
    }

function Invoke-UpgraderDockerDesktopProtectedLatest {
        param([string]$WingetPath)

        if ([string]::IsNullOrWhiteSpace($WingetPath) -or -not (Test-Path -LiteralPath $WingetPath -PathType Leaf)) {
            Write-Host '[upgrader] Docker Desktop latest check skipped: winget unavailable'
            return $true
        }

        # Do not launch hidden docker.exe probes from upgrader. Docker Desktop
        # upgrades are deferred unless explicitly handled by redocker/getdocker.
        $runningContainers = 1

        $beforeList = (& $WingetPath upgrade --id Docker.DockerDesktop --exact --include-unknown --accept-source-agreements --disable-interactivity 2>&1 | Out-String)
        if ($beforeList -match '(?i)(No available upgrade found|No installed package found matching input criteria|No newer package versions are available)') {
            Write-Host '[upgrader] Docker Desktop already latest or not winget-managed'
            $env:HERMES_UPGRADER_DOCKER_DESKTOP_PROTECTED = '1'
            return $true
        }

        if ($runningContainers -gt 0) {
            Write-Warning ("Docker Desktop update is available but deferred to protect {0} running Docker container(s); no Docker restart/stop was attempted." -f $runningContainers)
            $env:HERMES_UPGRADER_DOCKER_DESKTOP_PROTECTED = '1'
            return $true
        }

        Write-Host '[upgrader] Docker Desktop protected latest pass (silent, no interactive close/reboot requested)'
        $dockerArgs = @(
            'upgrade',
            '--id', 'Docker.DockerDesktop',
            '--exact',
            '--include-unknown',
            '--accept-package-agreements',
            '--accept-source-agreements',
            '--silent',
            '--disable-interactivity',
            '--force'
        )
        $dockerOutput = (& $WingetPath @dockerArgs 2>&1 | Out-String)
        if ($dockerOutput) { Write-Host $dockerOutput.Trim() }
        $ok = ($LASTEXITCODE -eq 0 -or $dockerOutput -match '(?i)(No available upgrade found|No newer package versions are available|Successfully (installed|upgraded|updated))')
        if ($dockerOutput -match '(?i)(restart|reboot|close Docker|application is currently running|installer failed)') {
            Write-Warning 'Docker Desktop installer requested/mentioned restart, close, or failure; leaving Docker running and letting the existing upgrader continue with other apps.'
        }
        $env:HERMES_UPGRADER_DOCKER_DESKTOP_PROTECTED = '1'
        return [bool]$ok
    }

function Invoke-UpgraderStep {
        param(
            [string]$Name,
            [scriptblock]$Action,
            [int]$Retries = 3,
            [int]$SleepSeconds = 2
        )

        for ($i = 1; $i -le $Retries; $i++) {
            try {
                $global:LASTEXITCODE = $null
                & $Action
                if ($LASTEXITCODE -eq 0 -or $null -eq $LASTEXITCODE) {
                    return $true
                }
            } catch {
                if ($i -eq $Retries) {
                    Write-Warning ("upgrader step failed [{0}]: {1}" -f $Name, $_.Exception.Message)
                }
            }

            if ($i -lt $Retries) {
                Start-Sleep -Seconds $SleepSeconds
            }
        }

        return $false
    }

