old_value="""  const valueFor=(q,type)=>{let l=q.toLowerCase();
   if(/g-recaptcha|captcha/.test(l)) return '';
   if(/phone/.test(l)) return '';
   if(/how many|years|year(s)? of|experience/.test(l)) return '5';
   if(/notice period/.test(l)) return '0';
   if(/salary|compensation|rate|pay/.test(l)) return '0';
   if(/city|current location|location/.test(l)) return 'Tel Aviv';
   if(/country/.test(l)) return 'Israel';
   if(type==='number') return '5';
   return 'Yes';};"""
new_value="""  const valueFor=(q,type)=>{let l=q.toLowerCase();
   if(/g-recaptcha|captcha/.test(l)) return '';
   if(/phone|mobile|whatsapp/.test(l)) return '';
   if(/notice period|available to start|start date/.test(l)) return '0';
   if(/salary|compensation|rate|pay/.test(l)) return '0';
   if(/city|current location|location/.test(l)) return 'Tel Aviv';
   if(/country/.test(l)) return 'Israel';
   if(/postal|zip/.test(l)) return '61000';
   if(/how many|years|year(s)? of|experience|yrs|months|count|number/.test(l)) return '1';
   if(/english|language/.test(l)) return 'Professional';
   if(/github|portfolio|website|linkedin/.test(l)) return '';
   if(/why|cover letter|summary|about you|motivation/.test(l)) return 'I am a motivated junior DevOps and system administrator candidate with hands-on Linux, Windows, cloud, automation, and troubleshooting experience. I learn quickly and can support reliable infrastructure and operations.';
   if(/address/.test(l)) return 'Tel Aviv, Israel';
   if(type==='number') return '1';
   if(type==='textarea') return 'I am a motivated junior DevOps and system administrator candidate with hands-on Linux, Windows, cloud, automation, and troubleshooting experience.';
   return 'Yes';};"""
literal(old_value, new_value, 'valueFor')

old_select="""   const q=questionFor(sel); if(/sponsorship|authorized to work|authorised to work|citizenship|clearance|commut|relocation/i.test(q)) continue;
   let opt=[...sel.options].find(o=>/yes|true|remote|israel|english/i.test(o.textContent))||[...sel.options].find(o=>o.value&&!/select|choose/i.test(o.textContent));
   if(opt){sel.value=opt.value; sel.dispatchEvent(new Event('change',{bubbles:true})); actions.push({kind:'SELECT',q:q.slice(0,160),v:clean(opt.textContent)});}"""
new_select="""   const q=questionFor(sel);
   const ql=q.toLowerCase();
   let prefs=[];
   if(/sponsorship|visa/.test(ql)) prefs=[/^no\\b/i,/no/i];
   else if(/authorized|authorised|eligible|permission|right to work|work permit/.test(ql)) prefs=[/^yes\\b/i,/yes/i];
   else if(/clearance/.test(ql)) prefs=[/^no\\b/i,/no/i];
   else if(/citizenship|country|location/.test(ql)) prefs=[/israel/i,/tel aviv/i,/remote/i,/yes/i];
   else if(/commut|relocation|relocate/.test(ql)) prefs=[/^yes\\b/i,/yes/i,/remote/i,/hybrid/i,/no/i];
   else if(/language|english/.test(ql)) prefs=[/professional/i,/fluent/i,/advanced/i,/english/i];
   else if(/experience|years|level/.test(ql)) prefs=[/^1\\b/i,/1\\+?/i,/junior/i,/entry/i,/0-1/i,/1-2/i];
   else if(/work model|workplace|remote|hybrid/.test(ql)) prefs=[/remote/i,/hybrid/i,/yes/i];
   else prefs=[/yes/i,/true/i,/remote/i,/israel/i,/english/i];
   let opts=[...sel.options].filter(o=>o.value&&!/select|choose/i.test(o.textContent));
   let opt=null;
   for(const ptn of prefs){ opt=opts.find(o=>ptn.test(o.textContent)); if(opt) break; }
   opt=opt||opts[0];
   if(opt){sel.value=opt.value; sel.dispatchEvent(new Event('change',{bubbles:true})); actions.push({kind:'SELECT',q:q.slice(0,160),v:clean(opt.textContent)});}"""
literal(old_select, new_select, 'selects')

smart_controls="""  for(const name of [...new Set([...document.querySelectorAll('[role="dialog"] input[type="radio"], .jobs-easy-apply-modal input[type="radio"]')].map(r=>r.name).filter(Boolean))]){
   const group=[...document.querySelectorAll('[role="dialog"] input[type="radio"][name="'+CSS.escape(name)+'"], .jobs-easy-apply-modal input[type="radio"][name="'+CSS.escape(name)+'"]')].filter(visible);
   if(!group.length||group.some(r=>r.checked)||group.some(r=>r.disabled)) continue;
   const q=questionFor(group[0]); const ql=q.toLowerCase();
   if(/captcha|security verification/.test(ql)) continue;
   const labelled=group.map(r=>({el:r,txt:clean((document.querySelector('label[for="'+CSS.escape(r.id)+'"]')||r.closest('label')||r.parentElement)?.innerText||r.value||r.getAttribute('aria-label')||'')}));
   let pick=null;
   if(/sponsorship|visa/.test(ql)) pick=labelled.find(x=>/^no\\b/i.test(x.txt));
   else if(/clearance/.test(ql)) pick=labelled.find(x=>/^no\\b/i.test(x.txt))||labelled.find(x=>/^yes\\b/i.test(x.txt));
   else if(/citizenship/.test(ql)) pick=labelled.find(x=>/israel/i.test(x.txt))||labelled.find(x=>/^yes\\b/i.test(x.txt))||labelled[0];
   else if(/relocation|relocate|commut/.test(ql)) pick=labelled.find(x=>/^yes\\b/i.test(x.txt))||labelled.find(x=>/^no\\b/i.test(x.txt));
   else if(/authorized|authorised|eligible|permission|can you|are you|do you/.test(ql)) pick=labelled.find(x=>/^yes\\b/i.test(x.txt))||labelled.find(x=>/^no\\b/i.test(x.txt));
   pick=pick||labelled.find(x=>/^yes\\b/i.test(x.txt))||labelled[0];
   if(pick){pick.el.click(); pick.el.dispatchEvent(new Event('change',{bubbles:true})); actions.push({kind:'RADIO',q:q.slice(0,160),v:pick.txt});}
  }
  for(const cb of [...document.querySelectorAll('[role="dialog"] input[type="checkbox"], .jobs-easy-apply-modal input[type="checkbox"]')]){
   if(!visible(cb)||cb.disabled||cb.checked) continue;
   const q=questionFor(cb); const ql=q.toLowerCase();
   if(/captcha|security|unsubscribe|do not|don't|not agree/.test(ql)) continue;
   if(cb.required||/agree|confirm|acknowledge|consent|terms|privacy|accurate|certify/.test(ql)){
    cb.click(); cb.dispatchEvent(new Event('change',{bubbles:true})); actions.push({kind:'CHECKBOX',q:q.slice(0,160),v:'checked'});
   }
  }
  return actions;
 });"""
literal("  return actions;\n });", smart_controls, 'radio_checkbox_controls')

