function global:megafix {
    [CmdletBinding()]
    param(
        [ValidateRange(1,10)][int]$MaxCycles = 3,
        [switch]$SkipComponentCleanup,
        [switch]$SelfTest
    )

    $ErrorActionPreference = 'Stop'
    $ps5 = 'C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe'
    $dism = 'C:\Windows\System32\dism.exe'
    $sfc = 'C:\Windows\System32\sfc.exe'
    $chkdsk = 'C:\Windows\System32\chkdsk.exe'
    $logRoot = Join-Path $env:LOCALAPPDATA 'Hermes\megafix'
    if (-not (Test-Path -LiteralPath $logRoot)) { New-Item -ItemType Directory -Path $logRoot -Force | Out-Null }
    $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
    $log = Join-Path $logRoot ("megafix-$stamp.log")

    function Write-MegaFixLine([string]$Message) {
        $line = '[{0}] {1}' -f (Get-Date -Format 'HH:mm:ss'), $Message
        Write-Host $line
        Add-Content -LiteralPath $log -Value $line -Encoding UTF8
    }

    function Invoke-MegaFixNative {
        param([string]$Label,[string]$FilePath,[string[]]$Arguments)
        Write-MegaFixLine ("START: {0}" -f $Label)
        Write-MegaFixLine ("CMD: {0} {1}" -f $FilePath, ($Arguments -join ' '))
        $old = $ErrorActionPreference
        try {
            $ErrorActionPreference = 'Continue'
            & $FilePath @Arguments 2>&1 | ForEach-Object {
                $text = [string]$_
                Write-Host $text
                Add-Content -LiteralPath $log -Value $text -Encoding UTF8
            }
            $code = if ($null -eq $global:LASTEXITCODE) { 0 } else { [int]$global:LASTEXITCODE }
        } finally {
            $ErrorActionPreference = $old
        }
        Write-MegaFixLine ("END: {0}; exit={1}" -f $Label, $code)
        return $code
    }

    function Test-MegaFixPendingReboot {
        $keys = @(
            'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending',
            'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired',
            'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager'
        )
        foreach ($k in $keys) {
            try {
                if ($k -like '*Session Manager') {
                    $v = (Get-ItemProperty -LiteralPath $k -Name PendingFileRenameOperations -ErrorAction SilentlyContinue).PendingFileRenameOperations
                    if ($v) { return $true }
                } elseif (Test-Path -LiteralPath $k) { return $true }
            } catch { }
        }
        return $false
    }

    if ($SelfTest) {
        [pscustomobject]@{
            Function = 'megafix'
            PowerShell = $PSVersionTable.PSVersion.ToString()
            UsesPS5 = (Test-Path -LiteralPath $ps5)
            Dism = (Test-Path -LiteralPath $dism)
            Sfc = (Test-Path -LiteralPath $sfc)
            Chkdsk = (Test-Path -LiteralPath $chkdsk)
            LogRoot = $logRoot
            MaxCycles = $MaxCycles
            Plan = 'Component cleanup -> DISM RestoreHealth -> SFC scan loop -> SFC verify-only gate -> CHKDSK online scan -> pending reboot detection'
        }
        return
    }

    $admin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    Write-MegaFixLine 'MEGAFIX: Windows corruption repair started'
    Write-MegaFixLine ("PowerShell: {0}; Admin: {1}; Log: {2}" -f $PSVersionTable.PSVersion, $admin, $log)
    if (-not $admin) { throw 'megafix must be run from an elevated Windows PowerShell 5 window.' }

    if (-not $SkipComponentCleanup) {
        [void](Invoke-MegaFixNative 'DISM StartComponentCleanup' $dism @('/Online','/Cleanup-Image','/StartComponentCleanup','/NoRestart'))
    }

    $clean = $false
    for ($cycle = 1; $cycle -le $MaxCycles; $cycle++) {
        Write-MegaFixLine ("CYCLE {0}/{1}: repair pass" -f $cycle, $MaxCycles)
        [void](Invoke-MegaFixNative 'DISM CheckHealth' $dism @('/Online','/Cleanup-Image','/CheckHealth'))
        [void](Invoke-MegaFixNative 'DISM RestoreHealth' $dism @('/Online','/Cleanup-Image','/RestoreHealth','/NoRestart'))
        [void](Invoke-MegaFixNative 'SFC ScanNow' $sfc @('/scannow'))
        $verifyTextPath = Join-Path $logRoot ("sfc-verify-$stamp-cycle$cycle.txt")
        Write-MegaFixLine 'START: SFC VerifyOnly gate'
        $old = $ErrorActionPreference
        try {
            $ErrorActionPreference = 'Continue'
            & $sfc /verifyonly 2>&1 | Tee-Object -FilePath $verifyTextPath | ForEach-Object {
                $t = [string]$_
                Write-Host $t
                Add-Content -LiteralPath $log -Value $t -Encoding UTF8
            }
        } finally { $ErrorActionPreference = $old }
        $verifyText = Get-Content -LiteralPath $verifyTextPath -Raw -ErrorAction SilentlyContinue
        if ($verifyText -match 'did not find any integrity violations') {
            $clean = $true
            Write-MegaFixLine 'SFC VERIFY CLEAN: no integrity violations remain.'
            break
        }
        Write-MegaFixLine 'SFC VERIFY STILL REPORTS CORRUPTION: another repair pass will run if cycles remain.'
    }

    [void](Invoke-MegaFixNative 'CHKDSK online scan C:' $chkdsk @('C:','/scan'))

    $pending = Test-MegaFixPendingReboot
    if ($pending) {
        Write-MegaFixLine 'PENDING REBOOT DETECTED: reboot is required to finish file replacement; run megafix again after reboot.'
    }

    if ($clean -and -not $pending) {
        Write-MegaFixLine 'MEGAFIX RESULT: clean now; no SFC integrity violations detected and no pending reboot marker found.'
    } elseif ($clean -and $pending) {
        Write-MegaFixLine 'MEGAFIX RESULT: clean verification, but reboot is required to make the repair durable.'
    } else {
        Write-MegaFixLine 'MEGAFIX RESULT: corruption still reported after max repair cycles; inspect CBS.log lines around latest SFC entries.'
    }
    Write-MegaFixLine 'MEGAFIX: finished.'
}

