function global:myth {
    [CmdletBinding()]
    param(
        [string] $SourceRoot = 'E:\games\black-myth-wukong\b1\Saved\SaveGames',
        [string] $BackupRoot = 'F:\backup\gamesaves\Black Myth Wukong',
        [switch] $Quiet,
        [switch] $DirectOnly
    )

    $oldEap = $ErrorActionPreference
    $ErrorActionPreference = 'Stop'
    $shadow = $null
    $shadowLink = $null
    $dest = $null
    try {
        $source = (Resolve-Path -LiteralPath $SourceRoot).ProviderPath.TrimEnd('\')
        if (-not (Test-Path -LiteralPath $source -PathType Container)) { throw ('missing source SaveGames folder: {0}' -f $SourceRoot) }
        if (-not (Test-Path -LiteralPath $BackupRoot)) { [void](New-Item -ItemType Directory -Path $BackupRoot -Force) }
        $backupBase = (Resolve-Path -LiteralPath $BackupRoot).ProviderPath.TrimEnd('\')
        $stamp = Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'
        $dest = Join-Path $backupBase $stamp
        $destSave = Join-Path $dest 'SaveGames'
        [void](New-Item -ItemType Directory -Path $destSave -Force)

        $copySource = $source
        $usedSnapshot = $false
        $snapshotId = $null
        $volumeRoot = [System.IO.Path]::GetPathRoot($source)
        if (-not $DirectOnly) {
            try {
                $shadowClass = [wmiclass]'root\cimv2:Win32_ShadowCopy'
                $create = $shadowClass.Create($volumeRoot, 'ClientAccessible')
                if ($create.ReturnValue -eq 0) {
                    $snapshotId = [string]$create.ShadowID
                    $shadow = Get-WmiObject -Class Win32_ShadowCopy | Where-Object { $_.ID -eq $snapshotId } | Select-Object -First 1
                    if ($shadow -and $shadow.DeviceObject) {
                        $rel = $source.Substring($volumeRoot.Length).TrimStart('\')
                        $shadowLink = Join-Path $env:TEMP ('myth_vss_' + [guid]::NewGuid().ToString('N'))
                        $shadowRoot = $shadow.DeviceObject.TrimEnd('\') + '\'
                        $mk = cmd.exe /c mklink /d "$shadowLink" "$shadowRoot" 2>&1
                        if ($LASTEXITCODE -ne 0 -or -not (Test-Path -LiteralPath $shadowLink)) { throw ('failed to create VSS access link: ' + (($mk | Out-String).Trim())) }
                        $copySource = (Join-Path $shadowLink $rel).TrimEnd('\')
                        if (-not (Test-Path -LiteralPath $copySource -PathType Container)) { throw ('VSS source path unavailable through link: ' + $copySource) }
                        $usedSnapshot = $true
                    }
                }
            } catch {
                if (-not $Quiet) { Write-Host ('[myth] VSS snapshot unavailable, using direct copy: {0}' -f $_.Exception.Message) }
            }
        }

        $args = @($copySource, $destSave, '/E', '/XJ', '/R:5', '/W:1', '/FFT', '/COPY:DAT', '/DCOPY:DAT', '/Z', '/NP', '/MT:8')
        if ($Quiet) { $args += @('/NFL','/NDL') }
        & robocopy.exe @args | Out-Host
        $rc = $LASTEXITCODE
        if ($rc -gt 7) { throw ('robocopy backup failed with exit code {0}' -f $rc) }

        $sourceHashes = @(Get-ChildItem -LiteralPath $copySource -Recurse -File -Force | Sort-Object FullName | ForEach-Object {
            $rel = $_.FullName.Substring($copySource.Length).TrimStart('\')
            $h = Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256
            New-Object psobject -Property ([ordered]@{ RelativePath=$rel; Size=$_.Length; Hash=$h.Hash })
        })
        $backupHashes = @(Get-ChildItem -LiteralPath $destSave -Recurse -File -Force | Sort-Object FullName | ForEach-Object {
            $rel = $_.FullName.Substring($destSave.Length).TrimStart('\')
            $h = Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256
            New-Object psobject -Property ([ordered]@{ RelativePath=$rel; Size=$_.Length; Hash=$h.Hash })
        })
        $srcJson = ($sourceHashes | ConvertTo-Json -Depth 5 -Compress)
        $dstJson = ($backupHashes | ConvertTo-Json -Depth 5 -Compress)
        if ($srcJson -ne $dstJson) { throw 'backup hash verification failed; refusing to call this backup good' }

        $primary = @($backupHashes | Where-Object { $_.RelativePath -like '*ArchiveSaveFile*.sav' } | Select-Object -First 1)
        $manifest = New-Object psobject -Property ([ordered]@{
            Game = 'Black Myth: Wukong'
            Created = (Get-Date).ToString('o')
            SourceSaveFolder = $source
            BackupFolder = $dest
            BackupSaveFolder = $destSave
            UsedVssSnapshot = $usedSnapshot
            SnapshotId = $snapshotId
            RobocopyExitCode = $rc
            FileCount = $backupHashes.Count
            TotalBytes = (($backupHashes | Measure-Object -Property Size -Sum).Sum)
            Restore = 'remyth'
        })
        $manifest | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $dest 'manifest.json') -Encoding UTF8 -Force
        @(
            'Game: Black Myth: Wukong'
            ('Created: {0}' -f (Get-Date).ToString('o'))
            ('Source save folder: {0}' -f $source)
            ('Backup folder: {0}' -f $dest)
            'Restore behavior: run remyth to replace current SaveGames with the latest timestamped backup, matching /myth restore.'
        ) | Set-Content -LiteralPath (Join-Path $dest 'RESTORE_INFO.txt') -Encoding UTF8 -Force

        if (-not $Quiet) {
            Write-Host 'myth: backup created.'
            Write-Host ('backup={0}' -f $dest)
            Write-Host ('verify_backup_hash_match=True files={0} bytes={1} used_vss_snapshot={2}' -f $backupHashes.Count,$manifest.TotalBytes,$usedSnapshot)
            Write-Host 'restore=remyth'
        }
        return $manifest
    } catch {
        if ($dest -and (Test-Path -LiteralPath $dest)) { Remove-Item -LiteralPath $dest -Recurse -Force -ErrorAction SilentlyContinue }
        throw
    } finally {
        if ($shadowLink -and (Test-Path -LiteralPath $shadowLink)) { try { cmd.exe /c rmdir "$shadowLink" 2>$null | Out-Null } catch { } }
        if ($shadow) { try { [void]$shadow.Delete() } catch { } }
        $ErrorActionPreference = $oldEap
    }
}

function global:New-HermesDockerRealtimeMmenuHelper {
    [CmdletBinding()]
    param([Parameter(Mandatory=$true)][string]$SourceScript)
    if (-not (Test-Path -LiteralPath $SourceScript -PathType Leaf)) { throw "Docker backup helper missing: $SourceScript" }
    $sourcePath = (Resolve-Path -LiteralPath $SourceScript -ErrorAction Stop).ProviderPath
    $raw = [IO.File]::ReadAllText($sourcePath, [Text.Encoding]::UTF8)
    $tokens = $null
    $errors = $null
    [void][System.Management.Automation.Language.Parser]::ParseInput($raw, [ref]$tokens, [ref]$errors)
    if ($errors.Count -gt 0) { throw "Docker source helper parser error: $($errors[0].Message)" }
    if ($raw -match 'Where-Object\s*\{\s*\[CmdletBinding\(\)\]') { throw 'source helper contains Where-Object/CmdletBinding corruption' }
    if ($raw -notmatch 'Invoke-HermesDockerCommanderProcess' -or $raw -notmatch 'HermesProgressReader' -or $raw -notmatch 'file_percent' -or $raw -notmatch 'Wait-MmenuCVisibleRetry' -or $raw -notmatch '\$useFast = \$false' -or $raw -notmatch 'for\(\$attempt=1;\$true;\$attempt\+\+\)') { throw 'Docker source helper sentinel missing' }
    if ($raw -match '(?m)\[int\]\s*\$(?:ContextTotalBytes|[^=\r\n;]*Bytes)\b') { throw 'Docker source helper contains Int32 byte counter risk' }
    if ($raw -match '(?m)\[Math\]::Max\(\s*(?:\d+|\[int\][^,\r\n\)]*)\s*,\s*\$[^,\r\n\)]*(?:Bytes|total|done)\b') { throw 'Docker source helper contains Int32 Math.Max byte-total risk' }
    try { Remove-Item -LiteralPath 'C:\Temp\hermes-docker-realtime-helper' -Recurse -Force -ErrorAction SilentlyContinue } catch { }
    return $sourcePath
}

