function Optimize-CurrentTerminalResponsiveness {
    try {
        $current = [System.Diagnostics.Process]::GetCurrentProcess()
        if ($current.PriorityClass -in @('Idle', 'BelowNormal', 'Normal')) {
            $current.PriorityClass = 'AboveNormal'
        }

        $processId = $PID
        for ($depth = 0; $depth -lt 6; $depth++) {
            $procInfo = Get-CimInstance Win32_Process -Filter "ProcessId=$processId" -ErrorAction SilentlyContinue
            if (-not $procInfo -or -not $procInfo.ParentProcessId) { break }
            $processId = [int]$procInfo.ParentProcessId
            $parent = Get-Process -Id $processId -ErrorAction SilentlyContinue
            if (-not $parent) { continue }
            if ($parent.ProcessName -eq 'WindowsTerminal') {
                if ($parent.PriorityClass -ne 'High') { $parent.PriorityClass = 'High' }
            } elseif ($parent.ProcessName -in @('OpenConsole', 'conhost', 'cmd', 'powershell', 'pwsh')) {
                if ($parent.PriorityClass -in @('Idle', 'BelowNormal', 'Normal')) { $parent.PriorityClass = 'AboveNormal' }
            }
        }
    } catch { }
}

function global:pip {
    [CmdletBinding()]
    param(
        [Parameter(ValueFromRemainingArguments=$true)]
        [string[]]$Arguments
    )

    $ErrorActionPreference = 'Stop'
    $pyLauncher = Join-Path $env:WINDIR 'py.exe'
    $python = $null
    if (Test-Path -LiteralPath $pyLauncher) {
        $python = (& $pyLauncher -3 -c "import sys; print(sys.executable)" 2>$null | Select-Object -First 1)
    }
    if ([string]::IsNullOrWhiteSpace($python) -or -not (Test-Path -LiteralPath $python.Trim())) {
        $pythonCmd = Get-Command python.exe -CommandType Application -ErrorAction Stop
        $python = $pythonCmd.Path
    } else {
        $python = $python.Trim()
    }

    $fixedArgs = New-Object System.Collections.Generic.List[string]
    foreach ($arg in $Arguments) {
        if ($arg -ieq 'interpreter') {
            Write-Host 'fixpip: mapping PyPI package name interpreter -> open-interpreter' -ForegroundColor Yellow
            [void]$fixedArgs.Add('open-interpreter')
        } else {
            [void]$fixedArgs.Add($arg)
        }
    }
    & $python -m pip @fixedArgs
}

