function Register-NvidAppProtocol {
        param([Parameter(Mandatory=$true)][string]$NvidiaAppExe)
        if (-not (Test-Path -LiteralPath $NvidiaAppExe -PathType Leaf)) { throw ("NVIDIA App protocol repair cannot find executable: {0}" -f $NvidiaAppExe) }
        $commandValue = '"' + $NvidiaAppExe + '" "%1"'
        $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
        foreach($root in @('HKCU:\Software\Classes\nvidiaapp','HKLM:\Software\Classes\nvidiaapp')) {
            try {
                if ($root -like 'HKLM:*' -and -not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { continue }
                New-Item -Path $root -Force | Out-Null
                Set-Item -Path $root -Value 'URL:NVIDIA App Protocol' -ErrorAction SilentlyContinue
                New-ItemProperty -Path $root -Name 'URL Protocol' -PropertyType String -Value '' -Force | Out-Null
                New-Item -Path (Join-Path $root 'DefaultIcon') -Force | Out-Null
                Set-Item -Path (Join-Path $root 'DefaultIcon') -Value ('"{0}",0' -f $NvidiaAppExe) -ErrorAction SilentlyContinue
                New-Item -Path (Join-Path $root 'shell\open\command') -Force | Out-Null
                Set-Item -Path (Join-Path $root 'shell\open\command') -Value $commandValue -ErrorAction SilentlyContinue
            } catch { Write-Host ("[nvid] warning: failed to write NVIDIA App protocol key {0}: {1}" -f $root,$_.Exception.Message) -ForegroundColor Yellow }
        }
        foreach($appPathsRoot in @('HKCU:\Software\Microsoft\Windows\CurrentVersion\App Paths\NVIDIA App.exe','HKLM:\Software\Microsoft\Windows\CurrentVersion\App Paths\NVIDIA App.exe')) {
            try {
                if ($appPathsRoot -like 'HKLM:*' -and -not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { continue }
                New-Item -Path $appPathsRoot -Force | Out-Null
                Set-Item -Path $appPathsRoot -Value $NvidiaAppExe -ErrorAction SilentlyContinue
                New-ItemProperty -Path $appPathsRoot -Name 'Path' -PropertyType String -Value (Split-Path -Parent $NvidiaAppExe) -Force | Out-Null
            } catch { Write-Host ("[nvid] warning: failed to write NVIDIA App App Paths key {0}: {1}" -f $appPathsRoot,$_.Exception.Message) -ForegroundColor Yellow }
        }
        $verifyCommand = $null
        foreach($verifyPath in @('HKCU:\Software\Classes\nvidiaapp\shell\open\command','HKLM:\Software\Classes\nvidiaapp\shell\open\command')) {
            try { $verifyCommand = (Get-Item -LiteralPath $verifyPath -ErrorAction Stop).GetValue(''); if ($verifyCommand) { break } } catch {}
        }
        if (-not $verifyCommand -or $verifyCommand -notmatch [regex]::Escape($NvidiaAppExe)) { throw 'NVIDIA App protocol registration verification failed; nvidiaapp:// would still open Store/search.' }
        Write-NvidStep ("registered nvidiaapp:// protocol to {0}" -f $NvidiaAppExe)
        return $verifyCommand
    }

function Remove-DKillFastPath {
        param([string]$Path)
        if([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)){ return }
        $resolved = $null
        try { $resolved = (Resolve-Path -LiteralPath $Path -ErrorAction Stop).ProviderPath } catch { $resolved = $Path }
        if($resolved -notmatch '^(?i)C:\\'){ return }
        if($resolved -notmatch '(?i)(\\Docker\\?|\\Docker Desktop\\?|\\DockerDesktop\\?|\\containerd\\?|\\Windows\\Containers\\?|docker-desktop|ext4\.vhdx|\.avhdx$|docker.*\.vhdx)'){ return }
        $size = 0L
        try {
            $itemForSize = Get-Item -LiteralPath $resolved -Force -ErrorAction SilentlyContinue
            if($itemForSize -and -not $itemForSize.PSIsContainer){ $size = [int64]$itemForSize.Length }
        } catch { $size = 0L }
        Write-DKillFastLine ("delete {0} ({1})" -f $resolved,(Format-DKillFastBytes $size)) DarkCyan
        if($PSCmdlet.ShouldProcess($resolved,'delete Docker-owned C-drive data/cache')){
            [void](Invoke-DKillFastBoundedRemove -Path $resolved)
        }
        if(-not (Test-Path -LiteralPath $resolved)){
            $script:DKillFastDeletedBytes += [int64]$size
        } elseif(-not $WhatIfPreference) {
            $remainingSize = if((Get-DKillFastRemainingMilliseconds) -gt 1500){ Get-DKillFastPathBytes -Path $resolved } else { -1L }
            if($remainingSize -gt 0){
                Write-DKillFastLine ("blocked still exists: {0} ({1})" -f $resolved,(Format-DKillFastBytes $remainingSize)) Yellow
            } elseif($remainingSize -lt 0) {
                Write-DKillFastLine ("blocked still exists: {0} (size scan skipped to preserve readiness deadline)" -f $resolved) Yellow
            } else {
                Write-DKillFastLine ("empty live folder remains/recreated: {0}" -f $resolved) DarkGray
            }
        }
    }

function Remove-DKillPath {
        param([string]$Path)
        if ([string]::IsNullOrWhiteSpace($Path)) { return }
        if (-not (Test-Path -LiteralPath $Path)) { return }
        $size = Get-DKillPathBytes -Path $Path
        Write-DKillLine ("deleting {0} ({1})" -f $Path,(Format-DKillBytes $size))
        try { Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop } catch {}
        if (Test-Path -LiteralPath $Path) {
            try {
                $empty = Join-Path $env:TEMP ('dkill-empty-' + [guid]::NewGuid().ToString('N'))
                New-Item -ItemType Directory -Force -Path $empty | Out-Null
                cmd.exe /c robocopy "$empty" "$Path" /MIR /R:0 /W:0 /NFL /NDL /NJH /NJS /NP 1>$null 2>$null
                Remove-Item -LiteralPath $empty -Recurse -Force -ErrorAction SilentlyContinue
                Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction SilentlyContinue
            } catch {}
        }
        if (Test-Path -LiteralPath $Path) { Write-DKillLine ("blocked: still exists: {0}" -f $Path) } else { $script:DKillDeletedBytes += $size }
    }

function Remove-RedockerPath([string]$Path) {
        if ([string]::IsNullOrWhiteSpace($Path) -or -not [IO.Path]::IsPathRooted($Path)) { return }
        if (-not (Test-Path -LiteralPath $Path)) { return }
        Write-RedockerStep ("purging {0}" -f $Path)
        try { cmd.exe /d /c "takeown /f `"$Path`" /r /d Y /a >nul 2>nul" | Out-Null } catch {}
        try { cmd.exe /d /c "icacls `"$Path`" /grant Administrators:F /t /q >nul 2>nul" | Out-Null } catch {}
        try { Remove-Item -LiteralPath $Path -Recurse -Force -ErrorAction Stop } catch { cmd.exe /d /c "rd /s /q `"$Path`" 2>nul & del /f /q `"$Path`" 2>nul" | Out-Null }
    }

function Remove-RedockerSafePath {
        param([string]$Path)
        if([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)){ return }
        $resolved = $null
        try { $resolved = (Resolve-Path -LiteralPath $Path -ErrorAction Stop).ProviderPath } catch { $resolved = $Path }
        if($resolved -notmatch '^(?i)C:\\'){ return }
        if($resolved -notmatch '(?i)(\\Docker\\?|\\DockerDesktop\\?|\\Docker Desktop\\?|\\containerd\\?|docker-desktop|ext4\.vhdx|docker.*\.vhdx)'){ return }
        Write-RedockerSafeLine ("purge {0}" -f $resolved) DarkCyan
        try { Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction Stop } catch { try { Remove-Item -LiteralPath $resolved -Recurse -Force -ErrorAction SilentlyContinue } catch { } }
    }

function Remove-WingupStateEntry($state, [string]$id) {
        $removed = $false
        for ($i = $state.Entries.Count - 1; $i -ge 0; $i--) {
            if ($state.Entries[$i].Id -eq $id) {
                $state.Entries.RemoveAt($i)
                $removed = $true
            }
        }
        return $removed
    }

function global:remyth {
    [CmdletBinding()]
    param(
        [string] $SourceRoot = 'E:\games\black-myth-wukong\b1\Saved\SaveGames',
        [string] $BackupRoot = 'F:\backup\gamesaves\Black Myth Wukong',
        [switch] $Quiet,
        [switch] $DryRun,
        [switch] $SkipGameRunningCheck
    )

    $oldEap = $ErrorActionPreference
    $ErrorActionPreference = 'Stop'
    try {
        $target = [System.IO.Path]::GetFullPath($SourceRoot).TrimEnd('\')
        $backupBase = (Resolve-Path -LiteralPath $BackupRoot).ProviderPath.TrimEnd('\')
        $candidates = @(Get-ChildItem -LiteralPath $backupBase -Directory -Force | Where-Object { $_.Name -match '^\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}$' -and (Test-Path -LiteralPath (Join-Path $_.FullName 'SaveGames') -PathType Container) } | Sort-Object Name -Descending)
        if (-not $candidates -or $candidates.Count -eq 0) { throw ('no prior backups found under {0}' -f $backupBase) }
        $selected = $candidates[0].FullName
        $restoreSrc = Join-Path $selected 'SaveGames'

        if (-not $SkipGameRunningCheck) {
            $gameProc = @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.ProcessName -in @('b1','b1-Win64-Shipping','BlackMythWukong','Black Myth Wukong') -or $_.ProcessName -like '*Wukong*' -or $_.ProcessName -like 'b1*' })
            if ($gameProc.Count -gt 0) { throw ('game appears to be running; close Black Myth before restore: ' + (($gameProc | ForEach-Object { $_.ProcessName + ':' + $_.Id }) -join ', ')) }
        }

        $backupHashes = @(Get-ChildItem -LiteralPath $restoreSrc -Recurse -File -Force | Sort-Object FullName | ForEach-Object {
            $rel = $_.FullName.Substring($restoreSrc.Length).TrimStart('\')
            $h = Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256
            New-Object psobject -Property ([ordered]@{ RelativePath=$rel; Size=$_.Length; Hash=$h.Hash })
        })
        if ($backupHashes.Count -eq 0) { throw ('selected backup has no files: {0}' -f $selected) }
        if ($DryRun) {
            Write-Host 'myth: dry-run restore check passed; no files changed.'
            Write-Host ('selected_backup={0}' -f $selected)
            return
        }

        $parent = Split-Path -Parent $target
        if (-not (Test-Path -LiteralPath $parent)) { [void](New-Item -ItemType Directory -Path $parent -Force) }
        $stamp = Get-Date -Format 'yyyyMMddHHmmss'
        $tmp = Join-Path $parent ('SaveGames.restore_tmp_' + $stamp + '_' + $PID)
        $prev = Join-Path $parent ('SaveGames.restore_prev_' + $stamp + '_' + $PID)
        if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Recurse -Force }
        [void](New-Item -ItemType Directory -Path $tmp -Force)
        try {
            $args = @($restoreSrc, $tmp, '/MIR', '/XJ', '/R:2', '/W:1', '/FFT', '/COPY:DAT', '/DCOPY:DAT', '/Z', '/NP', '/MT:8')
            if ($Quiet) { $args += @('/NFL','/NDL') }
            & robocopy.exe @args | Out-Host
            $rc = $LASTEXITCODE
            if ($rc -gt 7) { throw ('robocopy restore stage failed with exit code {0}' -f $rc) }
            $tmpHashes = @(Get-ChildItem -LiteralPath $tmp -Recurse -File -Force | Sort-Object FullName | ForEach-Object {
                $rel = $_.FullName.Substring($tmp.Length).TrimStart('\')
                $h = Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256
                New-Object psobject -Property ([ordered]@{ RelativePath=$rel; Size=$_.Length; Hash=$h.Hash })
            })
            if (($backupHashes | ConvertTo-Json -Depth 5 -Compress) -ne ($tmpHashes | ConvertTo-Json -Depth 5 -Compress)) { throw 'staged restore hash verification failed' }
            if (Test-Path -LiteralPath $target) { Rename-Item -LiteralPath $target -NewName (Split-Path -Leaf $prev) -Force }
            Rename-Item -LiteralPath $tmp -NewName (Split-Path -Leaf $target) -Force
            $finalHashes = @(Get-ChildItem -LiteralPath $target -Recurse -File -Force | Sort-Object FullName | ForEach-Object {
                $rel = $_.FullName.Substring($target.Length).TrimStart('\')
                $h = Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256
                New-Object psobject -Property ([ordered]@{ RelativePath=$rel; Size=$_.Length; Hash=$h.Hash })
            })
            if (($backupHashes | ConvertTo-Json -Depth 5 -Compress) -ne ($finalHashes | ConvertTo-Json -Depth 5 -Compress)) { throw 'final restore hash verification failed' }
            if (Test-Path -LiteralPath $prev) { Remove-Item -LiteralPath $prev -Recurse -Force }
            if (-not $Quiet) {
                Write-Host 'myth: restore complete; current SaveGames is an exact hash-verified mirror of the latest timestamped backup.'
                Write-Host ('selected_backup={0}' -f $selected)
                Write-Host ('to={0}' -f $target)
                Write-Host ('local_save_exactly_matches_backup=True files={0}' -f $backupHashes.Count)
            }
            return (New-Object psobject -Property ([ordered]@{ RestoredPath=$target; SelectedBackup=$selected; FileCount=$backupHashes.Count; LocalSaveExactlyMatchesBackup=$true }))
        } catch {
            if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Recurse -Force -ErrorAction SilentlyContinue }
            if ((-not (Test-Path -LiteralPath $target)) -and (Test-Path -LiteralPath $prev)) { Rename-Item -LiteralPath $prev -NewName (Split-Path -Leaf $target) -Force }
            throw
        }
    } finally {
        $ErrorActionPreference = $oldEap
    }
}

function Repair-RedockerSafeSettings {
        $dockerRoaming = Join-Path $env:APPDATA 'Docker'
        $dotDocker = Join-Path $env:USERPROFILE '.docker'
        $settingsStore = Join-Path $dockerRoaming 'settings-store.json'
        $settingsJson = Join-Path $dockerRoaming 'settings.json'
        $daemonJson = Join-Path $dotDocker 'daemon.json'
        $windowsDaemonJson = Join-Path $dotDocker 'windows-daemon.json'
        $fullSettings = "{`n  `"AutoStart`": false,`n  `"DisplayedOnboarding`": true,`n  `"EnableCLIHints`": true,`n  `"EnableDockerAI`": true,`n  `"EnableIntegrationWithDefaultWslDistro`": false,`n  `"FilesharingDirectories`": [`"C:\\\\`", `"E:\\\\`", `"F:\\\\`"],`n  `"InferenceCanUseGPUVariant`": true,`n  `"LicenseTermsVersion`": 2,`n  `"MemoryMiB`": 33792,`n  `"OpenUIOnStartupDisabled`": true,`n  `"SettingsVersion`": 44,`n  `"SwapMiB`": 3072,`n  `"ThemeSource`": `"dark`",`n  `"UseBackgroundIndexing`": false,`n  `"UseContainerdSnapshotter`": true,`n  `"UseVirtualizationFramework`": false,`n  `"WslEngineEnabled`": false`n}"
        $desktopSettings = "{`n  `"WslEngineEnabled`": false,`n  `"UseVirtualizationFramework`": false,`n  `"EnableIntegrationWithDefaultWslDistro`": false,`n  `"AutoStart`": false`n}"
        $daemonSettings = "{`n  `"builder`": {`"gc`": {`"defaultKeepStorage`": `"20GB`", `"enabled`": true}},`n  `"experimental`": false,`n  `"max-concurrent-downloads`": 10,`n  `"max-concurrent-uploads`": 10,`n  `"max-download-attempts`": 5,`n  `"features`": {`"buildkit`": true}`n}"
        $needsFullSettings = $true
        if(Test-Path -LiteralPath $settingsStore){
            try {
                $current = [IO.File]::ReadAllText($settingsStore)
                $needsFullSettings = ($current -notmatch 'FilesharingDirectories' -or $current -notmatch 'MemoryMiB' -or $current -notmatch 'UseContainerdSnapshotter')
            } catch { $needsFullSettings = $true }
        }
        if($needsFullSettings){ Save-RedockerSafeText -Path $settingsStore -Text $fullSettings; Write-RedockerSafeLine 'restored full Docker Desktop settings-store including C/E/F file sharing and resource settings' Green }
        if(-not (Test-Path -LiteralPath $settingsJson)){ Save-RedockerSafeText -Path $settingsJson -Text $desktopSettings }
        $needsDaemon = $true
        if(Test-Path -LiteralPath $daemonJson){
            try { $needsDaemon = ([IO.File]::ReadAllText($daemonJson) -notmatch 'max-concurrent-downloads') } catch { $needsDaemon = $true }
        }
        if($needsDaemon){ Save-RedockerSafeText -Path $daemonJson -Text $daemonSettings; Write-RedockerSafeLine 'restored daemon performance settings' Green }
        if(-not (Test-Path -LiteralPath $windowsDaemonJson)){ Save-RedockerSafeText -Path $windowsDaemonJson -Text "{`n}`n" }
        foreach($var in @('DOCKER_BUILDKIT','COMPOSE_DOCKER_CLI_BUILD')){
            try { [Environment]::SetEnvironmentVariable($var,'1','Machine') } catch { }
            Set-Item -Path ("Env:{0}" -f $var) -Value '1' -ErrorAction SilentlyContinue
        }
        try { [Environment]::SetEnvironmentVariable('BUILDKIT_PROGRESS','plain','Machine'); $env:BUILDKIT_PROGRESS='plain' } catch { }
    }

function global:rescc {
    [CmdletBinding()]
    param()
    global:Invoke-CcRequireAdmin
    $latest = @(Get-ComputerRestorePoint | Sort-Object SequenceNumber -Descending | Select-Object -First 1)
    if ($latest.Count -eq 0) { throw 'No restore points found to restore.' }
    $seq = [int]$latest[0].SequenceNumber
    Write-Host ("Starting System Restore immediately from latest restore point #{0}: {1}" -f $seq, $latest[0].Description)
    $result = Invoke-CimMethod -Namespace root/default -ClassName SystemRestore -MethodName Restore -Arguments @{ SequenceNumber = $seq }
    Write-Host ("SystemRestore.Restore returned: {0}" -f ($result | Out-String).Trim())
    Write-Host 'If Windows accepts the restore request, it may continue through the built-in System Restore workflow and may require/restart Windows.'
}

