function Resolve-CleancRootPathLocal {
        param([Parameter(Mandatory=$true)][string]$Path)
        $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        if (-not $item.PSIsContainer) { throw "cleanc root path must be a directory: $Path" }
        $resolved = [System.IO.Path]::GetFullPath($item.FullName).TrimEnd('\')
        if ($resolved.Length -eq 2 -and $resolved[1] -eq ':') { return ($resolved + '\') }
        return $resolved
    }

function Resolve-CodexExecutableCandidate([string]$Path) {
        if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
        if (-not (Test-Path -LiteralPath $Path)) { return $null }

        try {
            $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
        } catch {
            return $null
        }

        if ($item.PSIsContainer) { return $null }

        $targets = @()
        if ($item.LinkType -and $item.Target) {
            $targets = @($item.Target)
        }

        foreach ($target in $targets) {
            $resolvedTarget = $target
            if (-not [System.IO.Path]::IsPathRooted($resolvedTarget)) {
                $resolvedTarget = Join-Path $item.DirectoryName $resolvedTarget
            }

            if (-not (Test-Path -LiteralPath $resolvedTarget)) { continue }

            try {
                $targetItem = Get-Item -LiteralPath $resolvedTarget -Force -ErrorAction Stop
            } catch {
                continue
            }

            if ($targetItem.PSIsContainer) { continue }
            if ([System.IO.Path]::GetExtension($targetItem.Name) -ne '.exe') { continue }
            if ($targetItem.Length -le 0) { continue }

            return $targetItem.FullName
        }

        if ([System.IO.Path]::GetExtension($item.Name) -ne '.exe') { return $null }
        if ($item.Length -le 0) { return $null }

        return $item.FullName
    }

function global:Resolve-HermesDockerAllFastBuildArgs {
    param([string[]]$DockerArgs)
    $result = [ordered]@{ Args = @($DockerArgs); TempRoot = $null; FullContext = $false; ContextPath = $null; Dockerfile = $null }
    $kind = Get-HermesDockerAllFastCommandKind -DockerArgs $DockerArgs
    if ($kind -ne 'build') { return [pscustomobject]$result }

    $contextIndex = Get-HermesDockerAllFastContextIndex -DockerArgs $DockerArgs
    if ($contextIndex -lt 0) { return [pscustomobject]$result }
    $contextPath = $DockerArgs[$contextIndex]
    if ($contextPath -eq '-' -or $contextPath -match '^[a-z]+://') { return [pscustomobject]$result }
    $contextFull = (Resolve-Path -LiteralPath $contextPath -ErrorAction Stop).ProviderPath

    $dockerfileIndex = Get-HermesDockerAllFastDockerfileIndex -DockerArgs $DockerArgs
    $dockerfilePath = $null
    if ($dockerfileIndex -ge 0) {
        $fileArg = $DockerArgs[$dockerfileIndex]
        if ($fileArg -like '--file=*') { $fileArg = $fileArg.Substring(7) }
        if ($fileArg -eq '-') { return [pscustomobject]$result }
        if ([IO.Path]::IsPathRooted($fileArg)) { $dockerfilePath = $fileArg } else { $dockerfilePath = Join-Path $contextFull $fileArg }
    } else {
        $dockerfilePath = Join-Path $contextFull 'Dockerfile'
    }
    if (-not (Test-Path -LiteralPath $dockerfilePath -PathType Leaf)) { return [pscustomobject]$result }

    $tempRoot = Join-Path 'C:\Temp' ('hermes-docker-full-context-' + [Guid]::NewGuid().ToString('N'))
    $null = New-Item -ItemType Directory -Path $tempRoot -Force
    $tempDockerfile = Join-Path $tempRoot 'Dockerfile'
    Copy-Item -LiteralPath $dockerfilePath -Destination $tempDockerfile -Force
    [IO.File]::WriteAllText(($tempDockerfile + '.dockerignore'), '', [Text.Encoding]::ASCII)

    $newArgs = @($DockerArgs)
    if ($dockerfileIndex -ge 0) {
        if ($newArgs[$dockerfileIndex] -like '--file=*') { $newArgs[$dockerfileIndex] = '--file=' + $tempDockerfile } else { $newArgs[$dockerfileIndex] = $tempDockerfile }
    } else {
        $insertAt = $contextIndex
        $before = @()
        if ($insertAt -gt 0) { $before = $newArgs[0..($insertAt - 1)] }
        $after = $newArgs[$insertAt..($newArgs.Count - 1)]
        $newArgs = @($before + @('-f', $tempDockerfile) + $after)
    }

    $result.Args = $newArgs
    $result.TempRoot = $tempRoot
    $result.FullContext = $true
    $result.ContextPath = $contextFull
    $result.Dockerfile = $dockerfilePath
    return [pscustomobject]$result
}

function Resolve-NvidLatestDriverDownload {
        param([Parameter(Mandatory=$true)]$Target)
        $osId = 135
        $uri = ('https://www.nvidia.com/Download/processFind.aspx?psid={0}&pfid={1}&osID={2}&languageCode=1033&beta=0&isWHQL=1&dltype=-1&sort1=0&numberOfResults=10&dtcid=1' -f $Target.SeriesId,$Target.ProductId,$osId)
        Write-NvidStep ("querying latest NVIDIA display driver for {0} via NVIDIA processFind" -f $Target.ProductName)
        $page = Invoke-WebRequest -Uri $uri -UseBasicParsing -TimeoutSec 60
        $html = [string]$page.Content
        $rows = [regex]::Matches($html, '<tr id="driverList">(?<row>[\s\S]*?)</tr>')
        foreach($m in $rows) {
            $row = $m.Groups['row'].Value
            $idMatch = [regex]::Match($row, 'driverResults\.aspx/(?<id>\d+)/en-us')
            $verMatch = [regex]::Match($row, '<td class="gridItem">(?<ver>\d+\.\d+)</td>')
            if ($idMatch.Success -and $verMatch.Success -and $row -match 'GeForce Game Ready Driver') {
                $ver = $verMatch.Groups['ver'].Value
                $driverId = $idMatch.Groups['id'].Value
                $candidates = @(
                    ('https://us.download.nvidia.com/Windows/{0}/{0}-desktop-win10-win11-64bit-international-dch-whql.exe' -f $ver),
                    ('https://international.download.nvidia.com/Windows/{0}/{0}-desktop-win10-win11-64bit-international-dch-whql.exe' -f $ver)
                )
                foreach($candidate in $candidates) {
                    try {
                        $req = [System.Net.HttpWebRequest]::Create($candidate)
                        $req.Method = 'HEAD'
                        $req.Timeout = 30000
                        $resp = $req.GetResponse()
                        try { if ([int]$resp.StatusCode -eq 200) { return [pscustomobject]@{ Version = $ver; DriverId = $driverId; Url = $candidate } } } finally { $resp.Close() }
                    } catch {}
                }
                throw ("Latest NVIDIA driver {0} was found but download URL pattern did not resolve." -f $ver)
            }
        }
        throw 'NVIDIA processFind returned no English GeForce Game Ready Driver rows.'
    }

function Resolve-PostAction($package, $state, $result, $afterPackage) {
        if (-not $afterPackage) {
            [void](Remove-WingupStateEntry $state $package.Id)
            return [pscustomobject]@{
                Status = 'success'
                Message = "$($package.Name) is no longer listed by winget."
            }
        }

        if ($result.RestartRequired) {
            $note = 'Upgrade succeeded, but winget still lists the old version until the app is restarted.'
            Set-WingupStateEntry $state $package 'restart-required' $note
            return [pscustomobject]@{
                Status = 'suppressed'
                Message = "$($package.Name) was updated and is now suppressed until restart state clears."
            }
        }

        if ($result.Succeeded -and $afterPackage.Current -eq 'Unknown' -and $afterPackage.Available -eq $package.Available) {
            $note = 'Upgrade succeeded, but winget still reports the package because the installed version stays Unknown.'
            Set-WingupStateEntry $state $package 'metadata-stuck' $note
            return [pscustomobject]@{
                Status = 'suppressed'
                Message = "$($package.Name) was upgraded; winget metadata is stuck, so it is suppressed until the available version changes."
            }
        }

        if ($package.Id -eq 'OpenAI.Codex' -and $result.AccessDenied -and (Test-CodexCliRunning)) {
            return [pscustomobject]@{
                Status = 'deferred'
                Message = 'Codex CLI is running from the winget-managed path. Close Codex CLI sessions and rerun wingup to finish that upgrade.'
            }
        }

        return [pscustomobject]@{
            Status = 'pending'
            Message = "$($package.Name) is still listed after the attempt."
        }
    }

function global:Resolve-ProfilePythonExecutable {
    if ($script:CachedProfilePythonExecutable -and (Test-Path -LiteralPath $script:CachedProfilePythonExecutable -PathType Leaf)) {
        return $script:CachedProfilePythonExecutable
    }

    $candidatePaths = @(
        $env:CODEX_PROFILE_PYTHON,
        (Join-Path $env:LOCALAPPDATA 'Programs\Python\Python312\python.exe'),
        (Join-Path $env:LOCALAPPDATA 'Programs\Python\Python311\python.exe'),
        'C:\Python312\python.exe',
        'C:\Python311\python.exe'
    )

    foreach ($candidate in $candidatePaths) {
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        if (Test-Path -LiteralPath $candidate -PathType Leaf) {
            $script:CachedProfilePythonExecutable = (Resolve-Path -LiteralPath $candidate).ProviderPath
            return $script:CachedProfilePythonExecutable
        }
    }

    $command = Get-Command python -All -CommandType Application -ErrorAction SilentlyContinue |
        Where-Object { $_.Path -and $_.Path -notlike '*\Microsoft\WindowsApps\python*.exe' } |
        Select-Object -First 1
    if ($command) {
        $script:CachedProfilePythonExecutable = $command.Path
        return $script:CachedProfilePythonExecutable
    }

    $launcher = Get-Command py.exe -CommandType Application -ErrorAction SilentlyContinue
    if ($launcher) { return $launcher.Path }

    throw 'No usable Python interpreter found. Install Python or set CODEX_PROFILE_PYTHON to a real python.exe path.'
}

function Resolve-RedockerDockerCli {
        $candidates=@('C:\Program Files\Docker\Docker\resources\bin\docker.exe','C:\Program Files\Docker\Docker\docker.exe')
        $cmd=Get-Command docker.exe -ErrorAction SilentlyContinue
        if($cmd){ $candidates=@($cmd.Source)+$candidates }
        foreach($candidate in ($candidates | Where-Object { $_ } | Select-Object -Unique)){
            if(Test-Path -LiteralPath $candidate -PathType Leaf){ return $candidate }
        }
        return $null
    }

