function Restore-DKillFastSettingsSnapshot {
        param([string]$SnapshotRoot)
        if(-not (Test-Path -LiteralPath $SnapshotRoot)){ return }
        try {
            Get-ChildItem -LiteralPath $SnapshotRoot -File -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object {
                try {
                    $relative = $_.FullName.Substring($SnapshotRoot.TrimEnd('\').Length).TrimStart('\')
                    if([string]::IsNullOrWhiteSpace($relative)){ return }
                    $dest = Join-Path 'C:\' $relative
                    $parent = Split-Path -Parent $dest
                    New-Item -ItemType Directory -Force -Path $parent | Out-Null
                    Copy-Item -LiteralPath $_.FullName -Destination $dest -Force -ErrorAction SilentlyContinue
                } catch { }
            }
        } catch { }
    }

function Restore-DKillFastSnapshot {
        param([string]$SnapshotRoot)
        if(-not (Test-Path -LiteralPath $SnapshotRoot)){ return }
        Get-ChildItem -LiteralPath $SnapshotRoot -Force -ErrorAction SilentlyContinue | ForEach-Object {
            $rel = $_.Name -replace '_','\'
            if($rel -match '^(Users\\[^\\]+\\\.docker)$'){ $dest = 'C:\' + $rel }
            elseif($rel -match '^(Users\\[^\\]+\\AppData\\Roaming\\Docker)$'){ $dest = 'C:\' + $rel }
            elseif($rel -match '^(Users\\[^\\]+\\AppData\\Roaming\\Docker Desktop)$'){ $dest = 'C:\' + $rel }
            else { return }
            try {
                $parent = Split-Path -Parent $dest
                New-Item -ItemType Directory -Force -Path $parent | Out-Null
                Copy-Item -LiteralPath $_.FullName -Destination $dest -Recurse -Force -ErrorAction SilentlyContinue
            } catch { }
        }
    }

