        Write-NvidStep ("restoring captured NVIDIA Control Panel/NVIDIA App settings baseline from {0}" -f $baseline)
        if (-not $NoProcessStop) { Stop-NvidAppProcesses }
        foreach($svcName in @('NVDisplay.ContainerLocalSystem','NvContainerLocalSystem')) {
