        }
        $map = @{
            'ProgramData_NVIDIA Corporation_Drs' = 'C:\ProgramData\NVIDIA Corporation\Drs'
            'ProgramData_NVIDIA Corporation_NVIDIA App_NvConfig' = 'C:\ProgramData\NVIDIA Corporation\NVIDIA App\NvConfig'
