function global:rmrmcc {
    [CmdletBinding()]
    param()
    global:Invoke-CcRequireAdmin
    if (-not ('Hermes.CcSrClient' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
namespace Hermes {
  public static class CcSrClient {
    [DllImport("SrClient.dll", SetLastError=true)]
    public static extern int SRRemoveRestorePoint(int dwRPNum);
  }
}
'@
    }
    $points = @(Get-ComputerRestorePoint | Sort-Object SequenceNumber -Descending)
    if ($points.Count -eq 0) {
        Write-Host 'No restore points to delete.'
        return
    }
    foreach ($point in $points) {
        $seq = [int]$point.SequenceNumber
        $rc = [Hermes.CcSrClient]::SRRemoveRestorePoint($seq)
        if ($rc -eq 0) {
            Write-Host ("Deleted restore point #{0}: {1}" -f $seq, $point.Description)
        } else {
            Write-Warning ("Failed to delete restore point #{0}; SRRemoveRestorePoint returned {1}" -f $seq, $rc)
        }
    }
    Write-Host 'rmrmcc finished deleting available restore points.'
}

