function Set-FixDocker2DockerWrapper {
        Set-Item -Path 'Function:\global:docker' -Value {
            [CmdletBinding()]
            param([Parameter(ValueFromRemainingArguments = $true)][string[]]$Arguments)

            $dockerExe = 'C:\Program Files\Docker\Docker\resources\bin\docker.exe'
            if (-not (Test-Path -LiteralPath $dockerExe -PathType Leaf)) { throw "docker.exe not found: $dockerExe" }

            $oldCliHints = $env:DOCKER_CLI_HINTS
            $oldBuildKit = $env:DOCKER_BUILDKIT
            $oldBuildKitProgress = $env:BUILDKIT_PROGRESS
            $env:DOCKER_CLI_HINTS = 'false'
            $env:DOCKER_BUILDKIT = '1'
            if ($Arguments -and $Arguments.Count -gt 0 -and $Arguments[0] -in @('build','builder','buildx','compose')) { $env:BUILDKIT_PROGRESS = 'plain' }

            $verb = if ($Arguments -and $Arguments.Count -gt 0) { $Arguments[0] } else { 'help' }
            $commandText = ('docker {0}' -f ($Arguments -join ' ')).TrimEnd()
            $sw = [System.Diagnostics.Stopwatch]::StartNew()
            Write-Host ('[docker-progress] 0.000s START {0}' -f $commandText) -ForegroundColor Cyan

            function Quote-FixDocker2DockerArgument {
                param([string]$Value)
                if ($null -eq $Value) { return '""' }
                if ($Value.Length -eq 0) { return '""' }
                if ($Value -notmatch '[\s"`]') { return $Value }
                return '"' + ($Value -replace '([\\"])', '\$1') + '"'
            }

            function Read-FixDocker2NewText {
                param([string]$Path, [ref]$Position)
                if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return '' }
                $stream = $null
                $reader = $null
                try {
                    $stream = [System.IO.File]::Open($Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
                    if ($Position.Value -gt $stream.Length) { $Position.Value = 0 }
                    [void]$stream.Seek([int64]$Position.Value, [System.IO.SeekOrigin]::Begin)
                    $reader = New-Object System.IO.StreamReader($stream)
                    $text = $reader.ReadToEnd()
                    $Position.Value = $stream.Position
                    return $text
                } catch {
                    return ''
                } finally {
                    if ($reader) { $reader.Dispose() } elseif ($stream) { $stream.Dispose() }
                }
            }

            $longLiveVerbs = @('build','push','pull','run','compose','buildx','builder','logs','attach','exec','rm','rmi','stop','start','restart','kill','prune','load','save','import','export','cp')
            $longLiveSecondVerbs = @('build','push','pull','run','rm','rmi','remove','prune','load','save','import','export','cp','stop','start','restart','kill')
            $interactiveArgs = @($Arguments | Where-Object { $_ -in @('-i','--interactive','-t','--tty','-it','-ti') })
            $helpArgs = @($Arguments | Where-Object { $_ -in @('--help','-h','help') })
            $formatArgs = @($Arguments | Where-Object { $_ -eq '--format' -or $_ -like '--format=*' })
            $secondVerb = if ($Arguments -and $Arguments.Count -gt 1) { $Arguments[1] } else { '' }
            # Default to live monitoring for every Docker command so nothing can look frozen.
            # Preserve direct/capturable behavior only for help, --format queries, and interactive TTY commands.
            $useLiveMonitor = ($interactiveArgs.Count -eq 0) -and ($helpArgs.Count -eq 0) -and ($formatArgs.Count -eq 0)

            try {
                if (-not $useLiveMonitor) {
                    & $dockerExe @Arguments
                    $global:LASTEXITCODE = [int]$LASTEXITCODE
                    $duration = if ($sw.Elapsed.TotalHours -ge 1) { '{0:hh\:mm\:ss\.fff}' -f $sw.Elapsed } else { '{0:mm\:ss\.fff}' -f $sw.Elapsed }
                    if ($global:LASTEXITCODE -eq 0) { Write-Host ('[docker-progress] DONE exit=0 duration={0}' -f $duration) -ForegroundColor Green }
                    else { Write-Host ('[docker-progress] FAILED exit={0} duration={1}' -f $global:LASTEXITCODE,$duration) -ForegroundColor Red }
                    return
                }

                Write-Host ('[docker-progress] {0}: live Docker output is mirrored below; heartbeat continues until exit.' -f $verb) -ForegroundColor Cyan
                $tempRoot = Join-Path $env:TEMP 'hermes_docker_progress'
                New-Item -ItemType Directory -Path $tempRoot -Force | Out-Null
                $stamp = '{0}_{1}' -f (Get-Date -Format 'yyyyMMdd_HHmmss'),([guid]::NewGuid().ToString('N'))
                $stdoutPath = Join-Path $tempRoot ("docker_$stamp.out.log")
                $stderrPath = Join-Path $tempRoot ("docker_$stamp.err.log")
                New-Item -ItemType File -Path $stdoutPath -Force | Out-Null
                New-Item -ItemType File -Path $stderrPath -Force | Out-Null

                $isPush = $verb -eq 'push'
                $pushLayerStatus = @{}
                $pushLayerFirstSeen = @{}
                $pushLayerLastChanged = @{}
                $pushLastPrinted = @{}
                $pushLastSummary = ''
                $pushRawWaitingSuppressed = 0
                $pushStartedAt = Get-Date
                $pushLastAnyChangeAt = Get-Date
                $dockerLiveState = @{ ErrorDetected = $false }
                function Write-FixDocker2LiveText {
                    param([string]$Text)
                    if ([string]::IsNullOrEmpty($Text)) { return }
                    if (-not $isPush) { Write-Host -NoNewline $Text; return }
                    $normalized = $Text -replace "`r", "`n"
                    foreach ($line in @($normalized -split "`n")) {
                        if ([string]::IsNullOrWhiteSpace($line)) { continue }
                        $trimmed = $line.Trim()
                        if ($trimmed -match '^([a-f0-9]{12,}):\s+(.+)$') {
                            $layer = $Matches[1]
                            $status = $Matches[2].Trim()
                            $previous = if ($pushLayerStatus.ContainsKey($layer)) { [string]$pushLayerStatus[$layer] } else { '' }
                            $nowSeen = Get-Date
                            if (-not $pushLayerFirstSeen.ContainsKey($layer)) { $pushLayerFirstSeen[$layer] = $nowSeen }
                            if ($previous -ne $status) {
                                $pushLayerLastChanged[$layer] = $nowSeen
                                $pushLastAnyChangeAt = $nowSeen
                            } elseif (-not $pushLayerLastChanged.ContainsKey($layer)) {
                                $pushLayerLastChanged[$layer] = $nowSeen
                            }
                            $pushLayerStatus[$layer] = $status
                            $printKey = "$layer|$status"
                            if ($status -eq 'Waiting' -and $previous -eq 'Waiting') {
                                $script:__fixdocker2_unused = $null
                                $pushRawWaitingSuppressed++
                                continue
                            }
                            if (-not $pushLastPrinted.ContainsKey($printKey)) {
                                Write-Host ('[push-layer] {0}: {1}' -f $layer,$status)
                                $pushLastPrinted[$printKey] = $true
                            }
                        } else {
                            if ($trimmed -match '(?i)\b(failed|error|denied|unauthorized|timeout|refused)\b') { $dockerLiveState.ErrorDetected = $true }
                            Write-Host $trimmed
                        }
                    }
                }
                function Write-FixDocker2PushSummary {
                    if (-not $isPush) { return }
                    $nowSummary = Get-Date
                    $sinceAnyChange = [int](($nowSummary - $pushLastAnyChangeAt).TotalSeconds)
                    if ($pushLayerStatus.Count -eq 0) {
                        $elapsedForSummary = if ($sw.Elapsed.TotalHours -ge 1) { '{0:hh\:mm\:ss}' -f $sw.Elapsed } else { '{0:mm\:ss}' -f $sw.Elapsed }
                        Write-Host ('[push-progress] elapsed={0}; waiting for Docker registry/layer status lines; no layer data yet; process alive.' -f $elapsedForSummary) -ForegroundColor DarkCyan
                        return
                    }
                    $doneCount = 0
                    $activeCount = 0
                    $waitingCount = 0
                    foreach ($value in $pushLayerStatus.Values) {
                        if ($value -match 'Pushed|Mounted from|Layer already exists') { $doneCount++ }
                        elseif ($value -match 'Pushing|Preparing') { $activeCount++ }
                        elseif ($value -match 'Waiting') { $waitingCount++ }
                    }
                    $parts = @($pushLayerStatus.GetEnumerator() | Sort-Object Name | ForEach-Object {
                        $layerName = $_.Name
                        $statusValue = [string]$_.Value
                        $age = if ($pushLayerLastChanged.ContainsKey($layerName)) { [int](($nowSummary - ([datetime]$pushLayerLastChanged[$layerName])).TotalSeconds) } else { 0 }
                        ('{0}={1}({2}s)' -f $layerName,$statusValue,$age)
                    })
                    $etaText = if ($waitingCount -gt 0 -and $activeCount -eq 0) { 'ETA unknown: Docker registry has not reported byte progress for waiting layer(s)' } elseif ($activeCount -gt 0) { 'ETA depends on current upload speed; Docker will print bytes when registry reports them' } else { 'finishing registry commit/manifest update' }
                    $summary = 'layers done={0}/{1} active={2} waiting={3}; no-status-change={4}s; {5}; {6}; repeated Waiting lines suppressed={7}' -f $doneCount,$pushLayerStatus.Count,$activeCount,$waitingCount,$sinceAnyChange,$etaText,($parts -join '; '),$pushRawWaitingSuppressed
                    Write-Host ('[push-progress] {0}' -f $summary) -ForegroundColor DarkCyan
                    $pushLastSummary = $summary
                }

                $argLine = (@($Arguments) | ForEach-Object { Quote-FixDocker2DockerArgument $_ }) -join ' '
                $process = Start-Process -FilePath $dockerExe -ArgumentList $argLine -WorkingDirectory (Get-Location).ProviderPath -NoNewWindow -RedirectStandardOutput $stdoutPath -RedirectStandardError $stderrPath -PassThru
                $stdoutPos = [int64]0
                $stderrPos = [int64]0
                $nextHeartbeat = [DateTime]::UtcNow.AddMilliseconds(1)
                while (-not $process.HasExited) {
                    $outText = Read-FixDocker2NewText -Path $stdoutPath -Position ([ref]$stdoutPos)
                    Write-FixDocker2LiveText -Text $outText
                    $errText = Read-FixDocker2NewText -Path $stderrPath -Position ([ref]$stderrPos)
                    Write-FixDocker2LiveText -Text $errText
                    $now = [DateTime]::UtcNow
                    if ($now -ge $nextHeartbeat) {
                        $elapsed = if ($sw.Elapsed.TotalHours -ge 1) { '{0:hh\:mm\:ss}' -f $sw.Elapsed } else { '{0:mm\:ss}' -f $sw.Elapsed }
                        Write-Host ('[docker-progress] elapsed {0}; docker {1} still running.' -f $elapsed,$verb) -ForegroundColor DarkCyan
                        Write-FixDocker2PushSummary
                        $nextHeartbeat = $now.AddSeconds(2)
                    }
                    Start-Sleep -Milliseconds 200
                }
                $process.WaitForExit()
                $outText = Read-FixDocker2NewText -Path $stdoutPath -Position ([ref]$stdoutPos)
                Write-FixDocker2LiveText -Text $outText
                $errText = Read-FixDocker2NewText -Path $stderrPath -Position ([ref]$stderrPos)
                Write-FixDocker2LiveText -Text $errText
                Write-FixDocker2PushSummary
                $exitCode = [int]$process.ExitCode
                if ($exitCode -eq 0 -and $dockerLiveState.ErrorDetected) { $exitCode = 1 }
                $global:LASTEXITCODE = $exitCode
                $duration = if ($sw.Elapsed.TotalHours -ge 1) { '{0:hh\:mm\:ss\.fff}' -f $sw.Elapsed } else { '{0:mm\:ss\.fff}' -f $sw.Elapsed }
                if ($global:LASTEXITCODE -eq 0) { Write-Host ('[docker-progress] DONE exit=0 duration={0}' -f $duration) -ForegroundColor Green }
                else { Write-Host ('[docker-progress] FAILED exit={0} duration={1}' -f $global:LASTEXITCODE,$duration) -ForegroundColor Red }
                return
            } finally {
                if ($null -eq $oldCliHints) { Remove-Item Env:DOCKER_CLI_HINTS -ErrorAction SilentlyContinue } else { $env:DOCKER_CLI_HINTS = $oldCliHints }
                if ($null -eq $oldBuildKit) { Remove-Item Env:DOCKER_BUILDKIT -ErrorAction SilentlyContinue } else { $env:DOCKER_BUILDKIT = $oldBuildKit }
                if ($null -eq $oldBuildKitProgress) { Remove-Item Env:BUILDKIT_PROGRESS -ErrorAction SilentlyContinue } else { $env:BUILDKIT_PROGRESS = $oldBuildKitProgress }
            }
        } -Force
    }

function Set-WingupStateEntry($state, $package, [string]$reason, [string]$note) {
        [void](Remove-WingupStateEntry $state $package.Id)
        [void]$state.Entries.Add([pscustomobject]@{
            Id = $package.Id
            Name = $package.Name
            Available = $package.Available
            Reason = $reason
            Note = $note
            UpdatedAt = (Get-Date).ToString('s')
        })
    }

function ShouldSuppressPackage($package, $entry) {
        if (-not $entry) { return $false }
        if ($entry.Available -ne $package.Available) { return $false }

        switch ($entry.Reason) {
            'metadata-stuck' { return $package.Current -eq 'Unknown' }
            'restart-required' { return $true }
            default { return $false }
        }
    }

function Show-WingetSummary([string]$text) {
        foreach ($line in @(Get-WingetSummary $text)) {
            Write-Host "    $line" -ForegroundColor DarkGray
        }
    }

