    if (-not (Test-Path -LiteralPath $ps5 -PathType Leaf)) { throw "Windows PowerShell 5 missing: $ps5" }
    $root = Join-Path $env:APPDATA 'com.fitlauncher.carrotrub'
    $scriptDir = Join-Path $root 'scripts'
    $logDir = Join-Path $root 'logs'
