function Stop-RedockerLingeringStartupProcesses {
        param([switch]$OnlyIfErrorDialog)
        $procs=@(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object { $_.Name -ieq 'docker-agent.exe' -or ($_.Name -ieq 'Docker Desktop.exe' -and $_.CommandLine -match 'error-dialog') })
        if($OnlyIfErrorDialog -and -not @($procs | Where-Object { $_.Name -ieq 'Docker Desktop.exe' -and $_.CommandLine -match 'error-dialog' }).Count){ return }
        foreach($proc in $procs){
            try { Write-RedockerStep ("stopping lingering startup blocker pid={0} name={1}" -f $proc.ProcessId,$proc.Name); Stop-Process -Id $proc.ProcessId -Force -ErrorAction SilentlyContinue } catch {}
        }
    }

function Stop-RedockerSafeDocker {
        foreach($name in @('Docker Desktop','Docker Desktop Installer','com.docker.backend','com.docker.proxy','docker-agent','docker-sandbox','dockerd','docker','vpnkit','com.docker.service')){
            try { Get-Process -Name $name -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue } catch { }
        }
        try { Stop-Service -Name 'com.docker.service' -Force -ErrorAction SilentlyContinue } catch { }
        try {
            if(Get-Command Get-VM -ErrorAction SilentlyContinue){
                $vm = Get-VM -Name 'DockerDesktopVM' -ErrorAction SilentlyContinue
                if($vm -and $vm.State -ne 'Off'){ Stop-VM -Name 'DockerDesktopVM' -TurnOff -Force -ErrorAction SilentlyContinue }
            }
        } catch { }
    }

function Stop-UnfreezePid([int]$TargetPid,[string]$Reason) {
        if ($TargetPid -le 0 -or $TargetPid -eq $PID) { return }
        try {
            $p = Get-Process -Id $TargetPid -ErrorAction Stop
            $label = ("{0}[{1}] {2}" -f $p.Name,$TargetPid,$Reason)
            if ($DryRun -or -not $PSCmdlet.ShouldProcess($label,'Stop-Process -Force')) { Add-UnfreezeReport 'would-kill' $label 'dry-run'; return }
            Stop-Process -Id $TargetPid -Force -ErrorAction Stop
            Add-UnfreezeReport 'killed' $label 'ok'
        } catch { Add-UnfreezeReport 'kill-failed' ("pid={0} {1}" -f $TargetPid,$Reason) $_.Exception.Message }
    }

