function Test-DKillFastDockerReady {
        param([string]$DockerExe,[switch]$FinalProbe)
        if([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe)){ return $false }
        $proc = $null
        try {
            $remaining = Get-DKillFastRemainingMilliseconds
            if(-not $FinalProbe -and $remaining -lt 300){ return $false }
            $waitMs = if($FinalProbe){ 2500 } else { [Math]::Max(350,[Math]::Min(1400,$remaining - 150)) }
            $psi = New-Object Diagnostics.ProcessStartInfo
            $psi.FileName = $DockerExe
            $psi.Arguments = 'version --format "{{.Server.Version}}"'
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $psi.RedirectStandardOutput = $true
            $psi.RedirectStandardError = $true
            $proc = New-Object Diagnostics.Process
            $proc.StartInfo = $psi
            [void]$proc.Start()
            if(-not $proc.WaitForExit($waitMs)){ try { $proc.Kill() } catch { }; return $false }
            $stdout = ''
            $stderr = ''
            try { $stdout = $proc.StandardOutput.ReadToEnd().Trim() } catch { $stdout = '' }
            try { $stderr = $proc.StandardError.ReadToEnd().Trim() } catch { $stderr = '' }
            if($proc.ExitCode -ne 0){ return $false }
            if([string]::IsNullOrWhiteSpace($stdout)){ return $false }
            if($stderr -match '(?i)failed to connect|daemon is not running|cannot find|error during connect'){ return $false }
            return $true
        } catch {
            return $false
        } finally {
            if($proc){ try { $proc.Dispose() } catch { } }
        }
    }

