    ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique
    foreach ($tempHelperRoot in $tempHelperRoots) {
        if (-not (Test-Path -LiteralPath $tempHelperRoot -PathType Container)) { continue }
            $commanderFilter = 'mmenu_chunked_push.' + 'commander_' + 'dashboard.*.ps1*'
            foreach ($existingHelper in @(Get-ChildItem -LiteralPath $tempHelperRoot -File -Filter $commanderFilter -ErrorAction SilentlyContinue)) {
            $generatedHelperCheckedCount++
            $badHelper = $false
            $reason = $null
            try {
                $existingRaw = Get-Content -LiteralPath $existingHelper.FullName -Raw -ErrorAction Stop
                if ($existingRaw -match 'Where-Object\s*\{\s*\[CmdletBinding\(\)\]') { $badHelper = $true; $reason = 'Where-Object/CmdletBinding corruption' }
                $__existingAliveTickPattern = 'alive ' + 'elapsed=.*' + 'tick'
                if (-not $badHelper -and $existingRaw -match $__existingAliveTickPattern) { $badHelper = $true; $reason = 'old alive tick spam' }
                if (-not $badHelper -and $existingRaw -notmatch 'Read-NewPretty') { $badHelper = $true; $reason = 'missing PS5 safe progress reader' }
                if (-not $badHelper -and $existingRaw -notmatch 'Invoke-HermesDockerCommanderProcess') { $badHelper = $true; $reason = 'missing Commander process route' }
                $legacyMmenuLayerPattern = '\.' + 'mmenu-layerctx'
                if (-not $badHelper -and $existingRaw -match $legacyMmenuLayerPattern) { $badHelper = $true; $reason = 'legacy mmenu layer-context artifact string' }
                if (-not $badHelper -and $existingRaw -match "buildx','build'.*'--push|--push.*buildx") { $badHelper = $true; $reason = 'opaque buildx --push path' }
                if (-not $badHelper -and $existingRaw -match '(?m)\[int\]\s*\$(?:ContextTotalBytes|[^=\r\n;]*Bytes)\b') { $badHelper = $true; $reason = 'Int32 byte counter risk' }
                if (-not $badHelper -and $existingRaw -match '(?m)\[Math\]::Max\(\s*(?:\d+|\[int\][^,\r\n\)]*)\s*,\s*\$[^,\r\n\)]*(?:Bytes|total|done)\b') { $badHelper = $true; $reason = 'Int32 Math.Max byte-total risk' }
                if (-not $badHelper -and $existingHelper.Extension -eq '.ps1') {
                    $existingTokens = $null
                    $existingErrors = $null
                    [void][System.Management.Automation.Language.Parser]::ParseFile($existingHelper.FullName, [ref]$existingTokens, [ref]$existingErrors)
                    if ($existingErrors.Count -gt 0) { $badHelper = $true; $reason = "parser error: $($existingErrors[0].Message)" }
                }
            } catch {
                $badHelper = $true
                $reason = "read failure: $($_.Exception.Message)"
            }
            if ($badHelper) {
                try { Remove-Item -LiteralPath $existingHelper.FullName -Force -ErrorAction SilentlyContinue } catch { }
                $generatedHelperQuarantinedCount++
                [void]$failures.Add("quarantined bad generated Docker helper $($existingHelper.FullName): $reason")
            }
        }
    }

    $externalDockerGuardScripts = @(
        'F:\study\Learning\01\01\Shells\powershell\profile-functions\devops\backup-docker\repository-tools\WaitBackupdockerdesktopready\Invoke-wait-backupdockerdesktopready.ps1',
        'F:\study\repos\shells\powershell\scripts\misc\windows\virtualization\docker\desktop\hyper-v\trust-provider\repair\ps5\launcher\Repair-DockerDesktopHyperVTrust.ps1'
    )
    foreach ($externalDockerGuardScript in $externalDockerGuardScripts) {
        if (-not (Test-Path -LiteralPath $externalDockerGuardScript -PathType Leaf)) {
            [void]$failures.Add("missing external Docker guard script: $externalDockerGuardScript")
            continue
        }
        try {
            $externalTokens = $null
            $externalErrors = $null
            [void][System.Management.Automation.Language.Parser]::ParseFile($externalDockerGuardScript, [ref]$externalTokens, [ref]$externalErrors)
            if ($externalErrors.Count -gt 0) { [void]$failures.Add("external Docker guard parser error in ${externalDockerGuardScript}: $($externalErrors[0].Message)") }
            $externalRaw = Get-Content -LiteralPath $externalDockerGuardScript -Raw
            if ($externalRaw -match 'F:\\Downloads\\.fitgirl_tmp|commander_dashboard|mmenu-progress|\.mmenu-layerctx') { [void]$failures.Add("external Docker guard contains stale helper/temp pattern: $externalDockerGuardScript") }
            if ($externalRaw -match '(?m)^\s*timeout\b|\btimeout\.exe\b') { [void]$failures.Add("external Docker guard contains timeout.exe usage: $externalDockerGuardScript") }
            if ($externalRaw -match 'Start-Process[^\r\n]+Docker Desktop\.exe(?![^\r\n]*WindowStyle Hidden)') { [void]$failures.Add("external Docker guard can launch Docker Desktop frontend: $externalDockerGuardScript") }
            if ($externalRaw -match '&\s*\$dockerCli\s+info') { [void]$failures.Add("external Docker guard still dumps direct docker info: $externalDockerGuardScript") }
        } catch {
            [void]$failures.Add("external Docker guard validation failed for ${externalDockerGuardScript}: $($_.Exception.Message)")
        }
    }

    if (-not $SkipDockerCliProbe) {
        try {
            docker --version | Out-Host
            if ($LASTEXITCODE -ne 0) { [void]$failures.Add("docker --version exited $LASTEXITCODE") }
            docker buildx version | Out-Host
            if ($LASTEXITCODE -ne 0) { [void]$failures.Add("docker buildx version exited $LASTEXITCODE") }
            Invoke-HermesDockerAllFastNative @('images','--help') | Out-Host
            if ($LASTEXITCODE -ne 0) { [void]$failures.Add("Invoke-HermesDockerAllFastNative images --help exited $LASTEXITCODE") }
            $nativeComposeHelpArgs = @('compose','up','--help')
            Invoke-HermesDockerAllFastNative @nativeComposeHelpArgs | Out-Host
            if ($LASTEXITCODE -ne 0) { [void]$failures.Add("Invoke-HermesDockerAllFastNative compose up --help exited $LASTEXITCODE") }
        } catch {
            [void]$failures.Add("docker --version probe failed: $($_.Exception.Message)")
        }
    }

    try {
        $cmdExe = Join-Path $env:WINDIR 'System32\cmd.exe'
        $progressLine = 'echo layer1: Pushing 1MB/4MB & echo layer1: Pushing 4MB/4MB & echo digest: sha256:selftest'
        $progressCode = Invoke-HermesDockerCommanderProcess -DockerExe $cmdExe -DockerArgs @('/d','/s','/c',$progressLine) -Name 'selftest' -RetryUntilSuccess
        if ($progressCode -ne 0) { [void]$failures.Add("fake progress command exited $progressCode") }
    } catch {
        [void]$failures.Add("fake progress command failed: $($_.Exception.Message)")
    }

    $buildKitContextProgressSelfTest = $false
    try {
        $cmdExe = Join-Path $env:WINDIR 'System32\cmd.exe'
        $contextLine = 'echo #6 transferring context: 128.00MB 5.0s & echo #6 transferring context: 1.00GB 10.0s & echo #8 exporting layers & echo #8 pushing layers & echo #8 DONE 12.3s'
        $contextCode = Invoke-HermesDockerCommanderProcess -DockerExe $cmdExe -DockerArgs @('/d','/s','/c',$contextLine) -Name 'context-selftest' -ContextTotalBytes ([int64](2GB))
        if ($contextCode -ne 0) {
            [void]$failures.Add("fake BuildKit context progress command exited $contextCode")
        } else {
            $buildKitContextProgressSelfTest = $true
        }
    } catch {
        [void]$failures.Add("fake BuildKit context progress command failed: $($_.Exception.Message)")
    }

    $publicMmenuPreflightSelfTest = $false
    $publicMmenuPreflightRoot = Join-Path 'C:\Temp' ('docker-public-mmenu-preflight-' + [Guid]::NewGuid().ToString('N'))
    try {
        New-Item -ItemType Directory -Force -Path $publicMmenuPreflightRoot | Out-Null
        [IO.File]::WriteAllText((Join-Path $publicMmenuPreflightRoot 'selftest.txt'), 'public mmenu preflight self-test', [Text.Encoding]::UTF8)
        $global:LASTEXITCODE = 0
        mmenu $publicMmenuPreflightRoot -PreflightOnly | Out-Host
        $mmenuPreflightCode = if ($null -eq $global:LASTEXITCODE) { 0 } else { [int]$global:LASTEXITCODE }
        $global:LASTEXITCODE = 0
        mmmenu $publicMmenuPreflightRoot -PreflightOnly | Out-Host
        $mmmenuPreflightCode = if ($null -eq $global:LASTEXITCODE) { 0 } else { [int]$global:LASTEXITCODE }
        if ($mmenuPreflightCode -ne 0 -or $mmmenuPreflightCode -ne 0) {
            [void]$failures.Add("public mmenu preflight failed: mmenu=$mmenuPreflightCode mmmenu=$mmmenuPreflightCode")
        } else {
            $publicMmenuPreflightSelfTest = $true
        }
    } catch {
        [void]$failures.Add("public mmenu preflight failed: $($_.Exception.Message)")
    } finally {
        if (Test-Path -LiteralPath $publicMmenuPreflightRoot -PathType Container) {
            Remove-Item -LiteralPath $publicMmenuPreflightRoot -Recurse -Force -ErrorAction SilentlyContinue
        }
    }

    try {
        $whoamiExe = Join-Path $env:WINDIR 'System32\whoami.exe'
        $noArgCode = Invoke-HermesDockerCommanderProcess -DockerExe $whoamiExe -DockerArgs @() -Name 'selftest-noargs'
        if ($noArgCode -ne 0) { [void]$failures.Add("no-argument command exited $noArgCode") }
    } catch {
        [void]$failures.Add("no-argument command failed: $($_.Exception.Message)")
    }

    $retryMarker = Join-Path 'C:\Temp' ('docker-commander-retry-' + [Guid]::NewGuid().ToString('N') + '.txt')
    $retryScriptPath = Join-Path 'C:\Temp' ('docker-commander-retry-' + [Guid]::NewGuid().ToString('N') + '.ps1')
    try {
        $retryMarkerLiteral = "'" + $retryMarker.Replace("'", "''") + "'"
        $retryScript = @(
            ('$marker = {0}' -f $retryMarkerLiteral),
            'if (Test-Path -LiteralPath $marker -PathType Leaf) {',
            '    Write-Output ''layer1: Pushing 4MB/4MB''',
            '    exit 0',
            '}',
            'Set-Content -LiteralPath $marker -Value ''first-failure'' -Encoding ASCII',
            'Write-Output ''layer1: Pushing 1MB/4MB''',
            'exit 7'
        ) -join "`r`n"
        [IO.File]::WriteAllText($retryScriptPath, $retryScript, [Text.Encoding]::ASCII)
        $ps5Exe = Join-Path $env:WINDIR 'System32\WindowsPowerShell\v1.0\powershell.exe'
        $retryCode = Invoke-HermesDockerCommanderProcess -DockerExe $ps5Exe -DockerArgs @('-NoProfile','-ExecutionPolicy','Bypass','-File',$retryScriptPath) -Name 'selftest-retry' -RetryUntilSuccess
        if ($retryCode -ne 0) { [void]$failures.Add("retry command exited $retryCode") }
        if (-not (Test-Path -LiteralPath $retryMarker -PathType Leaf)) { [void]$failures.Add('retry command did not create first-failure marker') }
    } catch {
        [void]$failures.Add("retry command failed: $($_.Exception.Message)")
    } finally {
        Remove-Item -LiteralPath $retryMarker -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath $retryScriptPath -Force -ErrorAction SilentlyContinue
    }

    foreach ($selfTestTempRoot in @(
            (Join-Path 'C:\Temp' 'hermes-docker-commander'),
            (Join-Path 'C:\Temp' 'hermes-docker-realtime-helper'),
            (Join-Path 'C:\Temp' 'hermes-docker-mmenu-contexts'),
            (Join-Path 'C:\Temp' 'mmenu-progress'),
        'C:\Temp\hermes-docker-commander',
        'C:\Temp\hermes-docker-realtime-helper',
        'C:\Temp\hermes-docker-mmenu-contexts',
        'C:\Temp\mmenu-progress'
    )) {
        if (Test-Path -LiteralPath $selfTestTempRoot) {
            try { Remove-Item -LiteralPath $selfTestTempRoot -Recurse -Force -ErrorAction SilentlyContinue } catch { }
        }
    }

    if ($failures.Count -gt 0) {
        $failures | ForEach-Object { Write-Host "[docker-commander-selftest][FAIL] $_" -ForegroundColor Red }
        throw "Docker Commander profile self-test failed with $($failures.Count) issue(s)."
    }
    Write-Host '[docker-commander-selftest] PASS' -ForegroundColor Green
    return [pscustomobject]@{
        Success = $true
        CheckedCommands = $requiredCommands.Count
        ActiveDockerFunctions = $activeDockerRelatedCount
        GeneratedHelpersChecked = $generatedHelperCheckedCount
        GeneratedHelpersQuarantined = $generatedHelperQuarantinedCount
        SeededBadHelperCleaned = $seededBadHelperCleaned
        BuildKitContextProgressSelfTest = $buildKitContextProgressSelfTest
        PublicMmenuPreflightSelfTest = $publicMmenuPreflightSelfTest
        DockerCliProbe = (-not $SkipDockerCliProbe)
    }
}

function Test-HermesDockerCommanderReadyNow([string]$Exe,[int]$Milliseconds) {
        $p = $null
        try {
            $psi = New-Object Diagnostics.ProcessStartInfo
            $psi.FileName = $Exe
            $psi.Arguments = 'version --format "{{.Server.Version}}"'
            $psi.UseShellExecute = $false
            $psi.CreateNoWindow = $true
            $psi.RedirectStandardOutput = $true
            $psi.RedirectStandardError = $true
            $p = New-Object Diagnostics.Process
            $p.StartInfo = $psi
            [void]$p.Start()
            if (-not $p.WaitForExit($Milliseconds)) { try { $p.Kill() } catch {}; return $false }
            $out = ''
            try { $out = $p.StandardOutput.ReadToEnd().Trim() } catch { $out = '' }
            return ($p.ExitCode -eq 0 -and -not [string]::IsNullOrWhiteSpace($out))
        } catch {
            return $false
        } finally {
            if ($p) { try { $p.Dispose() } catch {} }
        }
    }

function Test-HermesDockerGeneratedArtifactName {
        param([string]$Name)
        if ([string]::IsNullOrWhiteSpace($Name)) { return $false }
        if ($exactNames -contains $Name) { return $true }
        foreach ($prefix in $prefixes) {
            if ($Name.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase)) { return $true }
        }
        return $false
    }

function Test-MegaFixPendingReboot {
        $keys = @(
            'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending',
            'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired',
            'HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager'
        )
        foreach ($k in $keys) {
            try {
                if ($k -like '*Session Manager') {
                    $v = (Get-ItemProperty -LiteralPath $k -Name PendingFileRenameOperations -ErrorAction SilentlyContinue).PendingFileRenameOperations
                    if ($v) { return $true }
                } elseif (Test-Path -LiteralPath $k) { return $true }
            } catch { }
        }
        return $false
    }

