function Test-RedockerSafeDockerReady {
        param([string]$DockerExe,[int]$Milliseconds = 1200)
        if([string]::IsNullOrWhiteSpace($DockerExe) -or -not (Test-Path -LiteralPath $DockerExe)){ return $false }
        $outFile = Join-Path 'C:\Temp' ('redocker-ready-out-' + [guid]::NewGuid().ToString('N') + '.log')
        $errFile = Join-Path 'C:\Temp' ('redocker-ready-err-' + [guid]::NewGuid().ToString('N') + '.log')
        try {
            $p = Start-Process -FilePath $DockerExe -ArgumentList @('version','--format','{{.Server.Version}}') -RedirectStandardOutput $outFile -RedirectStandardError $errFile -WindowStyle Hidden -PassThru -ErrorAction Stop
            if(-not $p.WaitForExit([Math]::Max(250,$Milliseconds))){ try { $p.Kill() } catch { }; return $false }
            if([int]$p.ExitCode -ne 0){ return $false }
            $stdout = ''
            $stderr = ''
            try { $stdout = (Get-Content -LiteralPath $outFile -Raw -ErrorAction SilentlyContinue).Trim() } catch { $stdout = '' }
            try { $stderr = (Get-Content -LiteralPath $errFile -Raw -ErrorAction SilentlyContinue).Trim() } catch { $stderr = '' }
            if([string]::IsNullOrWhiteSpace($stdout)){ return $false }
            if($stderr -match '(?i)failed to connect|daemon is not running|error during connect|cannot find'){ return $false }
            return $true
        } catch {
            return $false
        } finally {
            foreach($f in @($outFile,$errFile)){ try { Remove-Item -LiteralPath $f -Force -ErrorAction SilentlyContinue } catch { } }
        }
    }

function Test-SpeedtestCliExecutable {
        param([Parameter(Mandatory = $true)][string] $Path)
        try {
            if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return $false }
            $item = Get-Item -LiteralPath $Path -Force -ErrorAction Stop
            if ($item.Length -lt 1024) { return $false }
            $fs = [System.IO.File]::Open($item.FullName, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            try {
                if ($fs.Length -lt 2) { return $false }
                $b1 = $fs.ReadByte(); $b2 = $fs.ReadByte()
                if ($b1 -ne 77 -or $b2 -ne 90) { return $false }
            } finally { $fs.Close() }
            $stdout = Join-Path $env:TEMP ('speedtest-probe-' + [Guid]::NewGuid().ToString('N') + '.out')
            $stderr = Join-Path $env:TEMP ('speedtest-probe-' + [Guid]::NewGuid().ToString('N') + '.err')
            try {
                $p = Start-Process -FilePath $item.FullName -ArgumentList '--version' -WorkingDirectory $env:TEMP -NoNewWindow -Wait -PassThru -RedirectStandardOutput $stdout -RedirectStandardError $stderr -ErrorAction Stop
                if ($p.ExitCode -ne 0) { return $false }
                return $true
            } finally {
                Remove-Item -LiteralPath $stdout,$stderr -Force -ErrorAction SilentlyContinue
            }
        } catch {
            return $false
        }
    }

