                    Where-Object { $_.Path -eq $Path }
            ).Count -gt 0
        } catch {
            return $false
        }
    }

function Test-WingiHasArg {
        param([string[]]$ArgsList, [string[]]$Names)
        foreach ($arg in $ArgsList) {
            foreach ($name in $Names) {
