                }
            }
        }
        return $false
    }

function ts { $e=[int]([datetime]::Now.Subtract($script:bleachStart).TotalSeconds); $mins=[int]($e/60); $secs=[int]($e%60); "[" + ("{0:D2}" -f $mins) + ":" + ("{0:D2}" -f $secs) + "]" }

function unfreeze {
    [CmdletBinding(SupportsShouldProcess=$true)]
    param(
        [switch] $DryRun,
        [switch] $SkipFitLauncher,
        [switch] $KillUnresponsiveGui,
        [switch] $RestartExplorer
    )

    $ErrorActionPreference = 'Continue'
    $started = Get-Date
    $report = New-Object System.Collections.Generic.List[object]
    function Add-UnfreezeReport([string]$Action,[string]$Target,[string]$Result) {
        [void]$report.Add([pscustomobject]@{ Time = (Get-Date).ToString('HH:mm:ss.fff'); Action = $Action; Target = $Target; Result = $Result })
    }
    function Stop-UnfreezePid([int]$TargetPid,[string]$Reason) {
        if ($TargetPid -le 0 -or $TargetPid -eq $PID) { return }
        try {
            $p = Get-Process -Id $TargetPid -ErrorAction Stop
            $label = ("{0}[{1}] {2}" -f $p.Name,$TargetPid,$Reason)
            if ($DryRun -or -not $PSCmdlet.ShouldProcess($label,'Stop-Process -Force')) { Add-UnfreezeReport 'would-kill' $label 'dry-run'; return }
            Stop-Process -Id $TargetPid -Force -ErrorAction Stop
            Add-UnfreezeReport 'killed' $label 'ok'
        } catch { Add-UnfreezeReport 'kill-failed' ("pid={0} {1}" -f $TargetPid,$Reason) $_.Exception.Message }
    }

    if (-not $PSBoundParameters.ContainsKey('KillUnresponsiveGui')) { $KillUnresponsiveGui = $true }
    Write-Host '[unfreeze] emergency freeze breaker starting now...' -ForegroundColor Cyan

    # 1) Kill the proven freeze storm: Fit Launcher/aria2 and stale afitgirl monitor/rescue processes.
    $all = @(Get-CimInstance Win32_Process -ErrorAction SilentlyContinue)
    if (-not $SkipFitLauncher) {
        $targets = New-Object System.Collections.Generic.HashSet[int]
        foreach ($p in $all) {
            $cmd = '' + $p.CommandLine
            $decoded = ''
            if ($cmd -match '-EncodedCommand\s+([^\s]+)') {
                try { $decoded = [Text.Encoding]::Unicode.GetString([Convert]::FromBase64String($Matches[1])) } catch {}
            }
            if ($p.Name -match '^(aria2c|aria2c\.real|Fit Launcher)\.exe$' -or
                $cmd -match 'apply_afit_speed_rescue|afitgirl|fitgirl|FitLauncherPathBridge|aria2\.session' -or
                $decoded -match 'afitgirl|Afitgirl|FitLauncher|aria2') {
                [void]$targets.Add([int]$p.ProcessId)
            }
        }
        # include child processes of matched processes, one pass loop for immediate but complete tree stop
        $changed = $true
        while ($changed) {
            $changed = $false
            foreach ($p in $all) {
                if ($targets.Contains([int]$p.ParentProcessId) -and -not $targets.Contains([int]$p.ProcessId)) { [void]$targets.Add([int]$p.ProcessId); $changed = $true }
            }
        }
        foreach ($id in @($targets)) { Stop-UnfreezePid $id 'Fit/aria2/afitgirl freeze-storm breaker' }
    }

    # 2) Kill visibly non-responding GUI apps on demand; keep current shell alive, restart Explorer instead of leaving desktop dead.
    if ($KillUnresponsiveGui) {
        foreach ($p in @(Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 -and $_.Id -ne $PID })) {
            $isResponding = $true
            try { $isResponding = [bool]$p.Responding } catch {}
            if (-not $isResponding) {
                if ($p.Name -ieq 'explorer') { $RestartExplorer = $true; Stop-UnfreezePid $p.Id 'non-responding Explorer restart' }
                else { Stop-UnfreezePid $p.Id 'non-responding GUI application' }
            }
        }
    }

    # 3) Optional Explorer shell reset when the desktop/taskbar is the frozen part.
    if ($RestartExplorer) {
        foreach ($p in @(Get-Process explorer -ErrorAction SilentlyContinue)) { Stop-UnfreezePid $p.Id 'Explorer shell restart' }
        if (-not $DryRun) {
            try { Start-Process explorer.exe; Add-UnfreezeReport 'started' 'explorer.exe' 'ok' } catch { Add-UnfreezeReport 'start-failed' 'explorer.exe' $_.Exception.Message }
        } else { Add-UnfreezeReport 'would-start' 'explorer.exe' 'dry-run' }
    }

    # 4) Immediate proof counters, bounded and no sleeps.
    try {
        $tcp = Get-NetTCPConnection -ErrorAction SilentlyContinue | Group-Object State | Sort-Object Count -Descending | Select-Object Count,Name
        foreach ($row in $tcp) { Add-UnfreezeReport 'tcp' $row.Name ('' + $row.Count) }
    } catch { Add-UnfreezeReport 'tcp-failed' 'Get-NetTCPConnection' $_.Exception.Message }
    try {
        $top = Get-Process -ErrorAction SilentlyContinue | Sort-Object CPU -Descending | Select-Object -First 8 Name,Id,CPU,@{n='MemMB';e={[math]::Round($_.WorkingSet64/1MB,1)}}
        foreach ($row in $top) { Add-UnfreezeReport 'top-cpu' ("{0}[{1}]" -f $row.Name,$row.Id) ("CPU={0};MemMB={1}" -f ([math]::Round($row.CPU,1)),$row.MemMB) }
    } catch {}

    $elapsed = [math]::Round(((Get-Date) - $started).TotalSeconds,2)
    Write-Host ("[unfreeze] done in {0}s" -f $elapsed) -ForegroundColor Green
    $report | Format-Table -AutoSize
    $global:LASTEXITCODE = 0
}

function unsnap {
    Write-Host "Force deleting ALL Rollback Rx snapshots..." -ForegroundColor Yellow
    
    # Check if Rollback Rx is installed
    $shieldPath = "C:\Program Files\Shield"
    if (-not (Test-Path $shieldPath)) {
        Write-Host "ERROR: Rollback Rx not found at $shieldPath" -ForegroundColor Red
        Write-Host "Please verify Rollback Rx installation" -ForegroundColor Yellow
        return
    }
    
    # Check if Rollback Rx service is running
    $shdService = Get-Service -Name "*Shield*" -ErrorAction SilentlyContinue
    if (-not $shdService -or $shdService.Status -ne "Running") {
        Write-Host "WARNING: Rollback Rx service may not be running" -ForegroundColor Yellow
    } else {
        Write-Host "Rollback Rx service is active" -ForegroundColor Green
    }
    
    try {
        # Method 1: Try command-line deletion
        Write-Host "Attempting to delete all Rollback Rx snapshots..." -ForegroundColor Cyan
        $shieldExe = Join-Path $shieldPath "Shield.exe"
        
        # Try various command line formats for deletion
        $commands = @(
            "/delete /all",
            "-delete -all",
            "/deleteall", 
            "-deleteall",
            "/clear",
            "-clear"
        )
        
        $success = $false
        foreach ($cmd in $commands) {
            try {
                Write-Host "Trying: $shieldExe $cmd" -ForegroundColor Gray
                $result = Start-Process -FilePath $shieldExe -ArgumentList $cmd -Wait -PassThru -WindowStyle Hidden -Timeout 30
                if ($result.ExitCode -eq 0) {
                    Write-Host "Rollback Rx snapshots deleted via command-line" -ForegroundColor Green
                    $success = $true
                    break
                }
            } catch {
                # Continue to next command
            }
        }
        
        if (-not $success) {
            Write-Host "Command-line deletion failed, trying GUI automation..." -ForegroundColor Yellow
            
            # Method 2: GUI automation approach (based on Rollback Rx Home interface)
            try {
                Write-Host "Launching Rollback Rx GUI for snapshot deletion..." -ForegroundColor Cyan
                $process = Start-Process -FilePath $shieldExe -PassThru -WindowStyle Normal
                Start-Sleep 3
                
                # Navigate to Snapshots section
                Add-Type -AssemblyName System.Windows.Forms
                
                # Click on Snapshots in the left menu
                [System.Windows.Forms.SendKeys]::SendWait("{TAB}{TAB}{DOWN}{DOWN}")  # Navigate to Snapshots
                Start-Sleep 1
                [System.Windows.Forms.SendKeys]::SendWait("{ENTER}")  # Enter Snapshots section
                Start-Sleep 2
                
                # Select all snapshots (Ctrl+A) then delete (Del key)
                [System.Windows.Forms.SendKeys]::SendWait("^a")  # Select All snapshots
                Start-Sleep 1
                [System.Windows.Forms.SendKeys]::SendWait("{DELETE}")  # Delete selected snapshots
                Start-Sleep 1
                [System.Windows.Forms.SendKeys]::SendWait("{ENTER}")  # Confirm deletion
                
                Write-Host "GUI automation attempted for snapshot deletion" -ForegroundColor Green
                Write-Host "All snapshots should be selected and deleted" -ForegroundColor Yellow
                Write-Host "Check Rollback Rx Snapshots section to confirm deletion" -ForegroundColor Cyan
                Write-Host "WARNING: This deletes ALL snapshots - cannot be undone!" -ForegroundColor Red
            } catch {
                Write-Host "GUI automation failed: $_" -ForegroundColor Red
            }
        }
        
        # Method 3: Direct file/registry cleanup
        Write-Host "Performing additional cleanup..." -ForegroundColor Cyan
        try {
            # Clear Rollback Rx temporary files
            $rollbackTempPaths = @(
                "$env:TEMP\*shield*",
                "$env:TEMP\*rollback*", 
                "$env:LOCALAPPDATA\Shield\*",
                "$env:PROGRAMDATA\Shield\*"
            )
            
            foreach ($path in $rollbackTempPaths) {
                Get-ChildItem $path -ErrorAction SilentlyContinue | Remove-Item -Force -Recurse -ErrorAction SilentlyContinue
            }
            Write-Host "Cleared Rollback Rx temp files" -ForegroundColor Green
            
        } catch {
            Write-Host "Temp file cleanup partially failed" -ForegroundColor Yellow
        }
        
    } catch {
        Write-Host "Error during Rollback Rx snapshot deletion: $_" -ForegroundColor Red
    }
    
    # Always provide manual instructions
    Write-Host ""
    Write-Host "=== MANUAL ROLLBACK RX CLEANUP ===" -ForegroundColor Cyan
    Write-Host "If automatic deletion failed:" -ForegroundColor White
    Write-Host "1. Open Rollback Rx (Start Menu > RollBack Rx Home)" -ForegroundColor Green
    Write-Host "2. Click 'Snapshots' in the left navigation menu" -ForegroundColor Green
    Write-Host "3. Select snapshots you want to delete (Ctrl+A for all)" -ForegroundColor Green
    Write-Host "4. Press Delete key or right-click > Delete" -ForegroundColor Green
    Write-Host "5. Confirm the deletion when prompted" -ForegroundColor Green
    Write-Host ""
    Write-Host "Alternative: Right-click Rollback Rx tray icon > Settings > Manage Snapshots" -ForegroundColor Cyan
    Write-Host "WARNING: Deleting ALL snapshots removes all restore points - cannot be undone!" -ForegroundColor Red
}

function Update-FullProfileDefinitionCache {
    param(
        [Parameter(Mandatory = $true)][string]$SourcePath,
        [Parameter(Mandatory = $true)][string]$CachePath
    )

    if (-not (Test-Path -LiteralPath $SourcePath -PathType Leaf)) {
        throw "Full PowerShell profile library not found: $SourcePath"
    }

    $sourceItem = Get-Item -LiteralPath $SourcePath
    $cacheFormat = '# FullProfileDefinitionCacheFormat: 2'
    if (Test-Path -LiteralPath $CachePath -PathType Leaf) {
        $cacheItem = Get-Item -LiteralPath $CachePath
        $cacheHeader = Get-Content -LiteralPath $CachePath -TotalCount 3 -ErrorAction SilentlyContinue
        if ($cacheItem.LastWriteTimeUtc -ge $sourceItem.LastWriteTimeUtc -and $cacheHeader -contains $cacheFormat) { return }
    }

    $parseErrors = $null
    $tokens = $null
    $ast = [System.Management.Automation.Language.Parser]::ParseFile($SourcePath, [ref]$tokens, [ref]$parseErrors)
    if ($parseErrors -and $parseErrors.Count -gt 0) {
        throw "Cannot parse full PowerShell profile library '$SourcePath': $($parseErrors[0].Message)"
    }

    $lastFunctionLines = New-Object 'System.Collections.Hashtable' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($functionAst in $ast.FindAll({ param($node) $node -is [System.Management.Automation.Language.FunctionDefinitionAst] }, $true)) {
        $functionName = $functionAst.Name -replace '^(?i:global:)', ''
        $lastFunctionLines[$functionName] = $functionAst.Extent.StartLineNumber
    }

    $parts = New-Object 'System.Collections.Generic.List[string]'
    $parts.Add($cacheFormat) | Out-Null
    $parts.Add("# Generated from $SourcePath. Contains final function definitions and safe assignments only.") | Out-Null
    $parts.Add("# Regenerate by calling fullprofile after editing the full profile source.") | Out-Null

    foreach ($statement in $ast.EndBlock.Statements) {
        if ($statement -is [System.Management.Automation.Language.FunctionDefinitionAst]) {
            $functionName = $statement.Name -replace '^(?i:global:)', ''
            if ($lastFunctionLines[$functionName] -eq $statement.Extent.StartLineNumber) {
                $parts.Add($statement.Extent.Text.TrimEnd()) | Out-Null
            }
            continue
        }

        if ($statement -is [System.Management.Automation.Language.AssignmentStatementAst]) {
            $commands = @($statement.FindAll({ param($node) $node -is [System.Management.Automation.Language.CommandAst] }, $true))
            if ($commands.Count -eq 0) {
                $parts.Add($statement.Extent.Text.TrimEnd()) | Out-Null
            }
            continue
        }

        if ($statement -is [System.Management.Automation.Language.PipelineAst]) {
            $commands = @($statement.FindAll({ param($node) $node -is [System.Management.Automation.Language.CommandAst] }, $true))
            if ($commands.Count -gt 0 -and @($commands | Where-Object { $_.GetCommandName() -ne 'Set-Alias' }).Count -eq 0) {
                $parts.Add($statement.Extent.Text.TrimEnd()) | Out-Null
            }
        }
    }

    $cacheDir = Split-Path -Parent $CachePath
    if (-not (Test-Path -LiteralPath $cacheDir -PathType Container)) {
        New-Item -ItemType Directory -Path $cacheDir -Force | Out-Null
    }

    $tempPath = "$CachePath.tmp"
    [System.IO.File]::WriteAllText($tempPath, ($parts -join [Environment]::NewLine + [Environment]::NewLine), [System.Text.UTF8Encoding]::new($false))
    Move-Item -LiteralPath $tempPath -Destination $CachePath -Force
}

function Update-HermesDockerCommanderLine([string]$Line) {
            if ([string]::IsNullOrEmpty($Line)) { return }
            $script:HermesDockerCommanderLastOutput = Get-Date
            $s = [string]$Line
            $matched = $false
            if ($s -match 'archived_bytes=(\d+)\s+total_bytes=(\d+)\s+percent=([0-9.]+).*current_layer=([^\s]+)(?:.*current_file=([^\s]+))?') {
                $script:HermesDockerCommanderLastDone = [int64]$matches[1]
                $script:HermesDockerCommanderLastTotal = [int64]$matches[2]
                $script:HermesDockerCommanderLastDetail = if ($matches[5]) { "$($matches[4]) $($matches[5])" } else { $matches[4] }
                $script:HermesDockerCommanderPhase = 'tar archive'
                $matched = $true
            } elseif ($s -match '(?i)transferring context:\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)') {
                $script:HermesDockerCommanderLastDone = Convert-HermesDockerCommanderBytes ([double]$matches[1]) $matches[2]
                if ($ContextTotalBytes -gt 0) {
                    $script:HermesDockerCommanderLastTotal = $ContextTotalBytes
                    if ($script:HermesDockerCommanderLastDone -gt $script:HermesDockerCommanderLastTotal) { $script:HermesDockerCommanderLastDone = $script:HermesDockerCommanderLastTotal }
                } elseif ($script:HermesDockerCommanderLastDone -gt $script:HermesDockerCommanderLastTotal) { $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderLastDone }
                $script:HermesDockerCommanderLastDetail = 'build context'
                $script:HermesDockerCommanderPhase = 'build context'
                $matched = $true
            } elseif ($s -match '(?i)(sha256:[a-f0-9]+|[A-Za-z0-9_.-]+):?.*?([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)\s*/\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)') {
                $id = $matches[1]
                $layerDone[$id] = Convert-HermesDockerCommanderBytes ([double]$matches[2]) $matches[3]
                $layerTotal[$id] = Convert-HermesDockerCommanderBytes ([double]$matches[4]) $matches[5]
                $script:HermesDockerCommanderLastDone = [int64](($layerDone.Values | Measure-Object -Sum).Sum)
                $script:HermesDockerCommanderLastTotal = [int64](($layerTotal.Values | Measure-Object -Sum).Sum)
                $script:HermesDockerCommanderLastDetail = "layer $id"
                $script:HermesDockerCommanderPhase = if ($DockerArgs -contains 'pull') { 'pull' } elseif ($DockerArgs -contains 'push' -or $DockerArgs -contains '--push') { 'push' } else { $script:HermesDockerCommanderPhase }
                $matched = $true
            } elseif ($s -match '(?i)exporting layers') {
                if ($ContextTotalBytes -gt 0) {
                    $script:HermesDockerCommanderLastTotal = $ContextTotalBytes
                    $targetPct = if ($s -match '(?i)\bdone\b') { 85.0 } else { 70.0 }
                    $phaseBytes = [int64]([double]$script:HermesDockerCommanderLastTotal * $targetPct / 100.0)
                    if ($script:HermesDockerCommanderLastDone -lt $phaseBytes) { $script:HermesDockerCommanderLastDone = $phaseBytes }
                }
                $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
                $script:HermesDockerCommanderPhase = 'export layers'
                $matched = $true
            } elseif ($s -match '(?i)pushing layers') {
                if ($ContextTotalBytes -gt 0) {
                    $script:HermesDockerCommanderLastTotal = $ContextTotalBytes
                    $targetPct = if ($s -match '(?i)\bdone\b') { 97.0 } else { 90.0 }
                    $phaseBytes = [int64]([double]$script:HermesDockerCommanderLastTotal * $targetPct / 100.0)
                    if ($script:HermesDockerCommanderLastDone -lt $phaseBytes) { $script:HermesDockerCommanderLastDone = $phaseBytes }
                }
                $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
                $script:HermesDockerCommanderPhase = 'push layers'
                $matched = $true
            } elseif ($s -match '(?i)pushing manifest') {
                if ($ContextTotalBytes -gt 0) {
                    $script:HermesDockerCommanderLastTotal = $ContextTotalBytes
                    $phaseBytes = [int64]([double]$script:HermesDockerCommanderLastTotal * 99.0 / 100.0)
                    if ($script:HermesDockerCommanderLastDone -lt $phaseBytes) { $script:HermesDockerCommanderLastDone = $phaseBytes }
                }
                $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
                $script:HermesDockerCommanderPhase = 'push manifest'
                $matched = $true
            } elseif ($s -match '(?i)(DONE|ERROR|failed|warning|success|digest:|writing image|naming to|exporting|importing|extracting|pull complete|pushed)') {
                Write-Host ''
                Write-Host $s -ForegroundColor DarkGray
                $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
            } else {
                Write-Host ''
                Write-Host $s -ForegroundColor Gray
                $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
            }
            if ($matched -or ((Get-Date) - $script:HermesDockerCommanderLastRender).TotalMilliseconds -ge 750) {
                Write-HermesDockerCommanderDashboard -Name $Name -Phase $script:HermesDockerCommanderPhase -Started $started -DoneBytes $script:HermesDockerCommanderLastDone -TotalBytes $script:HermesDockerCommanderLastTotal -Detail $script:HermesDockerCommanderLastDetail
                $script:HermesDockerCommanderLastRender = Get-Date
            }
        }

function Update-HermesDockerCommanderProgressLine([string]$Line) {
        if ([string]::IsNullOrEmpty($Line)) { return }
        $script:HermesDockerCommanderLastOutput = Get-Date
        $s = [string]$Line
        $matched = $false
        if ($script:HermesDockerCommanderIsPush -and (Update-HermesDockerPushStateLine $s)) { return }
        if ($script:HermesDockerCommanderIsPush) {
            Write-Host ''
            if ($s -match '(?i)(digest:|ERROR|failed|warning|denied|unauthorized|timeout|refused)') {
                Write-Host $s -ForegroundColor DarkGray
            } else {
                Write-Host $s -ForegroundColor Gray
            }
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
            return
        }
        if ($s -match 'archived_bytes=(\d+)\s+total_bytes=(\d+)\s+percent=([0-9.]+).*current_layer=([^\s]+)(?:.*current_file=([^\s]+))?') {
            $script:HermesDockerCommanderLastDone = [int64]$matches[1]
            $script:HermesDockerCommanderLastTotal = [int64]$matches[2]
            $script:HermesDockerCommanderLastDetail = if ($matches[5]) { "$($matches[4]) $($matches[5])" } else { $matches[4] }
            $script:HermesDockerCommanderPhase = 'tar archive'
            $matched = $true
        } elseif ($s -match '(?i)transferring context:\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)') {
            $script:HermesDockerCommanderLastDone = Convert-HermesDockerCommanderBytes ([double]$matches[1]) $matches[2]
            if ($script:HermesDockerCommanderContextTotalBytes -gt 0) {
                $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderContextTotalBytes
                if ($script:HermesDockerCommanderLastDone -gt $script:HermesDockerCommanderLastTotal) { $script:HermesDockerCommanderLastDone = $script:HermesDockerCommanderLastTotal }
            } elseif ($script:HermesDockerCommanderLastDone -gt $script:HermesDockerCommanderLastTotal) { $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderLastDone }
