        } elseif ($s -match '(?i)(sha256:[a-f0-9]+|[A-Za-z0-9_.-]+):?.*?([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)\s*/\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)') {
            $id = $matches[1]
            $script:HermesDockerCommanderLayerDone[$id] = Convert-HermesDockerCommanderBytes ([double]$matches[2]) $matches[3]
            $script:HermesDockerCommanderLayerTotal[$id] = Convert-HermesDockerCommanderBytes ([double]$matches[4]) $matches[5]
            $script:HermesDockerCommanderLastDone = [int64](($script:HermesDockerCommanderLayerDone.Values | Measure-Object -Sum).Sum)
            $script:HermesDockerCommanderLastTotal = [int64](($script:HermesDockerCommanderLayerTotal.Values | Measure-Object -Sum).Sum)
            $script:HermesDockerCommanderLastDetail = "layer $id"
            $script:HermesDockerCommanderPhase = if ($script:HermesDockerCommanderArgs -contains 'pull') { 'pull' } elseif ($script:HermesDockerCommanderArgs -contains 'push' -or $script:HermesDockerCommanderArgs -contains '--push') { 'push' } else { $script:HermesDockerCommanderPhase }
            $matched = $true
        } elseif ($s -match '(?i)exporting layers') {
            if ($script:HermesDockerCommanderContextTotalBytes -gt 0) {
                $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderContextTotalBytes
                $targetPct = if ($s -match '(?i)\bdone\b') { 85.0 } else { 70.0 }
                $phaseBytes = [int64]([double]$script:HermesDockerCommanderLastTotal * $targetPct / 100.0)
                if ($script:HermesDockerCommanderLastDone -lt $phaseBytes) { $script:HermesDockerCommanderLastDone = $phaseBytes }
            }
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
            $script:HermesDockerCommanderPhase = 'export layers'
            $matched = $true
        } elseif ($s -match '(?i)pushing layers') {
            if ($script:HermesDockerCommanderContextTotalBytes -gt 0) {
                $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderContextTotalBytes
                $targetPct = if ($s -match '(?i)\bdone\b') { 97.0 } else { 90.0 }
                $phaseBytes = [int64]([double]$script:HermesDockerCommanderLastTotal * $targetPct / 100.0)
                if ($script:HermesDockerCommanderLastDone -lt $phaseBytes) { $script:HermesDockerCommanderLastDone = $phaseBytes }
            }
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
            $script:HermesDockerCommanderPhase = 'push layers'
            $matched = $true
        } elseif ($s -match '(?i)pushing manifest') {
            if ($script:HermesDockerCommanderContextTotalBytes -gt 0) {
                $script:HermesDockerCommanderLastTotal = $script:HermesDockerCommanderContextTotalBytes
                $phaseBytes = [int64]([double]$script:HermesDockerCommanderLastTotal * 99.0 / 100.0)
                if ($script:HermesDockerCommanderLastDone -lt $phaseBytes) { $script:HermesDockerCommanderLastDone = $phaseBytes }
            }
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
            $script:HermesDockerCommanderPhase = 'push manifest'
            $matched = $true
        } elseif ($s -match '(?i)(DONE|ERROR|failed|warning|success|digest:|writing image|naming to|exporting|importing|extracting|pull complete|pushed)') {
            Write-Host ''
            Write-Host $s -ForegroundColor DarkGray
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
        } else {
            Write-Host ''
            Write-Host $s -ForegroundColor Gray
            $script:HermesDockerCommanderLastDetail = ($s -replace '\s+',' ')
        }
        if ($matched -or ((Get-Date) - $script:HermesDockerCommanderLastRender).TotalMilliseconds -ge 750) {
            Write-HermesDockerCommanderDashboard -Name $script:HermesDockerCommanderName -Phase $script:HermesDockerCommanderPhase -Started $script:HermesDockerCommanderStarted -DoneBytes $script:HermesDockerCommanderLastDone -TotalBytes $script:HermesDockerCommanderLastTotal -Detail $script:HermesDockerCommanderLastDetail
            $script:HermesDockerCommanderLastRender = Get-Date
        }
    }

function Update-HermesDockerPushStateLine([string]$Line) {
        $s = ([string]$Line).Trim()
        if ([string]::IsNullOrWhiteSpace($s)) { return $true }
        if ($s -match '(?i)\bdigest:\s*sha256:') { return $false }
        if ($s -notmatch '^([A-Za-z0-9][A-Za-z0-9_.-]{5,127}):\s+(.+)$') { return $false }
        $layer = [string]$matches[1]
        $status = ([string]$matches[2]).Trim() -replace '\s+',' '
        $now = Get-Date
        if (-not $script:HermesDockerCommanderPushLayerSeen.ContainsKey($layer)) { $script:HermesDockerCommanderPushLayerSeen[$layer] = $now }
        if ($status -match '(?i)([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)\s*/\s*([0-9]+(?:\.[0-9]+)?)\s*([KMGT]?i?B|[KMGT]?B|B)') {
            $script:HermesDockerCommanderPushLayerDone[$layer] = Convert-HermesDockerCommanderBytes ([double]$matches[1]) $matches[2]
            $script:HermesDockerCommanderPushLayerTotal[$layer] = Convert-HermesDockerCommanderBytes ([double]$matches[3]) $matches[4]
            $script:HermesDockerCommanderLastDone = [int64](($script:HermesDockerCommanderPushLayerDone.Values | Measure-Object -Sum).Sum)
            $script:HermesDockerCommanderLastTotal = [int64](($script:HermesDockerCommanderPushLayerTotal.Values | Measure-Object -Sum).Sum)
        }
        $previous = if ($script:HermesDockerCommanderPushLayerStatus.ContainsKey($layer)) { [string]$script:HermesDockerCommanderPushLayerStatus[$layer] } else { '' }
        $script:HermesDockerCommanderPushLayerStatus[$layer] = $status
        if ($previous -ne $status) {
            $script:HermesDockerCommanderPushLayerChanged[$layer] = $now
            $script:HermesDockerCommanderPushLastChange = $now
            $script:HermesDockerCommanderLastDetail = ('layer {0}: {1}' -f $layer,$status)
            Write-Host ''
            Invoke-HermesDockerAllFastLine $script:HermesDockerCommanderName ('push-layer {0}: {1}' -f $layer,$status)
            return $true
        }
        if ($status -match '(?i)^Waiting$') { $script:HermesDockerCommanderPushSuppressedWaiting++ }
        return $true
    }

function Update-MmenuProgressFromChunk {
        param([string]$Chunk)
        if ([string]::IsNullOrEmpty($Chunk)) { return }
        foreach($line in ($Chunk -split "[`r`n]+")) {
            if ($line -match '\[mmenu\]\[context\]\s+archived_bytes=(\d+)\s+total_bytes=(\d+)') {
                $script:MmenuContextDoneBytes=[int64]$matches[1]; $script:MmenuContextTotalBytes=[int64]$matches[2]; $script:MmenuLastNativeProgressUtc=Get-Date
            }
            if ($line -match 'transferring context:\s+([0-9]+(?:\.[0-9]+)?\s*[KMGT]?i?B|[0-9]+(?:\.[0-9]+)?\s*[KMGT]?B|[0-9]+\s*B)') {
                $bc=Convert-MmenuDockerSizeToBytes $matches[1]
                if($null -ne $bc){ $script:MmenuBuildCurrentBytes=[int64]$bc; $script:MmenuLastNativeProgressUtc=Get-Date }
            }
            if ($line -match '^\s*([a-f0-9]{12,}|[A-Za-z0-9_.-]+):\s+.*?([0-9]+(?:\.[0-9]+)?\s*[KMGT]?i?B|[0-9]+(?:\.[0-9]+)?\s*[KMGT]?B|[0-9]+\s*B)\s*/\s*([0-9]+(?:\.[0-9]+)?\s*[KMGT]?i?B|[0-9]+(?:\.[0-9]+)?\s*[KMGT]?B|[0-9]+\s*B)') {
                $cur=Convert-MmenuDockerSizeToBytes $matches[2]; $tot=Convert-MmenuDockerSizeToBytes $matches[3]
                if($null -ne $cur -and $null -ne $tot){ $script:MmenuPushLayers[$matches[1]]=@($cur,$tot); $script:MmenuLastNativeProgressUtc=Get-Date }
            }
        }
    }

