function global:Update-SessionEnvironment {
    Import-ProfileChocolatey
    $command = Get-Command Update-SessionEnvironment -CommandType Cmdlet -ErrorAction SilentlyContinue
    if (-not $command) {
        throw 'Chocolatey Update-SessionEnvironment is not available.'
    }
    & $command @args
}

function upup {
    $ErrorActionPreference = 'Continue'
    Repair-StandardWindowsProcessEnvironment

    $wingetPath = $null
    try { $wingetPath = Resolve-WingetExecutable } catch { $wingetPath = $null }

    if ($wingetPath -and (Test-Path -LiteralPath $wingetPath -PathType Leaf)) {
        $vcRuntimeIds = @('Microsoft.VCRedist.2015+.x64', 'Microsoft.VCRedist.2015+.x86')
        $vcDirectInstallers = @{
            'Microsoft.VCRedist.2015+.x64' = 'https://download.visualstudio.microsoft.com/download/pr/c1bd4f2c-3672-468e-8480-7ed419dbb641/90E48ADE404E4576D023ABFA374F323555F233982A8805EA9AC63DCA9491A16B/VC_redist.x64.exe'
            'Microsoft.VCRedist.2015+.x86' = 'https://download.visualstudio.microsoft.com/download/pr/0dd156af-82aa-4812-b524-49c2f894359a/B6AB675F0A27E6600F9726E75DEA08D99C15F8EA4B842A2A1D988FA9529D39B9/VC_redist.x86.exe'
        }

        try {
            $upgradeOutput = (& $wingetPath upgrade --include-unknown --accept-source-agreements --disable-interactivity 2>&1 | Out-String)
            foreach ($vcRuntimeId in $vcRuntimeIds) {
                if ($upgradeOutput -notmatch [regex]::Escape($vcRuntimeId)) {
                    Write-Host ("[upup] Visual C++ runtime {0} already current or not installed; no UI needed." -f $vcRuntimeId)
                    continue
                }

                Write-Host ("[upup] Visual C++ runtime {0} direct quiet update" -f $vcRuntimeId)
                $installerUrl = $vcDirectInstallers[$vcRuntimeId]
                $installerPath = Join-Path $env:TEMP ("{0}.exe" -f ($vcRuntimeId -replace '[^A-Za-z0-9]+', '_'))
                Invoke-WebRequest -Uri $installerUrl -OutFile $installerPath -UseBasicParsing
                $process = Start-Process -FilePath $installerPath -ArgumentList @('/install', '/quiet', '/norestart') -Wait -PassThru -WindowStyle Hidden
                Remove-Item -LiteralPath $installerPath -Force -ErrorAction SilentlyContinue
                if ($process.ExitCode -notin @(0, 3010, 1638)) {
                    Write-Warning ("Visual C++ runtime quiet installer did not verify for {0}: exit {1}" -f $vcRuntimeId, $process.ExitCode)
                }
            }
        } catch {
            Write-Warning ("[upup] Visual C++ runtime pre-check/update skipped after nonfatal error: {0}" -f $_.Exception.Message)
        }
    } else {
        Write-Warning 'winget not found; skipping Visual C++ runtime update check.'
    }

    $invokeUpupClean = {
        param([string]$Name)
        try {
            $raw = (& $Name 2>&1 | Out-String)
            $clean = [regex]::Replace($raw, '(?ms)^npm\.cmd\s*:\s*npm notice.*?FullyQualifiedErrorId\s*:\s*NativeCommandError\s*', '')
            if ($clean -ne $raw) { Write-Host ("[upup] suppressed known benign npm notice PowerShell NativeCommandError formatting from {0}." -f $Name) }
            if (-not [string]::IsNullOrWhiteSpace($clean)) { Write-Host ($clean.TrimEnd()) }
        } catch {
            Write-Warning ("[upup] {0} failed but upup continued: {1}" -f $Name, $_.Exception.Message)
        }
    }
    & $invokeUpupClean 'upgrader'
    & $invokeUpupClean 'wingup'
    $global:LASTEXITCODE = 0
}

function usrfindhandle { pnputil /delete-driver $(Get-ChildItem "$env:SystemRoot\System32\drivers\USRFindHandle64.sys" -ErrorAction SilentlyContinue | ForEach-Object { (pnputil /enum-drivers | Select-String $_.Name -Context 0,1) }) /uninstall /force 2>$null; Get-ChildItem "$env:SystemRoot\System32\drivers" -Filter "USR*.sys" | Remove-Item -Force; bcdedit /set recoveryenabled no | Out-Null }

function Wait-HermesDockerCommanderRetry([string]$Name,[string]$Phase,[datetime]$Started,[int]$Seconds,[int]$Attempt,[string]$Detail) {
        $until = (Get-Date).AddSeconds([Math]::Max(1,$Seconds))
        while ((Get-Date) -lt $until) {
            $remaining = [int][Math]::Ceiling(($until - (Get-Date)).TotalSeconds)
            Write-HermesDockerCommanderDashboard -Name $Name -Phase $Phase -Started $Started -DoneBytes 0 -TotalBytes 0 -Detail ("retry attempt {0} in {1}s; {2}" -f ($Attempt + 1),$remaining,$Detail)
            Start-Sleep -Milliseconds 250
        }
        Write-Host ''
    }

function Wait-RedockerSafeDockerFiles {
        param([int]$TimeoutSeconds = 180)
        $deadline = (Get-Date).AddSeconds([Math]::Max(5,$TimeoutSeconds))
        $last = -1
        do {
            $desktop = Find-RedockerSafeDockerPath -Kind Desktop
            $cli = Find-RedockerSafeDockerPath -Kind Cli
            if($desktop -and $cli){ return [pscustomobject]@{ DesktopExe = $desktop; DockerExe = $cli } }
            $elapsed = [int]([Math]::Max(0,((Get-Date).AddSeconds($TimeoutSeconds) - $deadline).TotalSeconds))
            $pct = [Math]::Min(99,[int](($elapsed / [Math]::Max(1,$TimeoutSeconds)) * 100))
            if($pct -ne $last){
                Write-RedockerSafeLine ("waiting for installed executables {0}% desktop={1} cli={2}" -f $pct,[bool]$desktop,[bool]$cli) DarkCyan
                $last = $pct
            }
            Start-Sleep -Milliseconds 500
        } while((Get-Date) -lt $deadline)
        return [pscustomobject]@{ DesktopExe = (Find-RedockerSafeDockerPath -Kind Desktop); DockerExe = (Find-RedockerSafeDockerPath -Kind Cli) }
    }

function Wait-RedockerSafeDockerReady {
        param([string]$DockerExe,[int]$TimeoutSeconds = 180)
        $deadline = (Get-Date).AddSeconds([Math]::Max(5,$TimeoutSeconds))
        $last = -1
        do {
            if(Test-RedockerSafeDockerReady -DockerExe $DockerExe){ return $true }
            $elapsed = [int]([Math]::Max(0,((Get-Date).AddSeconds($TimeoutSeconds) - $deadline).TotalSeconds))
            $pct = [Math]::Min(99,[int](($elapsed / [Math]::Max(1,$TimeoutSeconds)) * 100))
            if($pct -ne $last){
                Write-RedockerSafeLine ("waiting for Docker daemon readiness {0}%" -f $pct) DarkCyan
                $last = $pct
            }
            Start-Sleep -Milliseconds 750
        } while((Get-Date) -lt $deadline)
        return (Test-RedockerSafeDockerReady -DockerExe $DockerExe -Milliseconds 2500)
    }

function Write-DKillFastLine {
        param([string]$Message,[ConsoleColor]$Color=[ConsoleColor]::Cyan)
        $line = "[dkill] {0}" -f $Message
        Write-Host $line -ForegroundColor $Color
        if($script:DKillFastProofPath){
            try { Add-Content -LiteralPath $script:DKillFastProofPath -Value ("{0:o} {1}" -f (Get-Date),$line) -Encoding UTF8 -ErrorAction SilentlyContinue } catch { }
        }
    }

function Write-DKillLine { param([string]$Message) Write-Host ("[dkill] {0}" -f $Message) }

function Write-FixDocker2LiveText {
                    param([string]$Text)
                    if ([string]::IsNullOrEmpty($Text)) { return }
                    if (-not $isPush) { Write-Host -NoNewline $Text; return }
                    $normalized = $Text -replace "`r", "`n"
                    foreach ($line in @($normalized -split "`n")) {
                        if ([string]::IsNullOrWhiteSpace($line)) { continue }
                        $trimmed = $line.Trim()
                        if ($trimmed -match '^([a-f0-9]{12,}):\s+(.+)$') {
                            $layer = $Matches[1]
                            $status = $Matches[2].Trim()
                            $previous = if ($pushLayerStatus.ContainsKey($layer)) { [string]$pushLayerStatus[$layer] } else { '' }
                            $nowSeen = Get-Date
                            if (-not $pushLayerFirstSeen.ContainsKey($layer)) { $pushLayerFirstSeen[$layer] = $nowSeen }
                            if ($previous -ne $status) {
                                $pushLayerLastChanged[$layer] = $nowSeen
                                $pushLastAnyChangeAt = $nowSeen
                            } elseif (-not $pushLayerLastChanged.ContainsKey($layer)) {
                                $pushLayerLastChanged[$layer] = $nowSeen
                            }
                            $pushLayerStatus[$layer] = $status
                            $printKey = "$layer|$status"
                            if ($status -eq 'Waiting' -and $previous -eq 'Waiting') {
                                $script:__fixdocker2_unused = $null
                                $pushRawWaitingSuppressed++
                                continue
                            }
                            if (-not $pushLastPrinted.ContainsKey($printKey)) {
                                Write-Host ('[push-layer] {0}: {1}' -f $layer,$status)
                                $pushLastPrinted[$printKey] = $true
                            }
                        } else {
                            if ($trimmed -match '(?i)\b(failed|error|denied|unauthorized|timeout|refused)\b') { $dockerLiveState.ErrorDetected = $true }
                            Write-Host $trimmed
                        }
                    }
                }

function Write-FixDocker2PushSummary {
                    if (-not $isPush) { return }
                    $nowSummary = Get-Date
                    $sinceAnyChange = [int](($nowSummary - $pushLastAnyChangeAt).TotalSeconds)
                    if ($pushLayerStatus.Count -eq 0) {
                        $elapsedForSummary = if ($sw.Elapsed.TotalHours -ge 1) { '{0:hh\:mm\:ss}' -f $sw.Elapsed } else { '{0:mm\:ss}' -f $sw.Elapsed }
                        Write-Host ('[push-progress] elapsed={0}; waiting for Docker registry/layer status lines; no layer data yet; process alive.' -f $elapsedForSummary) -ForegroundColor DarkCyan
                        return
                    }
                    $doneCount = 0
                    $activeCount = 0
                    $waitingCount = 0
                    foreach ($value in $pushLayerStatus.Values) {
                        if ($value -match 'Pushed|Mounted from|Layer already exists') { $doneCount++ }
                        elseif ($value -match 'Pushing|Preparing') { $activeCount++ }
                        elseif ($value -match 'Waiting') { $waitingCount++ }
                    }
                    $parts = @($pushLayerStatus.GetEnumerator() | Sort-Object Name | ForEach-Object {
                        $layerName = $_.Name
                        $statusValue = [string]$_.Value
                        $age = if ($pushLayerLastChanged.ContainsKey($layerName)) { [int](($nowSummary - ([datetime]$pushLayerLastChanged[$layerName])).TotalSeconds) } else { 0 }
                        ('{0}={1}({2}s)' -f $layerName,$statusValue,$age)
                    })
                    $etaText = if ($waitingCount -gt 0 -and $activeCount -eq 0) { 'ETA unknown: Docker registry has not reported byte progress for waiting layer(s)' } elseif ($activeCount -gt 0) { 'ETA depends on current upload speed; Docker will print bytes when registry reports them' } else { 'finishing registry commit/manifest update' }
                    $summary = 'layers done={0}/{1} active={2} waiting={3}; no-status-change={4}s; {5}; {6}; repeated Waiting lines suppressed={7}' -f $doneCount,$pushLayerStatus.Count,$activeCount,$waitingCount,$sinceAnyChange,$etaText,($parts -join '; '),$pushRawWaitingSuppressed
                    Write-Host ('[push-progress] {0}' -f $summary) -ForegroundColor DarkCyan
                    $pushLastSummary = $summary
                }

