function global:Write-HermesDockerCommanderDashboard {
    param(
        [string]$Name,
        [string]$Phase,
        [datetime]$Started,
        [int64]$DoneBytes = 0,
        [int64]$TotalBytes = 0,
        [string]$Detail = ''
    )
    $elapsed = [Math]::Max(0.1, ((Get-Date) - $Started).TotalSeconds)
    $hasMeasuredBytes = ($TotalBytes -gt 0 -and $DoneBytes -gt 0)
    $pct = if ($hasMeasuredBytes) { [Math]::Min([double]100.0, (100.0 * [double]$DoneBytes / [Math]::Max([double]1.0, [double]$TotalBytes))) } else { 0.0 }
    $speed = if ($DoneBytes -gt 0) { [int64]($DoneBytes / $elapsed) } else { 0L }
    $barWidth = 24
    $fill = if ($hasMeasuredBytes) { [Math]::Min([int]$barWidth, [Math]::Max([int]0, [int][Math]::Round($barWidth * $pct / 100.0))) } else { 0 }
    $bar = ('#' * $fill).PadRight($barWidth, '.')
    if ($hasMeasuredBytes) {
        $metric = ('{0,6:N2}% {1}/{2} {3}/s' -f $pct, (Format-HermesDockerCommanderMiB $DoneBytes), (Format-HermesDockerCommanderMiB $TotalBytes), (Format-HermesDockerCommanderMiB $speed))
    } else {
        $metric = ('active elapsed={0,6:N0}s' -f $elapsed)
    }
    $line = ('[{0:HH:mm:ss}] {1,-7} {2,-13} [{3}] {4} {5}' -f (Get-Date), $Name, $Phase, $bar, $metric, $Detail)
    $width = try { [Console]::WindowWidth } catch { 160 }
    if ($width -lt 40) { $width = 160 }
    if ($line.Length -ge $width) { $line = $line.Substring(0, $width - 1) }
    Write-Host ("`r" + $line.PadRight($width - 1)) -NoNewline -ForegroundColor Cyan
}

function Write-HermesDockerPushSummary([datetime]$Started) {
        $now = Get-Date
        $totalLayers = $script:HermesDockerCommanderPushLayerStatus.Count
        $doneCount = 0
        $uploadingCount = 0
        $waitingCount = 0
        $otherCount = 0
        $knownDone = 0L
        $knownTotal = 0L
        foreach ($layer in $script:HermesDockerCommanderPushLayerStatus.Keys) {
            $status = [string]$script:HermesDockerCommanderPushLayerStatus[$layer]
            if ($script:HermesDockerCommanderPushLayerDone.ContainsKey($layer)) { $knownDone += [int64]$script:HermesDockerCommanderPushLayerDone[$layer] }
            if ($script:HermesDockerCommanderPushLayerTotal.ContainsKey($layer)) { $knownTotal += [int64]$script:HermesDockerCommanderPushLayerTotal[$layer] }
            if ($status -match '(?i)\b(Pushed|Mounted from|Layer already exists|Already exists)\b') { $doneCount++ }
            elseif ($status -match '(?i)\b(Pushing|Preparing)\b') { $uploadingCount++ }
            elseif ($status -match '(?i)\bWaiting\b') { $waitingCount++ }
            else { $otherCount++ }
        }
        $estimatedTotal = [int64]$script:HermesDockerCommanderPushImageBytes
        $estimatedDone = 0L
        if ($estimatedTotal -gt 0) {
            $denominator = [Math]::Max(1,$totalLayers)
            $weightedDone = [double]$doneCount
            if ($uploadingCount -gt 0) { $weightedDone += ([double]$uploadingCount * 0.5) }
            $estimatedDone = [int64]([Math]::Min([double]$estimatedTotal,[double]$estimatedTotal * $weightedDone / [double]$denominator))
        }
        $knownBytes = if ($knownTotal -gt 0) {
            $pct = [Math]::Min([double]100.0,[Math]::Round(100.0 * [double]$knownDone / [Math]::Max([double]1.0,[double]$knownTotal),2))
            ('docker-bytes {0:N2}% {1}/{2}' -f $pct,(Format-HermesDockerCommanderMiB $knownDone),(Format-HermesDockerCommanderMiB $knownTotal))
        } elseif ($estimatedTotal -gt 0) {
            ('docker-layer-bytes=not-exposed; local-image-size={0}' -f (Format-HermesDockerCommanderMiB $estimatedTotal))
        } else {
            'image-size-unavailable 0.00% 0.00 MiB/0.00 MiB'
        }
        $networkBytes = Get-HermesDockerNetworkSentBytes
        $networkText = 'network-sent=unavailable'
        if ($networkBytes -ge 0 -and $script:HermesDockerCommanderPushNetStartBytes -ge 0) {
            $sessionBytes = [Math]::Max([int64]0,([int64]$networkBytes - [int64]$script:HermesDockerCommanderPushNetStartBytes))
            $lastBytes = [int64]$script:HermesDockerCommanderPushNetLastBytes
            $lastSample = [datetime]$script:HermesDockerCommanderPushNetLastSample
            $deltaBytes = [Math]::Max([int64]0,([int64]$networkBytes - $lastBytes))
            $deltaSeconds = [Math]::Max(0.001,($now - $lastSample).TotalSeconds)
            $rateBytes = [int64]([double]$deltaBytes / $deltaSeconds)
            $networkText = ('network-sent={0} session; delta={1}; rate={2}/s; sample={3:N0}ms; source=windows-net-adapters' -f (Format-HermesDockerCommanderMiB $sessionBytes),(Format-HermesDockerCommanderMiB $deltaBytes),(Format-HermesDockerCommanderMiB $rateBytes),($deltaSeconds * 1000.0))
            $script:HermesDockerCommanderPushNetLastBytes = [int64]$networkBytes
            $script:HermesDockerCommanderPushNetLastSample = $now
        }
        $sinceChange = [int][Math]::Max(0,($now - $script:HermesDockerCommanderPushLastChange).TotalSeconds)
        $elapsed = Format-HermesDockerCommanderElapsed ($now - $Started)
        $states = New-Object System.Collections.Generic.List[string]
        foreach ($entry in ($script:HermesDockerCommanderPushLayerStatus.GetEnumerator() | Sort-Object Name | Select-Object -First 10)) {
            $layer = [string]$entry.Name
            $short = if ($layer.Length -gt 12) { $layer.Substring(0,12) } else { $layer }
            $status = ([string]$entry.Value) -replace '\s+',' '
            $age = if ($script:HermesDockerCommanderPushLayerChanged.ContainsKey($layer)) { [int][Math]::Max(0,($now - ([datetime]$script:HermesDockerCommanderPushLayerChanged[$layer])).TotalSeconds) } else { 0 }
            [void]$states.Add(('{0}={1} age={2}s' -f $short,$status,$age))
        }
        $silence = if ($knownTotal -eq 0 -and $estimatedTotal -gt 0 -and $waitingCount -gt 0 -and $uploadingCount -eq 0) {
            '; registry is silent for waiting layer(s); Docker layer bytes are not exposed yet, live network-sent MiB/rate is the real transfer signal'
        } elseif ($uploadingCount -gt 0 -and $knownTotal -eq 0) {
            '; uploading/preparing; Docker layer bytes are not exposed yet, live network-sent MiB/rate is the real transfer signal'
        } elseif ($knownTotal -eq 0 -and $estimatedTotal -le 0) {
            '; Docker did not expose push bytes and local image size lookup failed'
        } else {
            ''
        }
        Invoke-HermesDockerAllFastLine $script:HermesDockerCommanderName (
            'push-live elapsed={0}; layers done={1}/{2} uploading={3} waiting={4} other={5}; known-bytes={6}; live-bytes={7}; last-real-change={8}s; repeated-waiting-suppressed={9}{10}; {11}' -f
            $elapsed,$doneCount,$totalLayers,$uploadingCount,$waitingCount,$otherCount,$knownBytes,$networkText,$sinceChange,$script:HermesDockerCommanderPushSuppressedWaiting,$silence,($states -join '; ')
        )
        $script:HermesDockerCommanderPushLastSummary = Get-Date
    }

function Write-MegaFixLine([string]$Message) {
        $line = '[{0}] {1}' -f (Get-Date -Format 'HH:mm:ss'), $Message
        Write-Host $line
        Add-Content -LiteralPath $log -Value $line -Encoding UTF8
    }

function Write-MmenuNewLogBytes {
        param([Parameter(Mandatory=$true)][string]$File,[Parameter(Mandatory=$true)][ref]$Offset)
        if (-not (Test-Path -LiteralPath $File -PathType Leaf)) { return }
        $fs = [IO.File]::Open($File, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite)
        try {
            if ($fs.Length -gt $Offset.Value) {
                $fs.Seek([int64]$Offset.Value, [IO.SeekOrigin]::Begin) | Out-Null
                $reader = New-Object IO.StreamReader($fs, [Text.Encoding]::UTF8, $true, 4096, $true)
                $chunk = $reader.ReadToEnd(); $reader.Dispose(); $Offset.Value = $fs.Position
                if (-not [string]::IsNullOrEmpty($chunk)) { Update-MmenuProgressFromChunk $chunk; Write-Host $chunk.TrimEnd() }
            }
        } finally { $fs.Dispose() }
    }

function Write-MmenuRealProgressLine {
        param([string]$Label,[int]$Elapsed,[int]$ProcessId,[int]$Tick)
        $parts=@()
        $nativeAge=[int][Math]::Floor(((Get-Date)-$script:MmenuLastNativeProgressUtc).TotalSeconds)
        $showByteProgress = ($Label -eq 'tar-import')
        if($showByteProgress -and $script:MmenuContextTotalBytes -gt 0){
            if($script:MmenuContextDoneBytes -ge $script:MmenuContextTotalBytes){
                $parts += ('context-stream-complete={0}/{1}; docker-import-finalizing-no-native-percent' -f (Format-MmenuMB $script:MmenuContextDoneBytes),(Format-MmenuMB $script:MmenuContextTotalBytes))
            } else {
                $pct=[Math]::Min([double]99.99,[Math]::Round(100.0*[double]$script:MmenuContextDoneBytes/[Math]::Max([double]1,[double]$script:MmenuContextTotalBytes),2))
                $parts += ('context={0}/{1} {2}%' -f (Format-MmenuMB $script:MmenuContextDoneBytes),(Format-MmenuMB $script:MmenuContextTotalBytes),$pct)
            }
        }
        if($showByteProgress -and $script:MmenuBuildCurrentBytes -gt 0){
            if($script:MmenuContextTotalBytes -gt 0){
                if($script:MmenuBuildCurrentBytes -ge $script:MmenuContextTotalBytes){
                    $parts += ('build-transfer-complete={0}/{1}; waiting-for-docker-finalize' -f (Format-MmenuMB $script:MmenuBuildCurrentBytes),(Format-MmenuMB $script:MmenuContextTotalBytes))
                } else {
                    $pct=[Math]::Min([double]99.99,[Math]::Round(100.0*[double]$script:MmenuBuildCurrentBytes/[Math]::Max([double]1,[double]$script:MmenuContextTotalBytes),2))
                    $parts += ('build-transfer={0}/{1} {2}%' -f (Format-MmenuMB $script:MmenuBuildCurrentBytes),(Format-MmenuMB $script:MmenuContextTotalBytes),$pct)
                }
            } else {
                $parts += ('build-transfer={0}' -f (Format-MmenuMB $script:MmenuBuildCurrentBytes))
            }
        }
        if($showByteProgress -and $script:MmenuPushLayers.Count -gt 0){
            $cur=[int64]0; $tot=[int64]0
            foreach($v in $script:MmenuPushLayers.Values){ $cur += [int64]$v[0]; $tot += [int64]$v[1] }
            if($tot -gt 0 -and $cur -ge $tot){
                $parts += ('push-layers-complete={0}/{1}; waiting-for-registry-confirm' -f (Format-MmenuMB $cur),(Format-MmenuMB $tot))
            } else {
                $pct=[Math]::Min([double]99.99,[Math]::Round(100.0*[double]$cur/[Math]::Max([double]1,[double]$tot),2))
                $parts += ('push={0}/{1} {2}%' -f (Format-MmenuMB $cur),(Format-MmenuMB $tot),$pct)
            }
        }
        if($parts.Count -eq 0){ $parts += 'stage-running-no-byte-total' }
        $parts += ('last-real-byte-update={0}s-ago' -f $nativeAge)
        Write-Host ("[mmenu][docker:{0}] progress elapsed={1}s pid={2} {3}" -f $Label,$Elapsed,$ProcessId,($parts -join ' ')) -ForegroundColor DarkCyan
    }

function Write-MmenuTarStreamerScript {
        param([string]$ScriptPath)
        $py = @'
import os, sys, tarfile, time
root=os.path.abspath(sys.argv[1])
files=[]; total=0; phantom=0
def on_walk_error(e):
    global phantom
    phantom += 1
    print(f"[mmenu][context-warning] unreadable_reserved_or_phantom_path path={getattr(e,'filename',None)!r} error={e}", file=sys.stderr, flush=True)
for dp,dn,fn in os.walk(root, onerror=on_walk_error):
    for n in fn:
        p=os.path.join(dp,n)
        try:
            st=os.lstat(p); total += st.st_size; files.append(p)
        except OSError as e:
            phantom += 1
            print(f"[mmenu][context-warning] unreadable_reserved_or_phantom_path path={p!r} error={e}", file=sys.stderr, flush=True)
print(f"[mmenu][context] archived_bytes=0 total_bytes={total}", file=sys.stderr, flush=True)
if phantom:
    print(f"[mmenu][context-warning] reserved_or_phantom_entries_not_real_readable_files={phantom}", file=sys.stderr, flush=True)
class CountingWriter:
    def __init__(self, raw, total):
        self.raw=raw; self.total=total; self.done=0; self.last=0.0
    def write(self, b):
        n=self.raw.write(b)
        if n is None: n=len(b)
        self.done += n
        now=time.time()
        if now-self.last >= 1.0:
            print(f"[mmenu][context] archived_bytes={self.done} total_bytes={self.total}", file=sys.stderr, flush=True); self.last=now
        return n
    def flush(self):
        return self.raw.flush()
out=CountingWriter(sys.stdout.buffer, total)
with tarfile.open(fileobj=out, mode='w|') as tar:
    for p in files:
        arc=os.path.join('home', os.path.relpath(p, root)).replace('\\','/')
        try:
            tar.add(p, arcname=arc, recursive=False)
        except OSError as e:
            print(f"[mmenu][context-warning] unreadable_reserved_or_phantom_path path={p!r} error={e}", file=sys.stderr, flush=True)
print(f"[mmenu][context] archived_bytes={out.done} total_bytes={total}", file=sys.stderr, flush=True)
'@
        [IO.File]::WriteAllText($ScriptPath,$py,[Text.Encoding]::UTF8)
    }

function Write-MmmenuNewLogBytes {
        param([Parameter(Mandatory=$true)][string]$File,[Parameter(Mandatory=$true)][ref]$Offset)
        if (-not (Test-Path -LiteralPath $File -PathType Leaf)) { return }
        $fs = [IO.File]::Open($File, [IO.FileMode]::Open, [IO.FileAccess]::Read, [IO.FileShare]::ReadWrite)
        try {
            if ($fs.Length -gt $Offset.Value) {
                $fs.Seek([int64]$Offset.Value, [IO.SeekOrigin]::Begin) | Out-Null
                $reader = New-Object IO.StreamReader($fs, [Text.Encoding]::UTF8, $true, 4096, $true)
                $chunk = $reader.ReadToEnd(); $reader.Dispose(); $Offset.Value = $fs.Position
                if (-not [string]::IsNullOrEmpty($chunk)) { Update-MmmenuProgressFromChunk $chunk; Write-Host $chunk.TrimEnd() }
            }
        } finally { $fs.Dispose() }
    }

function Write-MmmenuRealProgressLine {
        param([string]$Label,[int]$Elapsed,[int]$ProcessId,[int]$Tick)
        $parts=@()
        $nativeAge=[int][Math]::Floor(((Get-Date)-$script:MmmenuLastNativeProgressUtc).TotalSeconds)
        $showByteProgress = ($Label -eq 'tar-import')
        if($showByteProgress -and $script:MmmenuContextTotalBytes -gt 0){
            if($script:MmmenuContextDoneBytes -ge $script:MmmenuContextTotalBytes){
                $parts += ('context-stream-complete={0}/{1}; docker-import-finalizing-no-native-percent' -f (Format-MmmenuMB $script:MmmenuContextDoneBytes),(Format-MmmenuMB $script:MmmenuContextTotalBytes))
            } else {
                $pct=[Math]::Min([double]99.99,[Math]::Round(100.0*[double]$script:MmmenuContextDoneBytes/[Math]::Max([double]1,[double]$script:MmmenuContextTotalBytes),2))
                $parts += ('context={0}/{1} {2}%' -f (Format-MmmenuMB $script:MmmenuContextDoneBytes),(Format-MmmenuMB $script:MmmenuContextTotalBytes),$pct)
            }
        }
        if($showByteProgress -and $script:MmmenuBuildCurrentBytes -gt 0){
            if($script:MmmenuContextTotalBytes -gt 0){
                if($script:MmmenuBuildCurrentBytes -ge $script:MmmenuContextTotalBytes){
                    $parts += ('build-transfer-complete={0}/{1}; waiting-for-docker-finalize' -f (Format-MmmenuMB $script:MmmenuBuildCurrentBytes),(Format-MmmenuMB $script:MmmenuContextTotalBytes))
                } else {
                    $pct=[Math]::Min([double]99.99,[Math]::Round(100.0*[double]$script:MmmenuBuildCurrentBytes/[Math]::Max([double]1,[double]$script:MmmenuContextTotalBytes),2))
                    $parts += ('build-transfer={0}/{1} {2}%' -f (Format-MmmenuMB $script:MmmenuBuildCurrentBytes),(Format-MmmenuMB $script:MmmenuContextTotalBytes),$pct)
                }
            } else {
                $parts += ('build-transfer={0}' -f (Format-MmmenuMB $script:MmmenuBuildCurrentBytes))
            }
        }
        if($showByteProgress -and $script:MmmenuPushLayers.Count -gt 0){
            $cur=[int64]0; $tot=[int64]0
            foreach($v in $script:MmmenuPushLayers.Values){ $cur += [int64]$v[0]; $tot += [int64]$v[1] }
            if($tot -gt 0 -and $cur -ge $tot){
                $parts += ('push-layers-complete={0}/{1}; waiting-for-registry-confirm' -f (Format-MmmenuMB $cur),(Format-MmmenuMB $tot))
            } else {
                $pct=[Math]::Min([double]99.99,[Math]::Round(100.0*[double]$cur/[Math]::Max([double]1,[double]$tot),2))
                $parts += ('push={0}/{1} {2}%' -f (Format-MmmenuMB $cur),(Format-MmmenuMB $tot),$pct)
            }
        }
        if($parts.Count -eq 0){ $parts += 'stage-running-no-byte-total' }
        $parts += ('last-real-byte-update={0}s-ago' -f $nativeAge)
        Write-Host ("[mmmenu][docker:{0}] progress elapsed={1}s pid={2} {3}" -f $Label,$Elapsed,$ProcessId,($parts -join ' ')) -ForegroundColor DarkCyan
    }

function Write-MmmenuTarStreamerScript {
        param([string]$ScriptPath)
        $py = @'
import os, sys, tarfile, time
root=os.path.abspath(sys.argv[1])
files=[]; total=0; skipped=0
def on_walk_error(e):
    global skipped
    skipped += 1
    print(f"[mmmenu][context-warning] unreadable_reserved_or_phantom_path path={getattr(e,'filename',None)!r} error={e}", file=sys.stderr, flush=True)
for dp,dn,fn in os.walk(root, onerror=on_walk_error):
    for n in fn:
        p=os.path.join(dp,n)
        try:
            st=os.lstat(p); total += st.st_size; files.append(p)
        except OSError as e:
            skipped += 1
            print(f"[mmmenu][context-warning] unreadable_reserved_or_phantom_path path={p!r} error={e}", file=sys.stderr, flush=True)
print(f"[mmmenu][context] archived_bytes=0 total_bytes={total}", file=sys.stderr, flush=True)
if skipped:
    print(f"[mmmenu][context-warning] reserved_or_phantom_entries_not_real_readable_files={skipped}", file=sys.stderr, flush=True)
class CountingWriter:
    def __init__(self, raw, total):
        self.raw=raw; self.total=total; self.done=0; self.last=0.0
    def write(self, b):
        n=self.raw.write(b)
        if n is None: n=len(b)
        self.done += n
        now=time.time()
        if now-self.last >= 1.0:
            print(f"[mmmenu][context] archived_bytes={self.done} total_bytes={self.total}", file=sys.stderr, flush=True); self.last=now
        return n
    def flush(self):
        return self.raw.flush()
out=CountingWriter(sys.stdout.buffer, total)
with tarfile.open(fileobj=out, mode='w|') as tar:
    for p in files:
        arc=os.path.join('home', os.path.relpath(p, root)).replace('\\','/')
        try:
            tar.add(p, arcname=arc, recursive=False)
        except OSError as e:
            print(f"[mmmenu][context-warning] unreadable_reserved_or_phantom_path path={p!r} error={e}", file=sys.stderr, flush=True)
print(f"[mmmenu][context] archived_bytes={out.done} total_bytes={total}", file=sys.stderr, flush=True)
'@
        [IO.File]::WriteAllText($ScriptPath,$py,[Text.Encoding]::UTF8)
    }

