function Write-TaskSection {
        param(
            [string]$Name,
            [string]$Color,
            [array]$Tasks,
            [string]$SeanUsername
        )

        Write-Host "  [$Name] ($($Tasks.Count))" -ForegroundColor $Color
        Write-Host "  $('-' * 80)" -ForegroundColor DarkGray

        if ($Tasks.Count -eq 0) {
            Write-Host "  (none)" -ForegroundColor DarkGray
            Write-Host ""
            return
        }

        foreach ($t in $Tasks | Sort-Object Number) {
            $assignee = if ($t.Assignees) { $t.Assignees } else { "UNASSIGNED" }
            $seanTag = if ($t.Assignees -eq $SeanUsername) { " [HANDOFF -> Sean]" } else { "" }
            $labelStr = if ($t.Labels) { " | $($t.Labels)" } else { "" }
            Write-Host "  #$($t.Number) $($t.Title)" -ForegroundColor White
            Write-Host "    -> $assignee$seanTag$labelStr" -ForegroundColor DarkCyan
            Write-Host "    $($t.Url)" -ForegroundColor DarkGray
        }

        Write-Host ""
    }

