# final Codex Windows Terminal settings restore override
function global:rester {
    [CmdletBinding()]
    param()

    $ErrorActionPreference = 'Stop'
    $source = 'F:\backup\windowsapps\profile\settings.json'
    $target = 'C:\Users\micha\AppData\Local\Packages\Microsoft.WindowsTerminal_8wekyb3d8bbwe\LocalState\settings.json'
    $targetDir = Split-Path -Parent $target

    if (-not (Test-Path -LiteralPath $source -PathType Leaf)) {
        throw "rester source settings file not found: $source"
    }
    if (-not (Test-Path -LiteralPath $targetDir -PathType Container)) {
        New-Item -ItemType Directory -Force -Path $targetDir | Out-Null
    }

    $sourceJson = Get-Content -LiteralPath $source -Raw | ConvertFrom-Json
    $sourceKeybindings = @($sourceJson.keybindings)
    $sourceKeyRows = @($sourceKeybindings | Where-Object { $_.keys -or $_.key })
    if ($sourceKeybindings.Count -eq 0 -or $sourceKeyRows.Count -eq 0) {
        throw "rester source contains no Windows Terminal key binding shortcuts: $source"
    }

    if (Test-Path -LiteralPath $target -PathType Leaf) {
        $stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
        Copy-Item -LiteralPath $target -Destination "$target.before-rester-$stamp.bak" -Force
    }

    Copy-Item -LiteralPath $source -Destination $target -Force

    $sourceHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $source).Hash
    $targetHash = (Get-FileHash -Algorithm SHA256 -LiteralPath $target).Hash
    if ($sourceHash -ne $targetHash) {
        throw "rester hash verification failed: source=$sourceHash target=$targetHash"
    }

    $targetJson = Get-Content -LiteralPath $target -Raw | ConvertFrom-Json
    $targetKeybindings = @($targetJson.keybindings)
    $targetKeyRows = @($targetKeybindings | Where-Object { $_.keys -or $_.key })
    if ($targetKeybindings.Count -ne $sourceKeybindings.Count -or $targetKeyRows.Count -ne $sourceKeyRows.Count) {
        throw "rester key binding verification failed: source=$($sourceKeybindings.Count)/$($sourceKeyRows.Count) target=$($targetKeybindings.Count)/$($targetKeyRows.Count)"
    }

    [pscustomobject]@{
        Restored = $true
        Source = $source
        Target = $target
        Sha256 = $targetHash
        Keybindings = $targetKeybindings.Count
        KeybindingShortcuts = $targetKeyRows.Count
    }
}

